    ["First Light"] = 209,
    ["Helfire Spirit"] = 153,
    ["30M Vampire Coffin"] = 175,
    ["Crystalline Colossus"] = 164,
    ["Angelus"] = 152,
    ["Sand Sovereign"] = 144,
    ["Party Doggy"] = 150,
    ["Party Kitty"] = 150,
    ["Soul Hunter"] = 110,
