-- The loop -------------------------------------------------------------------------------------

local stats = { eggs = 0, spent = 0, started = nil }
local recent = {} -- os.clock() of each hatched egg in the last minute, for the rate
local note = "Auto hatch is off."
local active = false -- the server believes we are auto hatching

local function stop()
    if active then
        active = false
        pcall(Env.fire, "EggService", "StopOfflineHatch")
    end
end

local function pause(text, seconds)
    note = text
    Life.wait(seconds)
end

local function noEggDetail(data)
    local P = Ui.__progressTest
    local coins = type(data) == "table" and type(data.Currencies) == "table" and tonumber(data.Currencies.Coins) or nil
    local slots = progressFreeSlots(data)
    local total, accessible, cooling = 0, 0, 0
    if type(P) == "table" and P.phase == "rebirth" and not targetMode(P) then
        local islands = type(data.Progression) == "table" and data.Progression.UnlockedIslands or nil
        for egg, def in pairs(EGGS) do
            total += 1
            local open = farmAreaOpen(data, def)
            local hasPosition = EGG_POSITIONS[egg] ~= nil or eggModel(egg) ~= nil
                or (islandApi and type(def.island) == "string" and def.island ~= "")
            if def.coinPricing and def.price > 0 and open and hasPosition then
                if os.clock() < (refused[egg] or 0) then cooling += 1 else accessible += 1 end
            end
        end
    else
        for _ in pairs(EGGS) do total += 1 end
    end
    local pricing = type(EggPricing) == "table" and type(EggPricing.GetTotal) == "function"
    local budget = coins and coins >= 0 and coins * 0.20 or nil
    local budgetText = targetMode(P) and "на 30M x3 нужно 900 млн, доступен весь баланс"
        or ("лимит на партию 20%=" .. tostring(budget))
    local floorText = ""
    if P and P.phase == "rebirth" and not targetMode(P) then
        if P.farmEggFloorError then floorText = ", ошибка уровня яйца=" .. tostring(P.farmEggFloorError)
        elseif finitePositive(P.farmEggFloor) then
            floorText = ", уровень=" .. tostring(P.farmEggName) .. " от " .. tostring(P.farmEggFloor)
                .. " за яйцо; дешевле не выбираю, жду доступность/баланс"
        end
    end
    return "нет подходящего яйца: фаза=" .. tostring(P and P.phase) .. ", монет=" .. tostring(coins)
        .. ", " .. budgetText .. floorText .. ", свободных мест=" .. (slots == math.huge and "неизвестно" or tostring(slots))
        .. ", доступно по острову/координатам=" .. tostring(accessible) .. ", временно пропущено=" .. tostring(cooling)
        .. ", яиц в конфиге=" .. tostring(total) .. ", формула цены=" .. (pricing and "есть" or "нет")
end

local function handleMoveFailure(egg, reason, detail)
    if reason == "paused" then return end
    local P = Ui.__progressTest
    local farm = P and P.phase == "rebirth" and not targetMode(P) and not P.farmThresholdReached
        and not P.holdHatch and not P.stopRequested and not P.pending and not P.cleaning
    local skip = farm and (reason == "model_missing" or reason == "no_position" or reason == "no_center"
        or reason == "not_near" or reason == "trip_error")
    local extra = ""
    if skip then
        -- Retry a temporarily missing stand later; equal or more expensive alternatives may
        -- still be used, but the user's selected price floor is never lowered.
        refused[egg] = os.clock() + 15
        extra = "; жду 15 с и проверяю только равноценные или более дорогие яйца"
    end
    hatchDiagnostic("move-failed", "не дошёл до " .. tostring(egg) .. ": " .. tostring(detail or reason) .. extra, 15)
end

local function autoLoop()
    local tooFar = 0
    while Life.alive do
        local P = Ui.__progressTest
        local sampleEgg = targetMode(P) and P.eggGoal or ""
        local sampleCount = targetMode(P) and 3 or 1
        local blocked = hatchDenied(P, sampleEgg, sampleCount)
        if Ui.hatchInFlight then blocked = "другая партия ещё ожидает ответ" end
        if blocked then
            stop()
            note = "Ожидание: " .. tostring(blocked)
            setHatchStage("пауза: " .. tostring(blocked))
            diagnoseWaiting("paused", "ожидание: " .. tostring(blocked) .. " | фаза=" .. tostring(P and P.phase))
            Life.wait(0.2)
            continue
        end
        local data = Env.data()
        if type(data) ~= "table" then
            setHatchStage("ожидание данных игрока")
            diagnoseWaiting("data", "нет данных игрока; запрос яйца не отправлен")
            Life.wait(0.5)
            continue
        end
        setHatchStage("выбор доступного яйца")
        local egg = chooseEgg(data)
        if not egg then
            setHatchStage("нет подходящего яйца")
            diagnoseWaiting("selection", noEggDetail(data))
            pause("No egg currently fits the budget or is available.", 1)
            continue
        end
        if egg ~= current then
            current, tooFar = egg, 0
            pcall(function() Env.LocalPlayer:SetAttribute("TAPSIM_Egg", egg) end)
            logEgg(string.format("выбрано %s (цена в конфиге %s, предварительно x%d; запрос ещё не отправлен)",
                egg, tostring(EGGS[egg] and EGGS[egg].price), hatchCount(data, egg) or 0))
        end
        local count = hatchCount(data, egg)
        if not count then
            setHatchStage("изменился баланс или свободные места")
            diagnoseWaiting("count", "не удалось выбрать партию для " .. tostring(egg) .. ": " .. noEggDetail(data))
            pause("Budget or storage changed.", 0.5)
            continue
        end
        if not nearEgg(egg) then
            if not Ui.on("HatchTeleport") then
                setHatchStage("далеко от стойки; телепорт выключен")
                diagnoseWaiting("teleport-off", "далеко от " .. tostring(egg) .. ": HatchTeleport выключен; запрос не отправлен")
                pause("Too far from the egg; teleport is off.", 1)
                continue
            end
            Ui.status = "Walking to the " .. egg .. " egg"
            local arrived, reason, detail = goToEgg(egg)
            if not arrived then
                handleMoveFailure(egg, reason, detail)
                pause("Could not reach the " .. egg .. " egg: " .. tostring(detail or reason), reason == "paused" and 0.2 or 0.5)
                continue
            end
        end
        -- Count was selected before a potentially long trip. Refresh it after arrival; a further
        -- increase before FireServer no longer invalidates an otherwise affordable smaller batch.
        if hatchDenied(P, egg, count) then Life.wait(0.1); continue end
        local afterTrip = Env.data()
        if type(afterTrip) ~= "table" then
            diagnoseWaiting("data", "после перемещения нет данных игрока; запрос не отправлен")
            Life.wait(0.5)
            continue
        end
        count = hatchCount(afterTrip, egg)
        if not count then
            hatchDiagnostic("count-changed", "после перемещения баланс или свободные места изменились для "
                .. tostring(egg) .. "; выберу партию заново", 20)
            Life.wait(0.2)
            continue
        end
        if hatchDenied(P, egg, count) then Life.wait(0.1); continue end
        applyAutoDelete(egg)
        if hatchDenied(P, egg, count) then Life.wait(0.1); continue end
        clearWaiting()
        Ui.status = string.format("Auto hatching %s x%d", egg, count)
        local result, attempted, verified = hatch(egg, count)
        if attempted then active = true end
        if not result then
            pause("The egg request is not confirmed; safety pause.", 0.5)
        elseif result.Success and verified then
            tooFar = 0
            local got = tonumber(result.Rolls) or (type(result.Pets) == "table" and #result.Pets > 0 and #result.Pets) or count
            stats.eggs += got
            stats.spent += tonumber(result.Spent) or 0
            stats.started = stats.started or os.clock()
            local now = os.clock()
            for _ = 1, got do recent[#recent + 1] = now end
            note = string.format("Hatched %s x%d.", egg, got)
        elseif result.Success then
            -- A success-shaped packet with inconsistent Egg/Rolls/Spent was not verified.
            pause("The server response could not be verified; safety pause.", 1)
        elseif result.Error == "Unavailable" then
            hatchDiagnostic("request-unavailable", "EggHatchRequested недоступен до отправки: "
                .. tostring(result.Reason) .. "; повторю через 5 с", 20)
            pause("Egg request remote unavailable.", 5)
        elseif result.Error == "RateLimited" then
            hatchDiagnostic("server-rate", "сервер отклонил " .. tostring(egg) .. ": RateLimited; жду повтор", 20)
            Life.wait(0.4)
        elseif result.Error == "Cancelled" then
            if attempted then
                hatchDiagnostic("server-refusal", "сервер ответил на " .. tostring(egg) .. ": Cancelled", 20)
            else
                hatchDiagnostic("cancelled", "запрос " .. tostring(egg) .. " не отправлен: " .. tostring(result.Reason), 20)
            end
            Life.wait(0.1)
        elseif result.Error == "TooFar" then
            tooFar += 1
            hatchDiagnostic("server-far", "сервер отклонил " .. tostring(egg) .. ": TooFar; попробую подойти снова", 15)
            if not Ui.on("HatchTeleport") then
                pause("Too far from the " .. egg .. " egg; teleport is off.", 2)
            elseif tooFar >= 3 and P and P.phase == "rebirth" and not targetMode(P) then
                refused[egg] = os.clock() + 15
                tooFar = 0
                hatchDiagnostic("server-far-skip", "три отказа TooFar для " .. tostring(egg)
                    .. "; пропускаю стойку на 15 с, дешевле яйцо не выбираю", 15)
                Life.wait(0.3)
            else
                local arrived, reason, detail = goToEgg(egg)
                if not arrived then handleMoveFailure(egg, reason, detail) end
                Life.wait(tooFar >= 3 and 2 or 0.2)
            end
        elseif result.Error == "StorageFull" then
            hatchDiagnostic("storage", "сервер отклонил яйцо: StorageFull; жду существующую чистку", 20)
            pause("Storage full; waiting for cleanup.", 2)
        elseif result.Error == "NotEnoughCoins" then
            refused[egg] = os.clock() + 5
            hatchDiagnostic("server-coins", "сервер отклонил " .. tostring(egg) .. ": NotEnoughCoins; жду доход", 20)
            Life.wait(0.25)
        elseif result.Error == "IslandLocked" then
            refused[egg] = os.clock() + 60
            hatchDiagnostic("server-island", "сервер отклонил " .. tostring(egg) .. ": IslandLocked", 20)
            note = egg .. " is on an island you have not unlocked."
        else
            hatchDiagnostic("server-refusal", "сервер отклонил " .. tostring(egg) .. ": "
                .. tostring(result.Error or result.Reason or "unknown"), 20)
            pause("Hatch refused: " .. tostring(result.Error or result.Reason or "unknown"), 1)
        end
    end
end

-- Life.spawn records an exception but does not restart a dead worker. Recover from exceptions
-- only if no request could have been sent. Once a request is possibly in flight, fail closed.
Life.spawn("hatch:auto", function()
    while Life.alive do
        local ok, err = pcall(autoLoop)
        if not Life.alive then return end
        if waiting or Ui.hatchInFlight then
            local why = "ошибка цикла при возможном запросе яйца: " .. tostring(err or "цикл завершился")
            hatchFailClosed(Ui.__progressTest, why)
            hatchDiagnostic("worker-uncertain", why .. "; повторно не отправляю", 20)
            return
        end
        local why = ok and "цикл неожиданно завершился" or tostring(err)
        setHatchStage("ошибка до отправки; повтор")
        hatchDiagnostic("worker-restart", "ошибка цикла яйца до отправки: " .. why .. "; повторю через 2 с", 20)
        Life.wait(2)
    end
end)

-- If a lookup itself gets stuck (or a Life.spawn dies outside the protected loop), report the
-- actual phase and stage in the same normal console log rather than silently showing zero eggs.
Life.loop("hatch:watchdog", 10, function()
    local P = Ui.__progressTest
    if type(P) ~= "table" or not Life.alive or not Ui.on("AutoHatch") then return end
    local errors = type(Life.errors) == "table" and Life.errors or {}
    local workerError = errors["hatch:auto"] or errors["hatch:results"] or errors["hatch:result"]
    if workerError then
        hatchDiagnostic("worker-error", "ошибка обработчика яиц: " .. tostring(workerError), 20)
    elseif not P.holdHatch and not P.stopRequested and os.clock() - hatchStageAt >= 15 then
        hatchDiagnostic("stall", "нет продвижения " .. tostring(math.floor(os.clock() - hatchStageAt))
            .. " с: этап=" .. tostring(hatchStage) .. ", фаза=" .. tostring(P.phase)
            .. ", ответ подключён=" .. tostring(resultReady) .. ", запрос в полёте=" .. tostring(Ui.hatchInFlight == true), 20)
    end
end)


Life.loop("hatch:panel", 0.5, function()
    local data = Env.data()
    if not data then
        return
    end
    local cutoff = os.clock() - 60
    while recent[1] and recent[1] < cutoff do
        table.remove(recent, 1)
    end
    local lines = {}
    if current and EGGS[current] then
        local count = hatchCount(data, current) or 0
        lines[#lines + 1] = string.format("Egg: %s (%s each), %d per hatch", current, shortNumber(unitPrice(data, current)), count)
        local drought = type(data.Eggs) == "table" and type(data.Eggs.SecretDroughtSeconds) == "table"
            and tonumber(data.Eggs.SecretDroughtSeconds[current]) or 0
        local fill = math.clamp(drought / SECRET_PITY_SECONDS, 0, 1)
        lines[#lines + 1] = string.format("Secret pity: %d%% (luck x%.2f)", math.floor(fill * 100), 1 + (SECRET_PITY_MAX - 1) * fill)
    end
    local window = stats.started and math.min(60, os.clock() - stats.started) or 0
    lines[#lines + 1] = string.format("Rate: %d eggs/min, %d this session, %s coins spent",
        window > 1 and math.floor(#recent * 60 / window) or 0, stats.eggs, shortNumber(stats.spent))
    local owned = 0
    for _ in pairs(type(data.Pets) == "table" and type(data.Pets.Owned) == "table" and data.Pets.Owned or {}) do
        owned += 1
    end
    lines[#lines + 1] = string.format("Storage: %d / %s", owned, tostring(type(data.Pets) == "table" and data.Pets.StorageLimit or "?"))
    lines[#lines + 1] = note
    panel.set(lines)
end)

Life.onCleanup(stop)

-- Разрешаем только однозначно найденный в живом конфиге 30M за 300 млн / 900 млн за x3.
local function is30M(value)
    local n = string.lower(tostring(value or "")):gsub("[^%w]", "")
    local function token(part)
        local cursor = 1
        while true do
            local at = n:find(part, cursor, true)
            if not at then return false end
            local before = at > 1 and n:sub(at - 1, at - 1) or ""
            local after = n:sub(at + #part, at + #part)
            if not before:match("%d") and not after:match("%d") then return true end
            cursor = at + 1
        end
    end
    return token("30m") or token("30000000")
end
local function progressTarget(data)
    if type(data) ~= "table" then return nil, "нет реплики" end
    local found, matches = nil, 0
    for name, def in pairs(EGGS) do
        if type(name) == "string" and def.price == 300000000 and (is30M(name) or is30M(def.display)) then
            found, matches = name, matches + 1
        end
    end
    if matches ~= 1 then return nil, "30M не найден однозначно в игровом конфиге (совпадений: " .. matches .. ")" end
    if progressStrictPrice(data, found) ~= 900000000 then return nil, "цена 30M x3 не подтверждена как 900 млн" end
    -- Отметка Eggs.Unlocked сама по себе не является подтверждённым запретом доступа.
    -- Явный отказ игры обработаем отдельно; другое яйцо вместо 30M выбирать нельзя.
    -- Старая сохранённая координата НЕ доказывает, что ивентовая стойка ещё существует.
    local visible = progressLivePosition(found) ~= nil
    return found, visible and "ready" or "no_position", 900000000
end

-- Если стойка ещё не стримится, прибываем к последней точке или к Spawn и смотрим модель.
-- Одна сохранённая координата без живой модели не считается доступным ивентом.
local function progressLocate(egg)
    local P = Ui.__progressTest
    if not P or not Life.alive or P.stopRequested or P.pending or P.previousHatchPending
        or P.previousRebirthPending or P.previousCraftPending or P.cleaning or P.craftBusy or P.craftInFlight
        or P.previousIslandPending or P.islandUncertain or P.islandTravelUncertain
        or Ui.travelling or not Ui.on("HatchTeleport")
        or (Env.genv and Env.genv.__handoverPaused) then return false end
    if progressLivePosition(egg) then return true end
    local destination, hrp = eggPosition(egg) or EGG_POSITIONS.Basic, root()
    if not destination or not hrp then return false end
    Ui.hatchMoving = true
    local ok = pcall(function()
        if islandApi and type(islandApi.travel) == "function" then
            local def = EGGS[egg]
            local island = def and type(def.island) == "string" and def.island ~= "" and def.island or "Spawn"
            local sent = islandApi.travel(island, function()
                return Life.alive and not P.stopRequested and not P.pending and not Ui.travelling
                    and not P.islandTravelUncertain and not (Env.genv and Env.genv.__handoverPaused)
            end)
            if sent then
                local deadline = os.clock() + 3
                while Life.alive and not P.stopRequested and not P.islandTravelUncertain
                    and not progressLivePosition(egg) and os.clock() < deadline do Life.wait(0.2) end
                if progressLivePosition(egg) then return end
            end
        end
        if P.islandTravelUncertain then return end
        Env.streamAround(destination, 5)
        if not Life.alive or P.stopRequested or P.pending or Ui.travelling
            or (Env.genv and Env.genv.__handoverPaused) then return end
        hrp = root()
        if not hrp then return end
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.CFrame = CFrame.new(destination + Vector3.new(0, 6, 0))
        Life.wait(3)
    end)
    Env.elevate()
    Ui.hatchMoving = false
    return ok and progressLivePosition(egg) ~= nil
end

return { progressTarget = progressTarget, progressLocate = progressLocate }
end
__modules["features/home"] = function(use) -- src/games/tapsim/features/home.luau
-- Home tab: the shared welcome box plus your live currencies and progress.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")
local Home = use("shared/home")

local _, statusLabel = Home.build()
local statsBox = Ui.Tabs.Home:AddGroupbox({ Side = "Right", Name = "You", IconName = "user" })
local stats = statsBox:AddLabel("Loading...", true)

local function comma(n)
    local text = string.format("%d", math.floor(tonumber(n) or 0))
    local out = text:reverse():gsub("(%d%d%d)", "%1,"):reverse()
    return (out:gsub("^,", ""))
end

Life.loop("home:stats", 1, function()
    statusLabel:SetText("Doing: " .. tostring(Ui.status or "Idle"))
    local data = Env.data()
    if not data then
        stats:SetText("Waiting for your data to load...")
        return
    end
    local prog = type(data.Progression) == "table" and data.Progression or {}
    local rebirths = type(data.Statistics) == "table" and data.Statistics.Rebirths
    stats:SetText(string.format(
        "Coins: %s\nGems: %s   Tokens: %s\nWorld: %s   Island: %s\nZone: %s%s",
        comma(Env.currency("Coins")),
        comma(Env.currency("Gems")), comma(Env.currency("Tokens")),
        tostring(prog.World or "?"), tostring(prog.Island or "?"),
        tostring(prog.Zone or "?"),
        rebirths and ("\nRebirths: " .. comma(rebirths)) or ""))
end)

return {}
end
__modules["features/honeypot"] = function(use) -- src/games/tapsim/features/honeypot.luau
-- Craft tab: the Honey Pot (Shared.Items.HoneyPotConfig), up at Sky Island height next to the
-- Map1 area. It turns the ingredients island creatures drop (Cloud Puff, Pumpkin Seeds, Glow
-- Spore, Cactus Fruit, Crystal Shard) into treats and pet boosts, in 3 timed slots.
--
-- HoneyPotService.Craft(key, amount) starts a batch in a free slot, Claim(slot) collects it and
-- Stop(slot) cancels; all of them need you within the machine's Range (25 studs). A batch of
-- `Amount` takes Amount x Seconds (HoneyPotConfig.Progress).

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local Options = Ui.Options
local tab = Ui.Tabs.Craft

local Config
do
    local ok, module = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Items.HoneyPotConfig)
    end)
    Config = ok and type(module) == "table" and module or nil
end

local MACHINE = Vector3.new(40.6, -27.1, -1964.4) -- measured in the game
-- Rarest first: when ingredients run short, the best recipe gets them.
local PRIORITY = { "SecretFruit", "RainbowStrawberry", "PetLevels10", "GoldenApple", "DragonFruit", "PetXP3x",
    "PetClicks2x", "BagOfTreats" }
local NAMES = {
    SecretFruit = "Secret Fruit", RainbowStrawberry = "Rainbow Strawberry", PetLevels10 = "+10 Pet Levels",
    GoldenApple = "Golden Apple", DragonFruit = "Dragon Fruit", PetXP3x = "2x Pet XP", PetClicks2x = "2x Pet Clicks",
    BagOfTreats = "Bag of Treats",
}

local labels, keyOf = {}, {}
for _, key in ipairs(PRIORITY) do
    if not Config or Config.ByKey[key] then
        labels[#labels + 1] = NAMES[key] or key
        keyOf[NAMES[key] or key] = key
    end
end

local box = tab:AddGroupbox({ Side = "Left", Name = "Honey Pot", IconName = "cooking-pot" })
box:AddToggle("AutoHoneyPot", {
    Text = "Auto Honey Pot",
    Default = false,
    Tooltip = "Keeps the Honey Pot's 3 slots cooking the recipes you pick from the ingredients you have, and collects them when done. Island creatures drop the ingredients.",
})
Ui.automation("AutoHoneyPot", false)
box:AddDropdown("HoneyPicks", {
    Text = "Cook these",
    Values = labels,
    Multi = true,
    Default = labels,
    Tooltip = "Rarest first: Secret Fruit, Rainbow Strawberry, +10 Pet Levels, Golden Apple, Dragon Fruit, 2x Pet XP, 2x Pet Clicks, Bag of Treats.",
})
local label = box:AddLabel("Off.", true)

local session = { crafted = 0, claimed = 0, note = "" }

local function slots(data)
    local pot = type(data.HoneyPot) == "table" and data.HoneyPot or {}
    return type(pot.Slots) == "table" and pot.Slots or {}
end

local function slotEntry(data, index)
    local all = slots(data)
    return all["Slot" .. index] or all[tostring(index)] or all[index]
end

local function finished(entry, now)
    if type(entry) ~= "table" or not Config then
        return false
    end
    local ok, done, endsAt = pcall(Config.Progress, entry, now)
    if not ok then
        return false
    end
    return (tonumber(done) or 0) > 0 and (tonumber(endsAt) or math.huge) <= now
end

-- The highest-priority picked recipe you have the ingredients for, and how many.
local function nextRecipe(data)
    if not Config then
        return nil
    end
    local picks = Options.HoneyPicks.Value or {}
    for _, key in ipairs(PRIORITY) do
        local recipe = Config.ByKey[key]
        if recipe and picks[NAMES[key] or key] then
            local ok, amount = pcall(Config.MaxCraftable, data, recipe)
            if ok and (tonumber(amount) or 0) > 0 then
                return recipe, amount
            end
        end
    end
    return nil
end

local function work(data)
    local now = os.time()
    local claim, free = false, false
    for index = 1, Config and Config.SlotCount or 3 do
        local entry = slotEntry(data, index)
        if entry == nil then
            free = true
        elseif finished(entry, now) then
            claim = true
        end
    end
    return claim, free and nextRecipe(data) ~= nil
end

local function root()
    local character = Env.LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

local function ask(name, ...)
    local ok, result = Env.invoke("HoneyPotService", name, ...)
    if ok and type(result) == "table" and result.Success ~= false and not result.Error then
        return result
    end
    return nil, tostring(ok and type(result) == "table" and (result.Error or result.Reason) or result)
end

local busy = false
local function trip()
    if busy or Ui.hatchMoving or Ui.travelling then
        return
    end
    busy = true
    Ui.travelling = "honeypot"
    local settle = os.clock() + 6
    while Ui.hatchInFlight and os.clock() < settle do
        Life.wait(0.05)
    end
    local hrp = root()
    local home = hrp and hrp.CFrame
    local ok, err = pcall(function()
        Env.streamAround(MACHINE, 6)
        local here = root()
        if here then
            here.AssemblyLinearVelocity = Vector3.zero
            here.CFrame = CFrame.new(MACHINE + Vector3.new(0, 4, 8))
        end
        Life.wait(0.6)
        local now = os.time()
        for index = 1, Config.SlotCount or 3 do
            local data = Env.data()
            local entry = data and slotEntry(data, index)
            if entry and finished(entry, now) then
                local result, why = ask("Claim", index)
                if result then
                    session.claimed += 1
                else
                    session.note = "Collect refused: " .. why .. "."
                end
                Life.wait(0.4)
            end
        end
        for index = 1, Config.SlotCount or 3 do
            local data = Env.data()
            if data and slotEntry(data, index) == nil then
                local recipe, amount = nextRecipe(data)
                if not recipe then
                    break
                end
                local result, why = ask("Craft", recipe.Key, amount)
                if result then
                    session.crafted += 1
                    session.note = string.format("Cooking %d %s.", amount, NAMES[recipe.Key] or recipe.Key)
                else
                    session.note = "Craft refused: " .. why .. "."
                    break
                end
                Life.wait(0.5)
            end
        end
    end)
    Env.elevate()
    if not ok then
        Life.errors["honeypot:trip"] = tostring(err)
    end
    if home then
        local back = root()
        if back then
            back.AssemblyLinearVelocity = Vector3.zero
            back.CFrame = home
        end
    end
    Ui.travelling = false
    busy = false
end

local nextTrip = 0
Life.loop("honeypot:auto", 2, function()
    local data = Env.data()
    if not (data and Config) then
        return
    end
    local now = os.time()
    local parts = {}
    for index = 1, Config.SlotCount or 3 do
        local entry = slotEntry(data, index)
        if type(entry) ~= "table" then
            parts[#parts + 1] = "empty"
        else
            local ok, _, endsAt = pcall(Config.Progress, entry, now)
            local left = ok and math.max(0, (tonumber(endsAt) or now) - now) or 0
            local key = entry.Recipe or entry.Key or (type(entry.Output) == "table" and entry.Output.Key)
            local name = NAMES[key] or tostring(key or "?")
            parts[#parts + 1] = left > 0 and string.format("%s %d:%02d", name, left // 60, left % 60) or (name .. " ready")
        end
    end
    local lines = { "Slots: " .. table.concat(parts, ", "),
        string.format("This session: %d batches started, %d collected.", session.crafted, session.claimed) }
    if session.note ~= "" then
        lines[#lines + 1] = session.note
    end
    label:SetText((Ui.on("AutoHoneyPot") and "" or "Off. ") .. table.concat(lines, "\n"))
    if not Ui.on("AutoHoneyPot") or busy or os.clock() < nextTrip then
        return
    end
    local claim, craft = work(data)
    if claim or craft then
        nextTrip = os.clock() + 20
        Life.spawn("honeypot:trip", trip)
    end
end)

Life.onCleanup(function()
    if busy then
        Ui.travelling = false
    end
end)

return {}
end
__modules["features/items"] = function(use) -- src/games/tapsim/features/items.luau
-- Rewards tab: items that do something when used, and rewards waiting to be claimed.
--
--   Totems (Shared.Items.TotemConfig): ItemService.PlaceTotem { TotemName, Position } drops one
--     where you stand; it boosts everyone within its Range (12-28 studs) for 5-17 minutes. Placed
--     only while you are standing at your hatch spot, and never on top of a running one of its kind
--     (ItemService.GetActiveTotems).
--   Gifts (Shared.Items.GiftConfig): GiftService.OpenGift { Gift, Amount }.
--   Weather dials: WeatherDialService.CanUse(kind) then Use(kind), "Rain" for the Rain Dial and
--     "Acid" for the Acid Dial, as the item's own use does.
--   Mastery rings (Shared.Progression.RelicConfig): earned at mastery level 100; MasteryService
--     .EquipRelic { Name } wears one.
--   Leaderboards: LeaderboardService.GetPendingRewards, then ClaimReward(LeaderboardId) each.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local Options = Ui.Options
local tab = Ui.Tabs.Rewards
local RS = Env.ReplicatedStorage

local function load(...)
    local path = { ... }
    local ok, module = Env.call(function()
        local node = RS
        for _, part in ipairs(path) do
            node = node:FindFirstChild(part)
        end
        return node and require(node)
    end)
    return ok and type(module) == "table" and module or nil
end

local TotemConfig = load("Shared", "Items", "TotemConfig")
local GiftConfig = load("Shared", "Items", "GiftConfig")
local RelicConfig = load("Shared", "Progression", "RelicConfig")

local TOTEMS = {}
for name in pairs(TotemConfig or {}) do
    if type(name) == "string" then
        TOTEMS[#TOTEMS + 1] = name
    end
end
table.sort(TOTEMS)

-- Gift items are the GiftConfig entries that hold a list of prizes.
local GIFTS = {}
for name, entry in pairs(GiftConfig or {}) do
    if type(name) == "string" and type(entry) == "table" and type(entry[1]) == "table" then
        GIFTS[#GIFTS + 1] = name
    end
end
table.sort(GIFTS)

local DIALS = { RainDial = "Rain", AcidDial = "Acid" }
local RINGS = RelicConfig and RelicConfig.Order or { "HatchRing", "SecretRing", "TapRing", "GoldenRing", "EnchantRing" }

local box = tab:AddGroupbox({ Side = "Right", Name = "Items and rewards", IconName = "package" })
box:AddToggle("AutoTotems", {
    Text = "Place totems",
    Default = false,
    Tooltip = "Places the totems you own where you hatch (they boost everything within 12-28 studs for 5-17 minutes), one of each kind at a time.",
})
Ui.automation("AutoTotems", true)
box:AddDropdown("TotemPicks", {
    Text = "Totems",
    Values = #TOTEMS > 0 and TOTEMS or { "TotemOfLuck" },
    Multi = true,
    Default = TOTEMS,
})
box:AddToggle("AutoGifts", {
    Text = "Open gifts",
    Default = false,
    Tooltip = "Opens every gift item you get (Octo Incubators, rare pets and more inside).",
})
Ui.automation("AutoGifts", true)
box:AddToggle("AutoDials", {
    Text = "Use weather dials",
    Default = false,
    Tooltip = "Uses Rain Dials and Acid Dials (from Pet Defense) as soon as the game lets you.",
})
Ui.automation("AutoDials", true)
box:AddToggle("AutoRing", {
    Text = "Wear a mastery ring",
    Default = true,
    Tooltip = "Mastery rings are earned at mastery level 100. When you have one and wear none, the first in the list you own goes on.",
})
Ui.automation("AutoRing", true)
box:AddDropdown("RingOrder", {
    Text = "Preferred ring",
    Values = RINGS,
    Default = RINGS[1],
})
box:AddToggle("AutoLeaderboard", {
    Text = "Claim leaderboard rewards",
    Default = true,
    Tooltip = "Claims the weekly leaderboard rewards as soon as you have any.",
})
Ui.automation("AutoLeaderboard", true)
local label = box:AddLabel("", true)

local session = { totems = 0, gifts = 0, dials = 0, rings = 0, boards = 0, note = "" }

local function owned(data, name)
    local items = type(data.Items) == "table" and type(data.Items.Owned) == "table" and data.Items.Owned or {}
    return tonumber(items[name]) or 0
end

local function root()
    local character = Env.LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

-- Totems --------------------------------------------------------------------------------------

local function activeTotems()
    local ok, result = Env.invoke("ItemService", "GetActiveTotems")
    local kinds = {}
    for _, entry in pairs(ok and type(result) == "table" and result or {}) do
        local name = type(entry) == "table" and (entry.TotemName or entry.Name or entry.Totem) or entry
        if type(name) == "string" then
            kinds[name] = true
        end
    end
    return kinds
end

local function placeTotems(data)
    -- Only where the boost matters: standing still at the egg, not mid-trip.
    if Ui.travelling or Ui.hatchMoving or not Ui.on("AutoHatch") then
        return
    end
    local picks = Options.TotemPicks.Value or {}
    local active
    for _, name in ipairs(TOTEMS) do
        if picks[name] and owned(data, name) > 0 then
            active = active or activeTotems()
            if not active[name] then
                local hrp = root()
                if not hrp then
                    return
                end
                local ok, result = Env.invoke("ItemService", "PlaceTotem", { TotemName = name, Position = hrp.Position })
                if ok and type(result) == "table" and result.Success == true then
                    session.totems += 1
                    session.note = "Placed a " .. name .. "."
                    active[name] = true
                else
                    session.note = string.format("%s: %s.", name, tostring(type(result) == "table" and (result.Reason or result.Error) or result))
                end
                Life.wait(0.5)
            end
        end
    end
end

-- Gifts and dials -------------------------------------------------------------------------------

local function openGifts(data)
    for _, gift in ipairs(GIFTS) do
        local count = owned(data, gift)
        if count > 0 then
            local ok, result = Env.invoke("GiftService", "OpenGift", { Gift = gift, Amount = count })
            if ok and type(result) == "table" and result.Success ~= false and not result.Error then
                session.gifts += count
                session.note = string.format("Opened %d %s.", count, gift)
            else
                session.note = string.format("%s: %s.", gift, tostring(type(result) == "table" and (result.Reason or result.Error) or result))
            end
            Life.wait(0.6)
        end
    end
end

local dialWait = {}
local function useDials(data)
    for item, kind in pairs(DIALS) do
        if owned(data, item) > 0 and (dialWait[kind] or 0) <= os.clock() then
            local ok, check = Env.invoke("WeatherDialService", "CanUse", kind)
            if ok and type(check) == "table" and check.Success == true then
                local used, result = Env.invoke("WeatherDialService", "Use", kind)
                if used and type(result) == "table" and result.Success == true then
                    session.dials += 1
                    session.note = "Used a " .. item .. "."
                else
                    dialWait[kind] = os.clock() + 60
                end
            else
                -- another weather is running, or the game says not yet
                dialWait[kind] = os.clock() + 60
            end
            Life.wait(0.5)
        end
    end
end

-- Mastery ring and leaderboards ---------------------------------------------------------------

local function wearRing(data)
    local mastery = type(data.Mastery) == "table" and data.Mastery or {}
    if type(mastery.EquippedRelic) == "string" or type(mastery.RelicInventory) ~= "table" then
        return
    end
    local order = { Options.RingOrder.Value }
    for _, ring in ipairs(RINGS) do
        order[#order + 1] = ring
    end
    for _, ring in ipairs(order) do
        if mastery.RelicInventory[ring] == true then
            local ok, result = Env.invoke("MasteryService", "EquipRelic", { Name = ring })
            if ok and type(result) == "table" and result.Success == true then
                session.rings += 1
                session.note = "Wearing the " .. ring .. "."
            end
            return
        end
    end
end

local nextBoards = 0
local function claimBoards()
    if os.clock() < nextBoards then
        return
    end
    nextBoards = os.clock() + 300
    local ok, pending = Env.invoke("LeaderboardService", "GetPendingRewards")
    for _, entry in pairs(ok and type(pending) == "table" and pending or {}) do
        if type(entry) == "table" and entry.LeaderboardId ~= nil then
            local claimed, result = Env.invoke("LeaderboardService", "ClaimReward", entry.LeaderboardId)
            if claimed and type(result) == "table" and result.Success ~= false then
                session.boards += 1
                session.note = "Claimed a leaderboard reward."
            elseif type(result) == "table" and result.Reason == "StorageFull" then
                session.note = "Leaderboard reward waiting: your pet storage is full."
            end
            Life.wait(0.5)
        end
    end
end

Life.loop("items:auto", 3, function()
    local data = Env.data()
    if not data then
        return
    end
    if Ui.on("AutoGifts") then
        openGifts(data)
    end
    if Ui.on("AutoDials") then
        useDials(data)
    end
    if Ui.on("AutoRing") then
        wearRing(data)
    end
    if Ui.on("AutoLeaderboard") then
        claimBoards()
    end
    if Ui.on("AutoTotems") then
        placeTotems(data)
    end
    local counts = {}
    for _, name in ipairs(TOTEMS) do
        local n = owned(data, name)
        if n > 0 then
            counts[#counts + 1] = string.format("%d %s", n, (name:gsub("^TotemOf", "")))
        end
    end
    local lines = {
        "Totems owned: " .. (#counts > 0 and table.concat(counts, ", ") or "none"),
        string.format("This session: %d totems, %d gifts, %d dials, %d leaderboard rewards.", session.totems, session.gifts,
            session.dials, session.boards),
    }
    if session.note ~= "" then
        lines[#lines + 1] = session.note
    end
    label:SetText(table.concat(lines, "\n"))
end)

return {}
end
__modules["features/minigames"] = function(use) -- src/games/tapsim/features/minigames.luau
-- Rewards tab: Memory Match and Boingo's quest.
--
-- Memory Match (MemoryMatchService, pad at workspace.MemoryMatch.TouchToPlay, within 24 studs):
-- Open(true) deals a board of 12 cards (6 pet pairs) once every 30 minutes; Flip(boardId, card)
-- turns one over and answers with the board, the flipped card's Pet showing, and after the second
-- card of a turn whether it was a Match. Cards cannot be flipped before UnlockAt. Played with a
-- perfect memory: a known pair is taken at once, an unknown card is turned first, and its partner
-- is taken if it was seen before.
--
-- Boingo's quest (Shared.Quests.NpcQuestConfig, line "BouncyBall"): NpcQuestService.Talk { Line }
-- starts and advances it, Collect { Line, Core } picks up each of the 5 Bounce Cores within 14
-- studs of it. The other steps (tap 1,000 times, hatch 20 eggs, unlock Sky Island) are progress you
-- make anyway. Reward: 5 Slime.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local tab = Ui.Tabs.Minigames
local RS = Env.ReplicatedStorage

local PAD = Vector3.new(-3118.3, -526.1, -2179.3)
local LINE = "BouncyBall"

local NpcQuestConfig
do
    local ok, module = Env.call(function()
        return require(RS.Shared.Quests.NpcQuestConfig)
    end)
    NpcQuestConfig = ok and type(module) == "table" and module or nil
end

local box = tab:AddGroupbox({ Side = "Left", Name = "Memory Match and quests", IconName = "gamepad-2" })
box:AddToggle("AutoMemory", {
    Text = "Play Memory Match",
    Default = false,
    Tooltip = "Plays Memory Match (by the spawn, every 30 minutes) with a perfect memory, then comes back.",
})
Ui.automation("AutoMemory", false)
box:AddToggle("AutoBoingo", {
    Text = "Do Boingo's quest",
    Default = false,
    Tooltip = "Talks to Boingo and picks up his 5 Bounce Cores around the spawn. Reward: 5 Slime. Once.",
})
Ui.automation("AutoBoingo", false)
-- Off until the game's Bouncy Obby can be finished: the live course has 3 of its 4 checkpoints and
-- no finish line (swept end to end), so a run can only fail. runObby below is kept for when it is
-- fixed; uncomment this toggle and the matching branch in the auto loop.
--[[
box:AddToggle("AutoObby", {
    Text = "Get the Bouncy Ball license",
    Default = false,
    Tooltip = "Once you have 20 Slime (the Glow Mushroom and Boingo give it), crafts a key, runs the Bouncy Obby checkpoint by checkpoint and finishes it, which earns the Bouncy Ball license. The run takes the game's minimum 45 seconds.",
})
Ui.automation("AutoObby", false)
]]
local label = box:AddLabel("", true)

local session = { played = 0, won = 0, note = "", boingo = "" }

local function root()
    local character = Env.LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

local function teleport(position)
    Env.streamAround(position, 5)
    local hrp = root()
    if hrp then
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.CFrame = CFrame.new(position + Vector3.new(0, 4, 0))
    end
end

-- Memory Match ---------------------------------------------------------------------------------

local function memoryCall(name, ...)
    for _ = 1, 6 do
        local ok, result = Env.invoke("MemoryMatchService", name, ...)
        if ok and type(result) == "table" and result.Error == "Please wait." then
            Life.wait(0.6)
        else
            return ok and type(result) == "table" and result or nil
        end
    end
    return nil
end

local function waitUnlock(state)
    local unlock = tonumber(state and state.UnlockAt) or 0
    local wait = unlock - workspace:GetServerTimeNow()
    if wait > 0 then
        Life.wait(wait + 0.15)
    end
end

local function playBoard(state)
    local known = {} -- card -> pet, for cards seen and not matched
    local function remember(board)
        for index, card in pairs(type(board.Cards) == "table" and board.Cards or {}) do
            index = tonumber(index)
            if index and type(card) == "table" then
                if card.Matched then
                    known[index] = nil
                elseif card.Pet then
                    known[index] = card.Pet
                end
            end
        end
    end
    local function unmatched(board)
        local list = {}
        for index, card in pairs(type(board.Cards) == "table" and board.Cards or {}) do
            index = tonumber(index)
            if index and type(card) == "table" and not card.Matched then
                list[#list + 1] = index
            end
        end
        table.sort(list)
        return list
    end
    local function flip(board, index)
        waitUnlock(board)
        local result = memoryCall("Flip", board.Id, index)
        if result then
            remember(result)
        end
        return result
    end
    local function knownPair(board)
        local open = unmatched(board)
        for a = 1, #open do
            for b = a + 1, #open do
                local pa, pb = known[open[a]], known[open[b]]
                if pa and pa == pb then
                    return open[a], open[b]
                end
            end
        end
        return nil
    end
    local function unknownCard(board, except)
        for _, index in ipairs(unmatched(board)) do
            if known[index] == nil and index ~= except then
                return index
            end
        end
        return nil
    end
    local function partnerOf(board, index)
        for _, other in ipairs(unmatched(board)) do
            if other ~= index and known[other] and known[other] == known[index] then
                return other
            end
        end
        return nil
    end

    remember(state)
    local board = state
    for _ = 1, 40 do
        if not (Life.alive and board and board.Outcome == "Playing") then
            break
        end
        local a, b = knownPair(board)
        if a then
            board = flip(board, a) or board
            board = flip(board, b) or board
        else
            local first = unknownCard(board)
            if not first then
                break
            end
            board = flip(board, first) or board
            local second = partnerOf(board, first) or unknownCard(board, first)
            if not second then
                break
            end
            board = flip(board, second) or board
        end
    end
    return board
end

local function playMemory()
    teleport(PAD)
    Life.wait(0.8)
    local state = memoryCall("Open", true)
    if not state then
        session.note = "Memory Match did not open."
        return
    end
    if state.Outcome ~= "Playing" then
        session.note = "Memory Match: " .. tostring(state.Error or state.Outcome)
        return
    end
    local final = playBoard(state)
    session.played += 1
    local outcome = final and final.Outcome or "?"
    if outcome == "Won" or (final and tonumber(final.Pairs) == 6) then
        session.won += 1
    end
    session.note = string.format("Memory Match: %s in %s tries.", tostring(outcome), tostring(final and final.Attempts or "?"))
end

-- Boingo ---------------------------------------------------------------------------------------

local function questLine()
    if not NpcQuestConfig then
        return nil
    end
    local ok, line = Env.call(NpcQuestConfig.LineForNpc, "Boingo")
    if ok and type(line) == "table" then
        return line
    end
    return type(NpcQuestConfig.Lines) == "table" and NpcQuestConfig.Lines[LINE] or nil
end

local function boingoState(data)
    local line = questLine()
    if not (line and data) then
        return nil
    end
    local ok, entry = Env.call(NpcQuestConfig.GetEntry, data, line.Id)
    entry = ok and entry or nil
    local okStep, step = Env.call(NpcQuestConfig.CurrentStep, line, entry)
    return line, entry, okStep and step or nil
end

local function doBoingo()
    for _ = 1, 12 do
        local data = Env.data()
        local line, entry, step = boingoState(data)
        if not line then
            session.boingo = "Quest config could not be read."
            return
        end
        if entry and entry.Done == true then
            session.boingo = "Boingo's quest is done."
            return
        end
        if entry == nil or (step and step.Kind == "Talk") then
            local ok, result = Env.invoke("NpcQuestService", "Talk", { Line = line.Id })
            if not (ok and type(result) == "table" and result.Success == true) then
                session.boingo = "Boingo: " .. tostring(type(result) == "table" and (result.Reason or result.Error) or result)
                return
            end
        elseif step and step.Kind == "Collect" then
            local okCores, cores = Env.call(NpcQuestConfig.OpenCores, line, entry)
            local list = okCores and type(cores) == "table" and cores or {}
            if #list == 0 then
                Env.invoke("NpcQuestService", "Talk", { Line = line.Id })
            end
            for _, core in ipairs(list) do
                if typeof(core.Position) == "Vector3" then
                    teleport(core.Position)
                    Life.wait(0.6)
                    Env.invoke("NpcQuestService", "Collect", { Line = line.Id, Core = core.Id })
                    Life.wait(0.3)
                end
            end
        else
            -- a progress step: done means Boingo moves you on when you talk to him
            local okDone, done = Env.call(NpcQuestConfig.IsStepComplete, line, entry, data)
            if okDone and done then
                Env.invoke("NpcQuestService", "Talk", { Line = line.Id })
            else
                session.boingo = "Boingo: waiting on \"" .. tostring(step and step.Title) .. "\"."
                return
            end
        end
        Life.wait(0.5)
    end
end

-- Bouncy Obby ----------------------------------------------------------------------------------
--
-- BouncyObbyService: CraftKey turns 20 Slime into a key, Enter puts you on the course, Reach
-- { Index } saves each checkpoint (parts with a CheckpointIndex attribute in workspace.BouncyObby),
-- Finish on the part marked Finish ends the run - refused as "TooFast" before MinFinishSeconds (45)
-- or "MissedCheckpoints". The first finish unlocks the Bouncy Ball license (Data.Unlocks).

local ObbyConfig
do
    local ok, module = Env.call(function()
        return require(RS.Shared.Game.BouncyObbyConfig)
    end)
    ObbyConfig = ok and type(module) == "table" and module or nil
end

local function obbyCall(name, payload)
    local ok, result
    if payload ~= nil then
        ok, result = Env.invoke("BouncyObbyService", name, payload)
    else
        ok, result = Env.invoke("BouncyObbyService", name)
    end
    return ok and type(result) == "table" and result or {}
end

-- The course is ~2,400 x 2,000 studs and only streams in 200 studs around you, so its checkpoints
-- and finish are found by sweeping it once; what was found is kept for later runs (it is built by
-- the server, the same every time).
local obbySpots = Env.genv.__SlopixObbySpots or { checkpoints = {}, finish = nil }
Env.genv.__SlopixObbySpots = obbySpots

local function obbyModel()
    return workspace:FindFirstChild(ObbyConfig and ObbyConfig.ModelName or "BouncyObby")
end

local function obbyCount()
    local count = tonumber(workspace:GetAttribute("BouncyObbyCheckpoints")) or 4
    local found = 0
    for _ in pairs(obbySpots.checkpoints) do
        found += 1
    end
    return found, count
end

local function obbyScan()
    local model = obbyModel()
    for _, part in ipairs(model and model:GetDescendants() or {}) do
        if part:IsA("BasePart") then
            local index = part:GetAttribute("CheckpointIndex")
            if type(index) == "number" then
                obbySpots.checkpoints[index] = part.Position
            elseif part:GetAttribute("Finish") == true then
                obbySpots.finish = part.Position
            end
        end
    end
end

local function streamAround(position, seconds)
    Env.streamAround(position, seconds)
end

local function obbySweep()
    obbyScan()
    local found, count = obbyCount()
    if found >= count and obbySpots.finish then
        return true
    end
    local model = obbyModel()
    if not model then
        return false
    end
    local ok, center, size = pcall(function()
        local cframe, extents = model:GetBoundingBox()
        return cframe.Position, extents
    end)
    if not ok then
        return false
    end
    local low, high = center - size / 2, center + size / 2
    -- 250-stud steps keep every point of the course within the 200-stud stream of one visit
    for y = low.Y + 100, high.Y, 250 do
        for x = low.X + 125, high.X, 250 do
            for z = low.Z + 125, high.Z, 250 do
                if not Life.alive then
                    return false
                end
                local point = Vector3.new(x, y, z)
                streamAround(point, 2)
                local hrp = root()
                if hrp then
                    hrp.AssemblyLinearVelocity = Vector3.zero
                    hrp.CFrame = CFrame.new(point)
                end
                Life.wait(0.3)
                obbyScan()
                found, count = obbyCount()
                if found >= count and obbySpots.finish then
                    return true
                end
            end
        end
    end
    return false
end

local function hasLicense(data)
    return ObbyConfig and ObbyConfig.HasLicense(data) or false
end

local function slime(data)
    return ObbyConfig and ObbyConfig.SlimeOwned(data) or 0
end

local function runObby()
    local data = Env.data()
    if not data or hasLicense(data) then
        return
    end
    local progress = ObbyConfig.GetProgress(data)
    if not progress.Key then
        local crafted = obbyCall("CraftKey")
        if crafted.Success ~= true then
            session.note = "Obby key: " .. tostring(crafted.Reason or crafted.Error or "refused")
            return
        end
    end
    local entered = obbyCall("Enter")
    if entered.Success ~= true then
        session.note = "Obby: " .. tostring(entered.Reason or entered.Error or "could not enter")
        return
    end
    local started = os.clock()
    local deadline = os.clock() + 15
    repeat
        Life.wait(0.5)
    until obbyModel() or not Life.alive or os.clock() > deadline
    if not obbySweep() then
        local found, count = obbyCount()
        session.note = string.format("Obby: found %d of %d checkpoints%s; leaving, the key is kept.", found, count,
            obbySpots.finish and "" or " and no finish")
        obbyCall("Leave")
        return
    end
    local order = {}
    for index, position in pairs(obbySpots.checkpoints) do
        order[#order + 1] = { index = index, position = position }
    end
    table.sort(order, function(a, b)
        return a.index < b.index
    end)
    local reached = ObbyConfig.GetProgress(Env.data()).Reached or 0
    for _, checkpoint in ipairs(order) do
        if not Life.alive then
            return
        end
        if checkpoint.index > reached then
            streamAround(checkpoint.position, 2)
            local hrp = root()
            if hrp then
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.CFrame = CFrame.new(checkpoint.position + Vector3.new(0, 3, 0))
            end
            Life.wait(0.6)
            local result = obbyCall("Reach", { Index = checkpoint.index })
            if result.Success ~= true then
                session.note = string.format("Obby checkpoint %d: %s.", checkpoint.index, tostring(result.Reason or "refused"))
            end
            Life.wait(2)
        end
    end
    -- The game refuses a finish sooner than MinFinishSeconds into the run ("TooFast").
    local minimum = (ObbyConfig.MinFinishSeconds or 45) + 2
    while Life.alive and os.clock() - started < minimum do
        Life.wait(0.5)
    end
    streamAround(obbySpots.finish, 2)
    local hrp = root()
    if hrp then
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.CFrame = CFrame.new(obbySpots.finish + Vector3.new(0, 3, 0))
    end
    Life.wait(0.6)
    local finished = obbyCall("Finish")
    session.note = finished.Success == true and "Bouncy Obby finished: license earned."
        or ("Obby finish: " .. tostring(finished.Reason or "refused") .. " (the key is kept).")
    obbyCall("Leave")
end

-- Trips ----------------------------------------------------------------------------------------

local busy = false
local function trip(job)
    if busy or Ui.hatchMoving or Ui.travelling then
        return
    end
    busy = true
    Ui.travelling = "minigames"
    local settle = os.clock() + 6
    while Ui.hatchInFlight and os.clock() < settle do
        Life.wait(0.05)
    end
    local hrp = root()
    local home = hrp and hrp.CFrame
    local ok, err = pcall(job)
    Env.elevate()
    if not ok then
        Life.errors["minigames:trip"] = tostring(err)
        session.note = "Error: " .. tostring(err)
    end
    if home then
        local back = root()
        if back then
            back.AssemblyLinearVelocity = Vector3.zero
            back.CFrame = home
        end
    end
    Ui.travelling = false
    busy = false
end

local nextMemory, nextBoingo, nextObby = 0, 0, 0
Life.loop("minigames:auto", 2, function()
    local data = Env.data()
    if not data then
        return
    end
    local memory = type(data.MemoryMatch) == "table" and data.MemoryMatch or {}
    local wait = math.max(0, (tonumber(memory.NextPlay) or 0) - workspace:GetServerTimeNow())
    local lines = {
        wait > 0 and string.format("Memory Match in %d:%02d. Won %d.", wait // 60, math.floor(wait % 60), tonumber(memory.Wins) or 0)
            or string.format("Memory Match is ready. Won %d.", tonumber(memory.Wins) or 0),
    }
    local _, entry, step = boingoState(data)
    lines[#lines + 1] = entry and entry.Done and "Boingo's quest: done."
        or ("Boingo's quest: " .. (entry and step and tostring(step.Title) or "not started") .. ".")
    for _, note in ipairs({ session.note, session.boingo }) do
        if note ~= "" then
            lines[#lines + 1] = note
        end
    end
    label:SetText(table.concat(lines, "\n"))
    if busy or Ui.travelling or Ui.hatchMoving then
        return
    end
    if Ui.on("AutoMemory") and wait <= 0 and os.clock() >= nextMemory then
        nextMemory = os.clock() + 60
        Life.spawn("minigames:memory", trip, playMemory)
    elseif Ui.on("AutoBoingo") and not (entry and entry.Done) and os.clock() >= nextBoingo then
        nextBoingo = os.clock() + 120
        Life.spawn("minigames:boingo", trip, doBoingo)
    --[[ Bouncy Obby: see the commented-out toggle above.
    elseif Ui.on("AutoObby") and ObbyConfig and not hasLicense(data) and os.clock() >= nextObby
        and (slime(data) >= (ObbyConfig.KeyCost or 20) or ObbyConfig.GetProgress(data).Key) then
        nextObby = os.clock() + 300
        Life.spawn("minigames:obby", trip, runObby)
    ]]
    end
end)

Life.onCleanup(function()
    if busy then
        Ui.travelling = false
    end
end)

return {
    -- Plays a board now, whatever the timer says (a board left half-played can be finished).
    memory = function()
        Life.spawn("minigames:memory", trip, playMemory)
    end,
}
end
__modules["features/mining"] = function(use) -- src/games/tapsim/features/mining.luau
-- Rewards tab: the mine under Crystal Cave (MiningService). A 20 x 20 x 25 block mine per player,
-- fresh every day. Ores fill your bag; selling them gives mining coins, which buy better pickaxes
-- and bags and, in the daily shop, packs of real Coins and Gems. Clearing 25/50/75/100% of the
-- mine pays milestone Coins and Gems once a day (MiningConfig.Milestones).
--
-- Everything goes through the game's own mine so it shows as you would play it:
--   enter   standing in the portal makes the game's MiningController travel in (Enter) and draw
--           the mine;
--   mine    the controller's TouchTapInWorld handler is the game's "tap a block" input: the camera
--           is pointed at the chosen block for that one call and put back, and the game aims,
--           checks reach, sight and pickaxe power, sends Hit and breaks the block on screen;
--   pets    your equipped pets mine blocks near you by themselves (the server's PetMine), which is
--           most of the speed;
--   sell    standing on the Sell pad makes the game sell the bag;
--   shop    Purchase("BuyTool" | "BuyStorage", name) and DailyBuy(id) on their pads;
--   leave   the Exit pad.
-- Without getconnections the hub sends Hit itself, and broken blocks are not removed on screen
-- until the mine is redrawn.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local Options = Ui.Options
local RS = Env.ReplicatedStorage
local UserInputService = game:GetService("UserInputService")
local tab = Ui.Tabs.Minigames

local function load(...)
    local path = { ... }
    local ok, module = Env.call(function()
        local node = RS
        for _, part in ipairs(path) do
            node = node:FindFirstChild(part)
        end
        return node and require(node)
    end)
    return ok and type(module) == "table" and module or nil
end

local MiningWorld = load("Shared", "Minigames", "Mining", "MiningWorld")
local MiningConfig = load("Shared", "Minigames", "Mining", "MiningConfig")
local DailyShop = load("Shared", "Minigames", "Mining", "DailyShop")

local CRYSTAL_CAVE = Vector3.new(-53, 5445, -1992)
local SKIP_SECONDS = 60
local DAILY_ALL, DAILY_COINS, DAILY_GEMS, DAILY_OFF = "Coins and Gems packs", "Coins packs", "Gems packs", "Off"

local box = tab:AddGroupbox({ Side = "Right", Name = "Mine", IconName = "pickaxe" })
box:AddToggle("AutoMine", {
    Text = "Auto mine",
    Default = false,
    Tooltip = "Goes into the Crystal Cave mine and mines with you and your pets, selling whenever the bag is full. Auto hatch and other trips wait while it runs; turn it off to come back.",
})
Ui.automation("AutoMine", false)
box:AddToggle("MineUpgrades", {
    Text = "Buy pickaxes and bags",
    Default = true,
    Tooltip = "Spends mining coins on the next pickaxe or bag as soon as one is affordable. Better pickaxes break harder ore; the Copper Pickaxe is the only one that breaks Hardened Stone and the rare ores.",
})
box:AddDropdown("MineDaily", {
    Text = "Daily shop",
    Values = { DAILY_ALL, DAILY_COINS, DAILY_GEMS, DAILY_OFF },
    Default = DAILY_ALL,
    Tooltip = "Once every pickaxe and bag is bought, spare mining coins buy the daily shop's packs of real Coins or Gems (the Mining Legend title is never bought).",
})
local label = box:AddLabel("Auto mine is off.", true)

local session = { sold = 0, earned = 0, bought = {}, note = "" }

local function root()
    local character = Env.LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

local function controller()
    local module = RS:FindFirstChild("Controllers") and RS.Controllers:FindFirstChild("Minigames")
    module = module and module:FindFirstChild("MiningController")
    if not module then
        return nil
    end
    local ok, result = Env.call(require, module)
    return ok and type(result) == "table" and result or nil
end

local function mineState()
    local mining = controller()
    if not mining or type(mining.GetState) ~= "function" then
        return nil
    end
    local ok, state = Env.call(mining.GetState, mining)
    return ok and type(state) == "table" and state or nil
end

local function inMine()
    return Env.LocalPlayer:GetAttribute("MiningActive") == true
end

local function teleport(cframe)
    local hrp = root()
    if hrp then
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.CFrame = cframe
    end
end

-- The game's own "tap a block" handler, once the mine's code has loaded.
local tapHandler
local function findTapHandler()
    if tapHandler or type(getconnections) ~= "function" then
        return tapHandler
    end
    local ok, connections = pcall(getconnections, UserInputService.TouchTapInWorld)
    for _, connection in ipairs(ok and type(connections) == "table" and connections or {}) do
        local fine, source = pcall(function()
            return connection.Function and debug.info(connection.Function, "s")
        end)
        if fine and type(source) == "string" and source:find("MiningController") then
            tapHandler = connection.Function
        end
    end
    Env.elevate()
    return tapHandler
end

local function enter()
    if inMine() then
        return true
    end
    Env.streamAround(CRYSTAL_CAVE, 10)
    teleport(CFrame.new(CRYSTAL_CAVE))
    local portal
    local deadline = os.clock() + 10
    repeat
        Life.wait(0.3)
        portal = MiningWorld and MiningWorld.Portal()
    until portal or not Life.alive or os.clock() > deadline
    if not portal then
        session.note = "Could not find the mine portal on Crystal Cave."
        return false
    end
    teleport(portal.CFrame)
    deadline = os.clock() + 20
    repeat
        Life.wait(0.3)
    until inMine() or not Life.alive or os.clock() > deadline
    Life.wait(1.5) -- the game's fade and the first blocks being drawn
    return inMine()
end

local function onPad(name, until_, seconds)
    local pad = MiningWorld and MiningWorld.Part(name)
    if not pad then
        return false
    end
    teleport(pad.CFrame + Vector3.new(0, 4, 0))
    local deadline = os.clock() + (seconds or 6)
    repeat
        Life.wait(0.3)
    until not until_ or until_() or not Life.alive or os.clock() > deadline
    return true
end

local function ask(name, ...)
    local ok, result = Env.invoke("MiningService", name, ...)
    if ok and type(result) == "table" and not result.Error then
        return result
    end
    return nil, tostring(ok and type(result) == "table" and result.Error or result)
end

-- The next pickaxe or bag above what you use, if you can pay for it now.
local function nextUpgrade(state)
    if not MiningConfig then
        return nil
    end
    local balance = tonumber(state.Balance) or 0
    local best
    for _, kind in ipairs({ "Tool", "Bag" }) do
        local list = kind == "Tool" and MiningConfig.Tools or MiningConfig.Bags
        local current = tonumber(kind == "Tool" and state.Tool or state.Backpack) or 1
        local item = list[current + 1]
        if item and (not best or item.Price < best.price) then
            best = { kind = kind, name = item.Name, price = item.Price, affordable = item.Price <= balance }
        end
    end
    return best
end

-- The dearest daily-shop pack of the chosen kind you can pay for, or nil.
local dailySkip = {} -- id -> day it sold out for you
local function nextDaily(state)
    local pick = Options.MineDaily.Value
    if not DailyShop or pick == DAILY_OFF then
        return nil
    end
    local day = DailyShop.Day(os.time())
    local offers = {}
    local ok, rotating = Env.call(DailyShop.Rotating, day)
    for _, offer in ipairs(ok and type(rotating) == "table" and rotating or {}) do
        offers[#offers + 1] = offer
    end
    for _, offer in ipairs(DailyShop.PermanentOffers()) do
        offers[#offers + 1] = offer
    end
    local balance = tonumber(state.Balance) or 0
    local best
    for _, offer in ipairs(offers) do
        local kindOk = (offer.Kind == "Clicks" and pick ~= DAILY_GEMS) or (offer.Kind == "Gems" and pick ~= DAILY_COINS)
        if kindOk and dailySkip[offer.Id] ~= day and (tonumber(offer.Price) or math.huge) <= balance
            and (not best or offer.Price > best.Price) then
            best = offer
        end
    end
    return best, day
end

local function spend()
    local state = mineState()
    if not state then
        return
    end
    if Ui.on("MineUpgrades") then
        local upgrade = nextUpgrade(state)
        while upgrade and upgrade.affordable and Life.alive do
            onPad("Shop")
            local result, why = ask("Purchase", upgrade.kind == "Tool" and "BuyTool" or "BuyStorage", upgrade.name)
            if not result then
                session.note = string.format("Could not buy the %s: %s.", upgrade.name, why)
                return
            end
            session.bought[#session.bought + 1] = upgrade.name
            session.note = "Bought the " .. upgrade.name .. "."
            Life.wait(0.6)
            state = mineState() or state
            upgrade = nextUpgrade(state)
        end
        if upgrade then
            return -- saving for the next upgrade before anything else
        end
    end
    local offer, day = nextDaily(state)
    while offer and Life.alive do
        onPad("Daily")
        local result, why = ask("DailyBuy", offer.Id)
        if not result then
            dailySkip[offer.Id] = day
            session.note = string.format("Daily shop: %s (%s).", offer.Name, why)
        else
            session.bought[#session.bought + 1] = offer.Name
            session.note = "Daily shop: bought a " .. offer.Name .. "."
        end
        Life.wait(0.6)
        state = mineState() or state
        offer, day = nextDaily(state)
    end
end

local function sellAndSpend()
    local before = mineState()
    local balance = before and tonumber(before.Balance) or 0
    onPad("Sell", function()
        local state = mineState()
        return state and (tonumber(state.Count) or 0) == 0
    end, 8)
    local after = mineState()
    if after and (tonumber(after.Count) or 0) == 0 then
        session.sold += 1
        session.earned += math.max(0, (tonumber(after.Balance) or 0) - balance)
    end
    spend()
end

-- Mining ---------------------------------------------------------------------------------------

local skipped = {} -- key -> skip until (os.clock)

-- Ores at least this valuable are taken before plain rock wherever they are uncovered: Copper (20)
-- and up. Dirt is worth 1, Stone 3, Coal 10; gems 250-650 (BlockStats).
local ORE_VALUE = 20

-- The block to mine: one the game has drawn (drawn blocks are the exposed ones near you) that your
-- pickaxe can break and that has open space above it. The most valuable uncovered ore first, then
-- plain rock top layers first (the mine is Dirt for 3 layers, Stone down to 20, Hardened Stone
-- below), then the nearest.
local function chooseTarget(state, marker)
    local folder = workspace:FindFirstChild("LocalMiningBlocks")
    if not folder or not MiningConfig then
        return nil
    end
    local tool = MiningConfig.Tools[tonumber(state.Tool) or 1]
    local power = tool and tool.Power or 1
    local drawn = {}
    for _, block in ipairs(folder:GetChildren()) do
        if block.Name:match("^%d+:%d+:%d+$") then
            drawn[block.Name] = block
        end
    end
    local hrp = root()
    local here = hrp and hrp.Position or marker.Position
    local now = os.clock()
    local best
    local function better(candidate)
        if not best then
            return true
        end
        local oreA, oreB = candidate.value >= ORE_VALUE, best.value >= ORE_VALUE
        if oreA ~= oreB then
            return oreA
        end
        if oreA and candidate.value ~= best.value then
            return candidate.value > best.value
        end
        if not oreA and candidate.y ~= best.y then
            return candidate.y < best.y
        end
        return candidate.distance < best.distance
    end
    for key, block in pairs(drawn) do
        if (skipped[key] or 0) <= now then
            local x, y, z = key:match("^(%d+):(%d+):(%d+)$")
            x, y, z = tonumber(x), tonumber(y), tonumber(z)
            local above = y > 0 and MiningConfig.Key(x, y - 1, z) or nil
            if not (above and drawn[above]) then
                local ok, _, stats = pcall(MiningConfig.Ore, state.Seed, x, y, z)
                if ok and stats and (tonumber(stats.pickaxeRequirement) or 0) <= power then
                    local position = MiningConfig.Position(marker, x, y, z)
                    local candidate = { key = key, x = x, y = y, z = z, position = position, block = block,
                        health = tonumber(stats.health) or 10, value = tonumber(stats.value) or 0,
                        distance = (position - here).Magnitude }
                    if better(candidate) then
                        best = candidate
                    end
                end
            end
        end
    end
    return best, tool
end

local function stillThere(target)
    return target.block.Parent ~= nil and target.block.Name == target.key
end

-- One swing at the target through the game's own input, or the remote when that is out of reach.
local function swing(state, target)
    local handler = findTapHandler()
    if handler then
        local camera = workspace.CurrentCamera
        local hrp = root()
        if not (camera and hrp) then
            return
        end
        local saved = camera.CFrame
        camera.CFrame = CFrame.lookAt(hrp.Position + Vector3.new(0, 1.5, 0), target.position)
        local center = camera.ViewportSize / 2
        pcall(handler, Vector2.new(center.X, center.Y), false)
        camera.CFrame = saved
        Env.elevate()
    else
        Env.invoke("MiningService", "Hit", state.Id, target.x, target.y, target.z)
    end
end

local function mineOne(state, marker)
    local target, tool = chooseTarget(state, marker)
    if not target then
        return false
    end
    local stand = target.position + Vector3.new(0, MiningConfig.BlockSize + 1, 0)
    local hrp = root()
    if hrp and (hrp.Position - stand).Magnitude > 3 then
        teleport(CFrame.new(stand))
        Life.wait(0.2)
    end
    local damage = tool and tool.Damage or 1
    local interval = tool and tool.Interval or 0.45
    local swings = math.ceil(target.health / math.max(damage, 1)) + 4
    for _ = 1, swings do
        if not (Life.alive and Ui.on("AutoMine") and stillThere(target)) then
            break
        end
        local current = mineState()
        if current and (tonumber(current.Count) or 0) >= (tonumber(current.Capacity) or math.huge) then
            return true -- the bag filled up mid-block
        end
        swing(state, target)
        Life.wait(interval + 0.03)
    end
    if stillThere(target) then
        skipped[target.key] = os.clock() + SKIP_SECONDS
    end
    return true
end

local busy = false
local function run()
    busy = true
    Ui.travelling = "mining"
    local settle = os.clock() + 6
    while Ui.hatchInFlight and os.clock() < settle do
        Life.wait(0.05)
    end
    local hrp = root()
    local home = hrp and hrp.CFrame
    local ok, err = pcall(function()
        Ui.status = "Mining"
        if not enter() then
            session.note = session.note ~= "" and session.note or "Could not get into the mine."
            return
        end
        local idle = 0
        while Life.alive and Ui.on("AutoMine") do
            if not inMine() and not enter() then
                break
            end
            local state = mineState()
            local marker = MiningWorld and MiningWorld.Marker()
            if not (state and marker and state.Seed) then
                Life.wait(0.5)
            elseif (tonumber(state.Count) or 0) >= (tonumber(state.Capacity) or math.huge) then
                sellAndSpend()
            elseif not mineOne(state, marker) then
                -- nothing drawn to mine right here: let the pets work and look again
                idle += 1
                Life.wait(1)
                if idle % 10 == 0 then
                    table.clear(skipped)
                end
            else
                idle = 0
            end
        end
        if inMine() then
            if (tonumber((mineState() or {}).Count) or 0) > 0 then
                sellAndSpend()
            end
            onPad("Exit", function()
                return not inMine()
            end, 12)
        end
    end)
    Env.elevate()
    if not ok then
        Life.errors["mining:run"] = tostring(err)
        session.note = "Mining error: " .. tostring(err)
    end
    Life.wait(1)
    if home then
        teleport(home)
    end
    if Ui.status == "Mining" then
        Ui.status = "Idle"
    end
    Ui.travelling = false
    busy = false
end

local function short(n)
    for _, unit in ipairs({ { 1e6, "M" }, { 1e3, "K" } }) do
        if n >= unit[1] then
            return string.format("%.1f%s", n / unit[1], unit[2])
        end
    end
    return tostring(math.floor(n))
end

Life.loop("mining:auto", 1, function()
    local data = Env.data()
    local mining = data and type(data.Mining) == "table" and data.Mining or {}
    local state = inMine() and mineState() or nil
    local lines = {}
    local tools = MiningConfig and MiningConfig.Tools or {}
    local bags = MiningConfig and MiningConfig.Bags or {}
    local tool = tools[tonumber(mining.Tool) or 1]
    local bag = bags[tonumber(mining.Backpack) or 1]
    lines[1] = string.format("%s, %s. %s mining coins.", tool and tool.Name or "?", bag and bag.Name or "?",
        short(tonumber(mining.Coins) or 0))
    if state then
        local total = tonumber(state.Total) or 10000
        local mined = tonumber(state.Mined) or 0
        lines[#lines + 1] = string.format("Mine %.1f%% cleared (%d / %d), bag %d/%d.", mined / total * 100, mined, total,
            tonumber(state.Count) or 0, tonumber(state.Capacity) or 0)
    end
    if session.sold > 0 then
        lines[#lines + 1] = string.format("%d sales this session for %s mining coins.", session.sold, short(session.earned))
    end
    if session.note ~= "" then
        lines[#lines + 1] = session.note
    end
    if not Ui.on("AutoMine") then
        label:SetText("Off. " .. table.concat(lines, "\n"))
        return
    end
    label:SetText(table.concat(lines, "\n"))
    if not busy and not Ui.travelling and not Ui.hatchMoving and MiningWorld and MiningConfig then
        Life.spawn("mining:run", run)
    end
end)

Life.onCleanup(function()
    if busy then
        Ui.travelling = false
    end
end)

return {}
end
__modules["features/performance"] = function(use) -- src/games/tapsim/features/performance.luau
-- Home tab, Performance: the shared performance mode (see shared/performance) plus Tap Simulator's
-- own quality settings, which is where this game spends its frames: the hatch reveal that plays for
-- every auto hatch, pets following everyone, tap pop-ups and screen shake.
--
-- The game keeps those settings on the server (SettingsService.UpdateSetting { Name, Value },
-- definitions in Shared.Core.SettingsConfig), so the game itself skips the work instead of the hub
-- fighting it. Your own values are read before anything changes and put back when performance mode
-- goes off or the hub unloads.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local group = use("shared/performance").build(Ui.Tabs.Home)

local KEEP = "Keep my setting"
local PET_VALUES = { [KEEP] = nil, ["Hide other players' pets"] = 2, ["Hide all pets"] = 3 }

-- What performance mode sets, besides the pets choice below.
local GAME_SETTINGS = {
    PerformanceMode = 3, -- "Potato"
    HatchAnimation = 1, -- keep the reveal available for Hold to Reveal in this test
    HideClicks = true,
    HideFlashes = true,
    ScreenShake = false,
    BlobShadows = false,
    HideTitles = true,
}

group:AddToggle("PerfGameSettings", {
    Text = "Use the game's lowest settings",
    Default = true,
    Tooltip = "While performance mode is on: Potato graphics, rare hatch reveal off, tap pop-ups, flashes, screen shake, blob shadows and titles hidden. Your settings come back afterwards.",
})
group:AddToggle("PerfHideHatching", {
    Text = "Hide hatching and crafting",
    Default = true,
    Tooltip = getconnections and "While performance mode is on, eggs you hatch and pets you craft no longer play their animation (the game has no setting for this). Hatching and crafting still happen."
        or "Your executor has no getconnections, so hatching cannot be hidden.",
})
group:AddDropdown("PerfHidePets", {
    Text = "Pets",
    Values = { KEEP, "Hide other players' pets", "Hide all pets" },
    Default = "Hide other players' pets",
    Tooltip = "Pets following players are a large share of what gets drawn and moved each frame.",
})

-- setting name -> the value it had before performance mode changed it. The game keeps settings on
-- the server, so if a session ends without switching performance mode off (a crash, a rejoin) the
-- next one would read "Potato" as your setting. The originals are kept on disk until put back.
local saved = {}
local FOLDER = "SlopixHub/TapSimulator"
local FILE = FOLDER .. "/game-settings.json"
local files = Env.files

local function persist()
    if not (files.writefile and files.isfolder and files.makefolder) then
        return
    end
    pcall(function()
        local path = ""
        for part in FOLDER:gmatch("[^/]+") do
            path = path == "" and part or path .. "/" .. part
            if not files.isfolder(path) then
                files.makefolder(path)
            end
        end
        files.writefile(FILE, Env.HttpService:JSONEncode(saved))
    end)
    Env.elevate()
end

do
    local ok, stored = pcall(function()
        return files.isfile and files.isfile(FILE) and Env.HttpService:JSONDecode(files.readfile(FILE))
    end)
    Env.elevate()
    if ok and type(stored) == "table" then
        for name, value in pairs(stored) do
            if type(name) == "string" and (type(value) == "number" or type(value) == "boolean") then
                saved[name] = value
            end
        end
    end
end

local SettingsConfig
do
    local ok, module = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Core.SettingsConfig)
    end)
    SettingsConfig = ok and type(module) == "table" and module or nil
end
local UserInputService = game:GetService("UserInputService")

-- The value the game is using. A setting you never changed is not stored at all, so its value is
-- the game's default (which differs on PC for some), read the same way the game reads it.
local function current(name)
    local data = Env.data()
    local settings = data and type(data.Settings) == "table" and data.Settings or nil
    if settings and settings[name] ~= nil then
        return settings[name]
    end
    if SettingsConfig then
        local pc = UserInputService.KeyboardEnabled and not UserInputService.TouchEnabled
        local ok, value = Env.call(SettingsConfig.Read, settings, name, pc)
        if ok then
            return value
        end
    end
    return nil
end

-- Several changes in a row get refused now and then (a restore once silently left one behind), so
-- each write is spaced out and retried. task.wait, not Life.wait: this also runs while unloading.
local function write(name, value)
    for attempt = 1, 4 do
        local ok, result = Env.invoke("SettingsService", "UpdateSetting", { Name = name, Value = value })
        if ok and (type(result) ~= "table" or result.Success ~= false) then
            task.wait(0.15)
            return true
        end
        task.wait(0.4 * attempt)
    end
    return false
end

local function wanted()
    local list = {}
    if Ui.on("PerfGameSettings") then
        for name, value in pairs(GAME_SETTINGS) do
            list[name] = value
        end
    end
    local pets = PET_VALUES[Ui.Options.PerfHidePets.Value]
    if pets then
        list.HidePets = pets
    end
    return list
end

local function restore()
    for name, value in pairs(saved) do
        write(name, value)
    end
    table.clear(saved)
    persist()
end

-- Brings the game's settings in line with the toggles: changes what performance mode wants (saving
-- the old value the first time) and puts back anything it no longer wants.
local function apply()
    if not Ui.on("PerfMode") then
        restore()
        return
    end
    local want = wanted()
    local changed = false
    for name, value in pairs(want) do
        local now = current(name)
        if now ~= value then
            if saved[name] == nil and now ~= nil then
                saved[name] = now
                changed = true
            end
            write(name, value)
        end
    end
    for name, value in pairs(saved) do
        if want[name] == nil then
            write(name, value)
            saved[name] = nil
            changed = true
        end
    end
    if changed then
        persist()
    end
end

local pending = false
local function schedule()
    if pending then
        return
    end
    pending = true
    Life.spawn("performance:game-settings", function()
        apply()
        pending = false
    end)
end

-- Hatching and crafting on screen ---------------------------------------------------------------
--
-- The game's Hatch Animation setting only chooses which rarities get the slow reveal: every hatch
-- still plays its egg and pet card (HatchRenderer), and every craft its machine roll. The only way
-- to keep them off the screen is to stop the game's own handlers for those results. Their
-- connections are disabled while this is on and enabled again afterwards. Only functions from the
-- game's ReplicatedStorage scripts are touched, so the hub's own result handlers keep working.

local VISUAL_EVENTS = {
    { "EggService", "EggHatchResult" },
    { "EggService", "ForcedHatchResult" },
    { "EggService", "SecretSkyFireworks" },
    { "EggService", "SecretEggFlash" },
    { "EggService", "SecretCelebration" },
    { "EggService", "ExclusiveEggHatchObserved" },
    { "MachineService", "MachineCraftResult" },
}
local muted = {} -- connection -> true

local function findRemote(service, name)
    local services = Env.ReplicatedStorage:FindFirstChild("RemoteServices")
    local folder = services and services:FindFirstChild(service)
    local events = folder and folder:FindFirstChild("RE")
    return events and events:FindFirstChild(name)
end

local function fromGame(connection)
    local ok, source = pcall(function()
        local fn = connection.Function
        return fn and debug.info(fn, "s")
    end)
    return ok and type(source) == "string" and source:find("^ReplicatedStorage%.") ~= nil
end

local function muteVisuals()
    for _, pair in ipairs(VISUAL_EVENTS) do
        local remote = findRemote(pair[1], pair[2])
        local ok, connections = false, nil
        if remote then
            ok, connections = pcall(getconnections, remote.OnClientEvent)
        end
        for _, connection in ipairs(ok and type(connections) == "table" and connections or {}) do
            if not muted[connection] and fromGame(connection) and pcall(function()
                connection:Disable()
            end) then
                muted[connection] = true
            end
        end
    end
    Env.elevate()
end

local function unmuteVisuals()
    for connection in pairs(muted) do
        pcall(function()
            connection:Enable()
        end)
    end
    table.clear(muted)
    Env.elevate()
end

local function refreshVisuals()
    if type(getconnections) == "function" and Ui.on("PerfMode") and Ui.on("PerfHideHatching") then
        muteVisuals()
    elseif next(muted) ~= nil then
        unmuteVisuals()
    end
end

-- The library keeps one Changed handler per control; shared/performance already owns PerfMode's.
local sharedHandler = Ui.Toggles.PerfMode.Changed
Ui.Toggles.PerfMode:OnChanged(function(...)
    if type(sharedHandler) == "function" then
        sharedHandler(...)
    end
    schedule()
    refreshVisuals()
end)
Ui.Toggles.PerfGameSettings:OnChanged(schedule)
Ui.Options.PerfHidePets:OnChanged(schedule)
Ui.Toggles.PerfHideHatching:OnChanged(refreshVisuals)
-- A handler the game connects later (after a respawn, a menu opening) is caught on the next pass.
Life.loop("performance:visuals", 3, refreshVisuals)
Life.onCleanup(unmuteVisuals)

-- A previous session that never put your settings back: do it now, unless the saved config is
-- about to switch performance mode on (that keeps them, and puts them back when it goes off).
Life.spawn("performance:repair", function()
    Life.wait(3) -- after the config autoload has had its say
    if next(saved) ~= nil and not Ui.on("PerfMode") then
        restore()
    end
end)

Life.onCleanup(restore)

return {}
end
__modules["features/pets"] = function(use) -- src/games/tapsim/features/pets.luau
-- Pets tab (right): keep your strongest pets equipped. The game ranks and swaps them for you with
-- PetActionRequested { Action = "EquipBest", Mode = "Clicks"|"Luck"|"Gems" }, so firing it as new pets
-- hatch means the team is kept full. Без поля Mode сервер запрос молча глотает, и команда стоит пустой.
-- always your highest-power four without opening the inventory.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local tab = Ui.Tabs.Pets
local box = tab:AddGroupbox({ Side = "Right", Name = "Auto equip", IconName = "star" })

-- Рабочий зов — с полем Mode. Без Mode сервер запрос молча глотает, и команда не набирается
-- (сверено с открытым TapFarm: PetActionRequested:Fire({Action="EquipBest", Mode=…})).
-- Режимы игры: Luck (удача при открытии яиц), Clicks (клики), Gems (гемы).
local EQUIP_MODES = { "Luck", "Clicks", "Gems" }
local EQUIP_MODE = "Clicks" -- безопасное значение по умолчанию; после lock выбирается Luck

local function equipModeNow()
    local options = Ui and Ui.Options or nil
    local option = options and options.EquipMode or nil
    local value = option and option.Value or nil
    if type(value) == "string" and value ~= "" then
        return value
    end
    return EQUIP_MODE
end

local function equipAllowed(mode)
    if not Life.alive or (Env.genv and Env.genv.__handoverPaused) then return false end
    local P = Ui.__progressTest
    if P then
        if P.equipReady ~= true or P.stopRequested or P.cleaning or P.craftBusy or P.craftInFlight then return false end
        local expected = (P.eggFixed or P.rebirthLocked) and "Luck" or "Clicks"
        if mode ~= expected or equipModeNow() ~= expected then return false end
    end
    return true
end
local function equipBest(mode)
    if not equipAllowed(mode or equipModeNow()) then return end
    local ok, remote = pcall(Env.remote, "PetService", "PetActionRequested")
    -- Lookup may yield while the saved phase, selected mode, Stop, or team work changes.
    local requestedMode = mode or equipModeNow()
    if not ok or not remote or not equipAllowed(requestedMode) then return end
    Env.elevate()
    if not equipAllowed(requestedMode) then return end
    remote:FireServer({ Action = "EquipBest", Mode = requestedMode })
    if Ui.__progressTest then
        Ui.__progressTest.lastEquipMode = requestedMode
        Ui.__progressTest.lastEquipAt = os.clock()
    end
end

box:AddToggle("AutoEquipBest", {
    Text = "Auto equip best pets",
    Default = false,
    Tooltip = "Keeps your highest-power pets equipped. Re-checks as you hatch so new strong pets go on automatically.",
})
Ui.automation("AutoEquipBest", true)
box:AddDropdown("EquipMode", {
    Text = "Equip best for",
    Values = { "Luck", "Clicks", "Gems" },
    Default = "Clicks",
    Tooltip = "How the game picks the team. 'Luck' takes pets that boost egg luck, 'Clicks' takes tap power, 'Gems' takes gem income. The mode goes into the request itself — without it the server ignores Equip Best.",
})
box:AddSlider("EquipEvery", {
    Text = "Re-equip every",
    Default = 5,
    Min = 2,
    Max = 30,
    Rounding = 0,
    Suffix = "s",
})
box:AddButton({
    Text = "Equip best now",
    Func = function()
        equipBest()
        Ui.notify("Tap Simulator", "Equipped your strongest pets.", 3)
    end,
})
local label = box:AddLabel("Auto equip is off.", true)

-- A compact read of what is on the team, so the label reflects the swap.
local function teamSummary()
    local data = Env.data()
    local pets = data and type(data.Pets) == "table" and data.Pets
    if not pets or type(pets.Owned) ~= "table" or type(pets.Equipped) ~= "table" then
        return nil
    end
    local names, best = {}, 0
    for _, petId in pairs(pets.Equipped) do
        local pet = pets.Owned[petId]
        if type(pet) == "table" then
            names[#names + 1] = string.format("%s (%s)", tostring(pet.Name), tostring(pet.Power or "?"))
            best = math.max(best, tonumber(pet.Power) or 0)
        end
    end
    return names, best
end

local lastEquip = 0
Life.loop("pets:equip", 1, function()
    if not Ui.on("AutoEquipBest") then
        return
    end
    local every = math.clamp(tonumber(Ui.Options.EquipEvery.Value) or 5, 2, 30)
    if os.clock() - lastEquip >= every then
        lastEquip = os.clock()
        equipBest()
        Ui.status = "Equipping best pets"
    end
    local names = teamSummary()
    if names then
        label:SetText("Equipped: " .. (table.concat(names, ", ")):sub(1, 140))
    end
end)

return {}
end
__modules["features/pickups"] = function(use) -- src/games/tapsim/features/pickups.luau
-- Rewards tab: the things that show up on screen to be clicked. The Lucky Ducky flying across the
-- screen, and the Balloon Party and "Pigs could fly" world events.
--
-- Lucky Ducky (LuckyDuckyService): once you have an hour of playtime, the server sends Spawn { Id,
-- Lifetime, Why } every 20-30 minutes and the duck crosses the screen for ~10 seconds. Claim(Id)
-- rolls x2 coins for 2 min (60%), a pile of coins (27%), x3 coins for 2 min (10%) or 1 in 4
-- hatches Golden for 1 min (3%). The server refuses a claim sooner than 0.3s after the spawn, so
-- the catch waits a human moment, then goes through the game's own LuckyDuckyController:CatchShown
-- (its animation, claim and reward banner); Claim(Id) is sent directly only if no duck was drawn.
--
-- Balloon Party (BalloonPartyService), every 45 minutes for 2 minutes: balloons launch around each
-- player (Launched { Uid, Origin, Rise, Phase, LaunchedAt, Size }) and rise on a path anyone can
-- compute (Shared.Admin.BalloonFlight). Hit(Uid) counts a tap from up to HitRange (150) studs, once
-- per HitCooldown per balloon; Size sets how many taps it takes. The server confirms each tap on
-- Hit (Uid, Taken, UserId), and Popped / Rewarded follow.
--
-- Pigs could fly (PigsCouldFlyService): pigs circle each player on PigFlight paths; one Hit(Uid)
-- from within 120 studs catches one, Caught (Uid, UserId) and Rewarded follow, Retired ends one.
--
-- Both events spawn around you, so nothing here moves the character: it taps what is in range.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local RunService = game:GetService("RunService")
local tab = Ui.Tabs.World
local RS = Env.ReplicatedStorage

local function load(...)
    local path = { ... }
    local ok, module = Env.call(function()
        local node = RS
        for _, part in ipairs(path) do
            node = node:FindFirstChild(part)
        end
        return node and require(node)
    end)
    return ok and type(module) == "table" and module or nil
end

local DuckController = load("Controllers", "Game", "LuckyDuckyController")
local WorldEventConfig = load("Shared", "Admin", "WorldEventConfig")
local BalloonFlight = load("Shared", "Admin", "BalloonFlight")
local PigFlight = load("Shared", "Admin", "PigFlight")
local BalloonRules = WorldEventConfig and WorldEventConfig.Balloon or {}
local PigRules = WorldEventConfig and WorldEventConfig.Pig or {}

-- Inside the game's own ranges, so a tap is never judged out of reach on the server's clock.
local BALLOON_RANGE = (tonumber(BalloonRules.HitRange) or 150) - 15
local BALLOON_GAP = (tonumber(BalloonRules.HitCooldown) or 0.1) + 0.06
local PIG_RANGE = (tonumber(PigRules.HitRange) or 120) - 15
local PIG_GAP = 0.6
local TAP_GAP = 0.09 -- between any two taps, about as fast as a quick thumb

local box = tab:AddGroupbox({ Side = "Left", Name = "Pickups", IconName = "sparkles" })
box:AddToggle("AutoDuck", {
    Text = "Catch the Lucky Ducky",
    Default = true,
    Tooltip = "Catches the duck that flies across your screen every 20-30 minutes (after an hour of playtime): x2 or x3 coins for 2 minutes, a pile of coins, or Golden hatches for a minute.",
})
Ui.automation("AutoDuck", true)
box:AddToggle("AutoBalloons", {
    Text = "Pop Balloon Party balloons",
    Default = true,
    Tooltip = "During the Balloon Party event (every 45 minutes, 2 minutes long), taps every balloon within reach until it pops. Balloons give coins and gems.",
})
Ui.automation("AutoBalloons", true)
box:AddToggle("AutoPigs", {
    Text = "Catch flying pigs",
    Default = true,
    Tooltip = "During the \"Pigs could fly\" event, catches every pig within reach for coins and gems.",
})
Ui.automation("AutoPigs", true)
local label = box:AddLabel("Waiting for a duck, balloons or pigs.", true)

local session = { ducks = 0, duckNote = nil, balloons = 0, pigs = 0, coins = 0, gems = 0 }

local function root()
    local character = Env.LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

local function short(n)
    for _, unit in ipairs({ { 1e18, "Qi" }, { 1e15, "Q" }, { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" } }) do
        if n >= unit[1] then
            return string.format("%.1f%s", n / unit[1], unit[2])
        end
    end
    return tostring(math.floor(n))
end

local function addReward(reward)
    if type(reward) ~= "table" then
        return
    end
    session.coins += tonumber(reward.Coins) or 0
    session.gems += tonumber(reward.Gems) or 0
end

-- Lucky Ducky ----------------------------------------------------------------------------------

local function catchDuck(payload)
    Life.wait(0.7 + math.random() * 0.8)
    if not Ui.on("AutoDuck") then
        return
    end
    local caught = false
    if DuckController and type(DuckController.CatchShown) == "function" then
        local ok, result = Env.call(DuckController.CatchShown, DuckController)
        caught = ok and result == true
    end
    if caught then
        session.ducks += 1
        session.duckNote = "caught"
        return
    end
    local ok, result = Env.invoke("LuckyDuckyService", "Claim", payload.Id)
    if ok and type(result) == "table" and result.Success == true then
        session.ducks += 1
        session.duckNote = tostring(result.Title or result.Reward or "caught")
        if type(result.Coins) == "number" then
            session.coins += result.Coins
        end
    else
        session.duckNote = "got away: " .. tostring(type(result) == "table" and result.Reason or result)
    end
end

Life.spawn("pickups:duck", function()
    local remote = Env.remote("LuckyDuckyService", "Spawn")
    Life.connect(remote.OnClientEvent, function(payload)
        if Ui.on("AutoDuck") and type(payload) == "table" and payload.Id ~= nil then
            Life.spawn("pickups:duck-catch", catchDuck, payload)
        end
    end)
end)

-- Balloons and pigs ----------------------------------------------------------------------------

local balloons = {} -- uid -> { flight, needed, taken, last }
local pigs = {} -- uid -> { flight, last }
-- uids this hub tapped: Rewarded is only counted for those, whoever else it may reach.
local tappedByMe = {}

local function trackBalloon(flight)
    if type(flight) ~= "table" or type(flight.Uid) ~= "string" or balloons[flight.Uid] then
        return
    end
    if typeof(flight.Origin) ~= "Vector3" or type(flight.Rise) ~= "number" or type(flight.LaunchedAt) ~= "number" then
        return
    end
    local size = type(BalloonRules.Sizes) == "table" and BalloonRules.Sizes[flight.Size]
    balloons[flight.Uid] = {
        flight = flight,
        needed = size and tonumber(size.Hits) or 1,
        taken = 0,
        last = 0,
    }
end

local function trackPig(flight)
    if type(flight) ~= "table" or type(flight.Uid) ~= "string" or pigs[flight.Uid] then
        return
    end
    if typeof(flight.Centre) ~= "Vector3" or typeof(flight.Pass) ~= "Vector3" or type(flight.LaunchedAt) ~= "number" then
        return
    end
    pigs[flight.Uid] = { flight = flight, last = 0 }
end

Life.spawn("pickups:balloon-events", function()
    Life.connect(Env.remote("BalloonPartyService", "Launched").OnClientEvent, trackBalloon)
    Life.connect(Env.remote("BalloonPartyService", "Hit").OnClientEvent, function(uid, taken)
        local balloon = type(uid) == "string" and balloons[uid]
        if balloon and type(taken) == "number" then
            balloon.taken = math.max(balloon.taken, taken)
        end
    end)
    Life.connect(Env.remote("BalloonPartyService", "Popped").OnClientEvent, function(uid)
        if type(uid) == "string" then
            balloons[uid] = nil
        end
    end)
    Life.connect(Env.remote("BalloonPartyService", "Rewarded").OnClientEvent, function(uid, reward)
        if tappedByMe[uid] then
            tappedByMe[uid] = nil
            session.balloons += 1
            addReward(reward)
        end
    end)
    -- A party already running when the hub loads.
    local ok, active = Env.invoke("BalloonPartyService", "GetActive")
    for _, flight in ipairs(ok and type(active) == "table" and active or {}) do
        trackBalloon(flight)
    end
end)

Life.spawn("pickups:pig-events", function()
    Life.connect(Env.remote("PigsCouldFlyService", "Launched").OnClientEvent, trackPig)
    local function gone(uid)
        if type(uid) == "string" then
            pigs[uid] = nil
        end
    end
    Life.connect(Env.remote("PigsCouldFlyService", "Caught").OnClientEvent, gone)
    Life.connect(Env.remote("PigsCouldFlyService", "Retired").OnClientEvent, gone)
    Life.connect(Env.remote("PigsCouldFlyService", "Rewarded").OnClientEvent, function(uid, reward)
        if tappedByMe[uid] then
            tappedByMe[uid] = nil
            session.pigs += 1
            addReward(reward)
        end
    end)
    local ok, active = Env.invoke("PigsCouldFlyService", "GetActive")
    for _, flight in ipairs(ok and type(active) == "table" and active or {}) do
        trackPig(flight)
    end
end)

-- Where a balloon is now, or nil once it has flown off.
local function balloonAt(balloon, now)
    local age = now - balloon.flight.LaunchedAt
    if not BalloonFlight or age >= (BalloonFlight.Lifetime or 25) then
        return nil
    end
    local ok, position = pcall(BalloonFlight.Position, balloon.flight, age)
    return ok and typeof(position) == "Vector3" and position or nil
end

local function pigAt(pig, now)
    local age = now - pig.flight.LaunchedAt
    if not PigFlight or age >= (PigFlight.Lifetime or 40) then
        return nil
    end
    local ok, position = pcall(PigFlight.Position, pig.flight, age)
    return ok and typeof(position) == "Vector3" and position or nil
end

-- The next tap: a pig first (one tap catches it), then the balloon closest to popping, so a
-- tap is never spread thin across a sky full of half-hit balloons.
local function nextTap(here, now, clock)
    if Ui.on("AutoPigs") then
        for uid, pig in pairs(pigs) do
            local at = pigAt(pig, now)
            if not at then
                pigs[uid] = nil
            elseif clock - pig.last >= PIG_GAP and (at - here).Magnitude <= PIG_RANGE then
                return "PigsCouldFlyService", uid, pig
            end
        end
    end
    if Ui.on("AutoBalloons") then
        local best, bestUid, bestLeft
        for uid, balloon in pairs(balloons) do
            local at = balloonAt(balloon, now)
            if not at then
                balloons[uid] = nil
            elseif clock - balloon.last >= BALLOON_GAP and (at - here).Magnitude <= BALLOON_RANGE then
                local left = balloon.needed - balloon.taken
                if left > 0 and (not best or left < bestLeft) then
                    best, bestUid, bestLeft = balloon, uid, left
                end
            end
        end
        if best then
            return "BalloonPartyService", bestUid, best
        end
    end
    return nil
end

Life.spawn("pickups:tap", function()
    while Life.alive do
        local hrp = root()
        local tapped = false
        if hrp and (next(balloons) or next(pigs)) then
            local clock = os.clock()
            local service, uid, target = nextTap(hrp.Position, workspace:GetServerTimeNow(), clock)
            if service then
                target.last = clock
                tappedByMe[uid] = true
                Env.fire(service, "Hit", uid)
                tapped = true
            end
        end
        if tapped then
            Life.wait(TAP_GAP)
        else
            Life.wait(0.15)
        end
    end
end)

Life.loop("pickups:panel", 1, function()
    local live = 0
    for _ in pairs(balloons) do
        live += 1
    end
    local pigsLive = 0
    for _ in pairs(pigs) do
        pigsLive += 1
    end
    local lines = {
        string.format("Ducks caught: %d%s", session.ducks, session.duckNote and (" (last " .. session.duckNote .. ")") or ""),
        string.format("Balloons popped: %d, pigs caught: %d", session.balloons, session.pigs),
    }
    if session.coins > 0 or session.gems > 0 then
        lines[#lines + 1] = string.format("From them: %s coins, %s gems", short(session.coins), short(session.gems))
    end
    if live > 0 or pigsLive > 0 then
        lines[#lines + 1] = string.format("In the sky now: %d balloons, %d pigs", live, pigsLive)
    end
    label:SetText(table.concat(lines, "\n"))
end)

return {}
end
__modules["features/potions"] = function(use) -- src/games/tapsim/features/potions.luau
-- Craft tab (right): the potion machine on Spawn, and drinking what it makes.
--
-- PotionMachineService (Shared.Items.PotionBrewConfig, PotionCraftConfig):
--   Brew(name, slot)  starts a Coins, Luck or Gems Potion I in one of 3 slots. It takes 5 minutes
--                     and costs PotionBrewConfig.GetPrice(rebirths) gems (1 + 5% of your rebirths).
--   ClaimAll()        collects every finished slot.
--   Craft(output)     merges 3 of a Potion I into its Potion II.
-- All three answer { Success, Error } and refuse with "TooFar" unless you stand at the machine, so
-- the machine is a trip like a craft: auto hatch pauses, one visit claims, merges and refills the
-- slots, and you go back where you were.
--
-- BoostService.Use(name) drinks a potion from anywhere. Active boosts of one type add up
-- (Shared.Items.BoostFormula sums every active potion's Multi), so each chosen potion is drunk
-- again as soon as its own timer (Data.ActiveBoosts[name], > 0 while it runs) is out.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local Options = Ui.Options
local RS = Env.ReplicatedStorage
local tab = Ui.Tabs.Craft

local function load(...)
    local path = { ... }
    local ok, module = Env.call(function()
        local node = RS
        for _, part in ipairs(path) do
            node = node:FindFirstChild(part)
        end
        return node and require(node)
    end)
    return ok and type(module) == "table" and module or nil
end

local BrewConfig = load("Shared", "Items", "PotionBrewConfig")
local CraftConfig = load("Shared", "Items", "PotionCraftConfig")
local BoostConfig = load("Shared", "Items", "BoostConfig")

local RECIPES = CraftConfig and CraftConfig.Recipes or {}
local SLOTS = BrewConfig and BrewConfig.SlotCount or 3
local BREWABLE = BrewConfig and BrewConfig.Potions or { "Coins Potion I", "Luck Potion I", "Gems Potion I" }
local MACHINE = { "Map1", "PotionMachine" }
local MACHINE_FALLBACK = Vector3.new(-354, -524, -12047) -- moved in the Oct 16 update

-- Everything drinkable: the six potions first, then the rarer boosts you might hold.
local DRINKABLE, DEFAULT_DRINKS = {}, {}
do
    local definitions = BoostConfig and BoostConfig.Definitions or {}
    local potions, others = {}, {}
    for name, def in pairs(definitions) do
        if type(def) == "table" and (tonumber(def.Duration) or 0) > 0 then
            if name:find("Potion") then
                potions[#potions + 1] = name
            elseif name == "Octo Incubator" or name == "Enchant Overclocker" then
                others[#others + 1] = name
            end
        end
    end
    table.sort(potions)
    table.sort(others)
    for _, name in ipairs(potions) do
        DRINKABLE[#DRINKABLE + 1] = name
        DEFAULT_DRINKS[#DEFAULT_DRINKS + 1] = name
    end
    for _, name in ipairs(others) do
        DRINKABLE[#DRINKABLE + 1] = name
    end
end

local box = tab:AddGroupbox({ Side = "Right", Name = "Potions", IconName = "flask-conical" })
box:AddToggle("AutoBrew", {
    Text = "Auto brew potions",
    Default = false,
    Tooltip = "Keeps the potion machine's 3 slots brewing and collects each potion when it is done (5 minutes each). Each brew costs gems: 1 plus 5% of your rebirths.",
})
Ui.automation("AutoBrew")
box:AddDropdown("BrewPicks", {
    Text = "Brew these",
    Values = BREWABLE,
    Multi = true,
    Default = BREWABLE,
    Tooltip = "Each empty slot gets the chosen potion you have fewest of.",
})
box:AddToggle("AutoCraftPotions", {
    Text = "Auto upgrade potions",
    Default = false,
    Tooltip = "Turns 3 tier I potions into 1 tier II at the potion machine whenever you have enough.",
})
Ui.automation("AutoCraftPotions")
box:AddToggle("AutoDrink", {
    Text = "Auto drink potions",
    Default = false,
    Tooltip = "Drinks each chosen potion again as soon as it runs out, from anywhere. Potions of the same kind add up, so a Coins I and a Coins II both count.",
})
Ui.automation("AutoDrink", true)
box:AddDropdown("DrinkPicks", {
    Text = "Drink these",
    Values = #DRINKABLE > 0 and DRINKABLE or { "Coins Potion I" },
    Multi = true,
    Default = DEFAULT_DRINKS,
    Tooltip = "Octo Incubator (hatch 8 at once) and Enchant Overclocker are here too, off by default.",
})
local label = box:AddLabel("Idle.", true)

local session = { brewed = 0, claimed = 0, merged = 0, drunk = 0 }
local note = ""

local function boosts(data)
    return type(data.Boosts) == "table" and data.Boosts or {}
end

local function slots(data)
    local machine = type(data.PotionMachine) == "table" and data.PotionMachine or {}
    return type(machine.Slots) == "table" and machine.Slots or {}
end

local function brewPrice(data)
    if not BrewConfig then
        return math.huge
    end
    local rebirths = tonumber(type(data.Statistics) == "table" and data.Statistics.Rebirths) or 0
    local ok, price = Env.call(BrewConfig.GetPrice, rebirths)
    return ok and tonumber(price) or math.huge
end

local function gems(data)
    return tonumber(type(data.Currencies) == "table" and data.Currencies.Gems) or 0
end

-- What a visit to the machine would do now: finished slots, empty slots it can fill, merges.
local function machineWork(data)
    local ready, empty = 0, 0
    local now = os.time()
    for slot = 1, SLOTS do
        local entry = slots(data)[tostring(slot)]
        if type(entry) ~= "table" then
            empty += 1
        elseif (tonumber(entry.ReadyAt) or math.huge) <= now then
            ready += 1
        end
    end
    local brew = Ui.on("AutoBrew") and next(Options.BrewPicks.Value or {}) ~= nil
    local work = {
        claim = brew and ready > 0,
        fill = brew and empty > 0 and gems(data) >= brewPrice(data),
        merge = false,
    }
    if Ui.on("AutoCraftPotions") then
        local owned = boosts(data)
        for _, recipe in ipairs(RECIPES) do
            if (tonumber(owned[recipe.Input]) or 0) >= (recipe.Required or 3) then
                work.merge = true
            end
        end
    end
    return work, ready, empty
end

-- The chosen brewable potion you hold the fewest of, counting what is already brewing.
local function nextBrew(data)
    local picks = Options.BrewPicks.Value or {}
    local counts = {}
    for name, count in pairs(boosts(data)) do
        counts[name] = tonumber(count) or 0
    end
    for _, entry in pairs(slots(data)) do
        if type(entry) == "table" and entry.Name then
            counts[entry.Name] = (counts[entry.Name] or 0) + 1
        end
    end
    local best, fewest
    for _, name in ipairs(BREWABLE) do
        if picks[name] and (not best or (counts[name] or 0) < fewest) then
            best, fewest = name, counts[name] or 0
        end
    end
    return best
end

local function root()
    local character = Env.LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

local function machinePosition()
    local node = workspace
    for _, name in ipairs(MACHINE) do
        node = node and node:FindFirstChild(name)
    end
    local ok, pivot = false, nil
    if node then
        ok, pivot = pcall(node.GetPivot, node)
    end
    return ok and pivot.Position or MACHINE_FALLBACK
end

local function ask(name, ...)
    local ok, result = Env.invoke("PotionMachineService", name, ...)
    if ok and type(result) == "table" and result.Error == "RateLimited" then
        Life.wait(1)
        ok, result = Env.invoke("PotionMachineService", name, ...)
    end
    if ok and type(result) == "table" and result.Success then
        return result
    end
    return nil, tostring(ok and type(result) == "table" and result.Error or result)
end

local function atMachine()
    local data = Env.data()
    if not data then
        return
    end
    local work, ready = machineWork(data)
    if work.claim then
        local claimed, why = ask("ClaimAll")
        if claimed then
            session.claimed += ready
        else
            note = "Collect refused: " .. why .. "."
        end
        Life.wait(0.4)
    end
    if Ui.on("AutoCraftPotions") then
        for _, recipe in ipairs(RECIPES) do
            while Life.alive and Ui.on("AutoCraftPotions") do
                local current = Env.data()
                if not current or (tonumber(boosts(current)[recipe.Input]) or 0) < (recipe.Required or 3) then
                    break
                end
                local merged, why = ask("Craft", recipe.Output)
                if not merged then
                    note = "Upgrade refused: " .. why .. "."
                    break
                end
                session.merged += 1
                Life.wait(0.3)
            end
        end
    end
    if Ui.on("AutoBrew") then
        for slot = 1, SLOTS do
            local current = Env.data()
            if not current then
                break
            end
            if type(slots(current)[tostring(slot)]) ~= "table" then
                local potion = nextBrew(current)
                if not potion then
                    break
                end
                if gems(current) < brewPrice(current) then
                    note = "Not enough gems to brew."
                    break
                end
                local brewed, why = ask("Brew", potion, slot)
                if not brewed then
                    note = "Brew refused: " .. why .. "."
                    break
                end
                session.brewed += 1
                Life.wait(0.4)
            end
        end
    end
end

local busy = false
local function trip()
    if busy or Ui.hatchMoving or Ui.travelling then
        return
    end
    busy = true
    Ui.travelling = "potions"
    local settle = os.clock() + 6
    while Ui.hatchInFlight and os.clock() < settle do
        Life.wait(0.05)
    end
    local hrp = root()
    local home = hrp and hrp.CFrame
    local ok, err = pcall(function()
        Ui.status = "At the potion machine"
        local target = machinePosition()
        Env.streamAround(target, 10)
        local here = root()
        if not here then
            return
        end
        here.AssemblyLinearVelocity = Vector3.zero
        here.CFrame = CFrame.new(target + Vector3.new(0, 4, 6))
        Life.wait(0.6)
        atMachine()
    end)
    Env.elevate()
    if not ok then
        Life.errors["potions:trip"] = tostring(err)
        note = "Potion trip error: " .. tostring(err)
    end
    -- The Craft tab's "Return to where I was" covers every machine trip.
    if home and (not Ui.Toggles.CraftReturn or Ui.on("CraftReturn")) then
        local back = root()
        if back then
            back.AssemblyLinearVelocity = Vector3.zero
            back.CFrame = home
        end
    end
    if Ui.status == "At the potion machine" then
        Ui.status = "Idle"
    end
    Ui.travelling = false
    busy = false
end

local nextTrip = 0
Life.loop("potions:machine", 2, function()
    if not (Ui.on("AutoBrew") or Ui.on("AutoCraftPotions")) or busy or os.clock() < nextTrip then
        return
    end
    local data = Env.data()
    if not data then
        return
    end
    local work = machineWork(data)
    if work.claim or work.fill or work.merge then
        nextTrip = os.clock() + 15 -- one visit at a time, and a refused one is not retried at once
        Life.spawn("potions:trip", trip)
    end
end)

-- Drinking --------------------------------------------------------------------------------------

local drinkRefused = {} -- name -> retry after (os.clock)
Life.loop("potions:drink", 2, function()
    if not Ui.on("AutoDrink") then
        return
    end
    local data = Env.data()
    if not data then
        return
    end
    local owned = boosts(data)
    local active = type(data.ActiveBoosts) == "table" and data.ActiveBoosts or {}
    local picks = Options.DrinkPicks.Value or {}
    for _, name in ipairs(DRINKABLE) do
        if picks[name] and (tonumber(owned[name]) or 0) > 0 and not ((tonumber(active[name]) or 0) > 0)
            and (drinkRefused[name] or 0) <= os.clock() then
            local ok, result = Env.invoke("BoostService", "Use", name)
            if ok and type(result) == "table" and result.Success then
                session.drunk += 1
                note = "Drank " .. name .. "."
            else
                drinkRefused[name] = os.clock() + 30
                note = string.format("Could not drink %s: %s.", name,
                    tostring(ok and type(result) == "table" and result.Error or result))
            end
            Life.wait(0.5)
        end
    end
end)

-- Panel -----------------------------------------------------------------------------------------

Life.loop("potions:panel", 1, function()
    local data = Env.data()
    if not data then
        return
    end
    local now = os.time()
    local parts = {}
    for slot = 1, SLOTS do
        local entry = slots(data)[tostring(slot)]
        if type(entry) ~= "table" then
            parts[#parts + 1] = "empty"
        else
            local left = (tonumber(entry.ReadyAt) or now) - now
            local short = tostring(entry.Name or "?"):gsub(" Potion", "")
            parts[#parts + 1] = left > 0 and string.format("%s %d:%02d", short, left // 60, left % 60)
                or (short .. " ready")
        end
    end
    local lines = {
        "Slots: " .. table.concat(parts, ", "),
        string.format("This session: %d brewed, %d collected, %d upgraded, %d drunk", session.brewed,
            session.claimed, session.merged, session.drunk),
    }
    if note ~= "" then
        lines[#lines + 1] = note
    end
    label:SetText(table.concat(lines, "\n"))
end)

Life.onCleanup(function()
    if busy then
        Ui.travelling = false
    end
end)

return {}
end
__modules["features/rewards"] = function(use) -- src/games/tapsim/features/rewards.luau
-- Rewards tab: everything the game hands out for free. Offline earnings, finished quests, tap
-- chests and the event spin wheel. Each claim is the game's own remote, fired only when the data
-- says there is something to take, so nothing spams a server that would just reject it.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local tab = Ui.Tabs.Rewards

-- Offline earnings -----------------------------------------------------------------------------

local offlineBox = tab:AddGroupbox({ Side = "Left", Name = "Offline earnings", IconName = "moon" })

local function claimOffline(instant)
    return (Env.invoke("OfflineRewardsService", "Claim", instant == true))
end

offlineBox:AddToggle("AutoClaimOffline", {
    Text = "Claim offline earnings on load",
    Default = true,
    Tooltip = "Claims whatever you banked while away as soon as the hub starts.",
})
offlineBox:AddButton({
    Text = "Claim now",
    Func = function()
        local ok = claimOffline(true)
        Ui.notify("Tap Simulator", ok and "Offline earnings claimed." or "Nothing to claim.", 4)
    end,
})
offlineBox:AddButton({
    Text = "Acknowledge offline hatches",
    Func = function()
        Env.invoke("OfflineRewardsService", "AcknowledgeHatches")
        Ui.notify("Tap Simulator", "Offline hatches acknowledged.", 3)
    end,
})

-- Quests -------------------------------------------------------------------------------------

local questBox = tab:AddGroupbox({ Side = "Left", Name = "Quests", IconName = "scroll-text" })
questBox:AddToggle("AutoClaimQuests", {
    Text = "Auto claim finished quests",
    Default = true,
    Tooltip = "Claims every quest that is complete but unclaimed.",
})
Ui.automation("AutoClaimQuests", true)
local questLabel = questBox:AddLabel("Idle.", true)

local claimedQuests = 0
Life.loop("rewards:quests", 2, function()
    if not Ui.on("AutoClaimQuests") then
        return
    end
    local data = Env.data()
    local quests = data and type(data.Quests) == "table" and data.Quests
    if not quests then
        return
    end
    local pending = 0
    for id, quest in pairs(quests) do
        if type(quest) == "table" and quest.Completed and not quest.Claimed then
            pending += 1
            local ok, res = Env.invoke("QuestService", "ClaimQuest", { Quest = id })
            if ok and (res == nil or type(res) ~= "table" or res.Success ~= false) then
                claimedQuests += 1
            end
            Life.wait(0.3)
        end
    end
    questLabel:SetText(pending > 0
        and string.format("Claimed %d quests this session.", claimedQuests)
        or string.format("No quests ready. %d claimed this session.", claimedQuests))
end)

-- Pet Index rewards ----------------------------------------------------------------------------
--
-- Each egg pays gems once you have found every pet it hatches, again for every pet in Golden,
-- Diamond and Rainbow, and "Secrets" pays when every secret pet is found. The Index screen's Claim
-- button sends PetIndexService.RewardClaimRequested(egg) and the server pays every tier that egg has
-- finished. A refused claim makes the game itself flash "No rewards to claim." with a sound, so this
-- only asks for an egg with a finished, unclaimed tier, and an egg the server turned down is not
-- asked again until you find another of its pets.

local LaunchEggConfig, PetIndexRewardConfig
do
    local ok, eggs = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Pets.LaunchEggConfig)
    end)
    LaunchEggConfig = ok and type(eggs) == "table" and eggs or nil
    local ok2, rewards = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Pets.PetIndexRewardConfig)
    end)
    PetIndexRewardConfig = ok2 and type(rewards) == "table" and rewards or nil
end

-- Reward tiers as PetIndexRewardConfig names them; IndexTiers keys the Rainbow tier "Shiny".
local INDEX_TIERS = { "Normal", "Golden", "Diamond", "Shiny" }

local function petFound(pets, name, tier)
    if tier == "Normal" then
        return type(pets.Index) == "table" and pets.Index[name] == true
    end
    local tiers = type(pets.IndexTiers) == "table" and pets.IndexTiers or {}
    return tiers[name .. "_" .. tier] == true or (tier == "Shiny" and tiers[name .. "_Rainbow"] == true)
end

local function tierClaimed(pets, egg, tier)
    local claimed = type(pets.IndexRewards) == "table" and pets.IndexRewards[egg]
    return type(claimed) == "table" and claimed[tier] == true
end

-- Every egg (plus "Secrets") with a finished tier the server has not paid yet, and how much of its
-- index is found, so a refusal can be remembered until that changes.
local function claimableIndex(pets)
    local list = {}
    if not (LaunchEggConfig and PetIndexRewardConfig) then
        return list
    end
    local secrets, secretsFound = 0, 0
    for egg, def in pairs(LaunchEggConfig) do
        if type(egg) == "string" and type(def) == "table" and type(def.Pets) == "table" then
            local found, ready = 0, false
            local rewards = PetIndexRewardConfig[egg]
            for _, tier in ipairs(INDEX_TIERS) do
                local have, total = 0, 0
                for name in pairs(def.Pets) do
                    total += 1
                    if petFound(pets, name, tier) then
                        have += 1
                    end
                end
                found += have
                if type(rewards) == "table" and type(rewards[tier]) == "number" and total > 0 and have == total
                    and not tierClaimed(pets, egg, tier) then
                    ready = true
                end
            end
            if ready then
                list[#list + 1] = { egg = egg, found = found }
            end
            for name in pairs(type(def.Secrets) == "table" and def.Secrets or {}) do
                secrets += 1
                if petFound(pets, name, "Normal") then
                    secretsFound += 1
                end
            end
        end
    end
    local secretReward = PetIndexRewardConfig.Secrets
    if secrets > 0 and secretsFound == secrets and type(secretReward) == "table"
        and type(secretReward.Complete) == "number" and not tierClaimed(pets, "Secrets", "Complete") then
        list[#list + 1] = { egg = "Secrets", found = secretsFound }
    end
    table.sort(list, function(a, b)
        return a.egg < b.egg
    end)
    return list
end

local indexBox = tab:AddGroupbox({ Side = "Left", Name = "Pet Index", IconName = "book-open" })
indexBox:AddToggle("AutoClaimIndex", {
    Text = "Auto claim index rewards",
    Default = true,
    Tooltip = "Claims the gems for every egg whose index you finish (Normal, Golden, Diamond and Rainbow) and the secret completion reward. Works from anywhere.",
})
Ui.automation("AutoClaimIndex", true)
local indexLabel = indexBox:AddLabel("Idle.", true)

local indexClaimed, indexLast = 0, nil
local indexRefused = {} -- egg -> pets found when the server last refused it
local indexWaiting -- the egg whose answer is pending
Life.spawn("rewards:index-results", function()
    local remote = Env.remote("PetIndexService", "RewardClaimResult")
    Life.connect(remote.OnClientEvent, function(result)
        if not indexWaiting then
            return
        end
        indexWaiting.result = type(result) == "table" and result or { Success = false }
    end)
end)

local function claimIndex(entry)
    local waiting = { egg = entry.egg }
    indexWaiting = waiting
    Env.fire("PetIndexService", "RewardClaimRequested", entry.egg)
    local deadline = os.clock() + 5
    while Life.alive and not waiting.result and os.clock() < deadline do
        Life.wait(0.1)
    end
    indexWaiting = nil
    if waiting.result and waiting.result.Success == true then
        indexClaimed += 1
        indexLast = entry.egg
        indexRefused[entry.egg] = nil
        return true
    end
    indexRefused[entry.egg] = entry.found
    return false
end

local function sweepIndex()
    local data = Env.data()
    local pets = data and type(data.Pets) == "table" and data.Pets
    if not pets then
        return 0
    end
    local claimed = 0
    for _, entry in ipairs(claimableIndex(pets)) do
        if indexRefused[entry.egg] ~= entry.found then
            if claimIndex(entry) then
                claimed += 1
            end
            Life.wait(0.5)
        end
    end
    return claimed
end

indexBox:AddButton({
    Text = "Claim now",
    Func = function()
        Life.spawn("rewards:index-manual", function()
            table.clear(indexRefused)
            local claimed = sweepIndex()
            Ui.notify("Tap Simulator", claimed > 0 and string.format("Claimed %d index rewards.", claimed)
                or "No index rewards to claim.", 4)
        end)
    end,
})

Life.loop("rewards:index", 5, function()
    if not Ui.on("AutoClaimIndex") then
        indexLabel:SetText("Off.")
        return
    end
    if not (LaunchEggConfig and PetIndexRewardConfig) then
        indexLabel:SetText("The game's index config could not be read.")
        return
    end
    sweepIndex()
    indexLabel:SetText(string.format("%d claimed this session%s.", indexClaimed,
        indexLast and (", last: " .. indexLast) or ""))
end)

-- Tap chests ---------------------------------------------------------------------------------

local chestBox = tab:AddGroupbox({ Side = "Right", Name = "Tap chests", IconName = "box" })
chestBox:AddToggle("AutoClaimChests", {
    Text = "Auto claim tap chests",
    Default = true,
    Tooltip = "Claims any tap chest the server shows as ready for you.",
})
Ui.automation("AutoClaimChests", true)
local chestLabel = chestBox:AddLabel("Idle.", true)

local claimedChests = 0
Life.loop("rewards:chests", 3, function()
    if not Ui.on("AutoClaimChests") then
        return
    end
    local data = Env.data()
    local chests = data and type(data.TapChests) == "table" and data.TapChests
    if not chests then
        return
    end
    local any = false
    for id in pairs(chests) do
        any = true
        local ok = Env.invoke("TapChestService", "Claim", id)
        if ok then
            claimedChests += 1
        end
        Life.wait(0.3)
    end
    chestLabel:SetText(any
        and string.format("Tried; %d chests claimed this session.", claimedChests)
        or "No tap chests ready.")
end)

-- Event spin wheel ---------------------------------------------------------------------------

local spinBox = tab:AddGroupbox({ Side = "Right", Name = "Spin wheel", IconName = "disc-3" })
spinBox:AddToggle("AutoSpin", {
    Text = "Auto spin event wheel",
    Default = false,
    Tooltip = "Spins each active event wheel on a timer. The server only gives a spin when one is free.",
})
Ui.automation("AutoSpin", true)
spinBox:AddSlider("SpinEvery", {
    Text = "Spin every",
    Default = 10,
    Min = 3,
    Max = 60,
    Rounding = 0,
    Suffix = "s",
})
local spinLabel = spinBox:AddLabel("Idle.", true)

local lastSpin, spins = 0, 0
Life.loop("rewards:spin", 1, function()
    if not Ui.on("AutoSpin") then
        return
    end
    local every = math.clamp(tonumber(Ui.Options.SpinEvery.Value) or 10, 3, 60)
    if os.clock() - lastSpin < every then
        return
    end
    local data = Env.data()
    local wheels = data and type(data.Spinwheels) == "table" and data.Spinwheels
    if not wheels then
        return
    end
    lastSpin = os.clock()
    local any = false
    for wheel in pairs(wheels) do
        any = true
        local ok = Env.invoke("EventWheelService", "Spin", { WheelType = wheel })
        if ok then
            spins += 1
        end
        Life.wait(0.3)
    end
    spinLabel:SetText(any and string.format("%d spins attempted this session.", spins) or "No event wheel active.")
end)

return {
    afterLoad = function()
        if Ui.on("AutoClaimOffline") then
            Life.spawn("rewards:offline", function()
                Life.wait(1)
                claimOffline(false)
            end)
        end
    end,
}
end
__modules["features/settings"] = function(use) -- src/games/tapsim/features/settings.luau
-- Settings tab (see shared/settings): Tap Simulator configs, and what each missing function changes.

use("core/ui")
local Settings = use("shared/settings")

return Settings.build({
    folder = "TapSimulator",
    effects = {
        queue_on_teleport = "the hub does not come back after a teleport: run the loader again",
        writefile = "configs, themes and the offline cache cannot be saved",
        readfile = "saved configs and cached downloads cannot be read",
        isfile = "saved configs and cached downloads cannot be located",
        isfolder = "config folders cannot be managed",
        makefolder = "config folders cannot be created",
        listfiles = "saved configs and themes cannot be listed",
        delfile = "saved configs cannot be deleted",
        setclipboard = "copy buttons display their text instead",
    },
})
end
__modules["features/shrine"] = function(use) -- src/games/tapsim/features/shrine.luau
-- Pets tab: the Shrine on Autumn (Shared.Game.ShrineConfig). A blessing is Luck (egg luck),
-- Golden Chance (golden and rainbow hatches) or Auto Clicker (auto click speed), and it grows
-- the longer you keep it: x1.1, x1.25 after 10 minutes, x1.5 after 25 (TierStarts 0/600/1500).
-- Your blessing shows on you as attributes (ShrineBlessing, ShrineTier, ShrineBlessingSince).
--
-- ShrineService.Choose(key) picks one from within UseDistance (45 studs) of the shrine. Choosing
-- again restarts the climb, so the hub only goes when you have none, or a different one than the
-- one picked here.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local Options = Ui.Options
local tab = Ui.Tabs.Pets

local SHRINE = Vector3.new(38.4, 880.7, -1832.4) -- its prompt circle, measured in the game
local NAMES = { Luck = "Luck (egg luck)", Golden = "Golden Chance", AutoClicker = "Auto Clicker speed" }
local ORDER = { "Luck", "Golden", "AutoClicker" }

local Config
do
    local ok, module = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Game.ShrineConfig)
    end)
    Config = ok and type(module) == "table" and module or nil
end

local labels, keyOf = {}, {}
for _, key in ipairs(ORDER) do
    labels[#labels + 1] = NAMES[key]
    keyOf[NAMES[key]] = key
end

local box = tab:AddGroupbox({ Side = "Left", Name = "Shrine blessing", IconName = "sparkles" })
box:AddToggle("AutoShrine", {
    Text = "Keep a blessing",
    Default = false,
    Tooltip = "Goes to the Shrine on Autumn and takes the blessing below whenever you have none (after a rejoin, for one). It grows from x1.1 to x1.25 after 10 minutes and x1.5 after 25.",
})
Ui.automation("AutoShrine", false)
box:AddDropdown("ShrineBlessing", {
    Text = "Blessing",
    Values = labels,
    Default = labels[1],
})
local label = box:AddLabel("Checking...", true)

local function root()
    local character = Env.LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

local function current()
    local player = Env.LocalPlayer
    return player:GetAttribute("ShrineBlessing"), tonumber(player:GetAttribute("ShrineTier")),
        tonumber(player:GetAttribute("ShrineBlessingSince"))
end

local busy, note, nextTry = false, "", 0
local function choose(key)
    if busy or Ui.hatchMoving or Ui.travelling then
        return
    end
    busy = true
    Ui.travelling = "shrine"
    local settle = os.clock() + 6
    while Ui.hatchInFlight and os.clock() < settle do
        Life.wait(0.05)
    end
    local hrp = root()
    local home = hrp and hrp.CFrame
    Env.streamAround(SHRINE, 6)
    if hrp then
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.CFrame = CFrame.new(SHRINE + Vector3.new(0, 4, 0))
    end
    Life.wait(0.6)
    local ok, result = Env.invoke("ShrineService", "Choose", key)
    if ok and type(result) == "table" and result.Success ~= false and not result.Error and not result.Reason then
        note = "Blessed with " .. NAMES[key] .. "."
    else
        note = "The Shrine said no: " .. tostring(type(result) == "table" and (result.Reason or result.Error) or result) .. "."
    end
    if home then
        local back = root()
        if back then
            back.AssemblyLinearVelocity = Vector3.zero
            back.CFrame = home
        end
    end
    Ui.travelling = false
    busy = false
end

Life.loop("shrine:auto", 2, function()
    local blessing, tier, since = current()
    local text
    if blessing then
        local held = since and math.max(0, workspace:GetServerTimeNow() - since) or 0
        local multiplier = Config and Config.GetMultiplier(tier or 1) or nil
        local nextIn = Config and Config.GetNextTierIn(held) or nil
        text = string.format("%s, tier %s%s%s.", NAMES[blessing] or tostring(blessing), tostring(tier or 1),
            multiplier and (" (x" .. tostring(multiplier) .. ")") or "",
            nextIn and string.format(", next tier in %d:%02d", nextIn // 60, math.floor(nextIn % 60)) or "")
    else
        text = "No blessing."
    end
    if note ~= "" then
        text = text .. "\n" .. note
    end
    label:SetText(Ui.on("AutoShrine") and text or ("Off. " .. text))
    local want = keyOf[Options.ShrineBlessing.Value] or "Luck"
    if Ui.on("AutoShrine") and blessing ~= want and not busy and os.clock() >= nextTry then
        nextTry = os.clock() + 30
        Life.spawn("shrine:choose", choose, want)
    end
end)

Life.onCleanup(function()
    if busy then
        Ui.travelling = false
    end
end)

return {}
end
__modules["features/skilltree"] = function(use)
-- В тесте используем реальные ключи SkillTreeFormula.Nodes, а не имена из произвольных
-- вложенных таблиц SkillTreeConfig. Схема Nodes/GetPrice сверена со сторонней реализацией;
-- текущий сервер ещё нужно проверить. Если формула недоступна, покупки не угадываются.
local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local tab = Ui.Tabs.Tapping
local box = tab:AddGroupbox({ Side = "Left", Name = "Skill tree", IconName = "git-branch" })
box:AddToggle("AutoSkillTree", {
    Text = "Auto unlock skill tree",
    Default = false,
    Tooltip = "During progression, attempts eligible gem skill nodes from the game's formula.",
})
Ui.automation("AutoSkillTree", true)
box:AddButton({
    Text = "Unlock affordable gem skills",
    Func = function()
        Ui.set("AutoSkillTree", true)
        Ui.notify("Tap Simulator", "Eligible gem skills will be checked during progression.", 4)
    end,
})
local label = box:AddLabel("Waiting for the game's skill formula.", true)
local PACE = 0.3
local FORMULA, NODES, priorities = nil, {}, {}
local configCurrencyConflicts = {}
local confirmedThisRun = 0
local lastOutcome = "ожидаю формулу"
local lastSummary = ""

-- Если сервер уже ответил Success, повторно тот же узел не отправляется до реплики,
-- в том числе при повторной загрузке скрипта в том же клиенте.
local accepted = {}
local uid = Env.LocalPlayer and tonumber(Env.LocalPlayer.UserId)
if Env.genv and uid and uid > 0 then
    if type(Env.genv.__TS30AcceptedSkills) ~= "table" then Env.genv.__TS30AcceptedSkills = {} end
    local key = tostring(math.floor(uid))
    if type(Env.genv.__TS30AcceptedSkills[key]) ~= "table" then Env.genv.__TS30AcceptedSkills[key] = {} end
    accepted = Env.genv.__TS30AcceptedSkills[key]
end
local retryAt = {}

local function reportSkills(message, summary)
    local P = Ui.__progressTest
    if not P then return end
    if summary ~= nil then lastSummary = summary end
    P.gemWork = P.gemWork or {}
    P.gemWork.skills = string.format("формула=%s, узлов=%d, подтверждено=%d, %s%s",
        FORMULA and "Nodes" or "недоступна", #NODES, confirmedThisRun, tostring(message),
        lastSummary ~= "" and (" | " .. lastSummary) or "")
end

local function active(P)
    return type(P) == "table" and Life.alive and Ui.__progressTest == P
        and P.phase == "rebirth" and P.gemReady and not P.farmThresholdReached
        and not P.holdSkillTree and not P.eggFixed and not P.rebirthLocked and not P.stopRequested
        and not P.skillUncertain and not (Env.genv and Env.genv.__handoverPaused)
        and Ui.on("AutoSkillTree")
end

local function normalized(s)
    return type(s) == "string" and s:lower():gsub("[^%w]", "") or ""
end
local function textOf(name, node)
    local parts = { tostring(name) }
    local function add(t)
        if type(t) ~= "table" then return end
        for _, key in ipairs({ "Name", "Id", "DisplayName", "Title", "Description", "Tooltip", "Category" }) do
            if type(t[key]) == "string" then parts[#parts + 1] = t[key] end
        end
    end
    add(node)
    add(type(node) == "table" and node.Data or nil)
    return normalized(table.concat(parts, " "))
end
local function forbiddenText(text)
    -- Catch Speed в журнале старой версии может относиться к ловле; консервативно пропускаем.
    for _, word in ipairs({ "fish", "bait", "catch", "potion", "brew", "enchant" }) do
        if text:find(word, 1, true) then return true end
    end
    return false
end
local function forbiddenSkill(name)
    local seen = {}
    while type(name) == "string" and name ~= "" and not seen[name] do
        seen[name] = true
        local node = FORMULA and FORMULA.Nodes and FORMULA.Nodes[name]
        if forbiddenText(textOf(name, node)) then return true end
        name = type(node) == "table" and node.Parent or nil
    end
    return false
end

-- Узел без Currency считается гемовым только внутри SkillTreeFormula.Nodes: так этот
-- дефолт трактует найденная реализация. Любая явная чужая/непонятная валюта, а также
-- явно смешанная стоимость отклоняются. Это не подтверждает схему будущих обновлений.
local function currencySafe(def)
    if type(def) ~= "table" then return false end
    local seen, denied = {}, false
    local currencyFields = { "Currency", "CostCurrency", "PriceCurrency", "CurrencyName" }
    local function nonzero(v)
        if v == nil or v == false then return false end
        local n = tonumber(v)
        return n == nil or n ~= 0
    end
    local function fields(t)
        for _, key in ipairs(currencyFields) do
            local v = t[key]
            if v ~= nil and (type(v) ~= "string" or normalized(v) ~= "gems") then denied = true end
        end
        for k, v in pairs(t) do
            local key = normalized(k)
            if key == "coins" or key == "coin" or key == "tokens" or key == "token"
                or key == "paidtokens" or key == "robux" or key == "candycorn"
                or key == "tickets" or key == "eventcurrency" then
                if nonzero(v) then denied = true end
            end
        end
    end
    local function costs(t, depth)
        if type(t) ~= "table" or seen[t] then return end
        if depth > 6 then denied = true; return end -- слишком вложенная цена: нельзя проверить
        seen[t] = true
        fields(t)
        for _, child in pairs(t) do if type(child) == "table" then costs(child, depth + 1) end end
    end
    fields(def)
    for _, key in ipairs({ "Cost", "Price", "Costs", "Prices" }) do
        local value = def[key]
        if type(value) == "table" then costs(value, 0)
        elseif type(value) == "string" and tonumber(value) == nil then denied = true end
    end
    return not denied
end

local function loadFormula()
    local ok, value = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Progression.SkillTreeFormula)
    end)
    if not ok or type(value) ~= "table" or type(value.Nodes) ~= "table"
        or type(value.GetPrice) ~= "function" then
        FORMULA, NODES, priorities = nil, {}, {}
        return false
    end
    local names = {}
    for name, node in pairs(value.Nodes) do
        if type(name) == "string" and name ~= "" and type(node) == "table" then names[#names + 1] = name end
    end
    table.sort(names)
    if #names == 0 then FORMULA, NODES, priorities = nil, {}, {}; return false end
    FORMULA, NODES, priorities = value, names, {}
    configCurrencyConflicts = {}
    -- Если второй конфиг явно называет у того же ключа другую валюту, сохраняем
    -- консервативный запрет v5. Отсутствие этого конфига не подменяет Nodes.
    local gotConfig, cfg = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Progression.SkillTreeConfig)
    end)
    if gotConfig and type(cfg) == "table" then
        local visited, budget = {}, 5000
        local function walk(t, depth)
            if type(t) ~= "table" or visited[t] or budget <= 0 or depth > 20 then return end
            visited[t] = true
            budget -= 1
            if type(t.Name) == "string" and value.Nodes[t.Name] ~= nil and not currencySafe(t) then
                configCurrencyConflicts[t.Name] = true
            end
            for _, child in pairs(t) do if type(child) == "table" then walk(child, depth + 1) end end
        end
        walk(cfg, 0)
    end
    -- Доступные автоклик/доход идут раньше остальных. Родители доходных узлов тоже
    -- получают приоритет: иначе полезная ветка не будет открываться.
    for _, name in ipairs(NODES) do
        local text = textOf(name, value.Nodes[name])
        local rank = nil
        if text:find("autoclick", 1, true) then rank = 0
        else
            for _, word in ipairs({ "click", "tap", "critical", "crit", "coin", "petpower", "rebirth", "gem" }) do
                if text:find(word, 1, true) then rank = 1; break end
            end
        end
        if rank then
            local current, seen = name, {}
            while type(current) == "string" and current ~= "" and not seen[current] do
                seen[current] = true
                local previous = priorities[current]
                if previous == nil or rank < previous then priorities[current] = rank end
                local node = value.Nodes[current]
                current = type(node) == "table" and node.Parent or nil
            end
        end
    end
    label:SetText(string.format("%d skill keys in the game's formula.", #NODES))
    return true
end

local function unlockedFlag(value)
    -- Нестандартное значение тоже не отправляем повторно; для родителя принимаем
    -- только однозначно включённые boolean/positive-number значения.
    return value == true or (type(value) == "number" and value > 0)
end

local function eligibility(data, name)
    local node = FORMULA and FORMULA.Nodes and FORMULA.Nodes[name]
    if type(node) ~= "table" or type(node.Data) ~= "table" then return false, nil, "схема" end
    local meta = node.Data
    if forbiddenSkill(name) then return false, nil, "запрещённая ветка" end
    if configCurrencyConflicts[name] or not currencySafe(node) or not currencySafe(meta) then return false, nil, "валюта" end
    local tree = type(data) == "table" and type(data.SkillTree) == "table" and data.SkillTree.Unlocked or nil
    if type(tree) ~= "table" then return false, nil, "нет данных" end
    local state = tree[name]
    if state ~= nil and state ~= false then return false, nil, "открыто" end
    if accepted[name] then return false, nil, "жду реплику" end
    if (retryAt[name] or 0) > os.clock() then return false, nil, "повтор позже" end
    local parent = node.Parent
    if parent ~= nil and parent ~= false and parent ~= "" then
        if type(parent) ~= "string" or not unlockedFlag(tree[parent]) then return false, nil, "родитель" end
    end
    local progression = type(data.Progression) == "table" and data.Progression or nil
    local island = meta.RequiredIsland
    if island ~= nil and island ~= false and island ~= "" then
        if type(island) ~= "string" or not progression or type(progression.UnlockedIslands) ~= "table"
            or not unlockedFlag(progression.UnlockedIslands[island]) then return false, nil, "остров" end
    end
    local world = meta.RequiredWorld
    if world ~= nil and world ~= false and world ~= "" then
        if type(world) ~= "string" or not progression or progression.World ~= world then return false, nil, "мир" end
    end
    local currencies = type(data.Currencies) == "table" and data.Currencies or nil
    local gems = currencies and tonumber(currencies.Gems) or nil
    if not gems or gems ~= gems or gems < 0 or gems == math.huge then return false, nil, "нет данных" end
    local ok, raw = Env.call(FORMULA.GetPrice, data, name)
    local price = ok and tonumber(raw) or nil
    if not price or price ~= price or price < 0 or price == math.huge then return false, nil, "цена" end
    if price > gems then return false, price, "мало гемов" end
    return true, price, nil
end

local function observeAccepted(data)
    local tree = type(data) == "table" and type(data.SkillTree) == "table" and data.SkillTree.Unlocked or nil
    if type(tree) ~= "table" then return end
    for name, entry in pairs(accepted) do
        if type(entry) == "table" then
            if unlockedFlag(tree[name]) and not entry.counted then
                entry.counted = true
                confirmedThisRun += 1
                lastOutcome = "подтверждён " .. tostring(name)
                reportSkills(lastOutcome)
                local P = Ui.__progressTest
                if P and type(P.log) == "function" then pcall(P.log, "гемовый навык подтверждён: " .. tostring(name)) end
            elseif not entry.counted and not entry.warned and os.clock() - (tonumber(entry.at) or os.clock()) >= 10 then
                entry.warned = true
                lastOutcome = "сервер принял " .. tostring(name) .. ", жду реплику; повтор не отправляю"
                reportSkills(lastOutcome)
            end
        end
    end
end

local function summarize(reasons, cheapestName, cheapestPrice, gems)
    local order = { "открыто", "родитель", "остров", "мир", "мало гемов", "валюта", "запрещённая ветка", "цена", "схема", "нет данных", "жду реплику", "повтор позже" }
    local parts = {}
    for _, reason in ipairs(order) do
        if reasons[reason] then parts[#parts + 1] = reason .. "=" .. tostring(reasons[reason]) end
    end
    if cheapestName then
        parts[#parts + 1] = string.format("ближайший %s=%s Gems при балансе %s", cheapestName, tostring(cheapestPrice), tostring(gems or "?"))
    end
    return #parts > 0 and table.concat(parts, ", ") or "нет подходящих узлов"
end

Life.spawn("skills:auto", function()
    local nextFormulaRetry = 0
    while Life.alive do
        local P = Ui.__progressTest
        if next(accepted) ~= nil then observeAccepted(Env.data()) end
        if not active(P) then Life.wait(0.3); continue end
        if not FORMULA then
            if os.clock() >= nextFormulaRetry then
                nextFormulaRetry = os.clock() + 30
                if loadFormula() then
                    lastOutcome = "проверяю доступные узлы"
                else
                    lastOutcome = "SkillTreeFormula.Nodes/GetPrice недоступны; покупки не угадываю"
                end
                reportSkills(lastOutcome, "")
            end
            Life.wait(1)
            continue
        end
        local data = Env.data()
        local best, bestPrice, bestRank, available = nil, nil, nil, 0
        local reasons, cheapestName, cheapestPrice = {}, nil, nil
        for _, name in ipairs(NODES) do
            if not active(P) then break end
            local eligible, price, reason = eligibility(data, name)
            if eligible then
                available += 1
                local rank = priorities[name] or 2
                if not best or rank < bestRank or (rank == bestRank
                    and (price < bestPrice or (price == bestPrice and name < best))) then
                    best, bestPrice, bestRank = name, price, rank
                end
            else
                reasons[reason or "схема"] = (reasons[reason or "схема"] or 0) + 1
                if reason == "мало гемов" and (not cheapestPrice or price < cheapestPrice) then
                    cheapestName, cheapestPrice = name, price
                end
            end
        end
        if not active(P) then Life.wait(0.2); continue end
        local gems = type(data) == "table" and type(data.Currencies) == "table" and data.Currencies.Gems or nil
        local summary = summarize(reasons, cheapestName, cheapestPrice, gems)
        if not best then
            reportSkills(lastOutcome .. "; доступно=0", summary)
            Life.wait(2)
            continue
        end
        lastOutcome = string.format("пробую %s за %s Gems; доступно=%d", best, tostring(bestPrice), available)
        reportSkills(lastOutcome, summary)
        P.skillInFlight = true
        local called, ok, response = pcall(Env.invokeGuarded, "SkillTreeService", "Unlock", function()
            if not active(P) then return false end
            local fresh = Env.data()
            local allowed = eligibility(fresh, best)
            return allowed and active(P)
        end, { Name = best })
        P.skillInFlight = false
        local unavailable = called and not ok and response == "ts30_unavailable_before_send"
        local cancelled = called and not ok and response == "ts30_cancelled_before_send"
        if cancelled then
            lastOutcome = "запрос отменён до отправки"
        elseif unavailable then
            P.skillRetryAt = os.clock() + 60
            lastOutcome = "сервис недоступен до отправки; повтор позже"
            if type(P.log) == "function" then pcall(P.log, "сервис навыков недоступен; продолжу фарм и повторю позже") end
        elseif called and ok and type(response) == "table" and response.Success == true
            and response.Error == nil then
            accepted[best] = { at = os.clock(), counted = false, warned = false }
            lastOutcome = "сервер принял " .. tostring(best) .. "; жду подтверждение в данных"
            observeAccepted(Env.data())
        elseif called and ok and type(response) == "table" and response.Success ~= true
            and (response.Success == false or type(response.Reason) == "string" or type(response.Error) == "string") then
            local reason = tostring(response.Reason or response.Error or "отказ")
            retryAt[best] = os.clock() + (reason == "RateLimited" and 1 or 30)
            lastOutcome = "отказ " .. tostring(best) .. ": " .. reason
        else
            P.skillUncertain = true
            lastOutcome = "нет подтверждения " .. tostring(best) .. "; повторы остановлены"
            if type(P.log) == "function" then pcall(P.log, "покупка навыка не подтверждена; новые покупки и ребёрты на паузе") end
        end
        reportSkills(lastOutcome)
        Life.wait(PACE)
    end
end)

return {}
end
__modules["features/stars"] = function(use) -- src/games/tapsim/features/stars.luau
-- Rewards tab: the 15 Shiny Stars hidden on the islands (Shared.Game.ShinyStarConfig). Finding all
-- of them doubles the Shiny mutation chance on every hatch, 2% -> 4%, for good.
--
-- The stars only exist on the client once streamed in (within ~200 studs), so where they stand is
-- kept here, measured in the game. ShinyStarService.Collect(id) picks one up when you are within
-- ServerReach (22 studs) of it; Data.ShinyStars.Found says which you have.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local RunService = game:GetService("RunService")
local tab = Ui.Tabs.Rewards

local Config
do
    local ok, module = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Game.ShinyStarConfig)
    end)
    Config = ok and type(module) == "table" and module or nil
end

local POSITIONS = {
    Spawn1 = Vector3.new(53.6, -512.3, -2015.7),
    Spawn2 = Vector3.new(-4.4, -512.3, -1699.5),
    Spawn3 = Vector3.new(-98.3, -386.5, -1534.2),
    SkyIsland1 = Vector3.new(-79.7, -47.9, -1930.4),
    SkyIsland2 = Vector3.new(-61.9, -52.6, -1791.1),
    Autumn1 = Vector3.new(-125.5, 906.1, -1978.3),
    Autumn2 = Vector3.new(23.6, 884.0, -1947.9),
    Mushroom1 = Vector3.new(78.9, 2035.8, -1996.0),
    Mushroom2 = Vector3.new(-124.1, 2033.5, -2067.9),
    Desert1 = Vector3.new(13.2, 3644.1, -2165.9),
    Desert2 = Vector3.new(59.1, 3637.2, -1979.1),
    CrystalCave1 = Vector3.new(-235.0, 5445.9, -2050.9),
    CrystalCave2 = Vector3.new(19.7, 5447.8, -2033.5),
    ShadowRelm1 = Vector3.new(13.2, 7693.0, -2106.3),
    ShadowRelm2 = Vector3.new(197.8, 7699.1, -1858.6),
}

local function starList()
    local list = {}
    for _, star in ipairs(Config and Config.Stars or {}) do
        list[#list + 1] = star
    end
    if #list == 0 then
        for id in pairs(POSITIONS) do
            list[#list + 1] = { Id = id }
        end
        table.sort(list, function(a, b)
            return a.Id < b.Id
        end)
    end
    return list
end

local function found(data, id)
    local stars = data and type(data.ShinyStars) == "table" and data.ShinyStars
    return type(stars) == "table" and type(stars.Found) == "table" and stars.Found[id] == true
end

local function unlocked(data)
    local stars = data and type(data.ShinyStars) == "table" and data.ShinyStars
    return type(stars) == "table" and stars.Unlocked == true
end

-- Where the star stands: the streamed-in star itself if it is here, else the measured spot.
local function positionOf(id)
    local folder = workspace:FindFirstChild(Config and Config.Folder or "ShinyStars")
    for _, part in ipairs(folder and folder:GetDescendants() or {}) do
        if part:GetAttribute("ShinyStarId") == id then
            local ok, position = pcall(function()
                return part:IsA("Model") and part:GetPivot().Position or part.Position
            end)
            if ok then
                return position
            end
        end
    end
    return POSITIONS[id]
end

local box = tab:AddGroupbox({ Side = "Right", Name = "Shiny Stars", IconName = "star" })
local label = box:AddLabel("Checking...", true)

local function root()
    local character = Env.LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

local busy = false
local function collectAll()
    if busy or Ui.hatchMoving or Ui.travelling then
        Ui.notify("Tap Simulator", Ui.travelling == "mining" and "Auto mine is using your character; turn it off first."
            or "Busy with another trip; try again in a moment.", 5)
        return
    end
    busy = true
    Ui.travelling = "stars"
    local settle = os.clock() + 6
    while Ui.hatchInFlight and os.clock() < settle do
        Life.wait(0.05)
    end
    local hrp = root()
    local home = hrp and hrp.CFrame
    local picked, failed = 0, {}
    local ok, err = pcall(function()
        for _, star in ipairs(starList()) do
            if not Life.alive then
                break
            end
            if not found(Env.data(), star.Id) then
                local spot = positionOf(star.Id)
                local here = root()
                if spot and here then
                    Env.streamAround(spot, 6)
                    -- Some stars float in mid-air: you are held on the spot (every frame) until the
                    -- star is yours, or a fall carries you out of the server's reach first.
                    local target = CFrame.new(spot + Vector3.new(0, 3, 0))
                    local hold = RunService.Heartbeat:Connect(function()
                        local current = root()
                        if current then
                            current.AssemblyLinearVelocity = Vector3.zero
                            current.CFrame = target
                        end
                    end)
                    local okHold = pcall(function()
                        Life.wait(0.5) -- the server has to see you there before it hands the star over
                        -- Standing on it, the game's own pickup may get there first; either is fine.
                        local deadline = os.clock() + 1.5
                        while Life.alive and not found(Env.data(), star.Id) and os.clock() < deadline do
                            Life.wait(0.2)
                        end
                        for _ = 1, 2 do
                            if found(Env.data(), star.Id) then
                                break
                            end
                            Env.invoke("ShinyStarService", "Collect", star.Id)
                            Life.wait(0.6)
                        end
                    end)
                    hold:Disconnect()
                    Env.elevate()
                    if not okHold then
                        failed[#failed + 1] = star.Id
                    elseif found(Env.data(), star.Id) then
                        picked += 1
                    else
                        failed[#failed + 1] = star.Id
                    end
                end
            end
        end
    end)
    Env.elevate()
    if not ok then
        Life.errors["stars:collect"] = tostring(err)
    end
    if home then
        local back = root()
        if back then
            back.AssemblyLinearVelocity = Vector3.zero
            back.CFrame = home
        end
    end
    Ui.travelling = false
    busy = false
    local data = Env.data()
    Ui.notify("Tap Simulator", (#failed == 0 and string.format("Collected %d Shiny Stars.", picked)
        or string.format("Collected %d; could not get %s.", picked, table.concat(failed, ", ")))
        .. (unlocked(data) and " Shiny mutation chance is now 4%." or ""), 8)
end

box:AddButton({
    Text = "Collect Shiny Stars",
    Func = function()
        Life.spawn("stars:collect", collectAll)
    end,
    Tooltip = "Goes to each Shiny Star you have not found, picks it up and brings you back. All 15 double the Shiny mutation chance on every hatch (2% to 4%).",
})

Life.loop("stars:panel", 2, function()
    local data = Env.data()
    if not data then
        return
    end
    local count, total = 0, 0
    for _, star in ipairs(starList()) do
        total += 1
        if found(data, star.Id) then
            count += 1
        end
    end
    label:SetText(unlocked(data) and string.format("All %d found: Shiny mutation chance is 4%%.", total)
        or string.format("%d / %d found. All of them double the Shiny mutation chance (2%% to 4%%).", count, total))
end)

Life.onCleanup(function()
    if busy then
        Ui.travelling = false
    end
end)

return {
    collect = function()
        Life.spawn("stars:collect", collectAll)
    end,
}
end
__modules["features/tap"] = function(use) -- src/games/tapsim/features/tap.luau
-- Tapping tab: auto tap (the coin engine), the game's own auto clicker, and auto rebirth.
--
-- A tap is TapService.TapRequested { Auto, ClientSequence, Source }: the server credits coins for
-- each one at the player's current tap power, so firing them on a timer is the whole trick. Source
-- names what was pressed ("button" is the tap button, as the game's own client sends it). The
-- server counts at most one tap per GameConfig.ManualTapInterval (0.1s) and drops the rest, so the
-- rate tops out at 10 a second, and the gaps are only ever stretched by the jitter, never shortened
-- below that interval (a real player's taps are never perfectly periodic either).

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local Options = Ui.Options
local tab = Ui.Tabs.Tapping

-- Auto tap -------------------------------------------------------------------------------------

local MIN_GAP = 0.1
do
    local ok, config = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Core.GameConfig)
    end)
    local interval = ok and type(config) == "table" and tonumber(config.ManualTapInterval)
    if interval and interval > 0 then
        MIN_GAP = interval
    end
end
local MAX_RATE = math.max(1, math.floor(1 / MIN_GAP + 1e-6))

local tapBox = tab:AddGroupbox({ Side = "Left", Name = "Auto tap", IconName = "hand" })
tapBox:AddToggle("AutoTap", {
    Text = "Auto tap",
    Default = false,
    Tooltip = "Fires taps on a timer. Earns coins exactly as tapping does, at your current tap power.",
})
Ui.automation("AutoTap", true)
tapBox:AddSlider("TapRate", {
    Text = "Taps per second",
    Default = MAX_RATE,
    Min = 1,
    Max = MAX_RATE,
    Rounding = 0,
    Suffix = "/s",
    Tooltip = string.format("The server counts at most %d taps a second and throws faster ones away.", MAX_RATE),
})
local tapLabel = tapBox:AddLabel("Auto tap is off.", true)

-- The server only takes a tap whose ClientSequence is above the last one it took from you this
-- session, and drops the rest without a word. A reloaded hub that counted from 0 again was ignored
-- until it caught up with the copy before it, so the count lives in the executor's globals and
-- carries on across reloads. Every accepted tap is answered on TapResult; if a run of taps gets no
-- answer (the game's own taps or another script got ahead), the count jumps forward until they do.
local SEQUENCE_KEY = "__SlopixTapSequence"
local STALL_TAPS, STALL_SECONDS = 25, 2
local sequence = tonumber(Env.genv[SEQUENCE_KEY]) or 0
local lastAnswer, unanswered, resyncs = os.clock(), 0, 0
local tapAnswerCount = 0

Life.spawn("tap:results", function()
    local results = Env.remote("TapService", "TapResult")
    Life.connect(results.OnClientEvent, function(result)
        if type(result) == "table" and result.ClientSequence ~= nil then
            tapAnswerCount += 1
            lastAnswer, unanswered = os.clock(), 0
        end
    end)
end)

Life.spawn("tap:auto", function()
    local remote = Env.remote("TapService", "TapRequested")
    local session = 0
    while Life.alive do
        -- Ui.tapDemand: another feature (breaking a creature or a meteor, which taps hit from
        -- 14 studs) needs taps even while auto tap is off.
        if (Ui.on("AutoTap") or Ui.tapDemand)
            and not (Ui.__progressTest and Ui.__progressTest.holdTap) then
            if unanswered >= STALL_TAPS and os.clock() - lastAnswer > STALL_SECONDS then
                sequence = math.max(sequence * 2, sequence + 1000000)
                lastAnswer, unanswered = os.clock(), 0
                resyncs += 1
            end
            sequence += 1
            session += 1
            unanswered += 1
            Env.genv[SEQUENCE_KEY] = sequence
            Env.elevate()
            remote:FireServer({ Auto = false, ClientSequence = sequence, Source = "button" })
            -- Tapping runs under everything else; it only names itself when nothing else has.
            if not Ui.status or Ui.status == "Idle" or Ui.status == "Off" then
                Ui.status = "Auto tapping"
            end
            if session % 11 == 0 then
                tapLabel:SetText(string.format("Tapped %d times this session.%s", session,
                    os.clock() - lastAnswer > STALL_SECONDS and "\nThe server is not answering taps; re-syncing."
                        or resyncs > 0 and string.format(" Re-synced %d times.", resyncs) or ""))
            end
            local rate = math.clamp(tonumber(Options.TapRate.Value) or MAX_RATE, 1, MAX_RATE)
            -- Jitter only lengthens a gap: one under the server's interval is a tap thrown away.
            local gap = math.max(1 / rate, MIN_GAP * 1.04)
            Life.wait(gap * (1 + math.random() * 0.12))
        else
            if Ui.status == "Auto tapping" then
                Ui.status = "Idle"
            end
            Life.wait(0.2)
        end
    end
end)

-- Auto clicker (the game's own) -----------------------------------------------------------------

local clickBox = tab:AddGroupbox({ Side = "Left", Name = "Auto clicker", IconName = "mouse-pointer-click" })
clickBox:AddToggle("AutoClicker", {
    Text = "Enable auto clicker",
    Default = false,
    Tooltip = "Turns on the game's built-in auto clicker (needs the auto-clicker unlock or gamepass).",
})
clickBox:AddLabel("Uses the game's own auto clicker. If you do not own it, the server ignores this.", true)

-- Поиск remote может уступить поток. После него отправляем только АКТУАЛЬНОЕ состояние:
-- запоздавшее включение не должно победить Stop/трейд/ожидание ребёрта.
function Ui.syncNativeClicker()
    local remote = Env.remote("AutoClickService", "AutoClickRequested")
    local P = Ui.__progressTest
    local enabled = Life.alive and Ui.on("AutoClicker")
        and not (P and (P.holdTap or P.stopRequested))
        and not (Env.genv and Env.genv.__handoverPaused)
    Env.elevate()
    remote:FireServer({ Enabled = enabled == true })
end
Ui.Toggles.AutoClicker:OnChanged(function(on)
    if Ui.__progressTest then Ui.syncNativeClicker()
    else Env.fire("AutoClickService", "AutoClickRequested", { Enabled = on == true }) end
end)
-- В тесте Stop all и пауза трейда останавливают и штатный автокликер игры.
Ui.automation("AutoClicker", true)

-- Auto rebirth ---------------------------------------------------------------------------------
--
-- RebirthRequested { Index } buys 5^(Index-1) rebirths, all at the price for your current rebirth
-- count (Shared.Progression.RebirthConfig), so the biggest pack you can afford is the cheapest per
-- rebirth; any single pack can be pinned instead. The game has GetMaximumOptions(world) buttons (14
-- on the main world) and you have unlocked 1 + Upgrades.RebirthButtons of them (RebirthButtonConfig).
-- Every button is listed, but a locked one is never pressed. With the Auto Rebirth skill the request
-- is flagged Auto, exactly as the game's own auto rebirth sends it, and never more often than its
-- 1.5 seconds.

local function shared(...)
    local path = { ... }
    local ok, module = Env.call(function()
        local node = Env.ReplicatedStorage.Shared
        for _, part in ipairs(path) do
            node = node:FindFirstChild(part)
        end
        return node and require(node)
    end)
    return ok and module or nil
end
local RebirthConfig = shared("Progression", "RebirthConfig")
local RebirthButtonConfig = shared("Progression", "RebirthButtonConfig")
local SkillTreeFormula = shared("Progression", "SkillTreeFormula")

local REBIRTH_GAP = 1.5

local function worldOf(data)
    return data and type(data.Progression) == "table" and data.Progression.World or "Main"
end

local function coinsOf(data)
    return tonumber(type(data.Currencies) == "table" and data.Currencies.Coins) or 0
end

-- How many buttons you have unlocked.
local function buttonCount(data)
    local upgrades = type(data.Upgrades) == "table" and data.Upgrades.RebirthButtons or 0
    if RebirthButtonConfig then
        local ok, count = Env.call(function()
            local world = worldOf(data)
            return RebirthButtonConfig.GetOptionCount(RebirthButtonConfig.GetUnlockedCount(upgrades, world), world)
        end)
        if ok and type(count) == "number" then
            return count
        end
    end
    return 1 + math.clamp(math.floor(tonumber(upgrades) or 0), 0, 13)
end

-- How many buttons the game has on this world, unlocked or not.
local function allButtons(data)
    if RebirthButtonConfig then
        local ok, count = Env.call(RebirthButtonConfig.GetMaximumOptions, worldOf(data))
        if ok and type(count) == "number" then
            return count
        end
    end
    return 14
end

local function packAmount(index)
    if RebirthConfig then
        local ok, amount = Env.call(RebirthConfig.GetAmountFromIndex, index)
        if ok and type(amount) == "number" then
            return amount
        end
    end
    return 5 ^ (index - 1)
end

local function packPrice(data, index)
    if not RebirthConfig then
        return nil
    end
    local rebirths = tonumber(type(data.Statistics) == "table" and data.Statistics.Rebirths) or 0
    local ok, price = Env.call(RebirthConfig.GetPrice, packAmount(index), rebirths)
    return ok and type(price) == "number" and price or nil
end

-- The biggest unlocked pack you can afford now, or nil.
local function bestPack(data)
    local coins = coinsOf(data)
    for index = buttonCount(data), 1, -1 do
        local price = packPrice(data, index)
        if price and price <= coins then
            return index
        end
    end
    return nil
end

local function hasAutoRebirth(data)
    if not SkillTreeFormula then
        return false
    end
    local ok, value = Env.call(SkillTreeFormula.HasAutoRebirth, data)
    return ok and value == true
end

local function short(n)
    for _, unit in ipairs({ { 1e33, "Dc" }, { 1e30, "No" }, { 1e27, "Oc" }, { 1e24, "Sp" }, { 1e21, "Sx" }, { 1e18, "Qi" },
        { 1e15, "Q" }, { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" } }) do
        if n >= unit[1] then
            return string.format("%.1f%s", n / unit[1], unit[2])
        end
    end
    return tostring(math.floor(n))
end

local BIGGEST = "Biggest I can afford"
local packLabels, packIndex = { BIGGEST }, {}
for index = 1, allButtons(Env.data()) do
    local label = string.format("x%s rebirths (button %d)", short(packAmount(index)), index)
    packLabels[#packLabels + 1] = label
    packIndex[label] = index
end

local rebirthBox = tab:AddGroupbox({ Side = "Right", Name = "Rebirth", IconName = "rotate-ccw" })
rebirthBox:AddToggle("AutoRebirth", {
    Text = "Auto rebirth",
    Default = false,
    Tooltip = "Presses the chosen rebirth pack whenever you can afford it, as often as the game allows.",
})
Ui.automation("AutoRebirth", true)
rebirthBox:AddDropdown("RebirthPack", {
    Text = "Pack",
    Values = packLabels,
    Default = BIGGEST,
    Tooltip = "Every rebirth button in the game. 'Biggest I can afford' is the cheapest per rebirth, since a pack is priced at your current rebirth count. A pinned pack waits until you can afford it; a locked one (more come from the Rebirth Buttons upgrade) is never pressed.",
})
local rebirthLabel = rebirthBox:AddLabel("Auto rebirth is off.", true)

-- The pack to press now, or nil and why not.
local function choosePack(data)
    local pinned = packIndex[Options.RebirthPack.Value or ""]
    if not pinned then
        local index = bestPack(data)
        return index, index == nil and "saving coins for x1" or nil
    end
    local unlocked = buttonCount(data)
    if pinned > unlocked then
        return nil, string.format("button %d is locked (you have %d; the Rebirth Buttons upgrade unlocks more)", pinned, unlocked)
    end
    local price = packPrice(data, pinned)
    if not price then
        return nil, "rebirth prices are unavailable"
    end
    if price > coinsOf(data) then
        return nil, string.format("saving for x%s (%s coins)", short(packAmount(pinned)), short(price))
    end
    return pinned
end

local lastRebirth, rebirthed = -math.huge, 0
local function rebirthNow(data)
    if Ui.__progressTest then return false, "rebirth controlled by 30M test" end
    local index, why = choosePack(data)
    if not index then
        return false, why
    end
    lastRebirth = os.clock()
    local payload = hasAutoRebirth(data) and { Auto = true, Index = index } or { Index = index }
    Env.fire("RebirthService", "RebirthRequested", payload)
    rebirthed += packAmount(index)
    return true, index
end

rebirthBox:AddButton({
    Text = "Rebirth now",
    Func = function()
        local data = Env.data()
        if not data then
            return
        end
        local ok, result = rebirthNow(data)
        Ui.notify("Tap Simulator", ok and string.format("Rebirthing x%s (button %d).", short(packAmount(result)), result)
            or ("Not rebirthing: " .. tostring(result) .. "."), 3)
    end,
})

Life.loop("tap:rebirth", 0.25, function()
    -- Авто-ребёрт в тесте ведёт один ограниченный контроллер с проверкой реальных данных.
    -- Даже старая сохранённая настройка AutoRebirth не запустит второй цикл.
    if Ui.__progressTest then
        rebirthLabel:SetText("Controlled by the progression test.")
        return
    end
    local data = Env.data()
    if not data then
        return
    end
    local index, why = choosePack(data)
    local upcoming = index and string.format("x%s for %s coins (button %d of %d)", short(packAmount(index)),
        short(packPrice(data, index) or 0), index, buttonCount(data)) or why
    if not Ui.on("AutoRebirth") then
        rebirthLabel:SetText("Off. Next: " .. tostring(upcoming) .. ".")
        return
    end
    if index and os.clock() - lastRebirth >= REBIRTH_GAP then
        rebirthNow(data)
    end
    rebirthLabel:SetText(string.format("%s this session. Next: %s.", short(rebirthed), tostring(upcoming)))
end)

local function progressPack(data, remaining)
    if not RebirthConfig or type(RebirthConfig.GetPrice) ~= "function" then
        return nil, nil, nil, "нет игрового RebirthConfig"
    end
    local stats = type(data) == "table" and data.Statistics
    local rb = type(stats) == "table" and tonumber(stats.Rebirths) or nil
    local coins = type(data) == "table" and coinsOf(data) or nil
    if not rb or rb ~= rb or rb < 0 or not coins or coins ~= coins then
        return nil, nil, nil, "нет достоверных ребёртов или монет"
    end
    local available = buttonCount(data)
    if type(available) ~= "number" or available ~= available or available < 1 then
        return nil, nil, nil, "число кнопок ребёрта неизвестно"
    end
    available = math.clamp(math.floor(available), 1, 64)
    local validPrice = false
    for index = available, 1, -1 do
        local amount = packAmount(index)
        if type(amount) == "number" and amount == amount and amount >= 1
            and amount < math.huge and math.floor(amount) == amount and amount <= remaining then
            local price = packPrice(data, index)
            if type(price) == "number" and price == price and price > 0 and price < math.huge then
                validPrice = true
                if price <= coins then return index, amount, price, nil end
            end
        end
    end
    return nil, nil, nil, validPrice and "unaffordable" or "игровая цена ребёрта недоступна"
end

-- Только отчёт: выбор пакета и формулы ребёрта v5 здесь не меняются.
-- Два разных вызова встречаются в сторонних скриптах; расхождение само по себе не
-- доказывает, какой из них верен для этой версии сервера.
local function progressExplain(data)
    if type(data) ~= "table" then return "нет данных" end
    local upgrades = type(data.Upgrades) == "table" and data.Upgrades.RebirthButtons or 0
    local world = worldOf(data)
    local selectedCount = buttonCount(data)
    local direct, nested = nil, nil
    if RebirthButtonConfig then
        local ok1, value1 = Env.call(function()
            return RebirthButtonConfig.GetOptionCount(upgrades, world)
        end)
        if ok1 and type(value1) == "number" and value1 == value1 and value1 >= 0 and value1 < math.huge then direct = value1 end
        local ok2, value2 = Env.call(function()
            return RebirthButtonConfig.GetOptionCount(RebirthButtonConfig.GetUnlockedCount(upgrades, world), world)
        end)
        if ok2 and type(value2) == "number" and value2 == value2 and value2 >= 0 and value2 < math.huge then nested = value2 end
    end
    local index, amount, price, reason = progressPack(data, math.huge)
    local chosen = index and string.format("сейчас кнопка=%s, x%s, цена=%s", tostring(index), tostring(amount), tostring(price))
        or (reason == "unaffordable" and "сейчас монет на ребёрт не хватает" or ("сейчас пакет не выбран: " .. tostring(reason)))
    local sampleIndex = index or 1
    local withoutPlayer = packPrice(data, sampleIndex)
    local stats = type(data.Statistics) == "table" and data.Statistics or nil
    local rebirths = stats and tonumber(stats.Rebirths) or nil
    local withPlayer = nil
    if rebirths and RebirthConfig and type(RebirthConfig.GetPrice) == "function" then
        local ok, value = Env.call(RebirthConfig.GetPrice, packAmount(sampleIndex), rebirths, Env.LocalPlayer)
        if ok and type(value) == "number" and value == value and value >= 0 and value < math.huge then withPlayer = value end
    end
    local nextNote = ""
    local maxOptions = allButtons(data)
    local nextIndex = index and index + 1 or 1
    if type(selectedCount) == "number" and selectedCount == selectedCount and selectedCount >= 1
        and type(maxOptions) == "number" and maxOptions == maxOptions and maxOptions >= nextIndex and nextIndex <= 64 then
        local nextAmount = packAmount(nextIndex)
        local nextPrice = packPrice(data, nextIndex)
        local why
        if nextIndex > selectedCount then why = "закрыта по текущему расчёту"
        elseif not nextPrice then why = "цена недоступна"
        elseif nextPrice > coinsOf(data) then why = "не хватает монет"
        else why = "доступна по текущей оценке" end
        nextNote = string.format("; следующая кнопка=%s, x%s, цена=%s (%s)",
            tostring(nextIndex), tostring(nextAmount), tostring(nextPrice or "нет"), why)
    end
    local extra = string.format("кнопок: уровень=%s, принято=%s, прямой=%s, вложенный=%s; %s%s; цена примера без/с игроком=%s/%s",
        tostring(upgrades), tostring(selectedCount), tostring(direct or "нет"), tostring(nested or "нет"),
        chosen, nextNote, tostring(withoutPlayer or "нет"), tostring(withPlayer or "нет"))
    if direct and nested and direct ~= nested then extra ..= "; методы расчёта кнопок расходятся" end
    if withoutPlayer and withPlayer and withoutPlayer ~= withPlayer then extra ..= "; методы расчёта цены расходятся" end
    return extra
end

return {
    progressPack = progressPack,
    progressExplain = progressExplain,
    hasAutoRebirth = hasAutoRebirth,
    tapAnswers = function() return tapAnswerCount end,
}
end
__modules["features/tradepost"] = function(use) -- src/games/tapsim/features/tradepost.luau
-- Pets tab (right): a trade post for Discord, built from your rarest pets and copied to the
-- clipboard, ready to paste into a trading channel.
--
-- Lists every owned Secret and every other pet above 10M Power, one pet per line. Posts are paged
-- to preserve each pet's serial while staying within the trading channel's message limits.
--
-- Trading channels auto-delete a post that has more than 18 lines, 18 emojis or 30% capitals, a
-- line repeated more than 3 times, or blank lines and runs of spaces. The post is checked against
-- all of those before it is copied, with no blank lines, no double spaces and no line used twice.
-- Posts list pets only (the trading rules: pets and Tokens, no cross-trading), so anything that
-- mentions Robux or real money is not copied.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local Options = Ui.Options
local tab = Ui.Tabs.Pets

local function shared(...)
    local path = { ... }
    local ok, module = Env.call(function()
        local node = Env.ReplicatedStorage.Shared
        for _, part in ipairs(path) do
            node = node:FindFirstChild(part)
        end
        return node and require(node)
    end)
    return ok and type(module) == "table" and module or nil
end

local PetOdds = shared("Pets", "PetOdds")
local PetPower = shared("Pets", "PetPower")
local IndexCatalog = shared("Pets", "PetIndexCatalog")
local TIER_NAMES = IndexCatalog and IndexCatalog.TierNames
    or { Normal = "Normal", Golden = "Golden", Diamond = "Diamond", Shiny = "Rainbow" }

local LIMITS = { lines = 18, emojis = 18, capitals = 0.3, chars = 2000 }
local HEADERS = {
    ["Looking for offers"] = "📢 Looking for offers on these pets:",
    ["Trading"] = "🤝 Trading these pets:",
}
-- Cross-trading words. Premium Tokens are fine, but by value, never as Robux.
local BANNED = { "robux", "rbx", "r%$", "paypal", "cashapp", "real money", "usd", "nitro", "gift card" }

local box = tab:AddGroupbox({ Side = "Right", Name = "Trade post", IconName = "megaphone" })
box:AddDropdown("TradePostKind", {
    Text = "Post",
    Values = { "Looking for offers", "Trading" },
    Default = "Looking for offers",
})
box:AddSlider("TradePostCount", {
    Text = "Pets per post",
    Default = 12,
    Min = 1,
    Max = 15,
    Rounding = 0,
    Tooltip = "Every owned Secret is included, plus other pets above 10,000,000 Power. Each pet gets its own line.",
})
box:AddInput("TradePostWant", {
    Text = "In return",
    Default = "pets or Tokens",
    Placeholder = "e.g. Secret pets or Tokens",
    Finished = true,
    ClearTextOnFocus = false,
    Tooltip = "What you want for them. The trading rules want this on every post. Premium Tokens by their value, never Robux.",
})
box:AddInput("TradePostNote", {
    Text = "Last line (optional)",
    Default = "",
    Placeholder = "e.g. DM me or reply here",
    Finished = true,
    ClearTextOnFocus = false,
})

-- Formatting -------------------------------------------------------------------------------------

-- One line of free text from an input: no line breaks, no runs of spaces.
local function clean(text)
    return (tostring(text or ""):gsub("[\r\n\t]", " "):gsub("  +", " "):gsub("^ ", ""):gsub(" $", ""))
end

local function emojiFor(pet)
    if pet.Mutation == "Shiny" then
        return "✨"
    elseif pet.Tier == "Shiny" then
        return "🌈"
    elseif pet.Tier == "Diamond" then
        return "💎"
    elseif pet.Tier == "Golden" then
        return "⭐"
    elseif type(pet.Rarity) == "string" and pet.Rarity:sub(1, 6) == "Secret" then
        return "🔮"
    elseif pet.Rarity == "Godly" then
        return "👑"
    end
    return "🔥"
end

local function displayName(pet)
    local parts = {}
    if type(pet.Mutation) == "string" and pet.Mutation ~= "" then
        parts[#parts + 1] = pet.Mutation
    end
    local tier = TIER_NAMES[pet.Tier]
    if tier and tier ~= "Normal" then
        parts[#parts + 1] = tier
    end
    parts[#parts + 1] = tostring(pet.Name)
    return clean(table.concat(parts, " "))
end

-- The game's 1-in-X for this exact pet (tier and mutation included), or nil when it has none.
local function oddsOf(pet)
    if not (PetOdds and type(pet.Name) == "string") then
        return nil
    end
    local ok, base = Env.call(PetOdds.OneIn, pet.Name)
    if not (ok and type(base) == "number") then
        return nil
    end
    local ok2, odds = Env.call(PetOdds.Variant, base, pet.Tier, pet.Mutation, pet.Name)
    return ok2 and type(odds) == "number" and odds or base
end

local POWER_THRESHOLD = 10000000

local function isSecret(pet)
    local rarity = type(pet.Rarity) == "string" and pet.Rarity:lower() or ""
    -- Godly — редкость выше секретов (30M Phantom Serpent и подобные). Считаем их тоже:
    -- иначе аккаунт с Godly показывал "секретов 0", хотя поймал его.
    return rarity:find("secret", 1, true) ~= nil or rarity:find("godly", 1, true) ~= nil
end

local function formatNumber(number)
    local value = tostring(math.floor((tonumber(number) or 0) + 0.5))
    local formatted, count
    repeat
        formatted, count = value:gsub("^(-?%d+)(%d%d%d)", "%1,%2")
        value = formatted
    until count == 0
    return value
end

-- Keep every qualifying pet separate so its own serial and power are shown.
local function qualifyingPets(data)
    local pets = type(data) == "table" and type(data.Pets) == "table" and data.Pets or {}
    local owned = type(pets.Owned) == "table" and pets.Owned or {}
    local ownedPowers
    if PetPower and type(PetPower.GetOwnedPowers) == "function" then
        local ok, result = Env.call(PetPower.GetOwnedPowers, owned)
        if ok and type(result) == "table" then
            ownedPowers = result
        end
    end
    local result = {}
    for id, pet in pairs(owned) do
        local power = ownedPowers and tonumber(ownedPowers[id])
        if not power and PetPower and type(PetPower.GetPercentage) == "function" and type(PetPower.Get) == "function" then
            local okPercentage, percentage = Env.call(PetPower.GetPercentage, pet)
            if okPercentage and percentage == nil then
                local okPower, value = Env.call(PetPower.Get, pet)
                power = okPower and tonumber(value) or nil
            end
        end
        if type(pet) == "table" and type(pet.Name) == "string"
            and (isSecret(pet) or (power and power > POWER_THRESHOLD)) then
            result[#result + 1] = {
                pet = pet,
                id = tostring(id),
                power = power,
                serial = tonumber(pet.Serial) or tonumber(pet.LeaderboardSerial),
                odds = oddsOf(pet),
                secret = isSecret(pet),
            }
        end
    end
    table.sort(result, function(a, b)
        if a.secret ~= b.secret then
            return a.secret
        end
        if a.odds and b.odds and a.odds ~= b.odds then
            return a.odds > b.odds
        end
        if a.odds ~= nil and b.odds == nil then
            return true
        elseif a.odds == nil and b.odds ~= nil then
            return false
        end
        if (tonumber(a.pet.Power) or 0) ~= (tonumber(b.pet.Power) or 0) then
            return (tonumber(a.pet.Power) or 0) > (tonumber(b.pet.Power) or 0)
        end
        return tostring(a.serial or a.id) < tostring(b.serial or b.id)
    end)
    return result
end

local function petLine(entry)
    local pet = entry.pet
    local rarity = type(pet.Rarity) == "string" and pet.Rarity or "Rarity unknown"
    local serial = entry.serial and ("#" .. formatNumber(entry.serial))
        or ("pending (ID " .. entry.id:sub(-8) .. ")")
    local odds = entry.odds and ("1 in " .. formatNumber(entry.odds)) or "unavailable"
    local power = entry.power and formatNumber(entry.power) or "unavailable"
    local text = emojiFor(pet) .. " **" .. rarity .. "** · " .. displayName(pet)
        .. " · Serial **" .. serial .. "** · Power **" .. power .. "** · Odds " .. odds
    return text
end

-- The rule check ---------------------------------------------------------------------------------

local function isEmoji(code)
    return code >= 0x1F000 or (code >= 0x2600 and code <= 0x27BF) or (code >= 0x2B00 and code <= 0x2BFF)
end

-- What the post would be deleted for, or nothing. Counts the way the channel's filters read it.
local function problems(text)
    local found = {}
    local lines = string.split(text, "\n")
    if #lines > LIMITS.lines then
        found[#found + 1] = string.format("%d lines (max %d)", #lines, LIMITS.lines)
    end
    local emojis, upper, letters = 0, 0, 0
    for _, code in utf8.codes(text) do
        if isEmoji(code) then
            emojis += 1
        elseif code >= 65 and code <= 90 then
            upper += 1
            letters += 1
        elseif code >= 97 and code <= 122 then
            letters += 1
        end
    end
    if emojis > LIMITS.emojis then
        found[#found + 1] = string.format("%d emojis (max %d)", emojis, LIMITS.emojis)
    end
    if letters > 0 and upper / letters > LIMITS.capitals then
        found[#found + 1] = string.format("%d%% capitals (max 30%%)", math.floor(upper / letters * 100 + 0.5))
    end
    local seen = {}
    for _, line in ipairs(lines) do
        if line:match("^%s*$") then
            found[#found + 1] = "a blank line"
            break
        end
        seen[line] = (seen[line] or 0) + 1
        if seen[line] == 2 then
            found[#found + 1] = "a repeated line"
        end
    end
    if text:find("  ") then
        found[#found + 1] = "a run of spaces"
    end
    if #text > LIMITS.chars then
        found[#found + 1] = string.format("%d characters (Discord's max is %d)", #text, LIMITS.chars)
    end
    local lower = text:lower()
    for _, word in ipairs(BANNED) do
        if lower:find(word) then
            found[#found + 1] = "a mention of Robux or real money (cross-trading)"
            break
        end
    end
    return found
end

local page = 1

local function buildPost()
    local pets = qualifyingPets(Env.data())
    if #pets == 0 then
        return nil, { "no owned Secrets or pets above 10,000,000 Power" }, 0, 0
    end
    local want = clean(Options.TradePostWant.Value)
    local note = clean(Options.TradePostNote.Value)
    local perPage = math.clamp(math.floor(tonumber(Options.TradePostCount.Value) or 12), 1, 15)
    local totalPages = math.ceil(#pets / perPage)
    page = math.clamp(page, 1, totalPages)
    local first = (page - 1) * perPage + 1
    local last = math.min(first + perPage - 1, #pets)
    local lines = { HEADERS[Options.TradePostKind.Value] or HEADERS["Looking for offers"] }
    for index = first, last do
        lines[#lines + 1] = petLine(pets[index])
    end
    lines[#lines + 1] = "**In return:** " .. (want ~= "" and want or "offers")
    if note ~= "" then
        lines[#lines + 1] = note
    end
    local text = table.concat(lines, "\n")
    return text, problems(text), totalPages, #pets, first, last
end

local preview = box:AddLabel("", true)

box:AddButton({
    Text = "Previous post",
    Func = function()
        page = math.max(1, page - 1)
    end,
})

box:AddButton({
    Text = "Next post",
    Func = function()
        page += 1
    end,
})

box:AddButton({
    Text = "Copy current post",
    Func = function()
        local text, found, totalPages = buildPost()
        if not text then
            Ui.notify("Trade post", "No owned Secrets or pets above 10,000,000 Power.", 4)
        elseif #found > 0 then
            Ui.notify("Trade post", "Not copied: it would be deleted for " .. table.concat(found, ", ") .. ".", 8)
        elseif not Env.setClipboard then
            Ui.notify("Trade post", "Your executor cannot copy to the clipboard. The post is printed in the console (F9).", 8)
            print(text)
        else
            Env.setClipboard(text)
            Ui.notify("Trade post", string.format("Copied post %d of %d. Send each post as a separate message.", page, totalPages), 5)
        end
    end,
    Tooltip = "Copies only this page. Send it as one separate Discord message; each page is checked against the channel rules.",
})

Life.loop("tradepost:preview", 3, function()
    local text, found, totalPages, totalPets, first, last = buildPost()
    if not text then
        preview:SetText("No pets to list.")
        return
    end
    local lines = #string.split(text, "\n")
    local status = #found == 0 and string.format("Passes the channel rules (%d of %d lines).", lines, LIMITS.lines)
        or ("Would be deleted for " .. table.concat(found, ", ") .. ".")
    local pageInfo = string.format("Post %d/%d · Pets %d–%d of %d qualifying", page, totalPages, first, last, totalPets)
    local oddsInfo = not PetOdds and "Odds data unavailable; rarity and power are still shown.\n" or ""
    preview:SetText(pageInfo .. "\n" .. oddsInfo .. text .. "\n\n" .. status)
end)

return {}
end
__modules["features/treats"] = function(use) -- src/games/tapsim/features/treats.luau
-- Pets tab (right): feed treats to the team. Treats (from digging, quests and drops) give pet XP,
-- and a pet's level multiplies its power, so they are worth more on the pets you actually use.
--
-- ItemService.UseOnPet { Item, PetId, Amount } is what the game sends when you drag a treat onto a
-- pet; it answers { Success, Kind, Amount, LevelsGained, Level, ... }. Only items the game marks as
-- pet treats or pet levels (Shared.Items.ItemBehaviorConfig) are offered, one at a time to the
-- lowest-level equipped pet that is below its rarity's cap (Shared.Pets.PetLevelConfig), so the
-- whole team climbs together. Pet levels unlock once the bridge is lowered.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local Options = Ui.Options
local tab = Ui.Tabs.Pets

local ItemBehaviorConfig, PetLevelConfig
do
    local ok, items = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Items.ItemBehaviorConfig)
    end)
    ItemBehaviorConfig = ok and type(items) == "table" and items or nil
    local ok2, levels = Env.call(function()
        return require(Env.ReplicatedStorage.Shared.Pets.PetLevelConfig)
    end)
    PetLevelConfig = ok2 and type(levels) == "table" and levels or nil
end

local TREAT_KINDS = { PetTreat = true, PetLevels = true }
-- The plain XP treats digging and quests hand out; fruits and shards are rarer and left to you.
local DEFAULT_PICKS = { RegularTreat = true, BagOfTreats = true }
local PACE = 0.35

local treatNames, defaults = {}, {}
for name, behavior in pairs(ItemBehaviorConfig or {}) do
    if type(behavior) == "table" and TREAT_KINDS[behavior.Kind] and behavior.Availability == "Active" then
        treatNames[#treatNames + 1] = name
    end
end
table.sort(treatNames)
for _, name in ipairs(treatNames) do
    if DEFAULT_PICKS[name] then
        defaults[#defaults + 1] = name
    end
end

local box = tab:AddGroupbox({ Side = "Right", Name = "Treats", IconName = "cookie" })
box:AddToggle("AutoTreats", {
    Text = "Auto feed treats",
    Default = false,
    Tooltip = "Feeds the chosen treats to your equipped pets, lowest level first, skipping pets at their level cap.",
})
Ui.automation("AutoTreats", true)
box:AddDropdown("TreatPicks", {
    Text = "Use these",
    Values = #treatNames > 0 and treatNames or { "RegularTreat", "BagOfTreats" },
    Multi = true,
    Default = defaults,
    Tooltip = "Treat and Bag of Treats come from digging. Fruits, Golden Apples and shards are rarer; pick them only if you mean to spend them.",
})
local label = box:AddLabel("Auto feed is off.", true)

local function maxLevel(pet)
    if PetLevelConfig then
        local ok, cap = Env.call(PetLevelConfig.GetMaxLevel, pet.Rarity or "Common")
        if ok and type(cap) == "number" then
            return cap
        end
    end
    return 50
end

-- Equipped pets below their cap, lowest level (then least XP) first.
local function hungryPets(data)
    local pets = type(data.Pets) == "table" and data.Pets
    if not pets or type(pets.Equipped) ~= "table" or type(pets.Owned) ~= "table" then
        return {}
    end
    local list = {}
    for _, id in pairs(pets.Equipped) do
        local pet = pets.Owned[id]
        if type(pet) == "table" and (tonumber(pet.Level) or 1) < maxLevel(pet) then
            list[#list + 1] = { id = id, pet = pet }
        end
    end
    table.sort(list, function(a, b)
        local la, lb = tonumber(a.pet.Level) or 1, tonumber(b.pet.Level) or 1
        if la ~= lb then
            return la < lb
        end
        return (tonumber(a.pet.XP) or 0) < (tonumber(b.pet.XP) or 0)
    end)
    return list
end

local session = { fed = 0, levels = 0, used = {} }
local refused = {} -- item .. "|" .. pet id -> retry after (os.clock)
local note = ""

local function feedOnce(data)
    local owned = type(data.Items) == "table" and type(data.Items.Owned) == "table" and data.Items.Owned or {}
    local picks = Options.TreatPicks.Value or {}
    local pets = hungryPets(data)
    if #pets == 0 then
        return false, "Every equipped pet is at its level cap."
    end
    for _, item in ipairs(treatNames) do
        if picks[item] and (tonumber(owned[item]) or 0) > 0 then
            for _, entry in ipairs(pets) do
                local key = item .. "|" .. entry.id
                if (refused[key] or 0) <= os.clock() then
                    local ok, result = Env.invoke("ItemService", "UseOnPet", { Item = item, PetId = entry.id, Amount = 1 })
                    if ok and type(result) == "table" and result.Success == true then
                        session.fed += 1
                        session.levels += tonumber(result.LevelsGained) or 0
                        session.used[item] = (session.used[item] or 0) + 1
                        note = string.format("Last: %s on %s (level %s).", item, tostring(entry.pet.Name), tostring(result.Level or entry.pet.Level))
                        return true
                    end
                    refused[key] = os.clock() + 60
                    note = string.format("%s on %s refused: %s.", item, tostring(entry.pet.Name),
                        tostring(type(result) == "table" and (result.Reason or result.Error) or result))
                end
            end
        end
    end
    return false, "No chosen treats left."
end

Life.spawn("pets:treats", function()
    while Life.alive do
        local data = Env.data()
        local wait = 1
        if not Ui.on("AutoTreats") then
            label:SetText("Off.")
        elseif not ItemBehaviorConfig then
            label:SetText("The game's item config could not be read.")
        elseif data and PetLevelConfig and type(data.Progression) == "table" and data.Progression.BridgeLowered ~= true then
            label:SetText("Pet levels unlock once the bridge is lowered.")
        elseif data then
            local fed, why = feedOnce(data)
            local parts = {}
            for item, count in pairs(session.used) do
                parts[#parts + 1] = string.format("%d %s", count, item)
            end
            table.sort(parts)
            label:SetText(string.format("%s%d treats fed this session (+%d levels)%s.%s",
                fed and "" or (tostring(why) .. "\n"), session.fed, session.levels,
                #parts > 0 and (": " .. table.concat(parts, ", ")) or "", note ~= "" and ("\n" .. note) or ""))
            wait = fed and PACE or 3
        end
        Life.wait(wait)
    end
end)

return {}
end
__modules["features/upgrades"] = function(use) -- src/games/tapsim/features/upgrades.luau
-- Upgrades (Tapping tab, right): buys the tap upgrades for you. ClickMultiplier and CriticalChance
-- raise what every tap is worth, so keeping them maxed is the biggest lever after auto tap itself.
--
-- UpgradeService.Purchase { Name } answers { Success, Reason, Current }. The server rate-limits
-- purchases and locks some behind zones (Reason "RateLimited" / "ZoneLocked"), so this paces itself
-- and skips what it cannot buy yet instead of hammering a locked upgrade.

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local Options = Ui.Options
local tab = Ui.Tabs.Tapping
local box = tab:AddGroupbox({ Side = "Right", Name = "Upgrades", IconName = "trending-up" })

-- The buyable upgrades, from the game's own config when it is readable.
local ORDER = { "FreeAutoClicker", "ClickMultiplier", "HatchSpeed", "CriticalChance", "AutoClickerSpeed", "Teleport" }
local ok, cfg = Env.call(function()
    return require(Env.ReplicatedStorage.Shared.Progression.UpgradeConfig)
end)
if ok and type(cfg) == "table" and type(cfg.Order) == "table" and #cfg.Order > 0 then
    ORDER = cfg.Order
end

local function currencyIn(def)
    if type(def) ~= "table" then return nil end
    local result, mixed, seen = nil, false, {}
    local function add(value)
        if type(value) ~= "string" or value == "" then return end
        local normalized = value:lower():gsub("%s+", "")
        if result and result ~= normalized then mixed = true else result = normalized end
    end
    local function fields(value)
        for _, key in ipairs({ "Currency", "CostCurrency", "PriceCurrency", "CurrencyName" }) do
            local v = value[key]
            if v ~= nil then
                if type(v) ~= "string" or v == "" then mixed = true else add(v) end
            end
        end
        for _, key in ipairs({ "Gems", "Coins", "Tokens", "PaidTokens", "Robux", "CandyCorn", "Tickets", "EventCurrency" }) do
            local v = value[key]
            if v ~= nil and v ~= false then
                local n = tonumber(v)
                if not n or n < 0 or n ~= n or n == math.huge then mixed = true
                elseif n > 0 then add(key) end
            end
        end
    end
    local function costs(value, depth)
        if type(value) ~= "table" or seen[value] then return end
        if depth > 6 then mixed = true; return end
        seen[value] = true
        fields(value)
        for _, child in pairs(value) do
            if type(child) == "table" then costs(child, depth + 1) end
        end
    end
    fields(def)
    for _, key in ipairs({ "Cost", "Price", "Costs", "Prices" }) do
        local v = def[key]
        if type(v) == "table" then costs(v, 0)
        elseif type(v) == "string" and not tonumber(v) then mixed = true end
    end
    return mixed and "mixed currencies" or result
end
local function upgradeCurrency(name)
    if not ok or type(cfg) ~= "table" then return nil end
    local containers = { cfg.Upgrades, cfg.Definitions, cfg.Items, cfg.ByName, cfg }
    local result, mixed = nil, false
    local function record(found)
        if found == "mixed currencies" then mixed = true
        elseif found then
            if result and result ~= found then mixed = true else result = found end
        end
    end
    for i = 1, 5 do
        local group = containers[i]
        if type(group) == "table" then
            record(currencyIn(group[name]))
            for _, entry in ipairs(group) do
                if type(entry) == "table" and (entry.Name == name or entry.Id == name) then
                    record(currencyIn(entry))
                end
            end
        end
    end
    return mixed and "mixed currencies" or result -- валюта неизвестна или неоднозначна: пропускаем
end
local function upgradeRelevant(name)
    local function forbidden(text)
        if type(text) ~= "string" then return false end
        local normalized = text:lower():gsub("[^%w]", "")
        for _, word in ipairs({ "fish", "bait", "catch", "potion", "brew", "enchant" }) do
            if normalized:find(word, 1, true) then return true end
        end
        return false
    end
    if forbidden(name) then return false end
    local function badDef(def)
        if type(def) ~= "table" then return false end
        for _, key in ipairs({ "Name", "Id", "DisplayName", "Title", "Description", "Tooltip", "Category" }) do
            if forbidden(def[key]) then return true end
        end
        local meta = def.Data
        if type(meta) == "table" then
            for _, key in ipairs({ "Name", "Id", "DisplayName", "Title", "Description", "Tooltip", "Category" }) do
                if forbidden(meta[key]) then return true end
            end
        end
        return false
    end
    if ok and type(cfg) == "table" then
        local containers = { cfg.Upgrades, cfg.Definitions, cfg.Items, cfg.ByName, cfg }
        for i = 1, 5 do
            local group = containers[i]
            if type(group) == "table" then
                if badDef(group[name]) then return false end
                for _, entry in ipairs(group) do
                    if type(entry) == "table" and (entry.Name == name or entry.Id == name) and badDef(entry) then return false end
                end
            end
        end
    end
    return true
end
local function gemUpgrade(name)
    local currency = upgradeCurrency(name)
    return type(currency) == "string" and currency:lower():gsub("%s+", "") == "gems" and upgradeRelevant(name)
end

box:AddToggle("AutoUpgrade", {
    Text = "Auto buy upgrades",
    Default = false,
    Tooltip = "Buys the chosen upgrades whenever you can afford one. Skips upgrades locked to a zone you have not reached.",
})
Ui.automation("AutoUpgrade", true)
box:AddDropdown("UpgradePicks", {
    Text = "Buy these",
    Values = ORDER,
    Multi = true,
    Default = ORDER, -- everything by default
    Tooltip = "ClickMultiplier and CriticalChance pay back fastest for a tapper.",
})
local label = box:AddLabel("Auto buy is off.", true)

local PACE = 0.4 -- seconds between purchase attempts (the server rate-limits)
local bought, blocked, upgradeCursor = 0, {}, 1
local knownGem, knownOther, forbidden, unknown, unknownNames = 0, 0, 0, 0, {}
for _, name in ipairs(ORDER) do
    local currency = upgradeCurrency(name)
    if not upgradeRelevant(name) then forbidden += 1
    elseif gemUpgrade(name) then knownGem += 1 elseif currency then knownOther += 1 else
        unknown += 1
        if #unknownNames < 8 then unknownNames[#unknownNames + 1] = tostring(name) end
    end
end
local configShape = {}
if unknown > 0 and ok and type(cfg) == "table" then
    for key, value in pairs(cfg) do
        if type(key) == "string" then configShape[#configShape + 1] = key .. ":" .. type(value) end
    end
    table.sort(configShape)
    while #configShape > 12 do table.remove(configShape) end
end
local function reportUpgrades(message)
    local P = Ui.__progressTest
    if P then
        P.gemWork = P.gemWork or {}
        P.gemWork.upgrades = string.format("Gems=%d, другая=%d, запрещено=%d, валюта неизвестна=%d%s, куплено=%d, %s",
            knownGem, knownOther, forbidden, unknown, #unknownNames > 0 and (" [" .. table.concat(unknownNames, ",") .. "]") or "",
            bought, tostring(message))
        if #configShape > 0 then P.gemWork.upgrades ..= " | ключи конфига=" .. table.concat(configShape, ",") end
    end
end
reportUpgrades("неподтверждённые валюты пропускаю")

Life.spawn("tap:upgrades", function()
    while Life.alive do
        if not Ui.on("AutoUpgrade") or (Ui.__progressTest and (Ui.__progressTest.holdUpgrades
            or Ui.__progressTest.phase ~= "rebirth" or Ui.__progressTest.stopRequested
            or Ui.__progressTest.upgradeUncertain or Ui.__progressTest.farmThresholdReached)) then
            Life.wait(0.3)
            continue
        end
        local picks = Options.UpgradePicks.Value or {}
        local progressed = false
        local startIndex = upgradeCursor
        for step = 0, #ORDER - 1 do
            local index = (startIndex - 1 + step) % #ORDER + 1
            local name = ORDER[index]
            if not (Life.alive and Ui.on("AutoUpgrade"))
                or (Ui.__progressTest and (Ui.__progressTest.holdUpgrades or Ui.__progressTest.stopRequested
                    or Ui.__progressTest.upgradeUncertain or Ui.__progressTest.eggFixed or Ui.__progressTest.rebirthLocked
                    or Ui.__progressTest.phase ~= "rebirth" or Ui.__progressTest.farmThresholdReached))
                or (Env.genv and Env.genv.__handoverPaused) then
                upgradeCursor = index
                break
            end
            upgradeCursor = index % #ORDER + 1
            if picks[name] and (not Ui.__progressTest or gemUpgrade(name)) then
                local progress = Ui.__progressTest
                local invoked, ok2, res
                if progress then
                    progress.upgradeInFlight = true
                    invoked, ok2, res = pcall(Env.invokeGuarded, "UpgradeService", "Purchase", function()
                        return Life.alive and Ui.__progressTest == progress and progress.phase == "rebirth" and progress.gemReady
                            and not progress.holdUpgrades and not progress.eggFixed and not progress.rebirthLocked and not progress.stopRequested
                            and not progress.farmThresholdReached and not progress.upgradeUncertain and Ui.on("AutoUpgrade") and gemUpgrade(name)
                            and not (Env.genv and Env.genv.__handoverPaused)
                    end, { Name = name })
                else
                    invoked, ok2, res = pcall(Env.invoke, "UpgradeService", "Purchase", { Name = name })
                end
                if progress then
                    progress.upgradeInFlight = false
                    local unavailable = invoked and not ok2 and res == "ts30_unavailable_before_send"
                    local cancelled = invoked and not ok2 and res == "ts30_cancelled_before_send"
                    if unavailable then
                        progress.upgradeRetryAt = os.clock() + 60
                        reportUpgrades("сервис недоступен до отправки; повтор позже")
                        if type(progress.log) == "function" then pcall(progress.log, "сервис улучшений недоступен; продолжу фарм и повторю позже") end
                    end
                    if not cancelled and not unavailable and (not invoked or not ok2 or type(res) ~= "table"
                        or (type(res.Success) ~= "boolean" and type(res.Reason) ~= "string")) then
                        progress.upgradeUncertain = true
                        reportUpgrades("ответ на " .. tostring(name) .. " не подтверждён")
                    end
                end
                if not invoked then ok2 = false end
                if ok2 and type(res) == "table" then
                    if res.Success then
                        bought += 1
                        reportUpgrades("успех " .. tostring(name))
                        progressed = true
                        blocked[name] = nil
                        Ui.status = "Bought " .. name
                        label:SetText(string.format("Bought %s (level %s). %d upgrades this session.",
                            name, tostring(res.Current or "?"), bought))
                    elseif res.Reason == "RateLimited" then
                        Life.wait(0.3)
                    else
                        blocked[name] = res.Reason or "unavailable"
                        if not (Ui.__progressTest and Ui.__progressTest.upgradeUncertain) then
                            reportUpgrades("отказ " .. tostring(name) .. ": " .. tostring(blocked[name]))
                        end
                    end
                end
                Life.wait(PACE)
            end
        end
        if not progressed then
            -- Nothing bought this pass: report why and wait a little longer before trying again.
            local notes = {}
            for name, reason in pairs(blocked) do
                notes[#notes + 1] = name .. ": " .. reason
            end
            table.sort(notes)
            if #notes > 0 then
                label:SetText("Waiting: " .. table.concat(notes, ", "):sub(1, 120))
            end
            Life.wait(2)
        end
    end
end)

return {}
end
__modules["features/handover"] = function(use) -- src/games/tapsim/features/handover.luau
-- Передача петов банку. Это ПОРТ отдельного скрипта farm_trade_only.lua (v2), который проверен
-- в игре: те же пути кнопок, те же тайминги, тот же порядок. Ничего «своего» здесь нет.
--
-- Порядок ровно как в отдельном скрипте:
--   1) событие TradeUpdate "Request" и проверка, что оно от банка (Riglafsma / id 11747325739),
--      остальным — Decline;
--   2) фарм на паузу;
--   3) с команды снимаются ТОЛЬКО Secret (Godly не трогаем вообще);
--   4) Accept — через обработчики скрытой кнопки, с повторами, пока сервер не пришлёт Started;
--   5) в оффер уходят ТОЛЬКО Secret, до 12 штук, по убыванию силы;
--   6) ровно 1.5 с после оффера -> READY: PlayerGui.Trading.Trading.Build.Actions.Ready;
--   7) ждём, пока оживёт CONFIRM: PlayerGui.Trading.Trading.Review.Confirm, затем раунды 8 x 1.5 с;
--   8) на Completed/Cancelled: тумблеры фарма возвращаются как были + родной EquipBest payload'а.
--
-- READY второй раз НЕ нажимаем: это переключатель, повторное нажатие снимает готовность.
-- Никаких remote-ов вместо кнопок: READY и CONFIRM нажимаются только как кнопки.
-- По GUI трейд не определяется: окно Tabs.TradeQuest и кнопки лежат в дереве всегда и всегда
-- с Visible = true. Правда только в событии RemoteServices.TradingService.RE.TradeUpdate.
--
-- Ручные команды: getgenv().farmTrade = { state, dump, unequip, offer, accept, ready, confirm,
--                                          full, stop }

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local BUILD = "v18"

local BANK_NAMES = { "Riglafsma" }
local BANK_IDS = { 11747325739 }

local ACCEPT_PATH = { "Tabs", "TradeQuest", "Menu", "Accept", "Button" }
local DECLINE_PATH = { "Tabs", "TradeQuest", "Menu", "Decline", "Button" }
local READY_PATH = { "Trading", "Trading", "Build", "Actions", "Ready" }
local CONFIRM_PATH = { "Trading", "Trading", "Review", "Confirm" }
local READY_PATH_BUTTON = { "Trading", "Trading", "Build", "Actions", "Ready", "Button" }
local CONFIRM_PATH_BUTTON = { "Trading", "Trading", "Review", "Confirm", "Button" }

local READY_DELAY = 3         -- пауза после оффера перед READY
local CONFIRM_WINDOW = 45       -- сколько ждём, пока оживёт CONFIRM
local CONFIRM_ROUNDS = 12       -- максимум раундов, если стадия Confirm всё не приходит
local CONFIRM_ROUND_WAIT = 1.5  -- пауза между раундами
local CONFIRM_DELAY = 4         -- пауза перед ПЕРВЫМ CONFIRM: у банка окно ~9 с, 6 с его почти съедали
local ACCEPT_TIMEOUT = 25       -- сколько ждём открытия сессии после Accept
-- Замер 09.11 (A/B на TurboLynx и Veifuzie): вызов игрового обработчика через 1 мс после
-- события Request НЕ принимает и вдобавок снимает обработчик с кнопки на ~20 с.
-- С паузой 0.15 с приём проходит с первой попытки за ~0.2 с. Меньше 0.12 ставить нельзя.
local ACCEPT_READY_DELAY = 0.15
local TRADE_TIMEOUT = 150       -- сколько всего ждём завершения сделки
local SECRET_WORD = "secret"    -- сравнение по подстроке: в живых данных пишется «Secret II»
local REVEAL_PATH = { "HatchScreen", "Main", "Info", "HatchEgg" }   -- карточка «Hold to Reveal»
local MAX_OFFER = 12
local POLL_SECONDS = 2          -- только для надписи в панели, ничего не нажимает

-- Всё состояние объявлено до функций: объявленное ниже стало бы для них отдельной переменной,
-- и проверки вида «if traded then» читали бы nil.
local running = true
local stage = "ждём трейд"
local busy = false           -- идёт сделка целиком (от Accept до итога)
local handoverActive = false -- идёт шаг «оффер -> READY -> CONFIRM»
local traded = false         -- сделка закрылась (Completed/Cancelled)
local sawReview = false      -- игра прислала стадию "Review": шаг подтверждения открыт
local sawConfirm = false     -- игра прислала стадию "Confirm": наш CONFIRM принят
local lastStage = "—"        -- последняя стадия из TradeUpdate (для лога ожидания)
local startedEvent = false   -- сервер прислал TradeUpdate "Started"
local finishedLogged = false -- «трейд закончился» уже напечатали для этой сделки
local readyAt = os.clock()   -- когда нажали READY (для лога «CONFIRM ожил через N с»)
local paused = false
local savedToggles = nil

local function log(fmt, ...)
    local ok, text = pcall(string.format, fmt, ...)
    print("[handover " .. BUILD .. "] " .. (ok and text or tostring(fmt)))
end

-- ---------------------------------------------------------------------------------------------
-- панель
-- ---------------------------------------------------------------------------------------------

local tab = Ui.Tabs.Home
local box = tab:AddGroupbox({ Side = "Right", Name = "Handover", IconName = "package" })

box:AddToggle("Handover", {
    Text = "Отдавать секретов банку (Godly не трогаем)",
    Default = true,
    -- Без Callback: pauseFarm() зовёт Ui.stopAll(false), тот выставляет ВСЕ тумблеры в false,
    -- и колбэк тут же гасил бы флаг модуля — после первой же сделки handover «выключался сам».
    -- Флаг модуля живёт в running, а тумблер читается на каждом заходе.
    Tooltip = "Ждёт трейд от банка: пауза фарма, снятие Secret с команды, приём, оффер Secret, "
        .. "1.5 с, READY, раунды CONFIRM. После сделки возвращает фарм и лучших петов.",
})

local statusLabel = box:AddLabel("Handover: ждём запрос от банка", true)

local function setStatus(text)
    pcall(function()
        statusLabel:SetText("Handover: " .. text)
    end)
end

local function moduleEnabled()
    if busy then
        -- сделку доводим до конца, даже если пауза фарма погасила тумблер
        return true
    end
    if not running then
        return false
    end
    local ok, value = pcall(function()
        return Ui.on("Handover")
    end)
    return ok and value == true
end

-- ---------------------------------------------------------------------------------------------
-- общее: gui, remote-ы, данные игрока
-- ---------------------------------------------------------------------------------------------

local function gui()
    local player = Env.LocalPlayer
    return player and player:FindFirstChild("PlayerGui")
end

local function fireRemote(service, name, payload)
    Env.elevate()
    local ok, err = pcall(function()
        Env.fire(service, name, payload)
    end)
    if not ok then
        log("FireServer %s не сработал: %s", tostring(name), tostring(err))
    end
    return ok
end

local function petsTable()
    local ok, data = pcall(Env.data)
    if not ok then
        return nil
    end
    return data and type(data.Pets) == "table" and data.Pets or nil
end

local function petIdOf(pet, fallback)
    if type(pet) == "table" and pet.Id ~= nil then
        return tostring(pet.Id)
    end
    return fallback and tostring(fallback) or nil
end

local function rarityMatches(pet, word)
    if type(pet) ~= "table" or not word then
        return false
    end
    local rarity = string.lower(tostring(pet.Rarity or ""))
    return string.find(rarity, word, 1, true) ~= nil
end

-- Кто стоит в команде. Главный источник — Pets.Equipped; поштучный Pet.Equip читаем только
-- если списка нет вовсе, иначе два источника спорят и «снялось/не снялось» врёт.
local function teamIds()
    local ids = {}
    local pets = petsTable()
    if not pets then
        return ids
    end
    if type(pets.Equipped) == "table" and next(pets.Equipped) ~= nil then
        for _, value in pairs(pets.Equipped) do
            local id = type(value) == "table" and (value.Id or value.PetId) or value
            if id ~= nil and id ~= false then
                ids[tostring(id)] = true
            end
        end
        return ids
    end
    for key, pet in pairs(pets.Owned or {}) do
        if type(pet) == "table" and pet.Equip == true then
            ids[tostring(pet.Id ~= nil and pet.Id or key)] = true
        end
    end
    return ids
end

local function isLocked(id)
    local pets = petsTable()
    for key, pet in pairs(pets and pets.Owned or {}) do
        if type(pet) == "table" and petIdOf(pet, key) == tostring(id) then
            return pet.Locked == true
        end
    end
    return false
end

local function unlockPet(id)
    if not isLocked(id) then
        return true
    end
    for _, action in ipairs({ "ToggleLock", "Unlock", "SetLocked" }) do
        fireRemote("PetService", "PetActionRequested", { Action = action, PetId = id, Locked = false })
        local deadline = os.clock() + 1.5
        while os.clock() < deadline do
            if not isLocked(id) then
                return true
            end
            task.wait(0.15)
        end
    end
    return false
end

-- Снять с команды всех петов указанной редкости (только Secret).
local function unequipRarity(word)
    local pets = petsTable()
    if not pets or type(pets.Owned) ~= "table" then
        log("данные петов не прочитались — снять не могу")
        return 0
    end
    Env.elevate()
    local team = teamIds()
    local removed = 0
    local onTeam = 0
    for key, pet in pairs(pets.Owned) do
        if rarityMatches(pet, word) then
            local id = petIdOf(pet, key)
            if id and team[id] then
                onTeam += 1
                if pet.Locked == true and not unlockPet(id) then
                    log("залочен, не снял: %s", tostring(pet.Name))
                else
                    local done = false
                    for _ = 1, 3 do
                        fireRemote("PetService", "PetActionRequested", { Action = "Unequip", PetId = id })
                        local deadline = os.clock() + 2
                        while os.clock() < deadline do
                            if not teamIds()[id] then
                                done = true
                                break
                            end
                            task.wait(0.15)
                        end
                        if done then
                            break
                        end
                    end
                    if done then
                        removed += 1
                        log("снял с команды: %s (%s)", tostring(pet.Name), tostring(pet.Rarity))
                    else
                        log("НЕ снялось: %s (%s)", tostring(pet.Name), tostring(pet.Rarity))
                    end
                end
                task.wait(0.2)
            end
        end
    end
    log("снято с команды %s-петов: %d (было на команде: %d)", word, removed, onTeam)
    return removed
end

-- Положить в трейд только Secret, максимум MAX_OFFER, по убыванию силы.
local function offerRarity(word)
    local pets = petsTable()
    if not pets or type(pets.Owned) ~= "table" then
        log("данные петов не прочитались — оффер не сделать")
        return 0
    end
    Env.elevate()
    local list = {}
    for key, pet in pairs(pets.Owned) do
        if rarityMatches(pet, word) then
            local id = petIdOf(pet, key)
            if id then
                if pet.Locked == true and not unlockPet(id) then
                    log("пропускаю залоченного: %s", tostring(pet.Name))
                else
                    list[#list + 1] = { id = id, power = tonumber(pet.Power) or 0, name = tostring(pet.Name) }
                end
            end
        end
    end
    table.sort(list, function(a, b)
        return a.power > b.power
    end)
    local ids, names = {}, {}
    for _, entry in ipairs(list) do
        if #ids < MAX_OFFER then
            ids[#ids + 1] = entry.id
            names[#names + 1] = entry.name
        end
    end
    if #ids == 0 then
        log("%s-петов нет — класть нечего", word)
        return 0
    end
    fireRemote("TradingService", "TradeRequested", { Action = "Offer", PetIds = ids })
    log("положил в трейд %d петов: %s", #ids, table.concat(names, ", "))
    return #ids
end

-- ---------------------------------------------------------------------------------------------
-- кнопки
-- ---------------------------------------------------------------------------------------------

local function resolvePath(parts)
    local node = gui()
    if not node then
        return nil
    end
    for _, name in ipairs(parts) do
        node = node:FindFirstChild(name)
        if not node then
            return nil
        end
    end
    return node
end

local function isShown(node)
    local ok, visible = pcall(function()
        return node.Visible
    end)
    if not ok or visible == false then
        return false
    end
    local parent = node
    for _ = 1, 8 do
        parent = parent.Parent
        if not parent or parent:IsA("PlayerGui") then
            break
        end
        local okParent, parentVisible = pcall(function()
            if parent:IsA("ScreenGui") then
                return parent.Enabled
            end
            return parent.Visible
        end)
        if okParent and parentVisible == false then
            return false
        end
    end
    return true
end

-- Путь может указывать и на сам GuiButton, и на его фрейм-обёртку: берём кнопку изнутри.
local function asButton(node)
    if not node then
        return nil
    end
    if node:IsA("GuiButton") then
        return node
    end
    local child = node:FindFirstChild("Button")
    if child and child:IsA("GuiButton") then
        return child
    end
    for _, deep in ipairs(node:GetDescendants()) do
        if deep:IsA("GuiButton") then
            return deep
        end
    end
    return nil
end

local function byPath(parts, partsButton)
    local button = asButton(resolvePath(parts))
    if button then
        return button
    end
    if partsButton then
        return asButton(resolvePath(partsButton))
    end
    return nil
end

-- Вызов ТОЛЬКО игровых обработчиков кнопки: тех, чей исходник — игровой контроллер
-- (ReplicatedStorage.Controllers.Trading.TradingController). Звук/анимацию из
-- ButtonEffects и чужие логгеры не дёргаем. Замер 09.11: именно этот вызов
-- переводит Request → Started, и делает это в том же кадре.
-- Возвращает: сколько вызвано, список источников.
local function fireTradeHandlers(button, label)
    if not button then
        return 0, {}
    end
    Env.elevate()
    local genv = Env.genv or {}
    local getconnections = genv.getconnections
    if type(getconnections) ~= "function" then
        return 0, {}
    end
    local debugLib = type(genv.debug) == "table" and genv.debug or debug
    local fired, sources = 0, {}
    for _, signalName in ipairs({ "Activated", "MouseButton1Click", "MouseButton1Down", "TouchTap" }) do
        local okSignal, signal = pcall(function()
            return button[signalName]
        end)
        if okSignal and signal then
            local okList, list = pcall(getconnections, signal)
            if okList and type(list) == "table" then
                for _, connection in ipairs(list) do
                    if connection.Enabled ~= false then
                        local source = "?"
                        pcall(function()
                            local func = connection.Function
                            if type(func) == "function" and type(debugLib) == "table"
                                and type(debugLib.info) == "function" then
                                source = tostring(debugLib.info(func, "s"))
                            end
                        end)
                        if string.find(string.lower(source), "trading", 1, true) then
                            local okFire = pcall(function()
                                connection:Fire()
                            end)
                            if okFire then
                                fired += 1
                                table.insert(sources, source .. " на " .. signalName)
                            end
                        end
                    end
                end
            end
        end
    end
    return fired, sources
end

local function findAcceptButton()
    return byPath(ACCEPT_PATH)
end

-- Настоящий клик по центру кнопки: координаты берём из AbsolutePosition, удержание
-- подобрано так, чтобы попасть в кадр даже при лимите 5 FPS (кадр 200 мс).
-- Нужен как запасной способ, если прямой вызов обработчика не принимает.
local function clickButtonCentre(button, hold)
    if not button then
        return false
    end
    local centre = button.AbsolutePosition + button.AbsoluteSize / 2
    local x, y = math.floor(centre.X), math.floor(centre.Y)
    local camera = workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize or Vector2.new(0, 0)
    if x < 0 or y < 0 or x > viewport.X or y > viewport.Y then
        log("клик вне экрана (%d,%d) при %dx%d — пропускаю", x, y, viewport.X, viewport.Y)
        return false
    end
    hold = hold or 0.25
    local ok = pcall(function()
        local vim = game:GetService("VirtualInputManager")
        vim:SendMouseButtonEvent(x, y, 0, true, game, 0)
        task.wait(hold)
        vim:SendMouseButtonEvent(x, y, 0, false, game, 0)
    end)
    log("клик по Accept (%d,%d), удержание %.2f — %s", x, y, hold, ok and "ok" or "ошибка")
    return ok
end

-- Клик по первой видимой строке списка заявок, затем игровой обработчик Accept.
-- Некоторые клиенты требуют, чтобы заявка была выделена в списке.
local function clickRequestRowThenHandler()
    local tabs = resolvePath({ "Tabs" })
    local quest = tabs and tabs:FindFirstChild("TradeQuest")
    local menu = quest and quest:FindFirstChild("Menu")
    if not menu then
        return 0
    end
    for _, node in ipairs(menu:GetDescendants()) do
        if node:IsA("GuiButton") then
            local path = string.lower(node:GetFullName())
            local skip = string.find(path, "accept", 1, true) or string.find(path, "decline", 1, true)
                or string.find(path, "cancel", 1, true) or string.find(path, "close", 1, true)
            if not skip and isShown(node) and node.AbsoluteSize.Magnitude > 0 then
                log("клик по строке заявки: %s", node:GetFullName())
                clickButtonCentre(node, 0.25)
                task.wait(0.3)
                break
            end
        end
    end
    local button = findAcceptButton()
    local fired = 0
    if button then
        fired = fireTradeHandlers(button, "ACCEPT-ROW")
    end
    return fired
end

-- Открыть панель трейда: контроллер подвязывает Accept к кнопке при инициализации панели,
-- а на фарм-аккаунте она может быть ни разу не открыта (замер 09.11, Veifuzie:
-- игрового обработчика на кнопке не было вообще). Ищем кнопку таба TradeQuest и жмём её
-- штатными обработчиками; ничего не ломаем, если такой кнопки нет.
local function openTradePanel()
    local tabs = resolvePath({ "Tabs" })
    if not tabs then
        log("openTradePanel: нет узла Tabs")
        return false
    end
    for _, node in ipairs(tabs:GetDescendants()) do
        if node:IsA("GuiButton") then
            local low = string.lower(node:GetFullName())
            local isTrade = string.find(low, "trade", 1, true) ~= nil
            local isOther = string.find(low, "accept", 1, true) or string.find(low, "decline", 1, true)
                or string.find(low, "cancel", 1, true) or string.find(low, "close", 1, true)
            if isTrade and not isOther then
                local fired = fireTradeHandlers(node, "OPEN-TAB")
                if fired > 0 then
                    log("openTradePanel: открыл через %s (обработчиков %d)", node:GetFullName(), fired)
                    return true
                end
            end
        end
    end
    log("openTradePanel: кнопки таба не нашёл — панель не открыть")
    return false
end

local function findReadyButton()
    return byPath(READY_PATH, READY_PATH_BUTTON)
end

local function findConfirmButton()
    return byPath(CONFIRM_PATH, CONFIRM_PATH_BUTTON)
end

-- Нажатие: сначала обработчики сигналов кнопки (так работают скрытые Accept/READY/CONFIRM),
-- если их нет — firesignal, и только потом настоящая мышь в центр видимой кнопки.
local function press(button, label)
    if not button then
        log("нажать нечего: %s", tostring(label))
        return 0
    end
    Env.elevate()
    local genv = Env.genv or {}
    local pressed = 0
    local getconnections = genv.getconnections
    if type(getconnections) == "function" then
        for _, signalName in ipairs({ "Activated", "MouseButton1Click", "MouseButton1Down" }) do
            local okSignal, signal = pcall(function()
                return button[signalName]
            end)
            if okSignal and signal then
                local okList, list = pcall(getconnections, signal)
                if okList and type(list) == "table" then
                    for _, connection in ipairs(list) do
                        local hasFire = pcall(function()
                            return connection.Fire
                        end)
                        if connection.Enabled ~= false and hasFire and pcall(connection.Fire) then
                            pressed += 1
                        end
                    end
                end
            end
        end
    end
    if pressed == 0 and type(genv.firesignal) == "function" then
        for _, signalName in ipairs({ "Activated", "MouseButton1Click" }) do
            local okSignal, signal = pcall(function()
                return button[signalName]
            end)
            if okSignal and signal and pcall(genv.firesignal, signal) then
                pressed += 1
            end
        end
    end
    if pressed == 0 and isShown(button) then
        local clicked = pcall(function()
            local pos = button.AbsolutePosition + button.AbsoluteSize * 0.5
            local x, y = math.floor(pos.X), math.floor(pos.Y)
            local vim = game:GetService("VirtualInputManager")
            vim:SendMouseButtonEvent(x, y, 0, true, game, 1)
            task.wait(0.1)
            vim:SendMouseButtonEvent(x, y, 0, false, game, 1)
        end)
        if clicked then
            pressed += 1
        end
    end
    log("нажал %s (%d) — %s", tostring(label), pressed, button:GetFullName())
    return pressed
end

-- Сколько живых обработчиков у кнопки: > 0 живая, = 0 мёртвая, = -1 getconnections недоступен.
-- По GUI трейд не определить (окно и кнопки лежат в дереве всегда), а обработчики — отражают.
local function liveConnections(button)
    if not button then
        return 0
    end
    local genv = Env.genv or {}
    if type(genv.getconnections) ~= "function" then
        return -1
    end
    local total = 0
    for _, signalName in ipairs({ "Activated", "MouseButton1Click", "MouseButton1Down" }) do
        local okSignal, signal = pcall(function()
            return button[signalName]
        end)
        if okSignal and signal then
            local okList, list = pcall(genv.getconnections, signal)
            if okList and type(list) == "table" then
                for _, connection in ipairs(list) do
                    if connection.Enabled ~= false then
                        total += 1
                    end
                end
            end
        end
    end
    return total
end

local function waitFor(condition, seconds, tick)
    local deadline = os.clock() + seconds
    while os.clock() < deadline do
        local value = condition()
        if value then
            return value
        end
        task.wait(tick or 0.25)
    end
    return nil
end

-- Карточка «Hold to Reveal» лежит поверх экрана и может съедать клики мышью. Своё зажатие делает
-- модуль holdreveal (его пауза фарма не гасит), поэтому перед Accept просто ждём, чтобы карточка
-- ушла. Кнопки трейда жмутся через обработчики, так что даже висящая карточка не блокирует.
local function revealCardUp()
    local card = resolvePath(REVEAL_PATH)
    return card ~= nil and isShown(card)
end

local function waitRevealClear(seconds)
    if not revealCardUp() then
        return true
    end
    log("на экране карточка Hold to Reveal — жду, пока освободит экран (до %.0f с)", seconds)
    local cleared = waitFor(function()
        return not revealCardUp()
    end, seconds, 0.25)
    if not cleared then
        log("карточка так и висит — жму Accept всё равно (кнопки нажимаются через обработчики)")
    end
    return cleared ~= nil
end

-- ---------------------------------------------------------------------------------------------
-- пауза и возврат фарма (родные тумблеры + родной EquipBest payload'а)
-- ---------------------------------------------------------------------------------------------

local function pauseFarm()
    if paused then
        return
    end
    paused = true
    -- Флаг ставим ДО отключения тумблеров, иначе другой поток успеет экипировать петов.
    if Env.genv then
        Env.genv.__handoverPaused = true
    end
    savedToggles = {}
    local toggles = Ui.Library and Ui.Library.Toggles or {}
    for name, toggle in pairs(toggles) do
        savedToggles[name] = toggle.Value == true
    end
    Ui.stopAll(false, true)
    setStatus("фарм на паузе, идёт сделка")
    log("фарм на паузе")
end

local function resumeFarm()
    if not paused then
        return
    end
    paused = false
    if Ui.__progressTest and Ui.__progressTest.stopRequested then
        savedToggles = nil
        if Env.genv then Env.genv.__handoverPaused = false end
        setStatus("трейд завершён; ручной Stop all сохранён")
        log("трейд завершён; фарм не возобновляю после ручной остановки")
        return
    end
    for name, value in pairs(savedToggles or {}) do
        local P = Ui.__progressTest
        if P and (P.eggFixed or P.rebirthLocked) and (name == "AutoUpgrade" or name == "AutoSkillTree" or name == "AutoCraft") then value = false end
        pcall(Ui.set, name, value)
    end
    savedToggles = nil
    if Env.genv then
        Env.genv.__handoverPaused = false
    end
    -- Restore произошёл при флаге трейда, поэтому обновляем игровой кликер после снятия паузы.
    if Ui.__progressTest and type(Ui.syncNativeClicker) == "function" then
        Life.spawn("handover:syncNativeClicker", function() pcall(Ui.syncNativeClicker) end)
    end
    -- Во время теста может быть выбран Clicks: не перезаписываем его на Luck после трейда.
    pcall(function()
        local remote = Env.remote("PetService", "PetActionRequested")
        -- Lookup может уступить поток: читаем актуальный режим уже после него.
        local option = Ui.Options and Ui.Options.EquipMode
        local mode = option and option.Value or "Luck"
        local P = Ui.__progressTest
        local phaseOK = not P or (P.equipReady == true and not P.stopRequested and not P.cleaning
            and not P.craftBusy and not P.craftInFlight and option
            and mode == ((P.eggFixed or P.rebirthLocked) and "Luck" or "Clicks"))
        if phaseOK and Life.alive and not paused and Ui.on("AutoEquipBest")
            and not (Env.genv and Env.genv.__handoverPaused) then
            Env.elevate()
            remote:FireServer({ Action = "EquipBest", Mode = mode })
        end
    end)
    setStatus("фарм снова работает, EquipBest отправлен")
    log("фарм снова работает, EquipBest отправлен в текущем режиме")
end

-- ---------------------------------------------------------------------------------------------
-- подтверждение: после READY жмём CONFIRM раундами, пока сделка не закроется
-- ---------------------------------------------------------------------------------------------

-- Подтверждение родным запросом игры — проверено на живой сделке (07.11):
--   ➜ TradeRequested {Action="Confirm"} -> TradeUpdate "Confirm" с НАШИМ UserId -> Countdown -> Completed.
-- Кнопка Review.Confirm при этом не двигает стадию: у неё пустой текст и те же три обработчика,
-- что у Cancel, а getconnections в части экзекуторов вообще не отдаёт соединения (Fire=0).
local function remoteConfirm()
    local ok = fireRemote("TradingService", "TradeRequested", { Action = "Confirm" })
    if ok then
        log("CONFIRM отправлен запросом TradeRequested {Action=\"Confirm\"}")
    else
        log("CONFIRM-запрос не ушёл")
    end
    return ok
end

local function pressConfirmRounds()
    local startedAt = os.clock()
    local rounds = 0
    -- Отправляем свой CONFIRM ВСЕГДА, даже если sawConfirm уже стоит: стадия "Confirm"
    -- означает лишь "шаг открыт", и нажатий 0 — это была наша же ошибка в v14/v15.
    if not traded then
        remoteConfirm()
    end
    while not traded and not sawConfirm and rounds < CONFIRM_ROUNDS do
        if not running then
            return false
        end
        if os.clock() - startedAt > CONFIRM_WINDOW then
            break
        end
        rounds += 1
        -- 1) главный способ: родной запрос игры (подтверждает сделку)
        remoteConfirm()
        local deadline = os.clock() + CONFIRM_ROUND_WAIT
        while os.clock() < deadline and not traded and not sawConfirm do
            task.wait(0.1)
        end
        -- 2) резерв: кнопка, если запрос почему-то не приняли
        if not traded and not sawConfirm then
            local confirm = findConfirmButton()
            if confirm then
                press(confirm, string.format("CONFIRM-кнопка, раунд %d", rounds))
                local buttonUntil = os.clock() + CONFIRM_ROUND_WAIT
                while os.clock() < buttonUntil and not traded and not sawConfirm do
                    task.wait(0.1)
                end
            end
        end
    end
    if sawConfirm then
        log("наш CONFIRM принят (стадия Confirm, нажатий: %d) — дальше ждём вторую сторону", rounds)
    elseif traded then
        log("сделка закрылась на CONFIRM (нажатий: %d)", rounds)
    else
        log("стадия Confirm так и не пришла за %d с (нажатий: %d)", CONFIRM_WINDOW, rounds)
    end
    return true
end

-- петов положили -> 1.5 с -> READY (ровно один раз) -> раунды CONFIRM
local function readyThenConfirm()
    log("пауза %.1f с после оффера…", READY_DELAY)
    task.wait(READY_DELAY)

    local ready = findReadyButton()
    if not ready then
        log("узла READY нет в дереве (%s) — подтверждать нечем", table.concat(READY_PATH, "."))
        return false
    end
    log("READY: %s | живых обработчиков: %d", ready:GetFullName(), liveConnections(ready))
    if press(ready, "READY") == 0 then
        log("READY не отозвался: ни обработчиков, ни мыши")
        return false
    end
    readyAt = os.clock()

    -- Открытие шага подтверждения определяем ПО СОБЫТИЮ "Review", а не по обработчикам кнопки:
    -- у Review.Confirm обработчики висят всегда, поэтому по ним момент не поймать (в живом логе
    -- выходило «CONFIRM ожил через 0.0 с» и четыре первых нажатия уходили в пустоту).
    local opened = waitFor(function()
        if traded then
            return "done"
        end
        if sawReview then
            return "review"
        end
        return nil
    end, CONFIRM_WINDOW, 0.25)
    if opened == "done" then
        log("сделка закрылась ещё до CONFIRM")
        return true
    elseif opened == "review" then
        log("шаг подтверждения открылся (Review) через %.1f с после READY", os.clock() - readyAt)
    else
        log("Review за %d с не пришёл — жму CONFIRM всё равно", CONFIRM_WINDOW)
    end

    -- Пауза перед первым нажатием CONFIRM: шаг открывается после Review, а окно подтверждения
    -- у игры успевает доехать не сразу. Ждём ровно CONFIRM_DELAY секунд.
    local pauseUntil = os.clock() + CONFIRM_DELAY
    log("пауза %.0f с перед CONFIRM…", CONFIRM_DELAY)
    while os.clock() < pauseUntil and not traded do
        task.wait(0.2)
    end
    if traded then
        log("сделка закрылась во время паузы перед CONFIRM")
        return true
    end

    return pressConfirmRounds()
end

-- ---------------------------------------------------------------------------------------------
-- сделка после того, как сессия открыта
-- ---------------------------------------------------------------------------------------------

local function handover()
    if handoverActive then
        log("подтверждение уже идёт — пропускаю")
        return false
    end
    handoverActive = true
    log("================ СДЕЛКА НАЧАТА ================")
    local ok, err = pcall(function()
        stage = "кладу Secret в трейд"
        log("этап: %s", stage)
        if offerRarity(SECRET_WORD) == 0 then
            error("класть нечего: Secret-петов нет")
        end

        stage = "жму READY"
        log("этап: %s", stage)
        readyThenConfirm()

        stage = "ждём завершения сделки"
        log("этап: %s", stage)
        local waitFrom = os.clock()
        local nextNote = os.clock() + 15
        while not traded and os.clock() - waitFrom < TRADE_TIMEOUT do
            task.wait(0.3)
            if not traded and os.clock() >= nextNote then
                nextNote = os.clock() + 15
                log("ждём завершения: стадия %s | наш CONFIRM принят: %s",
                    tostring(lastStage), tostring(sawConfirm))
            end
        end
        if traded then
            log("сделка завершена")
        else
            log("сделка не завершилась за %d с (стадия %s)", TRADE_TIMEOUT, tostring(lastStage))
        end
    end)
    if not ok then
        log("ошибка: %s", tostring(err))
    end
    handoverActive = false
    return ok
end

-- Трейд пришёл (событие Request): пауза фарма, снять Secret, нажать Accept.
-- Повторные нажатия Accept — пока сервер не пришлёт Started.
local function acceptTrade(name, fromId)
    if busy then
        log("уже в сделке — запрос пропускаю")
        return
    end
    busy = true
    startedEvent = false
    finishedLogged = false
    traded = false
    sawReview = false
    sawConfirm = false
    lastStage = "—"
    stage = "пришёл трейд от " .. tostring(name)
    log("этап: %s", stage)
    task.spawn(function()
        pauseFarm()
        log("запрос от %s", tostring(name))

        stage = "снимаю Secret с команды"
        log("этап: %s", stage)
        unequipRarity(SECRET_WORD)

        stage = "жму Accept"
        log("этап: %s", stage)
        waitRevealClear(4)
        local accept = findAcceptButton()
        if not accept then
            log("узла Accept нет в дереве — принять не могу")
            busy = false
            resumeFarm()
            stage = "ждём следующий трейд"
            return
        end

        -- Приём через НАСТОЯЩИЙ обработчик игры (замер 09.11, аккаунт AmberWolf5963):
        --   кнопка: Players.<ник>.PlayerGui.Tabs.TradeQuest.Menu.Accept.Button
        --           (своё имя "Button", слово Accept только в пути — искать по пути);
        --   приём:  Activated → ReplicatedStorage.Controllers.Trading.TradingController
        --           её вызов и открывает сессию: Request → Started за 0.19 с, с 1 попытки.
        -- Поэтому вызываем ТОЛЬКО игровые обработчики (conn:Fire()), а звук и анимацию
        -- из ButtonEffects не трогаем.
        -- Мышь, VirtualInputManager, firesignal и веер из трёх remote-пакетов убраны:
        -- они зависели от FPS (при лимите 5 FPS кадр 200 мс) и от раскладки окна —
        -- именно из-за этого часть аккаунтов не принимала трейд.
        local acceptStart = os.clock()
        local attempt = 0
        local winner = nil
        if startedEvent then
            winner = "сессия уже открыта"
        end
        -- Замер 09.11 (Veifuzie): вызов через 1 мс после Request не сработал, а затем
        -- игровой обработчик на кнопке исчез — на фарм-аккаунте контроллер к ней не
        -- подключён (панель трейда ни разу не открывалась). Поэтому:
        --   1) даём контроллеру привязку — короткая пауза перед первым вызовом;
        --   2) если обработчика нет — НЕ молотим косметику каждые 0.5 с, а пытаемся
        --      открыть панель трейда и ждём появления обработчика;
        --   3) press() как фолбэк — максимум 2 раза, с интервалом 1 с.
        task.wait(ACCEPT_READY_DELAY)
        local fallbackPresses = 0
        local triedOpenPanel = false
        -- Порядок способов: сначала быстрый игровой обработчик (на рабочих аккаунтах
        -- принимает за ~0.2 с), затем, если он не принял, запасные из A/B-прогона.
        local plan = { "handler", "vimclick", "allconns", "row", "handler" }
        while os.clock() - acceptStart < ACCEPT_TIMEOUT and not startedEvent do
            attempt += 1
            local method = plan[math.min(attempt, #plan)]
            local buttonNow = findAcceptButton()
            if buttonNow then
                local fired, sources = fireTradeHandlers(buttonNow, "ACCEPT")
                if method == "vimclick" then
                    log("способ vimclick (игровой обработчик не принял) — клик по центру")
                    clickButtonCentre(buttonNow, 0.25)
                elseif method == "allconns" then
                    local pressed = press(buttonNow, "ACCEPT (все обработчики)")
                    log("способ allconns — вызвано обработчиков: %d", pressed)
                elseif method == "row" then
                    log("способ row — выделяю заявку в списке и жму обработчик")
                    clickRequestRowThenHandler()
                end
                if fired > 0 then
                    log("ACCEPT (игровой обработчик: %s) — вызвано %d, попытка %d (%s)",
                        table.concat(sources, ", "), fired, attempt, method)
                else
                    -- обработчика нет: сначала пробуем открыть панель, чтобы контроллер подвязался
                    if not triedOpenPanel then
                        triedOpenPanel = true
                        log("игрового обработчика нет — открываю панель трейда, чтобы контроллер подвязался")
                        openTradePanel()
                        task.wait(0.5)
                    elseif fallbackPresses < 2 then
                        fallbackPresses += 1
                        local pressed = press(buttonNow, "ACCEPT (фолбэк: все обработчики)")
                        log("игровой обработчик не найден — фолбэк %d/2: вызвано %d", fallbackPresses, pressed)
                        if pressed == 0 then
                            -- единственный запрос, без веера: FromUserId берём из события Request
                            fireRemote("TradingService", "TradeRequested",
                                { Action = "Accept", FromUserId = fromId })
                            log("ACCEPT (remote {Action=Accept, FromUserId=%s})", tostring(fromId))
                        end
                        task.wait(1)
                    end
                end
            else
                log("кнопка Accept пропала из дерева — жду появления (попытка %d)", attempt)
            end
            local untilAt = os.clock() + 0.5
            while os.clock() < untilAt and not startedEvent do
                task.wait(0.05)
            end
            if startedEvent then
                winner = "игровой обработчик Accept"
                log("сделку принял %s (попытка %d, %.2f с)", winner, attempt, os.clock() - acceptStart)
            end
        end

        if not startedEvent then
            -- диагностика: почему не принялось
            local buttonNow = findAcceptButton()
            local tabGui = resolvePath({ "Tabs", "TradeQuest" })
            log("диагностика Accept: узел=%s visible=%s active=%s живых_обработчиков=%d панель_TradeQuest=%s",
                buttonNow and "есть" or "нет",
                buttonNow and tostring(buttonNow.Visible) or "-",
                buttonNow and tostring(buttonNow.Active) or "-",
                liveConnections(buttonNow),
                tabGui and tostring(isShown(tabGui)) or "нет")
            log("диагностика: последняя стадия TradeUpdate = %s, sawReview=%s", tostring(lastStage),
                tostring(sawReview))
            log("событие Started не пришло за %d с (попыток нажать: %d). Петов не выкладываю — "
                .. "без подтверждения сервера это была бы пустая сделка", ACCEPT_TIMEOUT, attempt)
            busy = false
            resumeFarm()
            stage = "ждём следующий трейд"
            return
        end

        log("сессия открыта (Started) через способ %s", tostring(winner))
        task.wait(1.5)
        handover()
        -- фарм вернёт событие Completed/Cancelled, там же снимется busy
        stage = "ждём завершения сделки"
    end)
end

-- ---------------------------------------------------------------------------------------------
-- события трейда: единственный надёжный источник правды
-- ---------------------------------------------------------------------------------------------

local function allowed(name, userId)
    for _, wanted in ipairs(BANK_NAMES) do
        if type(name) == "string" and string.lower(wanted) == string.lower(name) then
            return true
        end
    end
    for _, wanted in ipairs(BANK_IDS) do
        if tonumber(userId) == tonumber(wanted) then
            return true
        end
    end
    return false
end

local function dumpTrade()
    for _, part in ipairs({ "Trading", "Trading.Trading.Build.Actions.Ready",
        "Trading.Trading.Review.Confirm", "Tabs.TradeQuest.Menu.Accept", "Tabs.TradeQuest.Menu.Decline" }) do
        local node = gui()
        for piece in string.gmatch(part, "[^%.]+") do
            node = node and node:FindFirstChild(piece)
        end
        if node then
            log("%s [%s] Visible=%s handlers=%d", part, node.ClassName,
                tostring(node.Visible), liveConnections(asButton(node) or node))
        else
            log("%s — нет в дереве", part)
        end
    end
end

local okRemote, tradeUpdate = pcall(Env.remote, "TradingService", "TradeUpdate")
if okRemote and tradeUpdate then
    Life.connect(tradeUpdate.OnClientEvent, function(payload)
        Env.elevate()
        if type(payload) ~= "table" then
            return
        end
        local kind = tostring(payload.Type)
        if kind ~= "Offer" then
            log("TradeUpdate: %s", kind)
        end
        lastStage = kind
        if kind == "Review" then
            sawReview = true
        elseif kind == "Confirm" then
            -- ВАЖНО: "Confirm" — это подтверждение ЛЮБОЙ из сторон, а не наше.
            -- Банк часто подтверждает первым, и раньше мы из-за этого решали, что уже
            -- всё сделано, и не отправляли свой CONFIRM вообще (лог 07.11: нажатий 0).
            local me = Env.LocalPlayer and Env.LocalPlayer.UserId
            local by = tonumber(payload.UserId) or tonumber(payload.FromUserId) or tonumber(payload.Who)
            if by ~= nil and me ~= nil and by == me then
                sawConfirm = true
                log("наш CONFIRM принят игрой — ждём Countdown")
            elseif by ~= nil then
                log("вторая сторона подтвердила (UserId %s) — наш CONFIRM ещё не отправлен", tostring(by))
            else
                -- UserId в событии нет: не считаем это нашим подтверждением, шлём своё
                log("пришёл Confirm без UserId — считаю, что подтвердила другая сторона")
            end
        elseif kind == "Countdown" or kind == "Processing" or kind == "Securing" or kind == "Completed" then
            sawConfirm = true -- сделка пошла дальше: наш CONFIRM точно зарегистрирован
        end

        if kind == "Request" then
            local name, fromId = payload.FromName, tonumber(payload.FromUserId)
            if not name and fromId then
                pcall(function()
                    local player = Env.Players:GetPlayerByUserId(fromId)
                    name = player and player.Name or nil
                end)
            end
            if not allowed(name, fromId) then
                log("запрос не от банка (%s) — отклоняю", tostring(name))
                press(byPath(DECLINE_PATH), "DECLINE (не банк)")
                return
            end
            if not moduleEnabled() then
                log("handover выключен — трейд не отвечаю (getgenv().handoverEnable())")
                return
            end
            acceptTrade(name, fromId)
        elseif kind == "Started" then
            traded = false
            startedEvent = true
            if not busy then
                log("сессия уже открыта (Started пришёл без Request)")
                if moduleEnabled() then
                    busy = true
                    finishedLogged = false
                    task.spawn(function()
                        pauseFarm()
                        task.wait(1.5)
                        handover()
                    end)
                end
            end
        elseif kind == "Completed" or kind == "Cancelled" then
            if finishedLogged then
                return
            end
            finishedLogged = true
            traded = true
            log("трейд закончился: %s", kind)
            busy = false
            stage = "ждём следующий трейд"
            resumeFarm()
        end
    end)
else
    log("НЕТ remote TradeUpdate — трейд по GUI не определить, модуль работать не сможет")
end

-- Надпись в панели: раз в 2 секунды показываем, что видно. Ничего не нажимает и не пишет в лог —
-- сам трейд ловится только событием TradeUpdate.
Life.loop("handover:poll", POLL_SECONDS, function()
    if busy then
        pcall(function()
            statusLabel:SetText("Handover: " .. stage)
        end)
        return
    end
    local live = liveConnections(findAcceptButton())
    if live > 0 then
        setStatus("окно трейда открыто, ждём событие")
    else
        setStatus("ждём запрос от банка")
    end
end)

-- ---------------------------------------------------------------------------------------------
-- кнопки панели и ручные команды
-- ---------------------------------------------------------------------------------------------

box:AddButton({
    Text = "Проверить трейд сейчас",
    Func = function()
        task.spawn(function()
            busy = true
            finishedLogged = false
            traded = false
            handover()
            busy = false
        end)
    end,
})

box:AddButton({
    Text = "Дамп дерева трейда",
    Func = function()
        dumpTrade()
    end,
})

Env.genv.handoverEnable = function()
    running = true
    pcall(Ui.set, "Handover", true)
    log("handover включён вручную")
end

Env.genv.handoverDisable = function()
    running = false
    log("handover выключен вручную")
end

Env.genv.farmTradeDump = dumpTrade

Env.genv.farmTrade = {
    state = function()
        local ready = findReadyButton()
        local confirm = findConfirmButton()
        log("этап: %s | занят: %s | сделка закрыта: %s | Started: %s",
            stage, tostring(busy), tostring(traded), tostring(startedEvent))
        log("ACCEPT:  %s | обработчиков %d",
            findAcceptButton() and findAcceptButton():GetFullName() or "нет", liveConnections(findAcceptButton()))
        log("READY:   %s | обработчиков %d",
            ready and ready:GetFullName() or "нет", liveConnections(ready))
        log("CONFIRM: %s | обработчиков %d",
            confirm and confirm:GetFullName() or "нет", liveConnections(confirm))
        return stage
    end,
    dump = dumpTrade,
    unequip = function()
        return unequipRarity(SECRET_WORD)
    end,
    offer = function()
        return offerRarity(SECRET_WORD)
    end,
    accept = function()
        return press(findAcceptButton(), "ACCEPT")
    end,
    ready = function()
        return press(findReadyButton(), "READY")
    end,
    confirm = function()
        return pressConfirmRounds()
    end,
    full = function()
        task.spawn(handover)
        return "запущено"
    end,
    stop = function()
        running = false
        log("автоматика выключена")
    end,
}

log("=== handover %s === порт farm_trade_only: событие Request -> пауза фарма -> снять Secret -> "
    .. "Accept -> оффер Secret -> 1.5 с -> READY -> CONFIRM раундами. Godly не трогаем.", BUILD)
setStatus("ждём запрос от банка")
return {}
end

__modules["features/holdreveal"] = function(use) -- src/games/tapsim/features/holdreveal.luau
-- «Hold to Reveal!» на экране вылупления: одна карточка — одно зажатие.
--
-- Кнопку снял логгер нажатий (click_logger.lua):
--   PlayerGui.HatchScreen.Main.Info.HatchEgg            [TextButton]  — сама кнопка
--   ...HatchEgg.TextLabel                               «Hold to Reveal!»
--   ...HatchEgg.HoldProgress                            [Frame] — полоска, растёт при удержании
-- Игра слушает удержание парой MouseButton1Down / MouseButton1Up (Activated и
-- MouseButton1Click у кнопки пустые), поэтому жмём Down, следим за полоской и отпускаем на Up.
--
-- Правило, по просьбе, одно:
--   карточка появилась -> зажали -> полоска заполнилась -> отпустили -> ждём следующую.
-- На той же карточке повторов нет: после заполнения модуль молчит, пока карточка не пропадёт
-- с экрана (GONE_QUIET секунд) — или, страховки ради, пока полоска не продержится на нуле
-- FALLBACK_ZERO секунд спустя FALLBACK_GAP секунд после заполнения (если игра переиспользует ту
-- же карточку под следующее яйцо и не убирает её с экрана).
-- v2: добавлена прямая страховка от флуда — если полоска на карточке УЖЕ полная, модуль не жмёт
-- вообще (v1 в этой ситуации молчал только по таймингам, а старый отдельный скрипт жал повторно
-- каждые 0.16 с и забивал лог).
--
-- В лог — одна короткая строка на карточку, а не поток. Всё остальное по требованию:
--   getgenv().holdRevealState()   — что модуль видит сейчас (кнопка, полоска, состояние)
--   getgenv().holdRevealDebug(true) — подробный лог каждой попытки

local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")

local BUILD = "v2"

local BUTTON_PATH = { "HatchScreen", "Main", "Info", "HatchEgg" }
local FILLED = 0.98          -- полоска заполнена (доля ширины кнопки)
local HOLD_MAX = 12          -- максимум держим одну карточку, секунды
local POLL = 0.35            -- как часто смотрим на экран
local RETRY_AT = 1.2         -- полоска стоит на нуле столько — жмём ещё раз в центр надписи
local RETRY_LIMIT = 2        -- не больше стольких повторов на одну карточку
local GONE_QUIET = 1.5       -- карточка пропала на столько — считаем, что будет следующая
local MIN_GAP = 3            -- после заполнения столько секунд вообще не жмём
local FALLBACK_GAP = 3       -- страховка: следующее зажатие не раньше, чем через столько секунд
local FALLBACK_ZERO = 1      -- и только если полоска всё это время на нуле
local BLIND_HOLD = 2.5       -- если полоску прочитать нельзя — держим столько и отпускаем

local tab = Ui.Tabs.Pets
local box = tab:AddGroupbox({ Side = "Right", Name = "Hold to Reveal", IconName = "egg" })
box:AddToggle("AutoReveal", {
    Text = "Держать «Hold to Reveal»",
    Default = true,
    Tooltip = "Карточка вылупления: зажать, дождаться заполнения полоски, отпустить. Один раз на карточку — дальше модуль ждёт следующую.",
})
local statusLabel = box:AddLabel("Hold: ждём карточку", true)

local verbose = false

local function log(fmt, ...)
    local ok, text = pcall(string.format, fmt, ...)
    print("[hold " .. BUILD .. "] " .. (ok and text or tostring(fmt)))
end

local function debugLog(fmt, ...)
    if not verbose then
        return
    end
    local ok, text = pcall(string.format, fmt, ...)
    print("[hold " .. BUILD .. " debug] " .. (ok and text or tostring(fmt)))
end

local function setStatus(text)
    pcall(function()
        statusLabel:SetText("Hold: " .. text)
    end)
end

-- Тумблер читается на каждом проходе (без локального флага): Ui.stopAll от handover его не гасит,
-- потому что модуль не зарегистрирован как automation, а значение всегда живое.
local function enabled()
    local P = Ui.__progressTest
    -- Раскрытие уже появившейся карточки не открывает новое яйцо и не должно ждать конца прокачки.
    if P and (P.stopRequested or P.phase == "stopped") then return false end
    local ok, value = pcall(function()
        return Ui.on("AutoReveal")
    end)
    return ok and value == true
end

local function gui()
    local player = Env.LocalPlayer
    return player and player:FindFirstChild("PlayerGui")
end

local function textOf(node)
    local ok, text = pcall(function()
        return node.Text
    end)
    if ok and type(text) == "string" then
        return (string.lower(text):gsub("%s+", " "))
    end
    return ""
end

local function isHoldText(button)
    for _, child in ipairs(button:GetDescendants()) do
        local text = textOf(child)
        if string.find(text, "hold to reveal", 1, true)
            or (string.find(text, "hold", 1, true) and string.find(text, "reveal", 1, true)) then
            return true
        end
    end
    return false
end

-- Кнопка карточки: по точному пути, а если путь изменился — по надписи внутри HatchScreen.
local function findButton()
    local playerGui = gui()
    if not playerGui then
        return nil
    end
    local screen = playerGui:FindFirstChild(BUTTON_PATH[1])
    if not screen then
        return nil
    end
    local node = screen
    for index = 2, #BUTTON_PATH do
        node = node and node:FindFirstChild(BUTTON_PATH[index])
    end
    if node and node:IsA("GuiButton") and isHoldText(node) then
        return node
    end
    for _, candidate in ipairs(screen:GetDescendants()) do
        if candidate:IsA("GuiButton") and isHoldText(candidate) then
            return candidate
        end
    end
    return nil
end

-- Доля заполнения полоски: ширина HoldProgress к ширине кнопки.
local function progressOf(button)
    local bar = button:FindFirstChild("HoldProgress")
    if not bar then
        for _, child in ipairs(button:GetChildren()) do
            local name = string.lower(child.Name)
            if string.find(name, "progress", 1, true) or string.find(name, "fill", 1, true) then
                bar = child
                break
            end
        end
    end
    if not bar then
        return nil
    end
    local ok, ratio = pcall(function()
        local buttonWidth = button.AbsoluteSize.X
        if buttonWidth <= 0 then
            return nil
        end
        return bar.AbsoluteSize.X / buttonWidth
    end)
    return ok and ratio or nil
end

-- Запуск обработчиков сигнала кнопки. Раньше здесь был pcall(connection.Fire) без self: метод
-- падал, ошибка глоталась, и выходило ложное «обработчиков 0» при живом MouseButton1Down=1.
local function fireSignal(button, signalName)
    local okSignal, signal = pcall(function()
        return button[signalName]
    end)
    if not okSignal or not signal then
        return 0
    end
    local fired = 0
    local genv = Env.genv or {}
    if type(genv.firesignal) == "function" then
        if pcall(genv.firesignal, signal) then
            fired += 1
        end
    end
    if type(genv.getconnections) == "function" then
        local okList, list = pcall(genv.getconnections, signal)
        if okList and type(list) == "table" then
            for _, connection in ipairs(list) do
                if connection.Enabled ~= false then
                    local ok = pcall(function()
                        connection:Fire()
                    end)
                    if not ok then
                        ok = pcall(function()
                            connection.Fire(connection)
                        end)
                    end
                    if ok then
                        fired += 1
                    end
                end
            end
        end
    end
    return fired
end

-- Точка нажатия и центр надписи (запасная цель, если кнопка не отзывается на первую точку).
local function points(button)
    local ok, x, y, labelX, labelY = pcall(function()
        local pos = button.AbsolutePosition + button.AbsoluteSize * 0.5
        local lx, ly = math.floor(pos.X), math.floor(pos.Y)
        for _, child in ipairs(button:GetDescendants()) do
            if child:IsA("TextLabel") then
                local labelPos = child.AbsolutePosition + child.AbsoluteSize * 0.5
                lx, ly = math.floor(labelPos.X), math.floor(labelPos.Y)
                break
            end
        end
        return math.floor(pos.X), math.floor(pos.Y), lx, ly
    end)
    if not ok then
        return nil
    end
    return x, y, labelX, labelY
end

-- Снять Active с фреймов выше кнопки (они съедают нажатие), потом вернуть как было.
local function unblock(x, y, button)
    local playerGui = gui()
    if not playerGui then
        return {}
    end
    local ok, objects = pcall(function()
        return playerGui:GetGuiObjectsAtPosition(x, y)
    end)
    if not ok or type(objects) ~= "table" then
        return {}
    end
    local saved = {}
    for _, node in ipairs(objects) do
        local inside = false
        local ancestor = node
        while ancestor do
            if ancestor == button then
                inside = true
                break
            end
            ancestor = ancestor.Parent
        end
        if not inside and node:IsA("GuiObject") then
            local okActive, active = pcall(function()
                return node.Active
            end)
            if okActive and active == true then
                saved[#saved + 1] = node
                pcall(function()
                    node.Active = false
                end)
            end
        end
    end
    return saved
end

local function restore(saved)
    for _, node in ipairs(saved or {}) do
        pcall(function()
            node.Active = true
        end)
    end
end

-- Life.shutdown отменяет рабочую корутину, поэтому отпускание должно работать и из cleanup.
local activeHold = nil
local function releaseHold(hold)
    if not hold or activeHold ~= hold then return end
    activeHold = nil
    if hold.vim and hold.mouseDown and hold.x and hold.y then
        pcall(function() hold.vim:SendMouseButtonEvent(hold.x, hold.y, 0, false, game, 1) end)
    end
    fireSignal(hold.button, "MouseButton1Up")
    restore(hold.saved)
    Env.elevate()
end
Life.onCleanup(function() releaseHold(activeHold) end)

-- Одно зажатие: держим, пока полоска не заполнится (или карточка не уйдёт), максимум HOLD_MAX.
-- Возвращает "filled" | "gone" | "limit" | "gone-early" — по нему и решается, что писать в лог.
local function holdOnce(button)
    if not Life.alive or not enabled() then return "stopped", 0 end
    Env.elevate()
    local started = os.clock()
    local hold = { button = button }
    activeHold = hold
    local hands = fireSignal(button, "MouseButton1Down")
    if not Life.alive or not enabled() then
        releaseHold(hold)
        return "stopped", os.clock() - started
    end
    local x, y, labelX, labelY = points(button)
    if not x then
        releaseHold(hold)
        return "limit", 0
    end
    hold.x, hold.y = x, y
    local vim
    pcall(function()
        vim = game:GetService("VirtualInputManager")
    end)
    hold.vim = vim
    local saved = unblock(x, y, button)
    hold.saved = saved
    if not Life.alive or not enabled() then
        releaseHold(hold)
        restore(saved) -- на случай shutdown внутри получения перекрывающих фреймов
        return "stopped", os.clock() - started
    end
    debugLog("кнопка %s | обработчиков Down: %d | мышь %s | точка %d,%d",
        button:GetFullName(), hands, vim and "да" or "нет", x, y)
    if vim then
        hold.mouseDown = true -- даже при ошибке вызываем безопасное отпускание
        pcall(function()
            vim:SendMouseButtonEvent(x, y, 0, true, game, 1)
        end)
    end

    local result = "limit"
    local ratio = nil
    local retries = 0
    local zeroSince = nil
    while os.clock() - started < HOLD_MAX do
        task.wait(0.15)
        if not Life.alive or not enabled() then
            result = "stopped"
            break
        end
        if not button.Parent then
            result = "gone"
            break
        end
        ratio = progressOf(button)
        if ratio and ratio >= FILLED then
            result = "filled"
            break
        end
        if ratio and ratio <= 0.02 then
            zeroSince = zeroSince or os.clock()
            -- Нажатие не дошло: один-два раза пробуем ещё раз, но уже в центр надписи.
            if retries < RETRY_LIMIT and os.clock() - zeroSince >= RETRY_AT then
                retries += 1
                zeroSince = nil
                debugLog("полоска на нуле — повторное нажатие в %d,%d", labelX, labelY)
                if vim then
                    local released = pcall(function()
                        vim:SendMouseButtonEvent(x, y, 0, false, game, 1)
                    end)
                    if released then hold.mouseDown = false end
                    task.wait(0.1)
                    if not Life.alive or not enabled() then
                        result = "stopped"
                        break
                    end
                    x, y = labelX, labelY
                    hold.x, hold.y, hold.mouseDown = x, y, true
                    pcall(function()
                        vim:SendMouseButtonEvent(x, y, 0, true, game, 1)
                    end)
                end
                if not Life.alive or not enabled() then
                    result = "stopped"
                    break
                end
                x, y = labelX, labelY
                hold.x, hold.y = x, y
                fireSignal(button, "MouseButton1Down")
            end
        else
            zeroSince = nil
        end
        if not ratio and os.clock() - started >= BLIND_HOLD then
            result = "limit"
            break
        end
    end

    releaseHold(hold)
    return result, os.clock() - started, ratio
end

-- Состояние: одна карточка — одно зажатие -------------------------------------------------------

local state = {
    armed = true,      -- можно ли жать (false = уже заполнили эту карточку, ждём следующую)
    filledAt = 0,      -- когда отпустили после заполнения
    goneAt = nil,      -- когда карточку последний раз не было на экране
    zeroSince = nil,   -- с какого момента полоска стоит на нуле
    cards = 0,         -- сколько карточек заполнено с момента запуска
}

local function arm(reason)
    state.armed = true
    state.zeroSince = nil
    debugLog("снова можно жать: %s", reason)
end

Life.loop("holdreveal:watch", POLL, function()
    if not enabled() then
        local P = Ui.__progressTest
        if P and (P.stopRequested or P.phase == "stopped") then
            setStatus("остановлено пользователем")
            return
        end
        -- Карточка на экране, а модуль выключен — молчать нельзя, иначе «не работает» без причин.
        -- Одна строка не чаще раза в 30 с, и только когда карточка правда на экране.
        local nowClock = os.clock()
        if nowClock - (state.warnAt or 0) > 30 and findButton() then
            state.warnAt = nowClock
            log("карточка на экране, но тумблер «Держать Hold to Reveal» выключен — не жму")
            setStatus("выключен тумблер — карточку не держу")
        end
        return
    end
    local now = os.clock()
    local button = findButton()

    if not button then
        state.zeroSince = nil
        state.goneAt = state.goneAt or now
        if not state.armed and now - state.filledAt >= MIN_GAP and now - state.goneAt >= GONE_QUIET then
            arm("карточка ушла с экрана")
            setStatus("ждём карточку")
        end
        return
    end

    state.goneAt = nil
    if not state.armed then
        -- Страховка на случай, если игра переиспользует ту же карточку под следующее яйцо.
        local ratio = progressOf(button)
        if ratio and ratio <= 0.1 then
            state.zeroSince = state.zeroSince or now
        else
            state.zeroSince = nil
        end
        if state.zeroSince and now - state.filledAt >= FALLBACK_GAP
            and now - state.zeroSince >= FALLBACK_ZERO then
            arm("полоска снова на нуле — похоже, следующая карточка")
        else
            return
        end
    end

    -- Страховка от того самого флуда: если полоска уже полная, второе зажатие не нужно —
    -- эта карточка уже заполнена, ждём следующую (игра держит её на экране с полной полоской).
    local filledNow = progressOf(button)
    if filledNow and filledNow >= FILLED then
        state.armed = false
        state.filledAt = state.filledAt ~= 0 and state.filledAt or now
        setStatus("полоска уже заполнена — жду следующую")
        return
    end
    setStatus("держу кнопку")
    local result, seconds, ratio = holdOnce(button)
    state.armed = false
    state.filledAt = os.clock()

    if result == "filled" then
        state.cards += 1
        setStatus("заполнили — ждём следующую")
        log("карточка #%d: заполнил за %.2f с — отпустил, жду следующую", state.cards, seconds)
    elseif result == "gone" then
        state.cards += 1
        setStatus("карточка закрылась — ждём следующую")
        log("карточка #%d: закрылась во время удержания (%.2f с)", state.cards, seconds)
    elseif result == "stopped" then
        setStatus("остановлено пользователем")
    else
        -- заполнить не удалось: пишем это всегда, тут молчать нельзя
        setStatus("не заполнилась")
        log("карточка: заполнить не удалось за %.2f с (полоска %s) — жду следующую",
            seconds, ratio and string.format("%.2f", ratio) or "не читается")
    end
end)

Env.genv.holdRevealEnable = function()
    pcall(Ui.set, "AutoReveal", true)
    log("«Hold to Reveal» включён вручную")
    return true
end

Env.genv.holdRevealDisable = function()
    pcall(Ui.set, "AutoReveal", false)
    log("«Hold to Reveal» выключен вручную")
    return false
end

Env.genv.holdRevealDebug = function(value)
    verbose = value ~= false
    return verbose
end

Env.genv.holdRevealState = function()
    local button = findButton()
    local ratio = button and progressOf(button) or nil
    log("тумблер: %s", tostring(enabled()))
    log("кнопка: %s | полоска: %s | можно жать: %s | заполнено карточек: %d",
        button and button:GetFullName() or "нет",
        ratio and string.format("%.2f", ratio) or "нет",
        tostring(state.armed), state.cards)
    return button
end

log("готов: карточка появилась -> зажал -> полоска заполнилась -> отпустил -> ждём следующую")
log("тумблер «Держать Hold to Reveal»: %s%s", tostring(enabled()),
    enabled() and "" or " — модуль молчит, пока его не включат (getgenv().holdRevealEnable())")
return {}
end
__modules["features/craft_continue"] = function(use)
-- Craft results are separate from HatchScreen / Hold to Reveal. For one *visible* craft result
-- card, activate its Continue button and observe the result. If that same visible card remains,
-- retry every few seconds; stop once it is gone. Never force-hide/destroy the GUI,
-- and never deliberately activate an unrelated Continue button.
local Env = use("core/env")
local Life = use("shared/life")
local Ui = use("core/ui")
local WAIT_VISIBLE = 0.35
local WARN_AFTER = 4
local FIRST_RETRY_SECONDS = 2 -- one extra press after two seconds if the same card is still visible
local RETRY_SECONDS = 3 -- later retries if the same recognized card is still visible
local POLL, FAST_POLL = 0.75, 0.25 -- fast only while the first retry is approaching
local currentGui, nextRescan = nil, 0
local unmatchedSince, nextUnmatchedLog = nil, 0
local buttons = setmetatable({}, { __mode = "k" })
local rolls = setmetatable({}, { __mode = "k" })
local states = setmetatable({}, { __mode = "k" })
local rollStates = setmetatable({}, { __mode = "k" })
local ambiguousWarned = false
local mouseHeld

local function log(text)
    print("[TAPSIM] крафт: " .. tostring(text))
end
local function normalize(value)
    if type(value) ~= "string" then return "" end
    local text = string.lower(value):gsub("<[^>]->", ""):gsub("%s+", " ")
    return (text:gsub("^%s+", ""):gsub("%s+$", ""))
end
local function nameOf(node)
    local ok, name = pcall(function() return node.Name end)
    return ok and normalize(name) or ""
end
local function craftName(node)
    local compact = nameOf(node):gsub("[%s_%-]", "")
    return compact == "craftingroll" or compact == "craftresult" or compact == "craftresultwindow"
        or compact == "craftingresult"
end
local function fullName(node)
    local ok, value = pcall(function() return node:GetFullName() end)
    return ok and tostring(value) or tostring(node and node.Name or "?")
end
local function textOf(node)
    local ok, text = pcall(function() return node.Text end)
    return ok and normalize(text) or ""
end
local function isCraftedTitle(text)
    if type(text) ~= "string" then return false end
    if text:match("^crafted%s*[!%.]*$") then return true end
    -- Some layouts combine the title and tier in one label, e.g. "Crafted! GOLDEN".
    -- Restrict the suffix to known craft tiers; arbitrary nearby text is not evidence.
    local tier = text:match("^crafted%s*[!%.]+%s*(.-)%s*$")
    return tier == "golden" or tier == "diamond" or tier == "rainbow" or tier == "shiny"
end
local function isA(node, class)
    local ok, yes = pcall(function() return node:IsA(class) end)
    return ok and yes == true
end
local function children(node)
    local ok, list = pcall(function() return node:GetDescendants() end)
    return ok and type(list) == "table" and list or {}
end

-- An Enabled ScreenGui can contain hidden frames. Every ancestor must be visible, and it must
-- belong to this player's PlayerGui; an off-screen template or a hub button is never clicked.
local function shown(node, gui)
    if not node or not gui then return false end
    local current, limit = node, 0
    while current and current ~= gui and limit < 80 do
        if isA(current, "GuiObject") then
            local ok, visible = pcall(function() return current.Visible end)
            if not ok or visible ~= true then return false end
        elseif isA(current, "LayerCollector") then
            local ok, enabled = pcall(function() return current.Enabled end)
            if not ok or enabled ~= true then return false end
        end
        local ok, parent = pcall(function() return current.Parent end)
        if not ok then return false end
        current = parent
        limit += 1
    end
    return current == gui
end
local function isContinue(button, gui)
    local name = nameOf(button):gsub("[%s_%-]", "")
    if name == "continue" or name == "continuebutton" or textOf(button) == "continue" then return true end
    local parent = button.Parent
    local parentName = parent and nameOf(parent):gsub("[%s_%-]", "") or ""
    if parentName == "continue" and (name == "button" or name == "click") then return true end
    for _, child in ipairs(children(button)) do
        if textOf(child) == "continue" and shown(child, gui) then return true end
    end
    return false
end

local function resultEvidence(scope, gui)
    local title, rate, outcome = false, false, false
    for _, node in ipairs(children(scope)) do
        -- Only actually visible text can identify this card; hidden craft menus are not evidence.
        local text = textOf(node)
        if text ~= "" and shown(node, gui) then
            if isCraftedTitle(text) then title = true end
            if text:find("success rate", 1, true) then rate = true end
            if text:find(" became ", 1, true) then outcome = true end
            if title and rate and outcome then break end
        end
    end
    return title, rate, outcome
end
local function isWithin(node, ancestor)
    local depth = 0
    while node and depth < 80 do
        if node == ancestor then return true end
        node, depth = node.Parent, depth + 1
    end
    return false
end
local function separateResult(scope, button, gui)
    -- A common container can hold several dialogs. A Continue outside an explicitly named
    -- craft-result child is not that child's button, even if text happens to be visible.
    for _, child in ipairs(children(scope)) do
        if craftName(child) and not isWithin(button, child) and shown(child, gui) then
            local title, rate, outcome = resultEvidence(child, gui)
            if title or rate or outcome then return true end
        end
    end
    -- Even an anonymously named sibling may be a complete separate result dialog. If it
    -- contains the complete result evidence while the button is elsewhere, do not guess.
    local ok, direct = pcall(function() return scope:GetChildren() end)
    if not ok or type(direct) ~= "table" then return true end
    for _, child in ipairs(direct) do
        if isA(child, "GuiObject") and not isWithin(button, child) and shown(child, gui) then
            local title, rate, outcome = resultEvidence(child, gui)
            if title and (rate or outcome) then return true end
        end
    end
    return false
end
local function craftScope(button, gui)
    local node, steps = button.Parent, 0
    while node and node ~= gui and steps < 25 do
        local layer = isA(node, "LayerCollector")
        if shown(node, gui) then
            local title, rate, outcome = resultEvidence(node, gui)
            local marker = craftName(node)
            -- A rate label alone may be part of the crafting menu before any result exists.
            -- Named craft-result ScreenGuis are valid even when the button is their direct child.
            if marker and (title or outcome) then return node end
            -- Do not combine unrelated windows simply because they share a ScreenGui. The
            -- generic fallback must have a common *object* panel and no separate craft-result
            -- child elsewhere inside that panel. Unknown layouts are left untouched.
            if not layer and title and (rate or outcome)
                and not separateResult(node, button, gui) then return node end
        end
        if layer then break end
        node = node.Parent
        steps += 1
    end
    return nil
end
local function namedResultAncestor(node, gui)
    local depth = 0
    while node and node ~= gui and depth < 80 do
        if craftName(node) and shown(node, gui) then return node end
        node, depth = node.Parent, depth + 1
    end
    return nil
end
local function track(node)
    if isA(node, "GuiButton") then buttons[node] = true end
    if craftName(node) then rolls[node] = true end
end
local function disconnectState(state)
    for _, connection in ipairs(state.connections or {}) do
        pcall(function() connection:Disconnect() end)
    end
    state.connections = {}
end
local function forget(button, state, guiChanged)
    disconnectState(state)
    if state.attempted and state.sent and not guiChanged then
        if state.sawHidden and shown(button, currentGui) then
            log("окно результата скрывалось и появилось снова; старые повторы прекращены")
        else
            log("Continue или окно результата больше не видно; повторы прекращены")
        end
    end
    states[button] = nil
end
local function releaseMouse()
    local hold = mouseHeld
    mouseHeld = nil
    if hold then pcall(function() hold.vim:SendMouseButtonEvent(hold.x, hold.y, 0, false, game, 1) end) end
end
Life.onCleanup(function()
    releaseMouse()
    for button, state in pairs(states) do forget(button, state, true) end
end)
local function bind(gui)
    if gui == currentGui then return end
    for button, state in pairs(states) do forget(button, state, true) end
    table.clear(buttons)
    table.clear(rolls)
    table.clear(rollStates)
    ambiguousWarned = false
    unmatchedSince, nextUnmatchedLog, nextRescan = nil, 0, 0
    currentGui = gui
    if not gui then return end
    for _, node in ipairs(children(gui)) do track(node) end
    -- The game may build or replace the result card after the script starts.
    Life.connect(gui.DescendantAdded, function(node)
        if currentGui == gui then track(node) end
    end, "craft:continue:added")
    Life.connect(gui.DescendantRemoving, function(node)
        if currentGui == gui then buttons[node], rolls[node] = nil, nil end
    end, "craft:continue:removed")
end

-- Catch a quick hide/reopen even if both happen between two polls. Disconnect these watchers
-- after the card is gone; do not accumulate one connection per crafted pet.
local function watchVisibility(button, gui, state)
    state.connections = {}
    local node, depth = button, 0
    while node and node ~= gui and depth < 80 do
        local property = isA(node, "GuiObject") and "Visible" or (isA(node, "LayerCollector") and "Enabled" or nil)
        if property then
            local ok, signal = pcall(function() return node:GetPropertyChangedSignal(property) end)
            if ok and signal then
                local okConnect, connection = pcall(function()
                    return signal:Connect(function()
                        if Life.alive and not shown(button, gui) then state.sawHidden = true end
                    end)
                end)
                if okConnect and connection then state.connections[#state.connections + 1] = connection end
            end
        end
        node = node.Parent
        depth += 1
    end
end

local function executorFunction(name, global)
    local env = Env.genv or {}
    if type(env[name]) == "function" then return env[name] end
    return type(global) == "function" and global or nil
end
local function eventChoices(button)
    local getter = executorFunction("getconnections", getconnections)
    if not getter then return {} end
    local out = {}
    for _, eventName in ipairs({ "MouseButton1Click", "Activated" }) do
        local ok, signal = pcall(function() return button[eventName] end)
        if ok and signal then
            local listed, connections = pcall(getter, signal)
            if listed and type(connections) == "table" then
                local active, score = {}, 0
                for _, connection in ipairs(connections) do
                    local alive, enabled = pcall(function() return connection.Enabled end)
                    if not alive or enabled ~= false then
                        active[#active + 1] = connection
                        local okSource, source = pcall(function()
                            local fn = connection.Function
                            return type(fn) == "function" and debug.info(fn, "s") or ""
                        end)
                        if okSource and type(source) == "string" then
                            source = string.lower(source)
                            if source:find("craft", 1, true) or source:find("machine", 1, true)
                                or source:find("craftingroll", 1, true) then score += 10 end
                        end
                    end
                end
                if #active > 0 then out[#out + 1] = { name = eventName, signal = signal, connections = active, score = score } end
            end
        end
    end
    return out
end
local function relatedTo(a, b)
    local current, depth = a, 0
    while current and depth < 80 do
        if current == b then return true end
        current, depth = current.Parent, depth + 1
    end
    return false
end
local function virtualInput(button, gui)
    local ok, target = pcall(function()
        local size, pos = button.AbsoluteSize, button.AbsolutePosition
        assert(size.X > 0 and size.Y > 0, "button has no size")
        local x, y = math.floor(pos.X + size.X * 0.5), math.floor(pos.Y + size.Y * 0.5)
        local objects = gui:GetGuiObjectsAtPosition(x, y)
        assert(type(objects) == "table", "cannot check GUI hit test")
        local reached = false
        for _, object in ipairs(objects) do
            if object == button then reached = true; break end
            if not relatedTo(object, button) and not relatedTo(button, object) then
                -- A different active overlay or button above the target can receive the click.
                if isA(object, "GuiButton") or (isA(object, "GuiObject") and object.Active == true) then
                    return nil
                end
            end
        end
        if not reached then return nil end -- not known to be actually under the click
        return { vim = game:GetService("VirtualInputManager"), x = x, y = y, button = button, gui = gui }
    end)
    return ok and target or nil
end
local function viaMouse(target, stillCurrent)
    if not stillCurrent() or not shown(target.button, target.gui) or not craftScope(target.button, target.gui) then
        return false, "окно уже изменилось", nil
    end
    -- Recheck the exact coordinates and that no unrelated active control is now on top.
    local fresh = virtualInput(target.button, target.gui)
    if not fresh or fresh.x ~= target.x or fresh.y ~= target.y or not stillCurrent() then
        return false, "кнопка закрыта или перекрыта", nil
    end
    target = fresh
    mouseHeld = target -- cleanup releases even if Life shuts down during the click
    local ok, err = pcall(function() target.vim:SendMouseButtonEvent(target.x, target.y, 0, true, game, 1) end)
    if ok then Life.wait(0.12) end
    releaseMouse()
    return ok, "мышь", err
end
local function activateOnce(button, stillCurrent, attempt, rememberedPrimary)
    Env.elevate()
    if not stillCurrent() then return false, "окно изменилось", nil end
    local fire = executorFunction("firesignal", firesignal)
    local choices = eventChoices(button)
    local mouse = virtualInput(button, currentGui)
    local byName = {}
    for _, choice in ipairs(choices) do byName[choice.name] = choice end
    local signals = {}
    for _, name in ipairs({ "MouseButton1Click", "Activated" }) do
        local ok, value = pcall(function() return button[name] end)
        if ok and value then signals[name] = value end
    end
    local function available(name)
        if name == "мышь" then return mouse ~= nil end
        if not signals[name] then return false end
        if fire then return true end
        local choice = byName[name]
        for _, connection in ipairs(choice and choice.connections or {}) do
            local ok, fn = pcall(function() return connection.Fire end)
            if ok and type(fn) == "function" then return true end
        end
        return false
    end
    local function primaryMethod()
        if rememberedPrimary and available(rememberedPrimary) then return rememberedPrimary end
        if #choices == 1 and available(choices[1].name) then return choices[1].name end
        if #choices > 1 then
            if choices[1].score ~= choices[2].score then
                local best = choices[1].score > choices[2].score and choices[1] or choices[2]
                if available(best.name) then return best.name end
            elseif available("мышь") then
                return "мышь" -- one real click emits the native button signals
            end
            for _, choice in ipairs(choices) do if available(choice.name) then return choice.name end end
        end
        if available("мышь") then return "мышь" end
        if available("MouseButton1Click") then return "MouseButton1Click" end
        if available("Activated") then return "Activated" end
        return nil
    end
    local primary = primaryMethod()
    if not primary then return false, "нет доступного способа", nil end
    local method = primary
    if attempt >= 3 then
        -- V11 repeated only the same signal forever. Some executors cannot enumerate the
        -- game's listeners: an apparently successful MouseButton1Click may do nothing when
        -- the game actually listens to Activated (or vice versa). After the requested repeat
        -- at +2 s, rotate a hit-tested real click and the other signal, one method per attempt.
        local alternatives, used = {}, {}
        local function add(name)
            if not used[name] and available(name) then used[name] = true; alternatives[#alternatives + 1] = name end
        end
        if primary ~= "мышь" then add("мышь") end
        if primary ~= "Activated" then add("Activated") end
        if primary ~= "MouseButton1Click" then add("MouseButton1Click") end
        add(primary)
        if #alternatives > 0 then method = alternatives[((attempt - 3) % #alternatives) + 1] end
    end
    if method == "мышь" then return viaMouse(mouse, stillCurrent) end
    if not stillCurrent() then return false, "окно изменилось", nil end
    if fire then
        local ok, err = pcall(fire, signals[method])
        return ok, method, err -- a dispatch is NOT proof that the result has closed
    end
    local choice = byName[method]
    local fired, attempted, lastError = 0, 0, nil
    for _, connection in ipairs(choice and choice.connections or {}) do
        local okMethod, callback = pcall(function() return connection.Fire end)
        if okMethod and type(callback) == "function" then
            if not stillCurrent() then break end
            attempted += 1
            local ok, err = pcall(function() connection:Fire() end)
            if ok then fired += 1 else lastError = err end
        end
    end
    if attempted > 0 then return fired > 0, method, lastError end
    return false, "обработчик " .. method .. " недоступен", lastError
end

-- A Continue button is often wrapped inside another GuiButton. Both then match the same
-- label, although they form one visual action. Collapse only a single ancestor/descendant
-- chain in the SAME craft-result scope; independent sibling buttons remain ambiguous.
local function collapseNested(matches)
    local leaves = {}
    for i, candidate in ipairs(matches) do
        local hasChild = false
        for j, other in ipairs(matches) do
            if i ~= j and candidate.scope == other.scope and isWithin(other.button, candidate.button) then
                hasChild = true; break
            end
        end
        if not hasChild then leaves[#leaves + 1] = candidate end
    end
    if #leaves == 1 and #matches > 1 then
        local leaf = leaves[1]
        -- Prefer a wrapper with a discoverable handler over a purely decorative inner button.
        -- When listeners cannot be inspected at all, use the innermost button and log retries.
        local ok, list = pcall(eventChoices, leaf.button)
        if not ok or #list == 0 then
            for _, candidate in ipairs(matches) do
                if candidate ~= leaf and candidate.scope == leaf.scope and isWithin(leaf.button, candidate.button) then
                    local worked, listeners = pcall(eventChoices, candidate.button)
                    if worked and #listeners > 0 then leaves[1] = candidate; break end
                end
            end
        end
    end
    return leaves
end

-- Read-only GUI details are logged if a visible Crafted! result cannot be matched. This runs
-- in the main payload, so diagnosing the next failure does not require an extra farm script.
local function guiDetails(gui, manual)
    if not gui then log("диагностика Continue: PlayerGui не найден"); return false end
    local titles, found, labels = {}, {}, {}
    for _, node in ipairs(children(gui)) do
        local text = textOf(node)
        if isCraftedTitle(text) and shown(node, gui) then titles[#titles + 1] = node end
        if text == "continue" and shown(node, gui) then labels[#labels + 1] = node end
        if isA(node, "GuiButton") and shown(node, gui) and isContinue(node, gui) then found[#found + 1] = node end
    end
    if #titles == 0 and not manual then return false end
    log("диагностика Continue: видимых Crafted=" .. tostring(#titles) .. ", видимых кнопок Continue=" .. tostring(#found)
        .. ", видимых надписей Continue=" .. tostring(#labels))
    for i = 1, math.min(#titles, 3) do log("Crafted: " .. fullName(titles[i])) end
    -- If the game uses a Frame/TextLabel instead of a GuiButton, the path is still useful
    -- to diagnose the real layout. Reading it here does not activate the object.
    for i = 1, math.min(#labels, 6) do
        local label = labels[i]
        local ok, parent = pcall(function() return label.Parent end)
        log("надпись Continue: " .. fullName(label) .. "; класс=" .. tostring(label.ClassName)
            .. "; родитель=" .. (ok and parent and fullName(parent) or "нет")
            .. "; класс родителя=" .. tostring(ok and parent and parent.ClassName or "?"))
    end
    for i = 1, math.min(#found, 6) do
        local button = found[i]
        local scope = craftScope(button, gui)
        local ok, info = pcall(function()
            local pos, size = button.AbsolutePosition, button.AbsoluteSize
            return string.format("pos=%.0f,%.0f size=%.0f,%.0f Active=%s",
                pos.X, pos.Y, size.X, size.Y, tostring(button.Active))
        end)
        local listed, events = pcall(eventChoices, button)
        local names = {}
        if listed then for _, entry in ipairs(events) do names[#names + 1] = entry.name .. ":" .. tostring(#entry.connections) end end
        log("кнопка " .. fullName(button) .. "; класс=" .. tostring(button.ClassName)
            .. "; область=" .. (scope and fullName(scope) or "не распознана")
            .. "; " .. (ok and info or "позиция недоступна")
            .. "; найденные обработчики=" .. (#names > 0 and table.concat(names, ",") or "не видны/не получены"))
    end
    return #titles > 0
end

local function watch()
    local P = Ui.__progressTest
    if not Life.alive or (P and (P.stopRequested or P.phase == "stopped")) then return end
    local player = Env.LocalPlayer
    local gui = player and player:FindFirstChild("PlayerGui") or nil
    bind(gui)
    if not gui then return end
    local now = os.clock()
    -- Recover if the game creates/reparents a result between event delivery and tracking.
    if now >= nextRescan then
        nextRescan = now + 5
        for _, node in ipairs(children(gui)) do track(node) end
    end
    local matches = {}
    for button in pairs(buttons) do
        if shown(button, gui) and isContinue(button, gui) then
            local scope = craftScope(button, gui)
            if scope then matches[#matches + 1] = { button = button, scope = scope } end
        end
    end
    local rawMatches = matches
    matches = collapseNested(rawMatches)
    for button, state in pairs(states) do
        -- The text may briefly change while the same card remains visible: that is not a new card.
        if state.sawHidden or not shown(button, gui) then forget(button, state, false) end
    end
    if #matches > 1 then
        if not ambiguousWarned then
            log("найдено несколько подходящих Continue (независимые кнопки); случайную кнопку не нажимаю")
            for i = 1, math.min(#matches, 4) do log("кандидат: " .. fullName(matches[i].button)) end
            ambiguousWarned = true
        end
        return
    end
    ambiguousWarned = false
    if #matches == 0 then
        unmatchedSince = unmatchedSince or now
        if now - unmatchedSince >= WARN_AFTER and now >= nextUnmatchedLog then
            local visibleCraft = guiDetails(gui, false)
            nextUnmatchedLog = now + (visibleCraft and 30 or 5)
        end
    else
        unmatchedSince = nil
    end
    if #matches == 1 then
        local button, scope = matches[1].button, matches[1].scope
        local state = states[button]
        if not state then
            state = { seenAt = now, attempted = false, sent = false, sawHidden = false,
                scope = scope, attempts = 0, nextAttemptAt = now + WAIT_VISIBLE }
            states[button] = state
            watchVisibility(button, gui, state)
        elseif state.scope ~= scope then
            local named = namedResultAncestor(button, gui)
            if named and isWithin(state.scope, named) and isWithin(scope, named) then
                -- The result animation may move labels between child panels while reusing the
                -- same button. Rebind only within the SAME explicitly named result window.
                state.scope, state.scopeWarned = scope, false
                state.nextAttemptAt = math.max(state.nextAttemptAt, now + WAIT_VISIBLE)
                log("структура той же карточки крафта обновилась; продолжаю проверять Continue")
            elseif not state.scopeWarned then
                state.scopeWarned = true
                log("область Continue изменилась; другую карточку не нажимаю")
                guiDetails(gui, true)
            end
        end
        local function stillCurrent()
            local P = Ui.__progressTest
            if not Life.alive or currentGui ~= gui or states[button] ~= state or state.sawHidden
                or (P and (P.stopRequested or P.phase == "stopped"))
                or not shown(button, gui) or not isContinue(button, gui)
                or craftScope(button, gui) ~= state.scope then return false end
            -- GUI listeners/overlays can appear during a yielding input lookup: check again.
            for other in pairs(buttons) do
                if other ~= button and shown(other, gui) and isContinue(other, gui) then
                    local otherScope = craftScope(other, gui)
                    local sameBranch = isWithin(other, button) or isWithin(button, other)
                    if otherScope and (otherScope ~= state.scope or not sameBranch) then return false end
                end
            end
            -- DescendantAdded may be delivered a frame later: also inspect the card itself.
            -- Only a wrapper/child in the same action branch is exempt from ambiguity.
            for _, other in ipairs(children(state.scope)) do
                if other ~= button and isA(other, "GuiButton") and shown(other, gui)
                    and isContinue(other, gui) and not (isWithin(other, button) or isWithin(button, other)) then return false end
            end
            return true
        end
        if now >= state.nextAttemptAt and stillCurrent() then
            -- Mark before a potentially yielding input call. A hide/reopen is a new result,
            -- never a late retry of the old one. The first retry is after two seconds; subsequent
            -- retries are every three seconds while the same unique result is visible.
            state.attempted, state.attemptedAt = true, now
            state.attempts += 1
            local attempt = state.attempts
            local gap = attempt == 1 and FIRST_RETRY_SECONDS or RETRY_SECONDS
            state.nextAttemptAt = now + gap

            -- When listeners cannot be inspected, the real listener may sit on a clickable
            -- wrapper rather than its nested decorative button. The two initial attempts stay
            -- on the original button. Afterwards try one method at a time on that same nested
            -- branch, never on independent siblings. Three consecutive attempts per branch
            -- cover all available methods even when their list has two or three entries.
            local branch, extra = { button }, {}
            for _, candidate in ipairs(rawMatches) do
                local other = candidate.button
                if other ~= button and candidate.scope == state.scope
                    and (isWithin(other, button) or isWithin(button, other)) then extra[#extra + 1] = other end
            end
            table.sort(extra, function(a, b)
                if isWithin(a, b) then return true end
                if isWithin(b, a) then return false end
                return fullName(a) < fullName(b)
            end)
            for _, other in ipairs(extra) do branch[#branch + 1] = other end
            local target = button
            if attempt >= 3 and #branch > 1 then
                local index = ((math.floor((attempt - 3) / 3) + 1) % #branch) + 1
                target = branch[index]
            end
            local function targetStillCurrent()
                if not stillCurrent() then return false end
                if target == button then return true end
                return (isWithin(target, button) or isWithin(button, target)) and shown(target, gui)
                    and isContinue(target, gui) and craftScope(target, gui) == state.scope
            end
            local remembered = target == button and state.primaryMethod or nil
            local ok, sent, method, err = pcall(activateOnce, target, targetStillCurrent, attempt, remembered)
            -- Start the first two-second delay at completion, including slow/yielding lookups.
            -- Later retries remain three seconds apart. A hidden/replaced card is never clicked.
            state.nextAttemptAt = math.max(state.nextAttemptAt, os.clock() + gap)
            local dispatched = ok and sent == true
            if target == button and not state.primaryMethod and ok
                and (method == "мышь" or method == "Activated" or method == "MouseButton1Click") then
                state.primaryMethod = method
            end
            state.sent = state.sent or dispatched
            local targetText = target ~= button and ("; вложенная кнопка=" .. fullName(target)) or ""
            if dispatched then
                if attempt == 1 then
                    log("окно результата: Continue отправлен (" .. tostring(method) .. "); жду закрытия")
                elseif attempt <= 6 or attempt % 10 == 0 then
                    log("окно ещё видно: повтор Continue #" .. tostring(attempt) .. " (" .. tostring(method)
                        .. targetText .. "); закрытие не подтверждено")
                end
            elseif attempt <= 6 or attempt % 10 == 0 then
                log("Continue #" .. tostring(attempt) .. " не отправлен (" .. tostring(ok and method or sent)
                    .. targetText .. "); повторю, только если окно останется" .. (err and (": " .. tostring(err)) or ""))
            end
            if attempt >= 4 and os.clock() >= (state.nextDebugAt or 0) and stillCurrent() then
                state.nextDebugAt = os.clock() + 30
                log("окно результата всё ещё открыто после нескольких попыток; подробности ниже")
                guiDetails(gui, true) -- read-only; do not equate a sent signal with closing the UI
            end
        end
    end
    -- If the known game menu is visible but its button layout has changed, say so once rather
    -- than silently clicking an unrelated button. No extra action is taken.
    for roll in pairs(rolls) do
        local title, rate, outcome = false, false, false
        if shown(roll, gui) then title, rate, outcome = resultEvidence(roll, gui) end
        if title or rate or outcome then
            local state = rollStates[roll]
            if not state then state = { since = now }; rollStates[roll] = state end
            if #matches == 0 and not state.warned and now - state.since >= WARN_AFTER then
                state.warned = true
                log("вижу окно CraftingRoll, но кнопку Continue не распознал")
            end
        else
            rollStates[roll] = nil
        end
    end
end
local function pollInterval()
    local P = Ui.__progressTest
    if P and (P.stopRequested or P.phase == "stopped") then return POLL end
    local now = os.clock()
    for _, state in pairs(states) do
        if state.attempts == 1 and not state.sawHidden and now <= state.nextAttemptAt + FAST_POLL then
            return FAST_POLL
        end
    end
    return POLL
end
local lastWatchError, nextErrorLog = nil, 0
local function safeWatch()
    local ok, err = pcall(watch)
    if ok then lastWatchError = nil; return end
    local text, now = tostring(err), os.clock()
    if text ~= lastWatchError or now >= nextErrorLog then
        log("ошибка проверки окна Continue: " .. text .. "; повторю")
        nextErrorLog = now + 30
    end
    lastWatchError = text
end
local function debugNow()
    if not Life.alive then print("[TAPSIM] крафт: скрипт уже остановлен"); return end
    local player = Env.LocalPlayer
    local gui = player and player:FindFirstChild("PlayerGui") or nil
    guiDetails(gui, true)
    if lastWatchError then log("последняя ошибка проверки: " .. lastWatchError) end
end
if type(Env.genv) == "table" then Env.genv.ts30ContinueDiag = debugNow end
Life.onCleanup(function()
    if type(Env.genv) == "table" and Env.genv.ts30ContinueDiag == debugNow then Env.genv.ts30ContinueDiag = nil end
end)
Life.loop("craft:continue", pollInterval, safeWatch)
return {}
end
__modules["main"] = function(use) -- src/games/tapsim/main.luau
-- Entry point. Core first, then features in tab order, then settings (autoload last).

if not game:IsLoaded() then
    game.Loaded:Wait()
end

local Env = use("core/env")

-- Nothing is built until the replica and character are there (see core/ready).
use("core/ready").wait()

-- The whole hub reads the player's Replica through the game's DataController. An executor that
-- cannot require it cannot run the hub, so that is said once here instead of every feature failing.
local canRead, readError = pcall(function()
    return Env.preloadData() ~= nil
end)
Env.elevate()
if not canRead or not Env.data() then
    error("could not read your game data (Replica/DataController): " .. tostring(readError), 0)
end

-- A copy already running is closed first (two hubs fighting over the UI).
local previous = Env.genv.__SlopixHub
-- Старая копия может иметь отправленный запрос, который невозможно отозвать.
local prevUi = type(previous) == "table" and type(previous.Ui) == "table" and previous.Ui or nil
local prevState = prevUi and prevUi.__progressTest
-- Quiesce a running V11/V12 copy before unloading it. Otherwise replacing a farm while its
-- 30M request is in flight loses the listener and necessarily puts the new copy on safety pause.
-- Stop NEW actions first, but leave the old listeners alive for up to 15 seconds to finish
-- already-sent hatch/craft/island/gem requests. Never discard a still-uncertain operation.
if type(prevState) == "table" and prevUi and prevUi.Library then
    prevState.stopRequested = true
    prevState.holdHatch, prevState.holdCraft = true, true
    prevState.holdUpgrades, prevState.holdSkillTree = true, true
    local function previousWorking()
        return prevUi.hatchInFlight == true or prevState.craftInFlight == true
            or prevState.islandInFlight == true or prevState.islandTravelInFlight == true
            or prevState.skillInFlight == true or prevState.upgradeInFlight == true
    end
    if previousWorking() then
        print("[TAPSIM] обновление: останавливаю новые действия и жду ответы предыдущей версии до 15 с")
        local deadline = os.clock() + 15
        while previousWorking() and os.clock() < deadline do task.wait(0.1) end
        Env.elevate()
        if previousWorking() or prevState.hatchUncertain or prevState.craftUncertain
            or prevState.islandUncertain or prevState.islandTravelUncertain
            or prevState.skillUncertain or prevState.upgradeUncertain then
            print("[TAPSIM] обновление: остался неподтверждённый запрос; защиту передам новой версии")
        else
            print("[TAPSIM] обновление: ожидание прошлых ответов завершено; продолжаю загрузку")
        end
    end
end
-- Carry the last selected farming egg across a same-client V11/V12 reload. V12's own
-- account-scoped persisted maximum still wins if it is higher than this last selection.
local previousFarmEgg = nil
if type(prevState) == "table" and prevState.eggFixed ~= true and prevState.rebirthLocked ~= true then
    if type(prevState.farmEggName) == "string" then previousFarmEgg = prevState.farmEggName end
    if not previousFarmEgg then
        pcall(function()
            local value = Env.LocalPlayer and Env.LocalPlayer:GetAttribute("TAPSIM_Egg")
            if type(value) == "string" then previousFarmEgg = value end
        end)
    end
end
local previousHatchPending = prevUi and (prevUi.hatchInFlight == true
    or (type(prevState) == "table" and (prevState.previousHatchPending == true or prevState.hatchUncertain == true))) or false
local prevRequest = type(prevState) == "table" and (prevState.pending or prevState.previousRebirthPending) or nil
local previousRebirthPending = type(prevRequest) == "table" and { before = prevRequest.before } or nil
local previousSkillUncertain = type(prevState) == "table" and (prevState.skillInFlight == true or prevState.skillUncertain == true) or false
local previousUpgradeUncertain = type(prevState) == "table" and (prevState.upgradeInFlight == true or prevState.upgradeUncertain == true) or false
local previousCraftPending = type(prevState) == "table" and (prevState.craftInFlight == true
    or prevState.craftUncertain == true or prevState.previousCraftPending == true) or false
local previousIslandPending = type(prevState) == "table" and (prevState.islandInFlight == true
    or prevState.islandUncertain == true or prevState.islandTravelInFlight == true
    or prevState.islandTravelUncertain == true or prevState.previousIslandPending == true) or false
if type(previous) == "table" and type(previous.Ui) == "table" and previous.Ui.Library then
    pcall(previous.Ui.Library.Unload, previous.Ui.Library)
    Env.genv.__SlopixHub = nil
    Env.elevate()
end

local Life = use("shared/life")
local Ui = use("core/ui")

-- Защита с самого начала, ДО запуска модулей и автозагрузки старых настроек.
-- Тест запускать на свежем входе в игру, не во время открытого трейда.
Ui.__progressTest = {
    phase = "bootstrap", holdHatch = true, holdUpgrades = true, equipReady = false,
    disableAutoCraft = true, holdCraft = true, stopRequested = false,
    previousHatchPending = previousHatchPending, previousRebirthPending = previousRebirthPending,
    previousCraftPending = previousCraftPending, previousIslandPending = previousIslandPending,
    previousFarmEgg = previousFarmEgg,
    skillUncertain = previousSkillUncertain, upgradeUncertain = previousUpgradeUncertain,
    holdTap = true, minHatchInterval = 2, -- до проверки диска не накапливаем возможный сбрасываемый баланс
}
if Env.genv then Env.genv.__handoverPaused = false end

-- Loaded in tab order, and within a tab in the order the boxes stack in each column.
local FEATURES = {
    -- Only the requested farm, plus local anti-AFK, performance, and egg reveal UI.
    "features/home", "features/performance",
    "features/tap", "features/upgrades", "features/skilltree",
    "features/island_progress", "features/hatch", "features/holdreveal", "features/pets", "features/craft", "features/craft_continue",
}

local function load(name)
    local ok, result = xpcall(use, debug.traceback, name)
    Env.elevate()
    if not ok then
        Life.errors["load:" .. name] = tostring(result)
        Ui.notify("Slopix Hub", string.format("%s failed to load; the rest still works.", name), 8)
        warn("[Slopix] " .. name .. ": " .. tostring(result))
    end
    return ok and result or nil
end

local loaded = {}
for _, name in ipairs(FEATURES) do
    loaded[name] = load(name)
end

local Settings = load("features/settings")
if Settings then
    Settings.finish()
end

-- After the autoload, so a saved "Claim offline earnings on load: off" is respected.
local Rewards = loaded["features/rewards"]
-- Во время теста не запрашиваем разовую оффлайн-награду: она испортит замер дохода.
if Rewards and not Ui.__progressTest and type(Rewards.afterLoad) == "function" then
    pcall(Rewards.afterLoad)
end

Env.genv.__SlopixHub = {
    Ui = Ui,
    Life = Life,
    Features = loaded,
}
Life.onCleanup(function()
    Env.genv.__SlopixHub = nil
end)

if Env.RuntimeState then
    Env.RuntimeState.onCleanup(function()
        Env.elevate()
        pcall(function()
            Ui.Library:Unload()
        end)
    end)
end

return "Slopix Hub loaded"
end
__modules["shared/env"] = function(use) -- src/shared/env.luau
-- Services, the local player, and the executor, the same for every game. Each game's core/env
-- extends this table with what only that game has (its ModuleScripts, its places).
--
-- Two Real quirks shape everything here:
--  * Calling into one of the game's modules, or yielding, can leave the thread without the
--    capability the UI needs ("lacking capability Plugin") while getthreadidentity() still says
--    8. Env.elevate() puts it back; Env.call() wraps a game call and elevates afterwards.
--  * Game modules are required lazily (Env.modules), so a feature only pays for what it uses.

local Env = {}

Env.Players = game:GetService("Players")
Env.ReplicatedStorage = game:GetService("ReplicatedStorage")
Env.RunService = game:GetService("RunService")
Env.CollectionService = game:GetService("CollectionService")
Env.VirtualUser = game:GetService("VirtualUser")
Env.TeleportService = game:GetService("TeleportService")
Env.HttpService = game:GetService("HttpService")
Env.LocalPlayer = Env.Players.LocalPlayer
if not Env.LocalPlayer then
    local deadline = os.clock() + 30
    repeat
        task.wait(0.05)
        Env.LocalPlayer = Env.Players.LocalPlayer
    until Env.LocalPlayer or os.clock() >= deadline
    assert(Env.LocalPlayer, "Slopix: local player is not ready; run the script again once the game loads")
end

local function first(...)
    for index = 1, select("#", ...) do
        local fn = select(index, ...)
        if type(fn) == "function" then return fn end
    end
end

local setIdentity = first(setthreadidentity, set_thread_identity, setidentity, setthreadcontext)

function Env.elevate()
    if setIdentity then
        pcall(setIdentity, 8)
    end
end

-- Calls fn (usually a game-module function) and restores the thread afterwards.
-- Returns ok, ... like pcall.
function Env.call(fn, ...)
    local results = table.pack(pcall(fn, ...))
    Env.elevate()
    return table.unpack(results, 1, results.n)
end

-- Executor functions -------------------------------------------------------------------------
-- Functions are optional unless the feature actually needs them. An executor's name or sUNC
-- score does not establish that any particular operation will succeed on this client.
-- The hub must not break where a function is
-- missing or goes by another name: everything executor-specific is looked up here once, and a
-- feature that cannot work without one says so instead of silently doing nothing.

local executorEnv = getfenv()
local function member(container, key)
    return type(container) == "table" and container[key] or nil
end
local syn, fluxus = executorEnv.syn, executorEnv.fluxus
local envOk, globalEnv = pcall(function() return getgenv() end)
Env.genv = envOk and type(globalEnv) == "table" and globalEnv or _G
Env.request = first(request, http_request, member(http, "request"), member(syn, "request"), member(fluxus, "request"))
Env.queueOnTeleport = first(queue_on_teleport, queueonteleport, member(syn, "queue_on_teleport"), member(fluxus, "queue_on_teleport"))
Env.setClipboard = first(setclipboard, toclipboard, set_clipboard, member(Clipboard, "set"))
Env.loadstring = first(loadstring)
Env.files = {}
for _, name in ipairs({ "readfile", "writefile", "isfile", "isfolder", "makefolder", "listfiles", "delfile" }) do
    Env.files[name] = first(executorEnv[name], Env.genv[name])
end
Env.canCache = Env.files.readfile ~= nil and Env.files.isfile ~= nil
Env.canSave = true
for _, name in ipairs({ "readfile", "writefile", "isfile", "isfolder", "makefolder", "listfiles", "delfile" }) do
    if not Env.files[name] then Env.canSave = false end
end
Env.traceback = debug and first(debug.traceback) or tostring
local executorOk, executorName = pcall(function()
    return identifyexecutor()
end)
Env.executor = executorOk and type(executorName) == "string" and executorName or "Unknown"

-- Missing functions that switch a feature off or change how it works, for the Settings tab.
-- A list, not a map: a map literal drops the missing (nil) ones before they can be counted.
-- Each game names the functions it cares about (Env.checkMissing), since what one needs another
-- never calls.
Env.missing = {}
local missingSet = {}
function Env.checkMissing(entries)
    for _, entry in ipairs(entries) do
        if type(entry[2]) ~= "function" and not missingSet[entry[1]] then
            missingSet[entry[1]] = true
            Env.missing[#Env.missing + 1] = entry[1]
        end
    end
end

-- Triggers a ProximityPrompt. Without fireproximityprompt it is pressed the way a player would,
-- with its hold lifted for the moment: that only takes while the prompt is on screen, i.e. in
-- range, which every caller already stands within (the server checks range either way).
function Env.firePrompt(prompt)
    if fireproximityprompt and pcall(fireproximityprompt, prompt) then
        Env.elevate()
        return true
    end
    local hold, sight = prompt.HoldDuration, prompt.RequiresLineOfSight
    local ok = pcall(function()
        prompt.HoldDuration = 0
        prompt.RequiresLineOfSight = false
        task.wait(0.1)
        prompt:InputHoldBegin()
        task.wait()
        prompt:InputHoldEnd()
    end)
    pcall(function()
        prompt.HoldDuration, prompt.RequiresLineOfSight = hold, sight
    end)
    Env.elevate()
    return ok
end

-- Simulates a touch (start then end) of `part` by `by`. False where the executor cannot.
function Env.touch(by, part)
    if not firetouchinterest then
        return false
    end
    local began = pcall(firetouchinterest, by, part, 0)
    task.wait() -- some executors only register the touch on the next physics step
    pcall(firetouchinterest, by, part, 1)
    return began
end

-- True when this client simulates `part`'s physics (so moving it replicates). Nil when the
-- executor cannot tell.
function Env.ownsPart(part)
    if not isnetworkowner then
        return nil
    end
    local ok, owns = pcall(isnetworkowner, part)
    return ok and owns == true
end

-- parent:WaitForChild(name) that gives up after `seconds` (30 by default) with an error naming
-- what is missing, so one absent folder fails its own feature instead of freezing the hub.
function Env.need(parent, name, seconds)
    local child = parent:WaitForChild(name, seconds or 30)
    Env.elevate()
    if not child then
        error(string.format("%s.%s is missing", parent:GetFullName(), name), 2)
    end
    return child
end

-- A lazy table of the game's ModuleScripts: modules.Name is required on first use and cached.
-- `paths` maps each name to its path under `root` (a list of child names).
--
-- Also returns load(name), the same loader as a plain function. Indexing runs it inside __index,
-- and Luau cannot yield there ("attempt to yield across metamethod/C-call boundary"), which a
-- module does while it waits on the game: right after a teleport from the main menu the client
-- controllers wait for the character and inventory. Load those with load() (Env.preload) first.
function Env.modules(root, paths)
    local cache, pending = {}, {}
    local function load(name)
        local loaded = rawget(cache, name)
        if loaded ~= nil then
            return loaded
        end
        local path = paths[name]
        assert(path, "Slopix: unknown game module " .. tostring(name))
        if Env.stopped then error("Slopix: hub unloaded", 2) end
        local work = pending[name]
        if not work then
            work = {}
            pending[name] = work
            task.spawn(function()
                work.result = table.pack(Env.call(function()
                    local node = root
                    local deadline = os.clock() + 30
                    for _, part in ipairs(path) do
                        node = Env.need(node, part, math.max(0.1, deadline - os.clock()))
                    end
                    return require(node)
                end))
                work.done = true
            end)
        end
        local deadline = os.clock() + 30
        repeat
            if work.done then break end
            task.wait(0.05)
        until Env.stopped or os.clock() >= deadline
        Env.elevate()
        if Env.stopped then error("Slopix: hub unloaded", 2) end
        if not work.done then
            error("Slopix: game module " .. name .. " is still loading; try again after the game finishes loading", 2)
        end
        pending[name] = nil
        if not work.result[1] then error(work.result[2], 2) end
        local module = work.result[2]
        rawset(cache, name, module)
        return module
    end
    return setmetatable(cache, {
        __index = function(_, name)
            return load(name)
        end,
    }), load
end

-- The live-reload handle when Real's live-reload started us (nil from the GitHub loader).
Env.RuntimeState = getfenv().STATE

return Env
end
__modules["shared/home"] = function(use) -- src/shared/home.luau
-- The part of the Home tab every game has: welcome, Discord invite, stop-all and anti-AFK.
-- Home.build returns the groupbox and a "Doing: ..." label the game's own Home keeps up to date.

local Env = use("shared/env")
local Life = use("shared/life")
local Ui = use("shared/ui")

local DISCORD_INVITE = "https://discord.com/invite/WdPcxf5B83"

local Home = {}

-- notes: extra lines shown under the welcome (where you are, what works there).
function Home.build(notes)
    local hub = Ui.Tabs.Home:AddGroupbox({ Side = "Left", Name = "Slopix Hub", IconName = "sparkles" })
    hub:AddLabel(string.format("Welcome, %s.", Env.LocalPlayer.DisplayName), true)
    for _, note in ipairs(notes or {}) do
        hub:AddLabel(note, true)
    end
    local statusLabel = hub:AddLabel("Doing: Idle", true)
    hub:AddButton({
        Text = "Copy Discord invite",
        Func = function()
            if Env.setClipboard and pcall(Env.setClipboard, DISCORD_INVITE) then
                Ui.notify("Slopix Hub", "Discord invite copied to your clipboard.", 4)
            else
                Ui.notify("Slopix Hub", DISCORD_INVITE, 10)
            end
        end,
    })
    hub:AddButton({
        Text = "Stop all automation",
        Func = function()
            Ui.stopAll()
            Ui.notify("Slopix Hub", "Everything is switched off.", 3)
        end,
    })
    hub:AddToggle("AntiAfk", {
        Text = "Anti AFK",
        Default = true,
        Tooltip = "Stops Roblox from kicking you after 20 idle minutes.",
    })

    local function nudge()
        if Ui.on("AntiAfk") then
            pcall(function()
                Env.VirtualUser:CaptureController()
                Env.VirtualUser:ClickButton2(Vector2.zero)
            end)
        end
    end
    local _, idleCallback = Life.connect(Env.LocalPlayer.Idled, nudge, "home:idle")

    -- Belt and braces: the idle kick itself listens on Idled too. Where the executor has
    -- getconnections (Real, Volt), those listeners are switched off while Anti AFK is on and
    -- switched back on when it goes off or the hub unloads.
    local silenced = {}
    local function silenceIdle(off)
        if off and type(getconnections) == "function" then
            local ok, connections = pcall(getconnections, Env.LocalPlayer.Idled)
            for _, connection in ipairs(ok and type(connections) == "table" and connections or {}) do
                local inspected, eligible = pcall(function()
                    return type(connection.Function) == "function" and connection.Function ~= idleCallback
                        and connection.Enabled == true and type(connection.Disable) == "function"
                end)
                if inspected and eligible and pcall(connection.Disable, connection) then
                    silenced[#silenced + 1] = connection
                end
            end
        elseif not off then
            for _, connection in ipairs(silenced) do
                pcall(function() connection:Enable() end)
            end
            table.clear(silenced)
        end
    end
    Ui.Toggles.AntiAfk:OnChanged(function(on)
        silenceIdle(false)
        silenceIdle(on)
    end)
    silenceIdle(Ui.on("AntiAfk"))
    Life.onCleanup(function()
        silenceIdle(false)
    end)

    return hub, statusLabel
end

return Home
end
__modules["shared/http"] = function(use) -- src/shared/http.luau
-- Downloads the hub's own dependencies (the UI library and its addons), with a file cache.
--
-- Real's game:HttpGet does not throw when a request fails: it returns the status as the body
-- ("429: Too Many Requests", "404: Not Found"), loadstring of that is nil, and calling it killed
-- the whole hub with "attempt to call a nil value". GitHub answers like that now and then, most
-- often on the reload right after a teleport. So every download is checked and retried, the last
-- good copy is kept, and that copy is used when GitHub will not answer.

local Env = use("shared/env")

local Http = {}

local CACHE = "SlopixHub/cache"
local TRIES = 3

local files = Env.files
local canWrite = files.writefile and files.isfolder and files.makefolder
local pending = {}
local memory = {}

-- The body at url, or nil and the reason. Tries the executor's request first (it reports the
-- status code), then game:HttpGet.
local function download(url)
    local reason
    if Env.request then
        local ok, res = Env.call(Env.request, { Url = url, Method = "GET" })
        if ok and type(res) == "table" and res.StatusCode ~= nil then
            if tonumber(res.StatusCode) == 200 and res.Success ~= false and type(res.Body) == "string" and res.Body ~= "" then
                return res.Body
            end
            reason = "HTTP " .. tostring(res.StatusCode)
        else
            reason = ok and "invalid HTTP response" or tostring(res)
        end
    end
    local ok, body = Env.call(function() return game:HttpGet(url) end)
    if not ok then
        return nil, reason or tostring(body)
    end
    if type(body) ~= "string" or body == "" then
        return nil, "empty response"
    end
    local status = body:match("^%d%d%d: [^\n]*")
    if status then
        return nil, status
    end
    return body
end

local function get(url)
    local work = pending[url]
    if not work then
        work = {}
        pending[url] = work
        task.spawn(function()
            local ok, body, err = pcall(download, url)
            work.body, work.error = ok and body or nil, ok and err or tostring(body)
            work.done = true
        end)
    end
    local deadline = os.clock() + 15
    while not work.done and os.clock() < deadline do task.wait(0.05) end
    Env.elevate()
    if not work.done then
        -- Leave this one in flight. Reloading an addon must not spawn duplicate hung requests.
        return nil, "download timed out", true
    end
    pending[url] = nil
    return work.body, work.error
end

local function save(path, body)
    local dir = ""
    for part in CACHE:gmatch("[^/]+") do
        dir = dir == "" and part or dir .. "/" .. part
        if not files.isfolder(dir) then
            files.makefolder(dir)
        end
    end
    files.writefile(path, body)
end

local function compile(body, name)
    if not Env.loadstring then return nil, "loadstring is unavailable" end
    if type(body) ~= "string" or body == "" then return nil, "empty source" end
    local ok, chunk, reason = Env.call(Env.loadstring, body, "@" .. name)
    if not ok then return nil, tostring(chunk) end
    if type(chunk) ~= "function" then return nil, reason or "compilation failed" end
    return chunk
end

-- Downloads url and compiles it (chunk name `name`). Falls back to the cached copy saved under
-- `name` by an earlier load. Returns the compiled chunk; errors with the reason when neither works.
function Http.load(url, name)
    if not Env.loadstring then error("Slopix: loadstring is unavailable; optional downloads cannot be loaded", 0) end
    local path = CACHE .. "/" .. name
    local reason
    if memory[url] then
        local chunk = compile(memory[url], name)
        if chunk then return chunk end
    end
    for attempt = 1, TRIES do
        local body, err, timedOut = get(url)
        Env.elevate()
        if body then
            local chunk, compileError = compile(body, name)
            if chunk then
                memory[url] = body
                if canWrite then
                    pcall(save, path, body)
                end
                return chunk
            end
            err = compileError -- a cut-off download
        end
        reason = err
        if timedOut then break end
        if attempt < TRIES then
            task.wait(attempt)
        end
    end
    local ok, cached = pcall(function()
        return Env.canCache and files.isfile(path) and files.readfile(path)
    end)
    local chunk = ok and compile(cached, name)
    if chunk then
        warn(string.format("[Slopix] %s: %s, using the cached copy", name, tostring(reason)))
        return chunk
    end
    error(string.format("could not download %s (%s)", name, tostring(reason)), 0)
end

return Http
end
__modules["shared/life"] = function(use) -- src/shared/life.luau
-- Lifecycle: one "alive" flag for the whole hub, a teardown list, and guarded loops.
--
-- Every background loop goes through Life.loop so it elevates the thread on each pass, stops on
-- unload, and records its last error in Life.errors[name] instead of dying silently inside a
-- task.spawn (which is how panels used to break without anyone noticing).

local Env = use("shared/env")

local Life = {
    alive = true,
    errors = {},
}

local cleanups = {}
local workers = {}
local connectionId = 0

function Life.onCleanup(fn)
    if not Life.alive then
        pcall(fn)
        return
    end
    cleanups[#cleanups + 1] = fn
end

function Life.call(name, fn, ...)
    if not Life.alive then return false, "hub unloaded" end
    Env.elevate()
    local result = table.pack(xpcall(fn, Env.traceback, ...))
    Env.elevate()
    Life.errors[name] = not result[1] and tostring(result[2]) or nil
    return table.unpack(result, 1, result.n)
end

function Life.spawn(name, fn, ...)
    local args = table.pack(...)
    -- defer lets us track the thread before its first instruction (including a shutdown).
    local thread
    thread = task.defer(function()
        Life.call(name, fn, table.unpack(args, 1, args.n))
        workers[thread] = nil
    end)
    workers[thread] = true
    return thread
end

function Life.connect(signal, fn, name)
    connectionId += 1
    name = name or ("event:" .. connectionId)
    local function guarded(...)
        Life.call(name, fn, ...)
    end
    local connection = signal:Connect(guarded)
    Life.onCleanup(function()
        connection:Disconnect()
    end)
    return connection, guarded
end

-- Runs fn every `interval` seconds (a number, or a function returning one) until unload.
function Life.loop(name, interval, fn)
    Life.spawn("loop:" .. name, function()
        local failures = 0
        while Life.alive do
            local ok = Life.call(name, fn)
            failures = ok and 0 or math.min(failures + 1, 5)
            if not Life.alive then
                break
            end
            local intervalOk, delay = pcall(function()
                return type(interval) == "function" and interval() or interval
            end)
            delay = intervalOk and tonumber(delay) or 1
            if not delay or delay ~= delay or delay == math.huge then delay = 1 end
            -- A broken API should not be hammered several times per frame.
            task.wait(math.max(0.05, delay, failures > 0 and 2 ^ (failures - 1) or 0))
        end
    end)
end

-- Waits up to `seconds`, returning early (false) once the hub is unloading.
function Life.wait(seconds)
    local deadline = os.clock() + seconds
    repeat
        -- In slices of at most 0.1s so an unload is noticed, but never past the deadline: a full
        -- 0.1s slice after a 0.11s wait's first one made it 0.2s.
        task.wait(math.min(0.1, math.max(0, deadline - os.clock())))
    until not Life.alive or os.clock() >= deadline
    Env.elevate()
    return Life.alive
end

function Life.shutdown()
    if not Life.alive then
        return
    end
    Life.alive = false
    for thread in pairs(workers) do
        if thread ~= coroutine.running() then pcall(task.cancel, thread) end
    end
    table.clear(workers)
    for index = #cleanups, 1, -1 do
        pcall(cleanups[index])
    end
    table.clear(cleanups)
end

return Life
end
__modules["shared/performance"] = function(use) -- src/shared/performance.luau
-- Performance mode, for long AFK farming: cuts what the client draws. Every property it changes is
-- written down first and put back when it goes off or the hub unloads, so nothing sticks.
--   Performance mode   shadows, post effects (bloom, blur, sun rays, colour correction, depth of
--                      field), particles, beams, trails and fire, water waves and reflections, the
--                      render quality, and the frame rate (the FPS limit)
--   3D rendering off   Roblox stops drawing the world at all; the hub's window still shows
-- Effects the game adds while it is on (weather, lightning, hatches) are switched off as they come.

local Env = use("shared/env")
local Life = use("shared/life")
local Ui = use("shared/ui")

local Performance = {}

local EFFECTS = { "ParticleEmitter", "Trail", "Beam", "Fire", "Smoke", "Sparkles", "PostEffect", "Clouds" }
local DEFAULT_FPS = 60 -- what the frame rate goes back to where the executor cannot say what it was

local saved = setmetatable({}, { __mode = "k" }) -- instance -> { property -> original value }
local savedFps
local active = false

local function set(instance, property, value)
    local ok, current = pcall(function()
        return instance[property]
    end)
    if not ok or current == value then
        return
    end
    local entry = saved[instance]
    if not entry then
        entry = {}
        saved[instance] = entry
    end
    if entry[property] == nil then
        entry[property] = current
    end
    pcall(function()
        instance[property] = value
    end)
end

local function isEffect(instance)
    for _, class in ipairs(EFFECTS) do
        if instance:IsA(class) then
            return true
        end
    end
    return false
end

local function quiet(instance)
    if isEffect(instance) then
        set(instance, "Enabled", false)
    end
end

local function applyFps()
    if active and setfpscap then
        pcall(setfpscap, Ui.Options.PerfFps.Value)
    end
end

local function enable()
    if active then
        return
    end
    active = true
    if setfpscap then
        local ok, cap = pcall(function()
            return getfpscap and getfpscap()
        end)
        savedFps = ok and tonumber(cap) or DEFAULT_FPS
        applyFps()
    end
    local lighting = game:GetService("Lighting")
    set(lighting, "GlobalShadows", false)
    local terrain = workspace:FindFirstChildOfClass("Terrain")
    if terrain then
        set(terrain, "WaterWaveSize", 0)
        set(terrain, "WaterWaveSpeed", 0)
        set(terrain, "WaterReflectance", 0)
        set(terrain, "Decoration", false)
    end
    pcall(function()
        set(settings().Rendering, "QualityLevel", Enum.QualityLevel.Level01)
    end)
    for _, root in ipairs({ lighting, workspace }) do
        for index, instance in ipairs(root:GetDescendants()) do
            if not active then
                return
            end
            quiet(instance)
            if index % 4000 == 0 then
                task.wait() -- a big map in one go is a visible hitch
            end
        end
    end
end

local function disable()
    active = false
    for instance, properties in pairs(saved) do
        for property, value in pairs(properties) do
            pcall(function()
                instance[property] = value
            end)
        end
    end
    table.clear(saved)
    if savedFps and setfpscap then
        pcall(setfpscap, savedFps)
        savedFps = nil
    end
end

local function setRendering(on)
    pcall(Env.RunService.Set3dRenderingEnabled, Env.RunService, on)
end

-- The "Performance" box on `tab`.
function Performance.build(tab)
    local group = tab:AddGroupbox({ Side = "Left", Name = "Performance", IconName = "gauge" })
    group:AddToggle("PerfMode", {
        Text = "Performance mode",
        Default = false,
        Tooltip = "Turns off shadows, post effects, particles and water animation, lowers the render quality and limits the frame rate. All of it comes back when you switch it off.",
    })
    group:AddSlider("PerfFps", {
        Text = "FPS limit",
        Default = 30,
        Min = 5,
        Max = 240,
        Rounding = 0,
        Tooltip = setfpscap and "The frame rate while performance mode is on. Below about 15 the automation reacts more slowly."
            or "Your executor has no setfpscap, so the frame rate cannot be limited.",
    })
    group:AddToggle("PerfNoRender", {
        Text = "Turn off 3D rendering",
        Default = false,
        Tooltip = "The world is no longer drawn (a blank screen with the hub on it): the biggest saving while AFK. Everything keeps running.",
    })

    Ui.Toggles.PerfMode:OnChanged(function(on)
        if on then
            task.spawn(enable)
        else
            disable()
        end
    end)
    Ui.Options.PerfFps:OnChanged(applyFps)
    Ui.Toggles.PerfNoRender:OnChanged(function(on)
        setRendering(not on)
    end)

    for _, root in ipairs({ game:GetService("Lighting"), workspace }) do
        Life.connect(root.DescendantAdded, function(instance)
            if active then
                quiet(instance)
            end
        end)
    end
    Life.onCleanup(function()
        disable()
        setRendering(true)
    end)
    return group
end

return Performance
end
__modules["shared/settings"] = function(use) -- src/shared/settings.luau
-- Settings tab: menu options, the official Obsidian ThemeManager and SaveManager addons.
-- Each game's features/settings calls Settings.build with its config folder and what a missing
-- executor function changes there. Settings.finish() loads the autoload config; main calls it
-- after every feature is built so a saved config can switch toggles on only once their handlers
-- exist.

local Env = use("shared/env")
local Http = use("shared/http")
local Ui = use("shared/ui")
local Life = use("shared/life")

local ADDONS = "https://raw.githubusercontent.com/deividcomsono/Obsidian/main/addons/"

local Settings = {}

local function fetch(file)
    local ok, result = pcall(function()
        return Http.load(ADDONS .. file, file)()
    end)
    Env.elevate()
    return ok and result or nil, result
end

-- options.folder: where this game's configs are saved (under SlopixHub/).
-- options.effects: { [executor function] = "what goes missing without it" }.
function Settings.build(options)
    local Library, Options = Ui.Library, Ui.Options
    local tab = Ui.Tabs.Settings

    local menu = tab:AddGroupbox({ Side = "Left", Name = "Menu", IconName = "sliders-horizontal" })
    menu:AddDropdown("NotificationSide", {
        Text = "Notification side",
        Values = { "Left", "Right" },
        Default = "Right",
        Callback = function(value)
            Library:SetNotifySide(value)
        end,
    })
    menu:AddDropdown("DPIScale", {
        Text = "DPI scale",
        Values = { "50%", "75%", "100%", "125%", "150%", "175%", "200%" },
        Default = "100%",
        Callback = function(value)
            Library:SetDPIScale(tonumber((value:gsub("%%", ""))))
        end,
    })
    menu:AddDivider()
    menu:AddLabel("Menu bind"):AddKeyPicker("MenuKeybind", {
        Default = "RightShift",
        NoUI = true,
        Text = "Menu keybind",
    })
    menu:AddButton("Unload", function()
        Library:Unload()
    end)
    Library.ToggleKeybind = Options.MenuKeybind

    -- What this executor lacks and what that changes, so a bug report says it up front.
    local compat = tab:AddGroupbox({ Side = "Left", Name = "Compatibility", IconName = "cpu" })
    local lines = { "Executor: " .. Env.executor }
    for _, name in ipairs(Env.missing) do
        lines[#lines + 1] = string.format("No %s: %s.", name, options.effects[name] or "some features are limited")
    end
    if #Env.missing == 0 then
        lines[#lines + 1] = "Required function names are available. Runtime support depends on the executor."
    end
    compat:AddLabel(table.concat(lines, "\n"), true)
    local runtimeLabel = compat:AddLabel("Runtime: ready.", true)
    Life.loop("settings:runtime", 2, function()
        local messages = {}
        for name, reason in pairs(Env.requestIssues or {}) do
            messages[#messages + 1] = name .. ": " .. reason
        end
        for name, reason in pairs(Life.errors) do
            if name ~= "settings:runtime" then
                messages[#messages + 1] = name .. ": " .. (tostring(reason):match("^[^\n]+") or "unavailable")
            end
        end
        table.sort(messages)
        local extra = math.max(0, #messages - 4)
        while #messages > 4 do table.remove(messages) end
        if extra > 0 then messages[#messages + 1] = string.format("%d more runtime messages.", extra) end
        runtimeLabel:SetText(#messages > 0 and table.concat(messages, "\n") or "Runtime: ready.")
    end)

    if not Env.canSave or not Env.loadstring then
        local storage = tab:AddGroupbox({ Side = "Right", Name = "Saved settings", IconName = "save" })
        storage:AddLabel("Saved configs and custom themes are unavailable on this executor. You can still change the controls for this session.", true)
        function Settings.finish() end
        return Settings
    end

    -- Each addon is set up under pcall: one that breaks (no file functions, an upstream change)
    -- costs its own section, not the whole Settings tab.
    local SaveManager, saveError = fetch("SaveManager.lua")
    if SaveManager then
        local ok, err = pcall(function()
            SaveManager:SetLibrary(Library)
            SaveManager:IgnoreThemeSettings()
            SaveManager:SetIgnoreIndexes({ "MenuKeybind" })
            SaveManager:SetFolder("SlopixHub/" .. options.folder)
            SaveManager:BuildConfigSection(tab)
        end)
        Env.elevate()
        if not ok then
            SaveManager, saveError = nil, err
        end
    end
    if not SaveManager then
        Ui.notify("Slopix Hub", "Could not load the config manager: " .. tostring(saveError), 6)
    end

    local ThemeManager, themeError = fetch("ThemeManager.lua")
    if ThemeManager then
        local ok, err = pcall(function()
            ThemeManager:SetLibrary(Library)
            ThemeManager:SetFolder("SlopixHub")
            -- The crimson palette as "Default"; FontFace must be one of the Font Face dropdown values.
            ThemeManager:SetDefaultTheme({
                BackgroundColor = "0d0c12",
                MainColor = "1e1b28",
                AccentColor = "eb4060",
                OutlineColor = "302b3e",
                FontColor = "f0eef6",
                FontFace = "BuilderSans",
            })
            ThemeManager:ApplyToTab(tab)
            local _, hasSavedDefault = ThemeManager:GetDefaultTheme()
            if hasSavedDefault then
                ThemeManager:LoadDefault()
            else
                Options.ThemeManager_ThemeList:SetValue("Default")
            end
        end)
        Env.elevate()
        if not ok then
            ThemeManager, themeError = nil, err
        end
    end
    if not ThemeManager then
        Ui.notify("Slopix Hub", "Could not load the theme manager: " .. tostring(themeError), 6)
    end
    Env.elevate()

    function Settings.finish()
        if SaveManager then
            local ok, err = pcall(SaveManager.LoadAutoloadConfig, SaveManager)
            Env.elevate()
            if not ok then
                Ui.notify("Slopix Hub", "Autoload failed: " .. tostring(err), 6)
            end
        end
    end

    return Settings
end

return Settings
end
__modules["shared/ui"] = function(use) -- src/shared/ui.luau
-- The window, its tabs, notifications, and small helpers features build their panels from.
-- Each game's core/ui calls Ui.create once with its footer and tabs, then returns this table.
--
-- The library is the Crimson Obsidian fork. Its public methods re-elevate the thread themselves,
-- so UI writes after a game-module call are safe without extra care in feature code.

local Env = use("shared/env")
local Life = use("shared/life")
local Http = use("shared/http")

local LIBRARY_URL = "https://raw.githubusercontent.com/TrustyCoding/slopix-hub/main/ui/Library.lua"

local Ui = {}

-- options.footer: the game's name under the title.
-- options.tabs: { { name, icon, description }, ... } in sidebar order.
-- options.only: a set of tab names to create (the rest are skipped), or nil for all of them.
-- options.icons: a bundled icon registry, installed before any window controls are created.
function Ui.create(options)
    local Library = options.library and options.library() or Http.load(LIBRARY_URL, "Library.lua")()
    Env.elevate()
    assert(type(Library) == "table" and type(Library.CreateWindow) == "function", "Slopix: UI library did not load")
    if options.icons then
        Library:SetIconModule(options.icons)
    end
    Ui.Library = Library
    Ui.Options = Library.Options
    Ui.Toggles = Library.Toggles

    -- Register before constructing the window, so failed startup can also tear it down.
    Library:OnUnload(function()
        Env.elevate()
        Life.shutdown()
    end)

    Ui.Window = Library:CreateWindow({
        Title = "Slopix Hub",
        Footer = options.footer,
        AutoShow = true,
        Center = true,
        Resizable = true,
        ShowCustomCursor = false,
        NotifySide = "Right",
    })

    -- Created up front so the sidebar order is fixed here, whatever order features load in.
    Ui.Tabs = {}
    for _, entry in ipairs(options.tabs) do
        if not options.only or options.only[entry[1]] then
            Ui.Tabs[entry[1]] = Ui.Window:AddTab(entry[1], entry[2], entry[3])
        end
    end

    return Ui
end

function Ui.notify(title, text, seconds)
    if not Life.alive or not Ui.Library then return end
    Env.elevate()
    Ui.Library:Notify({ Title = title, Description = text, Time = seconds or 5 })
end

-- A fixed stack of labels plus a footer, for lists that change size (tasks, timers, chests).
function Ui.panel(groupbox, rows)
    local labels = {}
    for index = 1, rows do
        labels[index] = groupbox:AddLabel("", true)
        labels[index]:SetVisible(false)
    end
    groupbox:AddDivider()
    local footer = groupbox:AddLabel("", true)
    local panel = {}
    function panel.set(lines, footerText)
        if not Life.alive then return end
        Env.elevate()
        for index = 1, rows do
            local line = lines[index]
            labels[index]:SetVisible(line ~= nil)
            if line ~= nil then
                labels[index]:SetText(line)
            end
        end
        footer:SetText(footerText or "")
    end
    return panel
end

-- На время теста непрофильные функции выключены ещё ДО автозагрузки старых настроек.
-- Это закрывает окно, когда сохранённые тумблеры могли запустить покупки или награды.
local TEST_ALLOWED_TOGGLES = {
    AutoTap=true, AutoClicker=true, AutoHatch=true, HatchTeleport=true, AutoEquipBest=true,
    AutoUpgrade=true, AutoSkillTree=true, -- только улучшения, без рыбалки/зелий/зачарований
    AutoCraft=true, CraftKeepEquipped=true, CraftKeepMutated=true, CraftReturn=true,
    AntiAfk=true, PerfMode=true, PerfGameSettings=true, PerfNoRender=true, -- never mute hatch events in this test
    WebhookDisconnect=true, AutoReveal=true, -- раскрытие карточки уже открытого яйца
}
local TEST_GEM_AUTOMATION = { AutoUpgrade=true, AutoSkillTree=true }
-- Toggle value that is safe to read during unload (the library clears Toggles).
function Ui.on(name)
    local P = Ui.__progressTest
    if P and not TEST_ALLOWED_TOGGLES[name] then return false end
    if P and name == "AutoCraft" and (P.phase ~= "rebirth" or P.eggFixed or P.rebirthLocked or P.farmThresholdReached
        or P.disableAutoCraft or P.holdCraft or P.stopRequested or P.craftUncertain or P.previousCraftPending
        or (Env.genv and Env.genv.__handoverPaused)) then return false end
    if P and TEST_GEM_AUTOMATION[name] and (not P.gemReady or P.craftBusy or P.craftInFlight or P.cleaning or P.stopRequested or P.eggFixed or P.rebirthLocked
        or (name == "AutoSkillTree" and (P.holdSkillTree or (P.skillRetryAt and os.clock() < P.skillRetryAt)))
        or (name == "AutoUpgrade" and P.upgradeRetryAt and os.clock() < P.upgradeRetryAt)
        or P.previousHatchPending or P.previousRebirthPending or P.previousCraftPending or P.craftUncertain
        or P.hatchUncertain or P.upgradeUncertain or P.skillUncertain
        or P.phase == "blocked" or P.phase == "uncertain" or P.phase == "stopped" or P.phase == "hatch_uncertain"
        or (Env.genv and Env.genv.__handoverPaused)) then return false end
    local toggle = Ui.Library.Toggles[name]
    return toggle ~= nil and toggle.Value == true
end

function Ui.set(name, value)
    local toggle = Ui.Library.Toggles[name]
    if toggle and toggle.Value ~= value then
        toggle:SetValue(value)
    end
end

-- Toggles that start automation. `stays` marks ones that never pull the character somewhere
-- else (clan spins, auto heal), which travelling can leave running.
local automation = {}

function Ui.automation(name, stays)
    automation[#automation + 1] = { name = name, stays = stays == true }
end

-- Switches automation off: everything, or with moversOnly just what would move the character.
function Ui.stopAll(moversOnly, temporaryTradePause)
    -- Обычная Stop all отменяет тест. Пауза трейда не должна отменять его.
    if not moversOnly and not temporaryTradePause and Ui.__progressTest then
        Ui.__progressTest.stopRequested = true
    end
    for _, entry in ipairs(automation) do
        if not (moversOnly and entry.stays) then
            Ui.set(entry.name, false)
        end
    end
end

return Ui
end
__modules["shared/webhook"] = function(use) -- src/shared/webhook.luau
-- Discord webhook alerts: the URL, a user to ping, a test button, a disconnect alert, and a queue
-- that posts one message at a time through the executor's request (Roblox's own HttpService
-- cannot reach Discord). Each game's features/webhooks calls Webhook.build and adds its alerts.
--
-- Discord allows 5 posts per webhook every 2 seconds and answers 429 with retry_after past that.
-- The queue keeps a second between posts and waits out a 429. It holds at most 20 messages: in an
-- alert storm the oldest are dropped rather than everything arriving minutes late.

local Env = use("shared/env")
local Life = use("shared/life")
local Ui = use("shared/ui")

local Webhook = {}

local SPACING = 1.1 -- seconds between two posts
local MAX_QUEUE = 20

local queue = {}
local gameName = "Roblox"
local statusLabel

local function trim(text)
    return (tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", ""))
end

local function url()
    local option = Ui.Options.WebhookUrl
    return trim(option and option.Value)
end

-- The Discord user to ping, digits only, or nil.
local function pingId()
    local option = Ui.Options.WebhookUserId
    local id = trim(option and option.Value):gsub("%D", "")
    return id ~= "" and id or nil
end

function Webhook.ready()
    return Env.request ~= nil and url():match("^https?://.+") ~= nil
end

local function setStatus(text)
    if statusLabel then
        statusLabel:SetText(text)
    end
end

-- Posts one body. Returns true, or false, why, and how long Discord asked to wait.
local function post(body)
    local ok, res = pcall(Env.request, {
        Url = url(),
        Method = "POST",
        Headers = { ["Content-Type"] = "application/json" },
        Body = Env.HttpService:JSONEncode(body),
    })
    Env.elevate()
    if not ok or type(res) ~= "table" then
        return false, tostring(res)
    end
    local status = tonumber(res.StatusCode) or 0
    if status >= 200 and status < 300 then
        return true
    end
    if status == 429 then
        local decoded, data = pcall(Env.HttpService.JSONDecode, Env.HttpService, res.Body or "")
        return false, "rate limited", decoded and type(data) == "table" and tonumber(data.retry_after) or 2
    end
    return false, "HTTP " .. status
end

task.spawn(function()
    while Life.alive do
        local body = queue[1]
        if body and Webhook.ready() then
            table.remove(queue, 1)
            local ok, why, retry = post(body)
            if retry then
                table.insert(queue, 1, body)
                Life.wait(retry)
            elseif ok then
                setStatus("Last message sent at " .. os.date("%H:%M:%S"))
            else
                setStatus("Last message failed: " .. tostring(why))
            end
            Life.wait(SPACING)
        else
            Life.wait(0.25)
        end
    end
end)

-- Queues an alert. message: { title, description, color, fields = { { name, value, inline } },
-- ping = ping the user set, urgent = ahead of everything already waiting }. Does nothing while
-- no webhook is set.
function Webhook.send(message)
    if not Webhook.ready() then
        return false
    end
    local id = message.ping and pingId() or nil
    local fields = {}
    for _, field in ipairs(message.fields or {}) do
        fields[#fields + 1] = { name = tostring(field[1]), value = tostring(field[2]):sub(1, 1024), inline = field[3] ~= false }
    end
    local body = {
        username = "Slopix Hub",
        content = id and ("<@" .. id .. ">") or nil,
        allowed_mentions = { parse = {}, users = id and { id } or {} },
        embeds = {
            {
                title = tostring(message.title):sub(1, 256),
                description = message.description and tostring(message.description):sub(1, 4096) or nil,
                color = message.color or 0xEB4060,
                fields = #fields > 0 and fields or nil,
                footer = { text = string.format("%s · %s", Env.LocalPlayer.Name, gameName) },
                timestamp = DateTime.now():ToIsoDate(),
            },
        },
    }
    if message.urgent then
        table.insert(queue, 1, body)
    else
        queue[#queue + 1] = body
    end
    while #queue > MAX_QUEUE do
        table.remove(queue, message.urgent and #queue or 1)
    end
    return true
end

-- The "Discord webhook" box on `tab`. options.game: the game's name for the message footer.
function Webhook.build(tab, options)
    gameName = options.game or gameName
    local group = tab:AddGroupbox({ Side = "Left", Name = "Discord webhook", IconName = "webhook" })
    group:AddInput("WebhookUrl", {
        Text = "Webhook URL",
        Default = "",
        Placeholder = "https://discord.com/api/webhooks/...",
        Finished = true,
        ClearTextOnFocus = false,
        Tooltip = "In Discord: Server settings > Integrations > Webhooks > New webhook > Copy webhook URL.",
    })
    group:AddInput("WebhookUserId", {
        Text = "Your Discord user ID (to be pinged)",
        Default = "",
        Placeholder = "optional, e.g. 123456789012345678",
        Finished = true,
        ClearTextOnFocus = false,
        Tooltip = "Rare finds and disconnects ping you. Discord: Settings > Advanced > Developer mode, then right-click your name > Copy User ID.",
    })
    group:AddToggle("WebhookDisconnect", {
        Text = "Alert when disconnected or kicked",
        Default = true,
    })
    group:AddButton({ Text = "Send a test message", Func = function()
        if not Env.request then
            Ui.notify("Webhook", "Your executor has no request function, so nothing can be sent.", 6)
        elseif not Webhook.ready() then
            Ui.notify("Webhook", "Paste your webhook URL first.", 4)
        else
            Webhook.send({
                title = "Slopix Hub is connected",
                description = "Alerts for " .. gameName .. " will arrive here.",
                fields = { { "Executor", Env.executor } },
                ping = true,
                urgent = true,
            })
            Ui.notify("Webhook", "Test message queued.", 3)
        end
    end })
    statusLabel = group:AddLabel(Env.request and "Nothing sent yet" or "Your executor has no request function: webhooks cannot be sent.", true)

    -- The error screen of a kick or a lost connection: scripts still run behind it for a moment.
    local GuiService = game:GetService("GuiService")
    Life.connect(GuiService.ErrorMessageChanged, function()
        local ok, text = pcall(GuiService.GetErrorMessage, GuiService)
        text = ok and trim(text) or ""
        if text ~= "" and Ui.on("WebhookDisconnect") then
            Webhook.send({
                title = "Disconnected",
                description = text,
                color = 0x808080,
                ping = true,
                urgent = true,
            })
        end
    end)
    return Webhook
end

return Webhook
end
