end
local ParsedIcon = Library:GetCustomIcon(IconName)
if ParsedIcon then
local ColorKey = Button.Risky and "RedColor" or (ParsedIcon.Custom and "WhiteColor" or "FontColor")
if not Button.IconImage then
Button.IconImage = New("ImageLabel", {
