end
function Dialog:SetButtonOrder(ButtonIdx, Order)
if FooterButtonsList[ButtonIdx] and FooterButtonsList[ButtonIdx].Container then
FooterButtonsList[ButtonIdx].Container.LayoutOrder = Order
end
end
