if Variant == "Primary" then
BtnColor = "FontColor"
BtnOutline = "FontColor"
elseif Variant == "Secondary" then
BtnColor = "MainColor"
BtnOutline = "OutlineColor"
elseif Variant == "Destructive" then
BtnColor = "DestructiveColor"
BtnOutline = "DestructiveColor"
elseif Variant == "Ghost" then
BtnColor = "BackgroundColor"
BtnOutline = "BackgroundColor"
end
local TextBtn = New("TextButton", {
BackgroundColor3 = BtnColor,
BorderColor3 = BtnOutline,
Size = UDim2.fromOffset(0, 26),
Text = "",
AutoButtonColor = false,
Parent = ButtonContainer,
})
Library:AddOutline(TextBtn)
table.insert(
Library.Corners,
New("UICorner", {
CornerRadius = UDim.new(0, Library.CornerRadius),
Parent = TextBtn
})
)
New("UIPadding", {
PaddingLeft = UDim.new(0, 15),
PaddingRight = UDim.new(0, 15),
Parent = TextBtn,
})
local TextColor = Library.Scheme.FontColor
if Variant == "Primary" then
TextColor = Library.Scheme.BackgroundColor
elseif Variant == "Destructive" then
TextColor = Color3.new(1, 1, 1)
end
local BtnLabel = New("TextLabel", {
BackgroundTransparency = 1,
Size = UDim2.fromScale(1, 1),
Text = ButtonInfo.Title or Idx,
TextColor3 = TextColor,
TextSize = 14,
Parent = TextBtn,
})
local LabelX, _ = Library:GetTextBounds(BtnLabel.Text, Library.Scheme.Font, 14, 250)
ButtonContainer.Size = UDim2.fromOffset(LabelX + 30, 26)
TextBtn.Size = UDim2.fromOffset(LabelX + 30, 26)
local ActiveColor = typeof(BtnColor) == "Color3" and BtnColor or Library.Scheme[BtnColor]
local HoverColor = Variant == "Ghost" and Library.Scheme.MainColor or Library:GetBetterColor(ActiveColor, 10)
TextBtn.MouseEnter:Connect(function()
TweenService:Create(TextBtn, Library.TweenInfo, {
BackgroundColor3 = HoverColor
}):Play()
end)
TextBtn.MouseLeave:Connect(function()
TweenService:Create(TextBtn, Library.TweenInfo, {
BackgroundColor3 = ActiveColor
}):Play()
end)
TextBtn.MouseButton1Click:Connect(function()
if ButtonInfo.Callback then
ButtonInfo.Callback(Loading)
Elevate()
end
end)
end
Loading:UpdateLayout()
end
function Loading:Destroy()
if RotationTween then
StopTween(RotationTween, true)
RotationTween = nil
end
ScreenGui:Destroy()
Loading.Destroyed = true
Library.ActiveLoading = nil
if Library.Toggle and Library.Toggled == false and Library.Unloaded ~= true then
Library:Toggle(true)
end
end
Loading.Continue = Loading.Destroy;
if Library.Toggle and Library.Toggled and Library.Unloaded ~= true then
Library:Toggle(false)
end
Loading:SetCurrentStep(Loading.CurrentStep)
Library.ActiveLoading = Loading
return Loading
end
local function OnPlayerChange()
if Library.Unloaded then
return
end
local PlayerList, ExcludedPlayerList = GetPlayers(), GetPlayers(true)
for _, Dropdown in Options do
if Dropdown.Type == "Dropdown" and Dropdown.SpecialType == "Player" then
Dropdown:SetValues(Dropdown.ExcludeLocalPlayer and ExcludedPlayerList or PlayerList)
end
end
end
local function OnTeamChange()
if Library.Unloaded then
return
end
local TeamList = GetTeams()
for _, Dropdown in Options do
if Dropdown.Type == "Dropdown" and Dropdown.SpecialType == "Team" then
Dropdown:SetValues(TeamList)
end
end
end
Library:GiveSignal(Players.PlayerAdded:Connect(OnPlayerChange))
Library:GiveSignal(Players.PlayerRemoving:Connect(OnPlayerChange))
Library:GiveSignal(Teams.ChildAdded:Connect(OnTeamChange))
Library:GiveSignal(Teams.ChildRemoved:Connect(OnTeamChange))
function Library:Unload()
if Library.Unloaded then return end
Library.Unloaded = true
for Index = #Library.Signals, 1, -1 do
local Connection = table.remove(Library.Signals, Index)
if Connection and Connection.Connected then
Connection:Disconnect()
end
end
for _ = 1, #Library.UnloadSignals do
local Callback = table.remove(Library.UnloadSignals, 1)
if Callback then
Library:SafeCallback(Callback)
end
end
for Index = #Library.Tabs, 1, -1 do
local Tab = table.remove(Library.Tabs, Index)
if Tab and Tab.Destroy then
Library:SafeCallback(Tab.Destroy, Tab)
end
end
for Index = #Tooltips, 1, -1 do
local Tooltip = table.remove(Tooltips, Index)
if Tooltip and Tooltip.Destroy then
Library:SafeCallback(Tooltip.Destroy, Tooltip)
end
end
if Library.ActiveLoading then
Library.ActiveLoading:Destroy()
end
if ScreenGui then
ScreenGui:Destroy()
end
table.clear(Library.Registry)
table.clear(Options)
table.clear(Toggles)
table.clear(Buttons)
table.clear(Labels)
table.clear(Tooltips)
table.clear(Library.Tabs)
table.clear(Library.TabButtons)
table.clear(Library.Scales)
table.clear(Library.ScalesOffset)
table.clear(Library.Corners)
table.clear(Library.SpecificCorners)
table.clear(Library.ContextMenus)
table.clear(Library.Notifications)
table.clear(Library.Dialogues)
table.clear(Library.DraggableElements)
table.clear(Library.KeybindToggles)
table.clear(Library.DependencyBoxes)
table.clear(TransparencyCache)
table.clear(ActiveTabTweens)
Library.Toggle = function(...) end
Library.ScreenGui = nil
Library.Floats = nil
Library.Overlay = nil
Library.WindowContainer = nil
Library.KeybindFrame = nil
Library.KeybindContainer = nil
if getgenv().Library == Library then getgenv().Library = nil end
end
do
local GuardedFunctions = setmetatable({}, { __mode = "k" })
local GuardedObjects = setmetatable({}, { __mode = "k" })
local Skip = {
Validate = true,
SafeCallback = true,
GiveSignal = true,
AddToRegistry = true,
RemoveFromRegistry = true,
Callback = true,
Changed = true,
}
local GuardObject
local function GuardFunction(Function)
if GuardedFunctions[Function] then
return Function
end
local function Guarded(...)
Elevate()
local Results = table.pack(Function(...))
for Index = 1, Results.n do
if type(Results[Index]) == "table" then
GuardObject(Results[Index])
end
end
return table.unpack(Results, 1, Results.n)
end
GuardedFunctions[Guarded] = true
return Guarded
end
function GuardObject(Object, Rescan: boolean?)
if GuardedObjects[Object] and not Rescan then
return Object
end
GuardedObjects[Object] = true
for Key, Value in Object do
if type(Key) == "string" and type(Value) == "function" and not Skip[Key]
and not string.match(Key, "^Get") and not string.match(Key, "^Is") then
Object[Key] = GuardFunction(Value)
end
end
return Object
end
GuardObject(BaseGroupbox.__index)
GuardObject(BaseAddons.__index)
GuardObject(Library)
for _, Name in { "CreateWindow", "CreateLoading" } do
local Create = Library[Name]
if Create then
local function Rescanning(...)
local Results = table.pack(Create(...))
GuardObject(Library, true)
return table.unpack(Results, 1, Results.n)
end
GuardedFunctions[Rescanning] = true
Library[Name] = Rescanning
end
end
end
getgenv().Library = Library
return Library
end
-- ТЕСТ 30M: одна копия на 1-2 аккаунтах. Не изменяет GitHub или другие клиенты.
-- До lock яйца ограничены 20% текущего баланса на партию; после lock только 30M x3.
-- Задаётся ограничение собственного темпа, а не предполагается скорость сервера.
__modules["features/progress_test"] = function(use)
    local Env = use("core/env")
    local Life = use("shared/life")
    local Ui = use("core/ui")

    local BATCH_PRICE = 900000000
    local MIN_HATCH_INTERVAL = 2 -- ограничение этого теста, а не скорость игры
    local REQUIRED_INCOME = 300000000 -- Clicks coins/s: permanently select 30M
    local STOP_REBIRTH_INCOME = 900000000 -- Luck coins/s: independently and permanently stop rebirths
    local WINDOW = 10
    local REQUIRED_WINDOWS = 3
    local START_SETTLE = 7
    local REPLY_TIMEOUT = 15
    local REBIRTH_GAP = 20 -- от отправки до отправки; после рестарта выдерживаем весь интервал
    local REBIRTH_SYNC_SECONDS = 2 -- дать реплике счётчика и баланса стабилизироваться
    local RECHECK_SECONDS = 10
    local CLEAN_PROBE_PERIOD = 75 -- прямой замер без трат, даже если яйца скрывают прирост
    local CLICKER_REFRESH_SECONDS = 15
    local REPORT_SECONDS = 30
    local HATCH_OBSERVE_WINDOW = 30
    -- Legacy V11/V12 marker proves the 300M/s egg transition only, never the 900M/s stop.
    local LOCK_MAGIC = "TS30_LOCK_V1"
    local FINAL_LOCK_MAGIC = "TS30_REBIRTH_STOP_900_V1"
    local NO_PENDING_MAGIC = "TS30_NO_PENDING_V1"
    local PENDING_MAGIC = "TS30_RB_PENDING_V1:"
    local IO_MAGIC = "TS30_IO_OK_V1"
    local MAX_SAFE_INTEGER = 9007199254740991

    local function number(value)
        local n = tonumber(value)
        if not n or n ~= n or n == math.huge or n == -math.huge or n < 0 then return nil end
        return n
    end

    local function readValues()
        local data = Env.data()
        if type(data) ~= "table" then return nil, nil, nil end
        local stats = type(data.Statistics) == "table" and data.Statistics or nil
        local currencies = type(data.Currencies) == "table" and data.Currencies or nil
        local rebirths = number(stats and stats.Rebirths)
        if rebirths and math.floor(rebirths) ~= rebirths then rebirths = nil end
        return data, rebirths, number(currencies and currencies.Coins)
    end

    -- Before deciding the 900M/s stop, require a complete, stable equipped-team replica.
    -- This verifies team identity, not that the server actually honored EquipBest(Luck).
    local function teamSignature(data)
        local pets = type(data) == "table" and data.Pets or nil
        local owned = type(pets) == "table" and pets.Owned or nil
        local equipped = type(pets) == "table" and pets.Equipped or nil
        if type(owned) ~= "table" or type(equipped) ~= "table" then return nil end
        local aliases, primary, flagged = {}, {}, {}
        local function scalar(v)
            return (type(v) == "string" or type(v) == "number") and tostring(v) ~= ""
        end
        local function mark(value, id)
            if not scalar(value) then return end
            local key = tostring(value)
            if aliases[key] ~= nil and aliases[key] ~= id then aliases[key] = false
            elseif aliases[key] == nil then aliases[key] = id end
        end
        for key, pet in pairs(owned) do
            if type(pet) == "table" then
                local raw = pet.Id or key
                if not scalar(raw) then return nil end
                local id = tostring(raw)
                if primary[id] then return nil end
                primary[id] = true
                mark(key, id); mark(pet.Id, id); mark(pet.PetId, id); mark(pet.PetID, id)
                if pet.Equip == true or pet.Equipped == true or pet.IsEquipped == true then flagged[id] = true end
            end
        end
        local selected, result = {}, {}
        for key, value in pairs(equipped) do
            if value ~= nil and value ~= false then
                local raw
                if type(value) == "table" then
                    raw = value.Id or value.PetId or value.PetID
                    if raw == nil and type(key) == "string" then raw = key end
                elseif value == true then raw = key
                elseif scalar(value) then raw = value end
                if not scalar(raw) then return nil end
                local id = aliases[tostring(raw)]
                if not id or selected[id] then return nil end
                selected[id] = true
                result[#result + 1] = id
            end
        end
        if #result == 0 then return nil end
        for id in pairs(flagged) do if not selected[id] then return nil end end
        table.sort(result)
        return table.concat(result, "\0")
    end

    local function setMode(value)
        local option = Ui.Options and Ui.Options.EquipMode
        if not option then return false end
        local P = Ui.__progressTest
        -- Egg selection and rebirth shutdown are independent: Luck starts at 300M/s.
        if P and P.rebirthLocked ~= nil then
            local expected = (P.eggFixed or P.rebirthLocked) and "Luck" or "Clicks"
            if value ~= expected then return false end
        end
        local changed = option.Value ~= value
        if P and (changed or P.expectedEquipMode ~= value) then
            P.expectedEquipMode, P.equipMinimumAt = value, os.clock()
            P.modeReadySince = nil
        end
        if changed then option:SetValue(value) end
        return option.Value == value
    end

    local function start(emit)
        local P = Ui.__progressTest
        if type(P) ~= "table" then error("нет состояния теста") end
        local hub = Env.genv and Env.genv.__SlopixHub
        local features = hub and hub.Features or {}
        local tap, hatch = features["features/tap"], features["features/hatch"]
        if type(tap) ~= "table" or type(tap.progressPack) ~= "function"
            or type(tap.hasAutoRebirth) ~= "function" then
            error("не загружен безопасный модуль ребёртов")
        end
        local hatchApiReady = type(hatch) == "table" and type(hatch.progressTarget) == "function"
            and type(hatch.progressLocate) == "function"

        local userId = number(Env.LocalPlayer and Env.LocalPlayer.UserId)
        if not userId or userId < 1 or math.floor(userId) ~= userId then
            error("не удалось определить UserId для отдельного состояния аккаунта")
        end
        local userKey = string.format("%.0f", userId)
        local lockPath = "SlopixHub/TapSimulator/ts30_hatch_" .. userKey .. ".lock"
        local finalLockPath = "SlopixHub/TapSimulator/ts30_rebirth_stop_900_" .. userKey .. ".lock"
        local pendingPath = "SlopixHub/TapSimulator/ts30_rebirth_" .. userKey .. ".state"
        local ioPath = "SlopixHub/TapSimulator/ts30_io_" .. userKey .. ".probe"
        local genv = Env.genv or {}
        if type(genv.__TS30Locks) ~= "table" then genv.__TS30Locks = {} end
        if type(genv.__TS30RebirthStops900) ~= "table" then genv.__TS30RebirthStops900 = {} end
        local locks, finalLocks = genv.__TS30Locks, genv.__TS30RebirthStops900
        local files = Env.files or {}
        local canReadLock = type(files.isfile) == "function" and type(files.readfile) == "function"
        local canWriteLock = canReadLock and type(files.writefile) == "function"
            and type(files.isfolder) == "function" and type(files.makefolder) == "function"

        local function writeChecked(path, value)
            if not canWriteLock then return false, "нет функций чтения и записи файлов" end
            local ok, err = pcall(function()
                for _, folder in ipairs({ "SlopixHub", "SlopixHub/TapSimulator" }) do
                    if not files.isfolder(folder) then files.makefolder(folder) end
                end
                files.writefile(path, value)
                assert(files.isfile(path) and files.readfile(path) == value, "проверка записи не прошла")
            end)
            Env.elevate()
            return ok, ok and nil or tostring(err)
        end
        local function readLock()
            if not canWriteLock then return nil, "экзекутор не поддерживает сохранение состояния" end
            local ok, exists = pcall(files.isfile, lockPath)
            Env.elevate()
            if not ok then return nil, "не читается маркер фазы яиц" end
            if not exists then
                if locks[userKey] then return nil, "маркер фазы яиц пропал из файлов" end
                return false, nil
            end
            local readOk, value = pcall(files.readfile, lockPath)
            Env.elevate()
            if not readOk or value ~= LOCK_MAGIC then return nil, "повреждён маркер фазы яиц" end
            locks[userKey] = true
            return true, nil
        end
        local function saveLock()
            -- Даже при ошибке в этой сессии обратный переход запрещён.
            locks[userKey] = true
            return writeChecked(lockPath, LOCK_MAGIC)
        end
        local function readFinalLock()
            if not canWriteLock then return nil, "экзекутор не поддерживает сохранение состояния" end
            local ok, exists = pcall(files.isfile, finalLockPath)
            Env.elevate()
            if not ok then return nil, "не читается маркер остановки ребёртов 900 млн/с" end
            if not exists then
                if finalLocks[userKey] then return nil, "маркер остановки ребёртов 900 млн/с пропал из файлов" end
                return false, nil
            end
            local readOk, value = pcall(files.readfile, finalLockPath)
            Env.elevate()
            if not readOk or value ~= FINAL_LOCK_MAGIC then return nil, "повреждён маркер остановки ребёртов 900 млн/с" end
            finalLocks[userKey] = true
            return true, nil
        end
        local function saveFinalLock()
            -- Fail closed in this session even if a write or its verification fails.
            finalLocks[userKey] = true
            return writeChecked(finalLockPath, FINAL_LOCK_MAGIC)
        end
        local function readPending()
            local ok, exists = pcall(files.isfile, pendingPath)
            Env.elevate()
            if not ok then return nil, nil, "не читается маркер запроса ребёрта" end
            if not exists then return true, nil, nil end
            local readOk, raw = pcall(files.readfile, pendingPath)
            Env.elevate()
            if not readOk or type(raw) ~= "string" then return nil, nil, "не читается запрос ребёрта" end
            if raw == NO_PENDING_MAGIC then return true, nil, nil, true end
            local digits = raw:match("^TS30_RB_PENDING_V1:(%d+)$")
            local before = number(digits)
            if not before or before > MAX_SAFE_INTEGER or math.floor(before) ~= before then
                return nil, nil, "повреждён маркер запроса ребёрта"
            end
            return true, { before = before }, nil
        end
        local function writePending(before)
            if not before or before > MAX_SAFE_INTEGER or before < 0 or math.floor(before) ~= before then
                return false, "неверный или слишком большой счётчик ребёртов"
            end
            return writeChecked(pendingPath, PENDING_MAGIC .. string.format("%.0f", before))
        end
        local function clearPending()
            return writeChecked(pendingPath, NO_PENDING_MAGIC)
        end

        P.phase = "check"
        P.equipReady = false -- no sender equips the saved/default mode before the lock is read
        P.holdHatch = true
        P.holdCraft, P.disableAutoCraft = true, true
        P.holdUpgrades = true
        P.minHatchInterval = MIN_HATCH_INTERVAL
        P.requiredIncome = REQUIRED_INCOME
        P.stopRebirthIncome = STOP_REBIRTH_INCOME
        P.batchPrice = BATCH_PRICE
        P.activeClock = 0
        P.phaseAt = 0
        P.lastTick = os.clock()
        P.nextReport = REPORT_SECONDS
        P.pending = nil
        P.confirmed = 0
        if type(genv.__TS30LastRebirthSend) ~= "table" then genv.__TS30LastRebirthSend = {} end
        local lastSends = genv.__TS30LastRebirthSend
        local lastSent = number(lastSends[userKey])
        P.nextSendAt = lastSent and (lastSent + REBIRTH_GAP) or 0 -- сохраняется при перезагрузке скрипта в том же клиенте
        P.nextLocateAt = 0
        P.farmMode = nil
        P.farmThresholdReached = false
        P.farmPrevRebirths, P.farmPrevCoins = nil, nil
        P.farmWindowStart, P.farmWindowCoins, P.farmWindowMode = nil, 0, nil
        P.farmResetGraceUntil = 0
        P.farmResyncUntil = 0
        P.measureRebirths = nil
        P.nextClickerRefresh = 0
        P.eggFixed = false -- permanent 300M/s stage, compatible with the old TS30_LOCK_V1
        P.rebirthLocked = false -- separate permanent 900M/s stop, never inferred from the old marker
        P.targetProbeRequired, P.targetNextProbeAt = false, 0
        P.targetPrevRebirths = nil
        P.eggGoal = nil
        P.income = nil
        P.incomeByMode = {} -- последние отдельные оценки Clicks/Luck; вместе с возрастом замера
        P.lastRebirthPack = nil
        P.gemReady = false -- покупки навыков не стартуют до проверки состояния и профиля
        P.holdSkillTree = true
        P.gemWork = P.gemWork or {}
        P.actualBatchIntervals = {}
        P.confirmedBatches = 0
        P.farmBatches = 0
        P.note = "проверяю аккаунт и 30M"
        P.remoteError = nil

        local function log(text)
            emit("progress", "[30M FARM v13] " .. tostring(text))
        end
        P.log = log
        local function phase(name, note)
            P.phase = name
            P.phaseAt = P.activeClock
            P.note = note or name
        end
        local function stopNativeClicker()
            if Ui.on("AutoClicker") then pcall(Ui.set, "AutoClicker", false) end
            P.clickerStoppedForSafety = not Ui.on("AutoClicker")
            -- Значение тумблера не подтверждает сервер. Отправляем явную команду выключения.
            Life.spawn("progress:stopNativeClicker", function()
                local ok, err = pcall(function()
                    if type(Ui.syncNativeClicker) == "function" then Ui.syncNativeClicker()
                    else Env.fire("AutoClickService", "AutoClickRequested", { Enabled = false }) end
                end)
                if not ok then
                    log("не удалось отправить отключение штатного автокликера: " .. tostring(err)
                        .. "; он может продолжать работу, останови клиент вручную")
                end
            end)
            if not P.clickerStoppedForSafety then log("тумблер автокликера не выключился; останови клиент вручную") end
        end
        local function blocked(reason)
            P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
            P.holdUpgrades, P.holdSkillTree = true, true
            phase("blocked", reason)
            log(reason .. "; яйца и новые ребёрты на паузе")
        end
        local function uncertain(reason)
            P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
            P.holdUpgrades, P.holdSkillTree = true, true
            if P.pending or P.previousRebirthPending then
                P.holdTap = true
                stopNativeClicker()
            end
            phase("uncertain", reason)
            log(reason .. "; новые запросы и яйца остановлены"
                .. ((P.pending or P.previousRebirthPending) and ", тапы на паузе до подтверждения" or ""))
        end
        local function beginSettle(reason)
            P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
            P.holdUpgrades, P.holdSkillTree = true, true
            P.goodWindows = 0
            P.sampleCoins, P.sampleAt, P.sampleTeam = nil, nil, nil
            P.settleTeam = nil
            P.targetWindowStart, P.targetPrevCoins, P.targetWindowCoins = nil, nil, 0
            P.measureRebirths = nil -- фиксируем счётчик до первого окна прямого замера
            P.probeMode = P.eggFixed and "Luck" or "Clicks"
            P.equipMinimumAt = os.clock() -- после трейда/ребёрта нужен новый запрос команды
            P.modeReadySince = nil
            phase("settle", "подготавливаю чистый замер " .. P.probeMode)
            if reason then log(reason) end
        end
        local function resumeTarget(reason)
            -- The egg remains fixed after 300M/s. Only the second marker forbids rebirths.
            if not P.eggFixed then blocked("нет постоянного маркера фазы 30M"); return end
            P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
            P.holdUpgrades, P.holdSkillTree = true, true
            P.farmStorageFull, P.farmThresholdReached = false, false
            local ok, selected = pcall(setMode, "Luck")
            if not ok or not selected then blocked("не удалось выбрать команду Luck"); return end
            phase("save", P.rebirthLocked and "жду 30M x3; ребёрты окончательно остановлены"
                or "жду 30M x3; ребёрты продолжаются до 900 млн/с")
            if reason then log(reason) end
        end
        local function beginUpgradeWindow(reason)
            if P.eggFixed or P.rebirthLocked then
                resumeTarget("фаза 30M уже закреплена: дешёвые яйца, крафт и покупки не возобновляются")
                return
            end
            -- Прокачка, покупки и наблюдение дохода идут параллельно: ребёрт больше не ждёт
            -- отдельного 6-секундного окна улучшений и 30-секундного замера.
            P.holdHatch, P.holdCraft, P.disableAutoCraft = false, false, false
            P.holdUpgrades, P.holdSkillTree = false, false
            P.farmMode, P.farmThresholdReached = "Clicks", false
            P.farmResyncUntil, P.measureRebirths = 0, nil
            P.farmPrevRebirths, P.farmPrevCoins = nil, nil
            P.farmWindowStart, P.farmWindowCoins, P.farmWindowMode = nil, 0, nil
            P.farmNextProbeAt = P.activeClock + CLEAN_PROBE_PERIOD
            P.goodWindows, P.income = 0, nil
            local ok, selected = pcall(setMode, "Clicks")
            if not ok or not selected then blocked("не удалось выбрать команду Clicks"); return end
            phase("rebirth", "доступные яйца до 20% баланса; 100% крафт; ребёрт не чаще раза в 20 секунд")
            if reason then log(reason) end
        end
        local function pausedForTrade()
            return Env.genv and Env.genv.__handoverPaused == true
        end
        -- Автокликер могли купить уже ПОСЛЕ стартового включения, которое сервер игнорировал.
        -- Перед замером повторно отправляем Enable; это не покупка и не расходует гемы.
        local function refreshNativeClicker()
            if P.clickerRefreshPending or P.holdTap or P.stopRequested or pausedForTrade() or not Ui.on("AutoClicker") then return end
            P.clickerRefreshPending = true
            Life.spawn("progress:refreshNativeClicker", function()
                local ok, err = pcall(function()
                    local remote = Env.remote("AutoClickService", "AutoClickRequested")
                    if Life.alive and not P.holdTap and not P.stopRequested and not pausedForTrade() and Ui.on("AutoClicker") then
                        Env.elevate()
                        remote:FireServer({ Enabled = true })
                    end
                end)
                P.clickerRefreshPending = false
                if not ok then log("не удалось повторно включить игровой автокликер: " .. tostring(err)) end
            end)
        end
        local function hatchControlEnabled()
            -- Если модуль яйца вообще не загрузился, он не должен останавливать ПРОКАЧКУ.
            return not hatchApiReady or Ui.on("AutoHatch")
        end
        local function userStopped()
            return P.stopRequested or not Ui.on("AutoTap") or not hatchControlEnabled()
        end
        local function modeRequestSeen(mode)
            return Ui.on("AutoEquipBest") and P.lastEquipMode == mode
                and type(P.lastEquipAt) == "number" and P.lastEquipAt >= (P.equipMinimumAt or 0)
        end
        local function canRebirth(prepared)
            local farm = P.phase == "rebirth" and not P.eggFixed and not P.farmThresholdReached
            local activeNow = P.activeClock + math.max(0, os.clock() - (P.lastTick or os.clock()))
            local target = P.phase == "target_rebirth" and P.eggFixed and not P.targetProbeRequired
                and activeNow < (P.targetNextProbeAt or 0)
            return Life.alive and Ui.__progressTest == P and not P.stopRequested and not pausedForTrade()
                and Ui.on("AutoTap") and hatchControlEnabled() and not P.rebirthLocked and (farm or target)
                and P.holdHatch and P.holdCraft and P.holdUpgrades and P.holdSkillTree
                and P.pending == prepared and not P.previousHatchPending and not P.previousRebirthPending
                and not P.previousCraftPending and not P.hatchUncertain and not P.craftUncertain
                and not P.previousIslandPending and not P.islandUncertain and not P.islandTravelUncertain
                and not P.islandInFlight and not P.islandTravelInFlight
                and not P.upgradeUncertain and not P.upgradeInFlight and not P.skillUncertain and not P.skillInFlight
                and not P.craftBusy and not P.craftInFlight and not P.cleaning
                and not P.locating and not Ui.hatchInFlight and not Ui.hatchMoving and not Ui.travelling
                and os.clock() >= (P.nextSendAt or 0)
        end
        local function rememberIncome(mode, rate, kind)
            if mode ~= "Clicks" and mode ~= "Luck" then return end
            if type(rate) ~= "number" or rate ~= rate or rate < 0 or rate == math.huge then return end
            P.incomeByMode[mode] = { value = rate, at = os.clock(), kind = kind }
        end
        local function incomeText(mode)
            local sample = P.incomeByMode[mode]
            if type(sample) ~= "table" then return "ещё нет замера" end
            local age = math.max(0, math.floor(os.clock() - sample.at))
            return string.format("%.0f/с (%s, %d с назад)", sample.value, tostring(sample.kind), age)
        end
        local function status(rebirths, coins)
            local intervals = P.actualBatchIntervals or {}
            local actual = "пока нет"
            if #intervals > 0 then
                local sum = 0
                for _, v in ipairs(intervals) do sum += v end
                actual = string.format("%.2f с (среднее %d промежутков)", sum / #intervals, #intervals)
            end
            log(string.format("фаза=%s | ребёрты=%s | монеты=%s | доход=%s/с | нужно>=%.0f/с | яйцо=%s | тройных=%s | фактический интервал=%s | %s",
                tostring(P.phase), tostring(rebirths or "нет данных"), tostring(coins or "нет данных"),
                P.income and string.format("%.0f", P.income) or "измеряю",
                P.eggFixed and STOP_REBIRTH_INCOME or REQUIRED_INCOME,
                tostring(P.eggGoal or "ищу"), tostring(P.confirmedBatches or 0), actual, tostring(P.note)))
            log("доход команд: Clicks=" .. incomeText("Clicks") .. " | Luck=" .. incomeText("Luck"))
            log("яиц на прокачке: партий=" .. tostring(P.farmBatches or 0) .. " | крафт: "
                .. tostring(P.craftInfo or "модуль или формулы ещё не готовы"))
            local data = Env.data()
            if P.phase == "rebirth" and data and type(tap.progressExplain) == "function" then
                local ok, details = pcall(tap.progressExplain, data)
                if ok and type(details) == "string" then log("ребёрт: " .. details) end
            end
            if P.lastRebirthPack then
                local r = P.lastRebirthPack
                log(string.format("последний подтверждённый пакет: кнопка=%s, заявлено x%s, реально +%s, цена=%s",
                    tostring(r.index), tostring(r.amount), tostring(r.actual), tostring(r.price)))
            end
            local gems = data and type(data.Currencies) == "table" and data.Currencies.Gems
            local function switch(name)
                local toggle = Ui.Toggles and Ui.Toggles[name]
                return toggle and tostring(toggle.Value == true) or "нет"
            end
            local work = P.gemWork or {}
            log("гемы=" .. tostring(gems or "нет данных") .. " | тумблеры навыков/улучшений="
                .. switch("AutoSkillTree") .. "/" .. switch("AutoUpgrade")
                .. (P.eggFixed and " | новые покупки остановлены" or ""))
            log("улучшения: навыки=" .. tostring(work.skills or "нет данных модуля")
                .. " | прочие=" .. tostring(work.upgrades or "нет данных модуля"))
        end

        -- Сначала создаём свою директорию и проверяем фактическое чтение/запись.
        -- Без них после полного перезапуска нельзя отличить фарм от уже начатой фазы яиц.
        local ioOk, ioErr = writeChecked(ioPath, IO_MAGIC)
        if not ioOk then
            blocked("нельзя сохранить состояние теста: " .. tostring(ioErr))
        else
            local lock, lockErr = readLock()
            if lock == nil then
                blocked(lockErr)
            else
                P.eggFixed = lock == true
                local finalLock, finalErr = readFinalLock()
                if finalLock == nil then
                    blocked(finalErr)
                elseif finalLock and not P.eggFixed then
                    blocked("найден запрет ребёртов 900 млн/с, но маркер 30M отсутствует")
                else
                    P.rebirthLocked = finalLock == true
                    -- A legacy 300M marker is NOT evidence of 900M/s. Check the current Luck
                    -- income before allowing the first rebirth after migration or restart.
                    P.targetProbeRequired = P.eggFixed and not P.rebirthLocked
                    local pendingOk, fromDisk, pendingErr, hadClearedRequest = readPending()
                    -- A full restart loses the previous send time; conservatively wait 20s.
                    if pendingOk and hadClearedRequest and lastSent == nil then
                        P.nextSendAt = math.max(P.nextSendAt or 0, os.clock() + REBIRTH_GAP)
                    end
                    if not pendingOk then
                        blocked(pendingErr)
                    elseif fromDisk and P.previousRebirthPending
                        and number(P.previousRebirthPending.before) ~= fromDisk.before then
                        blocked("счётчики двух ожидающих ребёртов не совпадают")
                    elseif fromDisk then
                        P.previousRebirthPending = fromDisk
                        log("найден неподтверждённый ребёрт предыдущего запуска")
                    elseif P.previousRebirthPending then
                        local before = number(P.previousRebirthPending.before)
                        local persisted, err = writePending(before)
                        if not persisted then blocked("не удалось сохранить старый запрос ребёрта: " .. tostring(err)) end
                    end
                    if P.rebirthLocked then
                        log("найден отдельный маркер 900 млн/с: новые ребёрты запрещены")
                    elseif P.eggFixed then
                        log("найден маркер 30M: сначала проверяю Luck-доход; старый маркер не подтверждает 900 млн/с")
                    end
                end
            end
        end
        if P.previousRebirthPending then
            P.holdTap = true
            stopNativeClicker()
        elseif P.phase == "blocked" then
            stopNativeClicker()
        else
            -- До этой точки при загрузке тапы и штатный кликер были на паузе.
            P.holdTap = false
            if Ui.on("AutoClicker") and not pausedForTrade() and not P.stopRequested then
                pcall(Ui.set, "AutoClicker", false)
                if Life.alive and not pausedForTrade() and not P.stopRequested then pcall(Ui.set, "AutoClicker", true) end
            end
        end

        -- Choose the correct phase BEFORE enabling either EquipBest sender. This also covers
        -- saved configs that restored Luck during bootstrap and an already-persisted 30M lock.
        if P.phase ~= "blocked" then
            local initialMode = P.eggFixed and "Luck" or "Clicks"
            local modeOk, modeSelected = pcall(setMode, initialMode)
            if not modeOk or not modeSelected then
                blocked("не удалось установить режим команды " .. initialMode)
            else
                P.equipReady = true
            end
        end
        -- Покупки включаются только в окнах прокачки. При замере, ребёрте и после порога они на паузе.
        if not P.stopRequested and not pausedForTrade() then
            pcall(Ui.set, "AutoUpgrade", not P.eggFixed)
            pcall(Ui.set, "AutoSkillTree", not P.eggFixed)
            pcall(Ui.set, "AutoCraft", not P.eggFixed)
        end
        P.holdUpgrades = true
        P.gemReady = P.phase ~= "blocked" and not P.stopRequested

        Life.spawn("progress:resolve", function()
            local ok, remote = pcall(Env.remote, "RebirthService", "RebirthRequested")
            if ok and remote then P.remote = remote else P.remoteError = tostring(remote) end
        end)

        local function findTarget(data)
            if not hatchApiReady then return false, "модуль яйца 30M не загрузился" end
            local egg, why, price = hatch.progressTarget(data)
            if not egg then return false, why end
            if P.eggGoal and P.eggGoal ~= egg then
                return false, "ключ 30M изменился во время теста"
            end
            if price ~= BATCH_PRICE then return false, "цена x3 не равна 900000000" end
            P.eggGoal = egg
            if why == "no_position" and not P.locating and not P.pending
                and not P.previousHatchPending and not P.previousRebirthPending
                and P.activeClock >= P.nextLocateAt and not pausedForTrade() then
                P.nextLocateAt = P.activeClock + 45
                P.locating = true
                Life.spawn("progress:locate30m", function()
                    local ok, arrived = pcall(hatch.progressLocate, egg)
                    P.locating = false
                    if ok and arrived then
                        log("модель 30M обнаружена; позиция получена из игры")
                    else
                        log("позиция 30M пока не видна; попробую снова у Spawn")
                    end
                end)
            end
            return true, why
        end
        local function confirmed(rebirths, coins)
            local request = P.pending
            if not request or not rebirths or rebirths <= request.before then return false end
            local cleared, err = clearPending()
            if not cleared then
                P.holdTap = true
                blocked("ребёрт подтверждён, но не удалось сохранить состояние: " .. tostring(err))
                return true
            end
            P.pending = nil
            P.confirmed += 1
            -- Обновляем базовый снимок при КАЖДОМ своём подтверждении, а не только после timeout.
            P.farmPrevRebirths, P.farmPrevCoins = rebirths, coins
            P.lastRebirthPack = { index = request.index, amount = request.amount, price = request.price,
                actual = rebirths - request.before }
            -- Реплика монет может обновиться позже счётчика. Падение в этот период не считаем
            -- доходом и не принимаем за посторонний расход, но и не прибавляем как доход.
            P.farmResetGraceUntil = os.clock() + 5
            local wasUncertain = P.phase == "uncertain"
            if P.confirmed <= 3 or P.confirmed % 10 == 0 or wasUncertain then
                log(string.format("ребёрт подтверждён: %s -> %s; кнопка=%s, заявлено x%s, реально +%s; баланс до=%s, сейчас=%s",
                    tostring(request.before), tostring(rebirths), tostring(request.index), tostring(request.amount),
                    tostring(rebirths - request.before), tostring(request.coins), tostring(coins)))
            end
            if request.amount and rebirths - request.before ~= request.amount then
                log("прирост ребёртов отличается от выбранного пакета; источник расхождения неизвестен")
            end
            if wasUncertain then
                P.holdTap = false
                P.farmPrevRebirths, P.farmPrevCoins = rebirths, coins
                P.farmWindowStart, P.farmWindowCoins, P.farmWindowMode = nil, 0, nil
                P.goodWindows = 0
                if P.clickerStoppedForSafety and not P.stopRequested and not pausedForTrade() then
                    pcall(Ui.set, "AutoClicker", true)
                    P.clickerStoppedForSafety = false
                end
            end
            if P.eggFixed then
                -- The target-stage rebirth must never turn farm eggs, craft or upgrades back on.
                P.targetPrevRebirths = rebirths
                P.farmResyncUntil = os.clock() + REBIRTH_SYNC_SECONDS
                P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                P.holdUpgrades, P.holdSkillTree = true, true
                P.hatchSampleAt, P.hatchSampleCoins = nil, nil
                P.targetWindowStart, P.targetPrevCoins, P.targetWindowCoins = nil, nil, 0
                phase("target_sync", "ребёрт подтверждён; жду обновления счётчика и баланса")
            else
                if P.farmThresholdReached then
                    P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                    P.holdUpgrades, P.holdSkillTree = true, true
                else
                    P.holdHatch, P.holdCraft, P.disableAutoCraft = false, false, false
                    P.holdUpgrades, P.holdSkillTree = false, false
                end
                phase("rebirth", "ребёрт подтверждён; следующий не раньше 20 секунд после отправки")
            end
            return true
        end
        local function actionsOutstanding()
            return P.pending or P.previousRebirthPending or P.previousHatchPending or P.previousCraftPending
                or P.previousIslandPending or P.islandInFlight or P.islandTravelInFlight
                or P.islandUncertain or P.islandTravelUncertain or P.locating
                or Ui.hatchInFlight or Ui.hatchMoving or Ui.travelling or P.craftBusy or P.craftInFlight
                or P.cleaning or P.upgradeInFlight or P.skillInFlight or P.clickerRefreshPending
                or P.craftUncertain or P.hatchUncertain or P.upgradeUncertain or P.skillUncertain
        end
        local function fixEgg30(rebirths)
            if actionsOutstanding() then
                uncertain("нельзя закрепить 30M: отправленные действия ещё не завершены")
                return false
            end
            P.eggFixed = true -- before any yielding write: never fall back to cheaper eggs
            locks[userKey] = true -- a same-client reload during the write must fail closed
            P.targetPrevRebirths = rebirths
            P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
            P.holdUpgrades, P.holdSkillTree = true, true
            P.farmStorageFull, P.farmThresholdReached = false, false
            local saved, err = saveLock()
            if not saved then
                blocked("не удалось надёжно сохранить выбор 30M: " .. tostring(err))
                return false
            end
            -- The guards already block these on eggFixed even if toggles yield here.
            pcall(Ui.set, "AutoUpgrade", false)
            pcall(Ui.set, "AutoSkillTree", false)
            pcall(Ui.set, "AutoCraft", false)
            P.income = nil -- Clicks income is not a Luck measurement
            local ok, selected = pcall(setMode, "Luck")
            if not ok or not selected then blocked("30M сохранено, но не удалось выбрать Luck"); return false end
            P.targetProbeRequired = true
            log("три чистых окна Clicks подтвердили 300 млн/с: 30M закреплено; ребёрты пока НЕ отключены")
            beginSettle("перед продолжением ребёртов отдельно проверяю доход после запроса Luck")
            return true
        end
        local function lockRebirth(rebirths)
            if not P.eggFixed or P.probeMode ~= "Luck" or actionsOutstanding() then
                uncertain("нельзя подтвердить 900 млн/с: режим или отправленные действия изменились")
                return false
            end
            P.rebirthLocked = true -- block all senders before a potentially yielding write
            P.lockedRebirths = rebirths
            P.targetProbeRequired = false
            P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
            P.holdUpgrades, P.holdSkillTree = true, true
            local saved, err = saveFinalLock()
            if not saved then
                blocked("не удалось сохранить отдельный запрет ребёртов 900 млн/с: " .. tostring(err))
                return false
            end
            log("три чистых окна после запроса Luck подтвердили 900 млн монет/с: новые ребёрты окончательно отключены")
            resumeTarget("продолжаю только 30M x3, Luck и чистку")
            return true
        end

        local function resetFarmWindow()
            P.farmWindowStart, P.farmWindowCoins, P.farmWindowMode = nil, 0, nil
        end
        -- В ПРОКАЧКЕ неожиданный новый снимок не доказывает чужую команду и не должен
        -- навсегда останавливать аккаунт. Сбрасываем замер, выдерживаем короткую паузу
        -- и полный 20-секундный интервал до следующей собственной отправки. Не трогаем
        -- записанный pending/lock и не возобновляем прокачку после постоянного lock.
        local function resyncFarm(rebirths, coins, before, where)
            local now = os.clock()
            P.farmPrevRebirths, P.farmPrevCoins = rebirths, coins
            P.farmResyncUntil = now + REBIRTH_SYNC_SECONDS
            P.farmResetGraceUntil = now + 5 -- баланс может реплицироваться вслед за счётчиком
            P.nextSendAt = math.max(P.nextSendAt or 0, now + REBIRTH_GAP)
            -- Сохраняем защитный интервал и при перезагрузке скрипта в том же клиенте.
            lastSends[userKey] = math.max(number(lastSends[userKey]) or 0, now)
            P.farmThresholdReached = false
            P.goodWindows, P.income, P.modeReadySince = 0, nil, nil
            P.sampleCoins, P.sampleAt, P.measureRebirths = nil, nil, nil
            P.farmNextProbeAt = P.activeClock + CLEAN_PROBE_PERIOD
            resetFarmWindow()
            P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
            P.holdUpgrades, P.holdSkillTree = true, true
            if P.eggFixed then
                P.targetPrevRebirths = rebirths
                P.targetProbeRequired = true -- discard any old Luck windows and recheck
                phase("target_sync", "обновился счётчик ребёртов: сверяю данные, 30M остаётся закреплённым")
            else
                phase("rebirth", "обновился счётчик ребёртов: сверяю данные и продолжу прокачку")
            end
            log(string.format("счётчик ребёртов %s -> %s (%s), источник неизвестен; сверяю данные 2 с, следующий запрос не раньше 20 с",
                tostring(before), tostring(rebirths), tostring(where)))
        end
        local function farmMode(wanted, why)
            local ok, selected = pcall(setMode, wanted)
            if not ok or not selected then blocked("не удалось выбрать команду " .. tostring(wanted)); return false end
            P.farmMode = wanted
            P.goodWindows, P.income = 0, nil
            resetFarmWindow()
            if why then log(why) end
            return true
        end

        -- Ребёрты могут обнулить баланс, поэтому нельзя сравнивать кошелёк только раз в 10 с.
        -- Суммируем положительные последовательные изменения кошелька и НЕ прибавляем падения.
        -- Это предварительная оценка, не доказанная нижняя граница: репликация и посторонние
        -- поступления могут её исказить. До постоянного lock ещё раз измеряем доход без ребёртов.
        -- Никакая догадка о числе ребёртов, цене яйца или размере кошелька доходом не считается.
        local function observeFarmIncome(rebirths, coins)
            local lastRb, lastCoins = P.farmPrevRebirths, P.farmPrevCoins
            if lastRb and rebirths ~= lastRb then
                if P.pending then
                    if rebirths < lastRb then
                        -- Пока свой запрос ещё не подтверждён, не заменяем прежний снимок
                        -- откатившейся репликой и не делаем второй запрос.
                        resetFarmWindow()
                        P.goodWindows = 0
                        P.note = "жду стабильный счётчик для подтверждения ребёрта"
                        return true
                    end
                else
                    resyncFarm(rebirths, coins, lastRb, "во время прокачки")
                    return false
                end
            end
            local delta = lastCoins and (coins - lastCoins) or nil
            local precision = math.max(coins, lastCoins or 0) * 1e-15
            if delta and delta < -precision and not P.pending and not P.previousRebirthPending
                and os.clock() > (P.farmResetGraceUntil or 0) then
                if Ui.hatchInFlight or os.clock() <= (P.farmSpendWatchUntil or 0) then
                    -- A permitted egg expense must not masquerade as external interference or
                    -- become income. Discard this preliminary window; direct probes decide lock.
                    resetFarmWindow()
                    P.goodWindows = 0
                else
                    blocked("монеты уменьшились вне ожидаемого ребёрта/яйца: проверь другой скрипт")
                    return false
                end
            end
            P.farmPrevRebirths, P.farmPrevCoins = rebirths, coins
            if P.farmThresholdReached then return true end

            -- Do not use Luck during leveling, even for preliminary income samples.
            local mode = "Clicks"
            P.farmMode = mode
            local opt = Ui.Options and Ui.Options.EquipMode
            if not opt or opt.Value ~= mode then
                if not farmMode(mode, "режим команды изменился — заново замеряю доход") then return false end
                return true
            end
            if not modeRequestSeen(mode) then
                P.modeReadySince = nil
                resetFarmWindow()
                return true
            end
            P.modeReadySince = P.modeReadySince or P.activeClock
            if P.activeClock - P.modeReadySince < START_SETTLE then
                resetFarmWindow()
                return true
            end
            if P.farmWindowStart == nil or P.farmWindowMode ~= mode then
                P.farmWindowStart, P.farmWindowCoins, P.farmWindowMode = P.activeClock, 0, mode
                return true
            end
            if delta and delta > precision then
                P.farmWindowCoins += delta - precision
            end
            local seconds = P.activeClock - P.farmWindowStart
            if seconds < WINDOW then return true end
            local rate = math.max(0, P.farmWindowCoins / seconds)
            P.income = rate
            rememberIncome(mode, rate, "предварительно между ребёртами")
            P.farmWindowStart, P.farmWindowCoins = P.activeClock, 0
            if rate >= REQUIRED_INCOME then
                P.goodWindows += 1
                P.note = string.format("предварительно Clicks %.0f/с: %d/%d окон", rate, P.goodWindows, REQUIRED_WINDOWS)
                if P.goodWindows >= REQUIRED_WINDOWS then
                    -- Preliminary balances can be distorted by eggs/rebirths. Drain all actions,
                    -- then require three separate *clean actual income* windows before locking.
                    P.farmThresholdReached = true
                    P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                    P.holdUpgrades, P.holdSkillTree = true, true
                    P.note = "предварительный порог Clicks; жду завершения действий перед чистым замером"
                    log("предварительный доход Clicks достиг порога; приостанавливаю новые действия для чистого замера")
                end
            else
                P.goodWindows = 0
                P.note = string.format("ребёрты до 1/20 с; предварительная оценка Clicks %.0f/с", rate)
            end
            return true
        end

        -- A cheap preliminary Luck estimate can request an early *clean* check instead of
        -- waiting for the 75s periodic probe. Only positive replica deltas are accumulated;
        -- hatch/rebirth losses are never added. This estimate itself NEVER stops rebirths.
        local function observeTargetIncome(coins)
            local opt = Ui.Options and Ui.Options.EquipMode
            if P.targetProbeRequired or not opt or opt.Value ~= "Luck" or not modeRequestSeen("Luck") then
                P.targetWindowStart, P.targetPrevCoins, P.targetWindowCoins = nil, nil, 0
                return
            end
            local previous = P.targetPrevCoins
            P.targetPrevCoins = coins
            if P.targetWindowStart == nil or previous == nil then
                P.targetWindowStart, P.targetWindowCoins = P.activeClock, 0
                return
            end
            local precision = math.max(coins, previous) * 1e-15
            local change = coins - previous
            if change > precision then P.targetWindowCoins += change - precision end
            local seconds = P.activeClock - P.targetWindowStart
            if seconds < WINDOW then return end
            local rate = math.max(0, P.targetWindowCoins / seconds)
            P.income = rate
            rememberIncome("Luck", rate, "предварительно между партиями")
            P.targetWindowStart, P.targetWindowCoins = P.activeClock, 0
            if rate >= STOP_REBIRTH_INCOME then
                P.targetProbeRequired = true
                P.note = "предварительно Luck достиг 900 млн/с; проверяю тремя чистыми окнами"
                log("предварительный Luck-доход достиг 900 млн/с; останавливаю новые действия для проверки")
            end
        end

        local function step()
            if P.phase == "stopped" then return end
            local now = os.clock()
            local delta = math.max(0, now - (P.lastTick or now))
            P.lastTick = now
            if pausedForTrade() then
                P.wasTradePaused = true
                return
            end
            if userStopped() then
                P.holdHatch = true
                phase("stopped", "остановлено пользователем")
                log("тест остановлен; уже отправленный серверу запрос отозвать нельзя")
                return
            end
            P.activeClock += delta
            local data, rebirths, coins = readValues()
            if P.activeClock >= P.nextReport then
                P.nextReport = P.activeClock + REPORT_SECONDS
                status(rebirths, coins)
            end

            if P.wasTradePaused then
                P.wasTradePaused = false
                if not P.pending and P.phase ~= "blocked" and P.phase ~= "uncertain" and P.phase ~= "hatch_uncertain" then
                    if P.eggFixed then
                        if not P.rebirthLocked then P.targetProbeRequired = true end
                        resumeTarget("пауза завершена: 30M и Luck сохранены; доход перепроверю")
                    else beginUpgradeWindow("пауза завершена: продолжаю быстрые ребёрты") end
                end
            end
            -- Повреждённый/недоступный маркер не должен случайно разблокироваться подтверждением.
            if P.phase == "blocked" then return end
            if not P.rebirthLocked and not P.pending and not P.previousRebirthPending
                and (P.phase == "settle" or P.phase == "measure")
                and data and rebirths ~= nil and coins ~= nil then
                if P.measureRebirths == nil then
                    P.measureRebirths = rebirths
                elseif P.measureRebirths ~= rebirths then
                    -- Смена счётчика во время прямого замера делает окна недействительными.
                    resyncFarm(rebirths, coins, P.measureRebirths, "во время чистого замера")
                    return
                end
            end
            if P.phase == "rebirth" and not P.eggFixed and not P.rebirthLocked and not P.previousHatchPending
                and not P.previousRebirthPending and data and rebirths ~= nil and coins ~= nil then
                if not observeFarmIncome(rebirths, coins) then return end
            end

            if P.previousRebirthPending then
                local before = number(P.previousRebirthPending.before)
                if before and rebirths and rebirths > before then
                    local cleared, err = clearPending()
                    if not cleared then
                        blocked("ребёрт подтвердился, но состояние не сохранилось: " .. tostring(err))
                        return
                    end
                    P.previousRebirthPending = nil
                    P.holdTap = false
                    -- Не знаем точное время отправки предыдущей копии: выдерживаем полные 20 с.
                    P.nextSendAt = math.max(P.nextSendAt or 0, os.clock() + REBIRTH_GAP)
                    P.farmResetGraceUntil = os.clock() + 5
                    if P.clickerStoppedForSafety and not P.stopRequested and not pausedForTrade() then
                        pcall(Ui.set, "AutoClicker", true)
                        P.clickerStoppedForSafety = false
                    end
                    if P.eggFixed then
                        P.targetPrevRebirths = rebirths
                        P.farmResyncUntil = os.clock() + REBIRTH_SYNC_SECONDS
                        if not P.rebirthLocked then P.targetProbeRequired = true end
                        P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                        P.holdUpgrades, P.holdSkillTree = true, true
                        phase("target_sync", "подтвердился запрос прошлой копии; сверяю 30M и Luck")
                        log(P.note)
                    else
                        beginUpgradeWindow("ребёрт предыдущей копии подтвердился; продолжаю прокачку")
                    end
                else
                    if P.phase ~= "uncertain" then uncertain("у предыдущей копии был неподтверждённый ребёрт") end
                    return
                end
            end
            if P.previousHatchPending then
                if P.phase ~= "blocked" then blocked("у предыдущей копии оставался запрос яйца; нужен свежий вход") end
                return
            end
            if P.previousCraftPending or P.craftUncertain then
                blocked("у предыдущей копии или текущего крафта остался неподтверждённый запрос")
                return
            end
            if P.previousIslandPending or P.islandUncertain or P.islandTravelUncertain then
                blocked("покупка острова или переход остались без надёжного подтверждения; нужен свежий вход и диагностика")
                return
            end
            if P.pending then
                if confirmed(rebirths, coins) then return end
                if P.phase ~= "uncertain" and P.activeClock - P.pending.sentAt >= REPLY_TIMEOUT then
                    uncertain("ребёрт не подтвердился по Statistics.Rebirths")
                end
                return
            end
            if P.phase == "blocked" or P.phase == "uncertain" or P.phase == "hatch_uncertain" then return end
            if not data or rebirths == nil or coins == nil then
                P.goodWindows = 0
                P.sampleCoins, P.sampleAt = nil, nil
                P.note = "ожидаю корректные Currencies.Coins и Statistics.Rebirths"
                return
            end
            if P.rebirthLocked then
                if P.lockedRebirths == nil then P.lockedRebirths = rebirths end
                if rebirths ~= P.lockedRebirths then
                    blocked("счётчик ребёртов изменился после запрета на 900 млн/с: "
                        .. tostring(P.lockedRebirths) .. " -> " .. tostring(rebirths) .. "; источник неизвестен")
                    return
                end
            elseif P.eggFixed then
                if P.targetPrevRebirths ~= nil and rebirths ~= P.targetPrevRebirths then
                    resyncFarm(rebirths, coins, P.targetPrevRebirths, "на этапе 30M")
                    return
                end
                P.targetPrevRebirths = rebirths
            end
            if P.upgradeUncertain then
                blocked("ответ на покупку улучшения не подтверждён; новые яйца и ребёрты на паузе")
                return
            end
            if P.skillUncertain then
                blocked("ответ на покупку навыка не подтверждён; новые яйца и ребёрты на паузе")
                return
            end
            if P.phase == "rebirth" and not P.rebirthLocked and os.clock() < (P.farmResyncUntil or 0) then
                P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                P.holdUpgrades, P.holdSkillTree = true, true
                return
            end
            if P.phase == "check" then
                if P.eggFixed then
                    if P.rebirthLocked then
                        resumeTarget("сохранён и 30M, и окончательный запрет ребёртов")
                    else
                        P.targetProbeRequired = true
                        beginSettle("сначала проверяю Luck-доход старого/возобновлённого аккаунта до нового ребёрта")
                    end
                else
                    beginUpgradeWindow("прокачка: яйца до 20% текущего баланса, крафт 100%, гемовые улучшения")
                end
                return
            end
            if P.phase == "target_sync" then
                P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                P.holdUpgrades, P.holdSkillTree = true, true
                if os.clock() < (P.farmResyncUntil or 0) then return end
                if P.targetProbeRequired and not P.rebirthLocked then
                    if actionsOutstanding() then return end
                    beginSettle("сверка завершена; заново проверяю Luck без трат и ребёртов")
                else
                    resumeTarget("сверка завершена; 30M и Luck сохранены")
                end
                return
            end

            local targetWork = P.phase == "save" or P.phase == "hatch" or P.phase == "storage_wait"
                or P.phase == "target_wait" or P.phase == "locked_wait"
            if P.eggFixed and not P.rebirthLocked and targetWork then
                observeTargetIncome(coins)
                if P.activeClock >= (P.targetNextProbeAt or 0) then P.targetProbeRequired = true end
                if P.targetProbeRequired then
                    P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                    P.holdUpgrades, P.holdSkillTree = true, true
                    if actionsOutstanding() then return end
                    beginSettle("плановая проверка Luck-дохода: временно останавливаю яйца и ребёрты")
                    return
                end
                if os.clock() >= (P.nextSendAt or 0) then
                    -- If every 900M earned were spent immediately, expensive rebirths could
                    -- starve forever. When the 20s cooldown expires, save until *any* pack is
                    -- affordable, then send the largest available one; no larger pack is awaited.
                    P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                    P.holdUpgrades, P.holdSkillTree = true, true
                    if actionsOutstanding() then return end
                    if P.remoteError then blocked("RebirthRequested не найден: " .. tostring(P.remoteError)); return end
                    if not P.remote then return end
                    local index, _, _, why = tap.progressPack(data, math.huge)
                    if not index then
                        if why ~= "unaffordable" then blocked("цена ребёрта недоступна: " .. tostring(why)); return end
                        P.note = "жду монеты на минимально доступный ребёрт; 30M временно на паузе"
                        return
                    end
                    phase("target_rebirth", "30M закреплено; подготавливаю максимальный доступный ребёрт")
                    return
                end
            end
            if P.phase == "target_rebirth" and not P.rebirthLocked
                and (P.targetProbeRequired or P.activeClock >= (P.targetNextProbeAt or math.huge)) then
                P.targetProbeRequired = true
                if actionsOutstanding() then return end
                beginSettle("перед ребёртом наступило время проверки Luck-дохода")
                return
            end

            -- Target availability never prevents the still-allowed rebirth/probe scheduler above.
            local targetState = nil
            if P.eggFixed and (P.phase == "save" or P.phase == "hatch" or P.phase == "target_wait") then
                local okTarget
                if P.serverDeniedUntil and os.clock() < P.serverDeniedUntil then
                    okTarget = false
                    targetState = "отказ сервера " .. tostring(P.serverDeniedReason or "неизвестен") .. "; жду повтор"
                else
                    P.serverDeniedUntil, P.serverDeniedReason = nil, nil
                    okTarget, targetState = findTarget(data)
                end
                if not okTarget or targetState ~= "ready" then
                    P.goodWindows = 0
                    P.sampleCoins, P.sampleAt = nil, nil
                    P.holdHatch = true
                    P.holdUpgrades, P.holdSkillTree = true, true -- после перехода покупки не возобновляются
                    local reason = targetState == "no_position" and "ожидаю модель и координаты 30M" or tostring(targetState)
                    local note = "30M не подтверждено: " .. reason
                    if P.phase ~= "target_wait" then
                        phase("target_wait", note)
                        log(P.note .. (P.rebirthLocked and "; другое яйцо не выбираю, ребёрты остановлены"
                            or "; другое яйцо не выбираю, проверка ребёртов продолжается"))
                    elseif P.note ~= note then
                        P.note = note
                        log(P.note .. (P.rebirthLocked and "; ребёрты остановлены" or "; ребёрты ещё разрешены"))
                    end
                    return
                elseif P.phase == "target_wait" then
                    resumeTarget("30M найдено; жду 900 млн без дополнительного резерва")
                    return
                end
            end

            if P.phase == "settle" then
                if P.rebirthLocked then resumeTarget("ребёрты уже остановлены; команда Luck") return end
                if P.hatchUncertain or P.craftUncertain or P.upgradeUncertain or P.skillUncertain then
                    blocked("есть неподтверждённый запрос яйца, крафта или апгрейда")
                    return
                end
                if actionsOutstanding() then return end
                local mode = P.eggFixed and "Luck" or "Clicks"
                if P.probeMode ~= mode then beginSettle("сменилась фаза — начинаю замер заново"); return end
                local opt = Ui.Options and Ui.Options.EquipMode
                if not opt or opt.Value ~= mode then
                    local ok, set = pcall(setMode, mode)
                    if not ok or not set then blocked("режим команды " .. mode .. " недоступен"); return end
                    P.phaseAt, P.modeReadySince, P.settleTeam = P.activeClock, nil, nil
                    return
                end
                if not modeRequestSeen(mode) then
                    P.modeReadySince, P.settleTeam = nil, nil
                    P.note = "жду отправку команды " .. mode .. " перед замером"
                    return
                end
                if mode == "Luck" then
                    local sig = teamSignature(data)
                    if not sig then
                        P.modeReadySince, P.settleTeam = nil, nil
                        P.note = "жду полную реплику команды после запроса Luck для проверки 900 млн/с"
                        return
                    end
                    if P.settleTeam ~= sig then
                        P.settleTeam, P.modeReadySince = sig, P.activeClock
                        P.note = "жду стабильную команду после запроса Luck"
                        return
                    end
                end
                P.modeReadySince = P.modeReadySince or P.activeClock
                if P.activeClock - P.modeReadySince < START_SETTLE then return end
                P.sampleCoins, P.sampleAt, P.goodWindows = coins, P.activeClock, 0
                P.sampleTeam = mode == "Luck" and P.settleTeam or nil
                phase("measure", "измеряю доход " .. mode .. " без расходов, яиц и ребёртов")
                return
            end
            if P.phase == "measure" then
                if P.rebirthLocked then resumeTarget("ребёрты уже остановлены; команда Luck") return end
                local mode = P.eggFixed and "Luck" or "Clicks"
                local opt = Ui.Options and Ui.Options.EquipMode
                if P.probeMode ~= mode or not opt or opt.Value ~= mode or not modeRequestSeen(mode)
                    or actionsOutstanding() then
                    beginSettle("условия замера изменились — начинаю заново")
                    return
                end
                if mode == "Luck" and (not P.sampleTeam or teamSignature(data) ~= P.sampleTeam) then
                    beginSettle("состав команды изменился или реплика неполная — Luck-замер начинаю заново")
                    return
                end
                if not P.sampleAt or P.sampleCoins == nil then
                    P.sampleCoins, P.sampleAt, P.goodWindows = coins, P.activeClock, 0
                    return
                end
                local seconds = P.activeClock - P.sampleAt
                if seconds < WINDOW then return end
                local change = coins - P.sampleCoins
                local precision = math.max(coins, P.sampleCoins) * 1e-15 / seconds
                local rate = change / seconds
                P.sampleCoins, P.sampleAt = coins, P.activeClock
                if change < -precision * seconds then
                    blocked("во время замера баланс уменьшился: возможно, другой скрипт расходует монеты")
                    return
                end
                P.income = math.max(0, rate - precision)
                rememberIncome(mode, P.income, "без ребёртов и расходов")
                local threshold = mode == "Luck" and STOP_REBIRTH_INCOME or REQUIRED_INCOME
                -- Both decisions use income per second, not the wallet or the batch price.
                local boundaryTolerance = math.max(precision, threshold * 1e-9)
                if rate + boundaryTolerance >= threshold and precision < threshold * 0.05 then
                    P.goodWindows += 1
                    P.note = string.format("%s: доход подтверждается %d/%d окон", mode, P.goodWindows, REQUIRED_WINDOWS)
                    if P.goodWindows >= REQUIRED_WINDOWS then
                        if mode == "Luck" then
                            if not lockRebirth(rebirths) then return end
                        else
                            if not fixEgg30(rebirths) then return end
                        end
                    end
                elseif precision >= threshold * 0.05 then
                    blocked("баланс слишком велик для точного замера прироста числом клиента")
                elseif mode == "Luck" then
                    P.targetProbeRequired = false
                    P.targetNextProbeAt = P.activeClock + CLEAN_PROBE_PERIOD
                    P.goodWindows = 0
                    resumeTarget(string.format("Luck %.0f/с ниже 900 млн/с; продолжаю 30M и ребёрты", P.income))
                else
                    beginUpgradeWindow("доход Clicks ниже 300 млн/с; продолжаю прокачку")
                end
                return
            end
            if P.phase == "rebirth" or P.phase == "target_rebirth" then
                local inTarget = P.phase == "target_rebirth"
                if inTarget and (not P.eggFixed or P.rebirthLocked) then
                    blocked("ошибка стадии ребёрта после перехода на 30M")
                    return
                end
                if not inTarget then
                if P.farmStorageFull then
                    local pets = type(data.Pets) == "table" and data.Pets or nil
                    local owned = pets and type(pets.Owned) == "table" and pets.Owned or nil
                    local limit = pets and number(pets.StorageLimit) or nil
                    if owned and limit then
                        local n = 0
                        for _ in pairs(owned) do n += 1 end
                        if limit - n >= math.min(limit, P.storageNeeded or 1) then
                            P.farmStorageFull, P.storageNeeded = false, nil
                            log("в рюкзаке появились места: яйца на прокачке возобновлены")
                        end
                    end
                end
                if P.farmThresholdReached then
                    P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                    P.holdUpgrades, P.holdSkillTree = true, true
                    if P.upgradeInFlight or P.skillInFlight or P.clickerRefreshPending or P.cleaning
                        or P.craftBusy or P.craftInFlight or Ui.hatchInFlight or Ui.hatchMoving
                        or Ui.travelling or P.locating then return end
                    -- Положительные дельты между быстрыми сбросами могут быть искажены.
                    -- Постоянный запрет ставим только после трёх прямых окон без ребёртов
                    -- в фазах settle/measure; при недостаточном доходе прокачка возобновится.
                    beginSettle("проверяю доход Clicks без ребёртов и расходов перед переходом к 30M")
                    return
                end
                -- Hatch spend can conceal every preliminary 10-second window. Periodically
                -- pause spenders for a direct Clicks measurement, without requiring a fixed rebirth count.
                if P.activeClock >= (P.farmNextProbeAt or math.huge) then
                    P.farmThresholdReached = true
                    P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                    P.holdUpgrades, P.holdSkillTree = true, true
                    P.note = "плановая проверка реального дохода без трат"
                    log("плановая проверка дохода Clicks: временно жду завершения яиц, крафта и покупок")
                    return
                end
                end -- farm-only work; target stage never re-enables craft or upgrades
                if P.remoteError then blocked("RebirthRequested не найден: " .. tostring(P.remoteError)); return end
                if not P.remote then return end
                -- Между отправками и при нехватке монет гемовые улучшения могут покупаться.
                if os.clock() < (P.nextSendAt or 0) then
                    if inTarget then
                        resumeTarget("ожидаю конца 20-секундного интервала; 30M остаётся выбранным")
                        return
                    end
                    P.holdHatch, P.holdCraft, P.disableAutoCraft = false, false, false
                    P.holdUpgrades, P.holdSkillTree = false, false
                    if P.activeClock >= (P.nextClickerRefresh or 0) then
                        P.nextClickerRefresh = P.activeClock + CLICKER_REFRESH_SECONDS
                        refreshNativeClicker()
                    end
                    return
                end
                local index, amount, price, why = tap.progressPack(data, math.huge)
                if not index then
                    if inTarget then
                        P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                        P.holdUpgrades, P.holdSkillTree = true, true
                    else
                        P.holdHatch, P.holdCraft, P.disableAutoCraft = false, false, false
                        P.holdUpgrades, P.holdSkillTree = false, false
                    end
                    if why ~= "unaffordable" then blocked("цена ребёрта недоступна: " .. tostring(why)); return end
                    if inTarget then P.note = "жду монеты на минимально доступный ребёрт"; return end
                    if P.activeClock >= (P.nextClickerRefresh or 0) then
                        P.nextClickerRefresh = P.activeClock + CLICKER_REFRESH_SECONDS
                        refreshNativeClicker()
                    end
                    return
                end
                -- Как только ребёрт доступен, перестаём запускать покупки и дожидаемся только
                -- уже отправленных запросов; 6/30-секундных окон перед ребёртом больше нет.
                P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                P.holdUpgrades, P.holdSkillTree = true, true
                -- Включение штатного автокликера не покупка и не меняет цену пакета;
                -- долгий поиск его remote не должен задерживать доступный ребёрт.
                if P.upgradeInFlight or P.skillInFlight or not canRebirth() then return end
                local autoFlag = tap.hasAutoRebirth(data)
                local _, currentRebirths, currentCoins = readValues()
                if not canRebirth() or currentRebirths ~= rebirths or not currentCoins or currentCoins < price then return end
                if rebirths > MAX_SAFE_INTEGER then blocked("счётчик ребёртов слишком велик для точного подтверждения"); return end
                local prepared = { before = rebirths, coins = currentCoins, sentAt = P.activeClock,
                    index = index, amount = amount, price = price }
                P.pending = prepared
                -- До FireServer сохраняем ожидание на диск: после перезапуска не повторяем неизвестный запрос.
                local persisted, persistErr = writePending(rebirths)
                if not persisted then
                    P.pending = nil -- запрос ещё не отправлялся
                    blocked("не удалось сохранить запрос ребёрта: " .. tostring(persistErr))
                    return
                end
                -- Запись могла уступить поток: Stop, цена и максимальный доступный пакет проверяются снова.
                local fresh, freshRb, freshCoins = readValues()
                local i2, a2, p2 = tap.progressPack(fresh, math.huge)
                local _, lastRb, lastCoins = readValues()
                if not canRebirth(prepared) or freshRb ~= rebirths or lastRb ~= rebirths
                    or i2 ~= index or a2 ~= amount or p2 ~= price
                    or not freshCoins or not lastCoins or lastCoins < price then
                    local cleared, clearErr = clearPending() -- точно знаем, что запрос НЕ отправлен
                    if cleared then P.pending = nil else uncertain("не удалось отменить подготовленный запрос: " .. tostring(clearErr)) end
                    return
                end
                local payload = autoFlag and { Auto = true, Index = index } or { Index = index }
                local attempted = false
                local ok, err = pcall(function()
                    -- Elevation, replica reads and price calculation can all yield. Re-check the
                    -- actual stage, cooldown, exact maximum affordable pack and count AFTER them.
                    Env.elevate()
                    local data3, rb3 = readValues()
                    local i3, a3, p3 = tap.progressPack(data3, math.huge)
                    local _, rb4, coins4 = readValues()
                    if not canRebirth(prepared) or rb3 ~= rebirths or rb4 ~= rebirths
                        or i3 ~= index or a3 ~= amount or p3 ~= price or not coins4 or coins4 < price then
                        return
                    end
                    prepared.coins = coins4
                    prepared.sentAt = P.activeClock + math.max(0, os.clock() - (P.lastTick or os.clock()))
                    -- A transport failure after this point cannot prove the request was unsent.
                    local sentAt = os.clock()
                    P.nextSendAt = sentAt + REBIRTH_GAP
                    lastSends[userKey] = sentAt
                    attempted = true
                    P.remote:FireServer(payload)
                end)
                if not attempted then
                    -- The request was definitely not invoked; erase only that prepared marker.
                    local cleared, clearErr = clearPending()
                    if cleared then P.pending = nil
                    else uncertain("не удалось отменить неподтверждённую подготовку: " .. tostring(clearErr)); return end
                    if not ok then blocked("ошибка перед отправкой ребёрта: " .. tostring(err)) end
                elseif not ok then
                    uncertain("ошибка отправки ребёрта: " .. tostring(err))
                end
                return
            end
            if P.phase == "storage_wait" then
                P.holdUpgrades, P.holdSkillTree = true, true -- ждем места без новых покупок
                local pets = type(data.Pets) == "table" and data.Pets or nil
                local owned = pets and type(pets.Owned) == "table" and pets.Owned or nil
                local limit = pets and number(pets.StorageLimit) or nil
                if owned and limit then
                    local count = 0
                    for _ in pairs(owned) do count += 1 end
                    if limit - count >= (P.storageNeeded or 3) then
                        P.storageNeeded = nil
                        resumeTarget("в рюкзаке появились места; продолжаю 30M x3")
                    end
                end
                return
            end
            if P.phase == "locked_wait" then
                resumeTarget("ожидаю 30M x3; прокачка после сохранённого lock не возобновляется")
                return
            end
            if P.phase == "save" then
                if not P.eggFixed then blocked("не закреплён выбор 30M в фазе накопления"); return end
                P.holdCraft, P.disableAutoCraft = true, true
                P.holdUpgrades, P.holdSkillTree = true, true
                local opt = Ui.Options and Ui.Options.EquipMode
                if not opt or opt.Value ~= "Luck" then
                    local ok, selected = pcall(setMode, "Luck")
                    if not ok or not selected then blocked("режим команды Luck недоступен"); return end
                    return
                end
                if not modeRequestSeen("Luck") then
                    P.note = "жду запрос команды Luck"
                    return
                end
                if targetState ~= "ready" or P.locating or Ui.travelling or P.cleaning
                    or P.craftBusy or P.craftInFlight or Ui.hatchInFlight then return end
                if coins < BATCH_PRICE then
                    P.holdHatch = true
                    P.note = "жду 900 млн на одну тройку: " .. tostring(math.floor(coins)) .. " / " .. tostring(BATCH_PRICE)
                    return
                end
                P.holdHatch = false
                phase("hatch", "только 30M x3; доступен весь баланс")
                P.hatchSampleCoins, P.hatchSampleAt = coins, P.activeClock
                P.hatchSampleBatches = P.confirmedBatches or 0
                log("30M x3: открываю на доступный баланс; дополнительный резерв не требуется")
                return
            end
            if P.phase == "hatch" then
                if not P.eggFixed then blocked("ошибка фиксации 30M в фазе яиц"); return end
                P.holdCraft, P.disableAutoCraft = true, true
                P.holdUpgrades, P.holdSkillTree = true, true
                local opt = Ui.Options and Ui.Options.EquipMode
                if not opt or opt.Value ~= "Luck" or not modeRequestSeen("Luck") then
                    resumeTarget("восстанавливаю команду Luck; крафт и покупки запрещены")
                    return
                end
                if coins < BATCH_PRICE and not Ui.hatchInFlight then
                    P.holdHatch = true
                    phase("save", "жду заработка на следующую тройку 30M")
                    return
                end
                local dt = P.activeClock - (P.hatchSampleAt or P.activeClock)
                if dt >= HATCH_OBSERVE_WINDOW and not Ui.hatchInFlight then
                    local count = (P.confirmedBatches or 0) - (P.hatchSampleBatches or 0)
                    if count > 0 and P.hatchSampleCoins ~= nil then
                        P.income = math.max(0, (coins - P.hatchSampleCoins + count * BATCH_PRICE) / dt)
                        rememberIncome("Luck", P.income, "приблизительно во время открытия")
                    end
                    P.hatchSampleCoins, P.hatchSampleAt = coins, P.activeClock
                    P.hatchSampleBatches = P.confirmedBatches or 0
                end
                return
            end
        end

        local function guardedStep()
            local ok, err = pcall(step)
            if ok then return end
            if P.pending then
                uncertain("ошибка при ожидающем ребёрте: " .. tostring(err))
            else
                P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true
                P.holdUpgrades, P.holdSkillTree = true, true
                phase("blocked", "ошибка контроллера: " .. tostring(err))
                log(P.note .. "; яйца и ребёрты не запускаю")
            end
        end

        genv.ts30TestState = function()
            local _, rb, coins = readValues()
            status(rb, coins)
            return P.phase
        end
        genv.ts30TestStop = function()
            P.stopRequested = true
            P.holdTap, P.holdHatch, P.holdCraft, P.disableAutoCraft = true, true, true, true
            Ui.stopAll()
            stopNativeClicker()
            print("[TAPSIM] 30M TEST | остановлено; уже отправленный запрос отменить нельзя")
        end
        Life.onCleanup(function()
            genv.ts30TestState = nil
            genv.ts30TestStop = nil
        end)
        log("v13: до 300 млн/с Clicks, яйца до 20% текущих монет, уровень цены не понижается, крафт только 100%")
        log("ребёрт: максимальный доступный пакет не чаще одного запроса за 20 с; покупки только за гемы")
        log("300 млн монет/с по Clicks: только 30M x3 за 900 млн, Luck, без крафта и покупок; ребёрты продолжаются")
        log("проверка 900 млн монет/с: после запроса Luck, со стабильной командой, три чистых окна без трат и ребёртов")
        log("до 900 млн/с при наступлении ребёрта временно коплю на минимально доступный пакет; выбираю максимальный доступный")
        log("после подтверждения 900 млн/с новые ребёрты выключены; 30M x3 на весь баланс, Luck и чистка остаются")
        log("старый маркер 30M не доказывает 900 млн/с; при обновлении сначала проверяю доход Luck")
        log("во время прокачки пытаюсь открыть следующий остров по игровому конфигу; после 300 млн/с новые острова не покупаю")
        log("исходная чистка: не-секреты вне команды, включая Godly; с них может сниматься лок")
        log("рыбалка, приманки, зелья, зачарования и трейды не запускаются; старое игровое автоудаление может сохраняться")
        log("при неожиданном изменении счётчика во время прокачки повторно сверяю данные и возобновляю работу")
        if not hatchApiReady then log("модуль яйца не загрузился: прокачка продолжится без яиц, для 30M будет ожидание") end
        if type(features["features/craft"]) ~= "table" then
            log("модуль крафта не загрузился: прокачка продолжится без крафта")
        end
        if type(features["features/craft_continue"]) ~= "table" then
            log("обработчик Continue для окна крафта не загрузился")
        else
            log("окно крафта: повтор Continue через 2 с, если та же карточка видна; затем другие способы с проверкой окна")
        end
        if type(features["features/island_progress"]) ~= "table" then
            log("модуль островов не загрузился: прокачка продолжится, автоматическая покупка островов недоступна")
        end
        Life.loop("progress:test", 0.1, guardedStep)
        return P
    end
    return { start = start }
end
-- ===== патч: панель + логи в консоль и на сервер + разгрузка + вебхук =====
-- ============================================================================
-- TAPSIM OPEN · панель в старом дизайне (только статистика) + вебхук на петов
-- ============================================================================
local Hub = use("main")
do
	local Env = use("core/env")
