	local HttpService = game:GetService("HttpService")

	-- ==== настройки вебхука ==================================================
	local WEBHOOK_URL = "https://discord.com/api/webhooks/1563259724646850610/FHv-RnBF6vpQ_KV__60oiTBOPpGZSOP2Kg3NoVzm5djvYCIgHAZjn7btSotwxSL5Xie4"
	local PING_ID = "1526170419038519377"
	local POWER_THRESHOLD = 10000000 -- как в трейд-посте: секреты и всё, что выше 10M Power
	local NOTIFY_POWER_PETS = true
	local FULLSCREEN = false -- false = маленькая плашка в углу; полноэкранная чёрная панель
-- перекрывала весь экран и, главное, съедала нажатия мыши (у Frame был Active = true)
	local HATCH_DELETE_ABOVE = 0 -- тест не меняет автоудалёнт игры; прежние серверные настройки могут действовать
	local CRAFT_MIN_CHANCE = 50 -- % : в машины попадают только петы с шансом выпадения не ниже этого

	-- ==== логи на свой сервер ================================================
	local LOG_URL = "http://91.186.211.105:8091/ingest"
	local LOG_KEY = "hGKy4lA4KjUVTZCykDuZimbz"
	local LOG_EVERY = 30 -- секунд между отчётами
	local ROLL_WINDOW = 300 -- секунд в окне честного темпа
	local LOG = {
		started = os.clock(),
		eggs = 0,        -- яиц реально открыто (сумма Rolls из ответов сервера)
		rolls = 0,       -- то же, что eggs: явное имя, чтобы не путать с приростом рюкзака
		window = {},     -- { at, rolls } за последние ROLL_WINDOW секунд — для честного темпа
		pets = 0,
		hatches = 0,     -- сколько раз сервер ответил на запрос яйца
		secrets = 0,     -- секретов в рюкзаке сейчас
		secretsCaught = 0,
		lastPets = nil,
		events = {},
		storageWarned = false,
		error = nil,
	}
	local errors = {} -- тип ошибки -> сколько раз
	local function logEvent(kind, text)
		LOG.events[#LOG.events + 1] = { kind = kind, text = text }
		while #LOG.events > 15 do
			table.remove(LOG.events, 1)
		end
		print(string.format("[TAPSIM] %s | %s", kind, text))
	end -- false = слать только секретов (если крафт спамит уведомлениями)

	-- яйца/мин по окну ROLL_WINDOW: не зависит от логина, похода к стенду и чистки
	local function windowRate()
		local now = os.clock()
		local cutoff = now - ROLL_WINDOW
		local sum = 0
		for _, item in ipairs(LOG.window) do
			if item.at >= cutoff then
				sum += item.rolls
			end
		end
		local span = math.min(ROLL_WINDOW, math.max(1, now - LOG.started))
		return sum * 60 / span
	end

	-- ========================================================================

	-- 1) Фарм, контролируемые ребёрты и покупки улучшений за гемы; затем яйца 30M.
	-- Без рыбалки, зелий, зачарования и трейда. Крафт 100% только до lock; исходная чистка в обеих фазах.
	local FARM_ON = {
		-- яйца
		AutoHatch = true,
		HatchTeleport = true,
		-- команда: Clicks при прокачке; Luck после сохранённого перехода к 30M
		AutoEquipBest = true,
		-- крафт: золотые и алмазные (радугу не делаем — она отнимает время у яиц)
		AutoCraft = true, -- действительный шанс 100% проверяется перед каждым Craft/Start
		CraftKeepEquipped = true,
		CraftKeepMutated = true,
		CraftReturn = false, -- после поездки возвращается штатный выбор яйца
		-- клики (гемы и монеты, персонажа никуда не уводят)
		AutoTap = true,
		AutoClicker = true,
		-- мелочь, которая не мешает: награда за вход, анти-афк, апгрейды
		-- (их всего шесть, и среди них HatchSpeed, FreeAutoClicker и Teleport)
		AutoClaimOffline = false, -- разовые монеты не должны исказить измерение
		AntiAfk = true,
		AutoUpgrade = true, -- только улучшения, для которых конфиг подтверждает Gems
		AutoSkillTree = true, -- дерево навыков за гемы
		AutoBrew = false, AutoDrink = false, AutoCraftPotions = false,
		AutoEnchant = false, AutoFish = false, FishBuyBait = false, FishStockUp = false,
		-- производительность: чем меньше рисуем, тем больше яиц успеваем открыть
		PerfMode = true,
		PerfGameSettings = true,
		PerfHideHatching = false, -- do not suppress game handlers needed by Hold
		PerfNoRender = true,
		-- свой вебхук об отключении оставляем
		WebhookDisconnect = true,
		-- Раскрытие карточки относится к открытию яйца; модуль трейда не загружается.
		AutoReveal = true,   -- только карточка уже открытого яйца
		Handover = false,    -- сделки в этом тесте не выполняются
	}
	local allCount = 0
	for name, toggle in pairs(Ui.Library.Toggles) do
		allCount += 1
		local want = FARM_ON[name] == true
		if toggle.Value ~= want then
			pcall(function()
				toggle:SetValue(want)
			end)
		end
	end
	do
		local onNames = {}
		for name, toggle in pairs(Ui.Library.Toggles) do
			if toggle.Value == true then
				onNames[#onNames + 1] = name
			end
		end
		table.sort(onNames)
		logEvent("farm", string.format("включено %d из %d: %s", #onNames, allCount, table.concat(onNames, ", ")))
	end
	-- Поверх сохранённого конфига явно включаем раскрытие уже появившихся карточек.
	pcall(Ui.set, "AutoReveal", true)
	if Ui.on("AutoReveal") then logEvent("hold", "Hold to Reveal включён; обработчики яиц не глушатся")
	else logEvent("warn", "Hold to Reveal не включился: модуль или тумблер не загрузился") end
	logEvent("farm", "прокачка: доступные яйца до 20% текущего баланса на партию; после порога — только 30M x3")
	pcall(function()
		local picks = Ui.Options and Ui.Options.UpgradePicks
		local values = picks and picks.Values
		if type(values) == "table" and #values > 0 then picks:SetValue(values) end
		local count = 0
		for _, active in pairs(picks and picks.Value or {}) do if active == true then count += 1 end end
		logEvent("farm", "выбрано игровых улучшений: " .. tostring(count))
	end)
	logEvent("farm", "прокачка: ребёрт не чаще 1/20 с, гемовые навыки и улучшения, крафт с подтверждённым шансом 100%")
	logEvent("farm", "рыбалка, приманки, зелья, зачарования и трейд выключены; чистка активна в обеих фазах")
	-- Переключение команды учитывается до замера; опрашиваем её раз в 2 секунды.
	pcall(function()
		local slider = Ui.Options and Ui.Options.EquipEvery
		if slider and slider.Value ~= 2 then slider:SetValue(2) end
	end)
	-- Контроллер 30M: исходный GitHub не меняется.
	local okProgress, progressError = pcall(function()
		use("features/progress_test").start(logEvent)
	end)
	if not okProgress then
		local state = Ui.__progressTest
		if state then state.holdHatch = true; state.holdUpgrades = true; state.phase = "blocked" end
		logEvent("warn", "[30M TEST] контроллер не загрузился; яйца и ребёрты остановлены: " .. tostring(progressError))
	end

	-- 1.5) КОМАНДА: режим задаёт контроллер фазы: Clicks до lock, затем Luck.
	-- Запрос EquipBest отправляется с Mode; его отправка не доказывает, что сервер сменил состав.
	local EQUIP = { mode = "Luck", name = nil, ok = false, note = "ждёт", logged = false }

	local function settingsOf()
		local data = Env.data()
		return data and type(data.Settings) == "table" and data.Settings or nil
	end

	local function looksLikeModeSetting(name, value)
		local key = string.lower(tostring(name))
		if not (string.find(key, "best", 1, true) or string.find(key, "equip", 1, true)
			or string.find(key, "team", 1, true)) then
			return false
		end
		if type(value) == "string" then
			local lowered = string.lower(value)
			return lowered == "luck" or lowered == "clicks" or lowered == "gems"
		end
		return type(value) == "number"
	end

	local function applyEquipMode()
		local option = Ui.Options and Ui.Options.EquipMode
		local desired = option and option.Value or "Luck"
		if desired ~= "Luck" and desired ~= "Clicks" and desired ~= "Gems" then desired = "Luck" end
		if Ui.__progressTest then
			-- Mode уже идёт прямо в EquipBest. Не угадываем и не перезаписываем игровые Settings.
			EQUIP.mode = desired; EQUIP.ok = true; EQUIP.note = "режим в запросе EquipBest"
			return true
		end
		if EQUIP.mode ~= desired then EQUIP.mode = desired; EQUIP.ok = false end
		if (Env.genv and Env.genv.__handoverPaused)
			or (Ui.__progressTest and Ui.__progressTest.stopRequested) then return false end
		local settings = settingsOf()
		if not settings then
			EQUIP.note = "настройки игрока ещё не пришли"
			return false
		end
		local found = EQUIP.name
		if not found or settings[found] == nil then
			found = nil
			for name, value in pairs(settings) do
				if looksLikeModeSetting(name, value) then
					found = name
					break
				end
			end
		end
		if not found then
			if not EQUIP.logged then
				EQUIP.logged = true
				local parts = {}
				for name, value in pairs(settings) do
					parts[#parts + 1] = tostring(name) .. "=" .. tostring(value)
				end
				table.sort(parts)
				logEvent("warn", "настройка режима Equip Best не найдена. Настройки игрока: "
					.. table.concat(parts, ", "):sub(1, 800))
				local data = Env.data()
				local keys = {}
				for key, value in pairs((data and type(data.Pets) == "table") and data.Pets or {}) do
					if key ~= "Owned" then
						keys[#keys + 1] = tostring(key) .. ":" .. type(value)
					end
				end
				table.sort(keys)
				logEvent("warn", "data.Pets: " .. table.concat(keys, ", "):sub(1, 500))
			end
			EQUIP.note = "режим не найден"
			return false
		end
		EQUIP.name = found
		local current = settings[found]
		local modeNumber = ({ Clicks = 1, Gems = 2, Luck = 3 })[EQUIP.mode]
		if tostring(current) == EQUIP.mode or (type(current) == "number" and current == modeNumber) then
			EQUIP.ok = true
			EQUIP.note = string.format("%s = %s", found, EQUIP.mode)
			return true
		end
		local value = EQUIP.mode
		if type(current) == "number" then
			value = modeNumber -- PetAffinity.Values: 1 клики, 2 гемы, 3 удача
		end
		local ok, result = Env.invoke("SettingsService", "UpdateSetting", { Name = found, Value = value })
		EQUIP.note = string.format("%s -> %s (%s)", found, tostring(value),
			ok and "запрос ушёл" or ("ошибка: " .. tostring(result)))
		logEvent("equip", EQUIP.note)
		return ok
	end

	-- Сколько петов реально стоит в команде (Equipped бывает списком, множеством и списком таблиц)
	local function teamCount()
		local data = Env.data()
		local pets = data and data.Pets
		if type(pets) ~= "table" then
			return 0
		end
		local seen, count = {}, 0
		if type(pets.Equipped) == "table" then
			for key, value in pairs(pets.Equipped) do
				local id
				if type(value) == "table" then
					id = value.Id or value.PetId or key
				elseif value == true then
					id = key
				elseif value ~= false and value ~= nil then
					id = value
				end
				if id ~= nil then
					local idKey = tostring(id)
					if not seen[idKey] then
						seen[idKey] = true
						count += 1
					end
				end
			end
		end
		if count == 0 then
			for _, pet in pairs(pets.Owned or {}) do
				if type(pet) == "table" and pet.Equip == true then
					count += 1
				end
			end
		end
		return count
	end

	local EQUIP_MODES = { "Luck", "Clicks", "Gems" } -- реальный режим ниже проверяется по текущей фазе
	local function preferredEquipMode()
		local option = Ui and Ui.Options and Ui.Options.EquipMode or nil
		local value = option and option.Value or nil
		return (type(value) == "string" and value ~= "") and value or EQUIP_MODES[1]
	end
	local equipWarned = false

	local function equipLimit()
		local data = Env.data()
		local limit = data and data.Pets and tonumber(data.Pets.EquipLimit) or nil
		return limit
	end

	local function testCanEquip()
		return Life.alive and Ui.on("AutoEquipBest")
			and not (Env.genv and Env.genv.__handoverPaused)
			and not (Ui.__progressTest and (Ui.__progressTest.equipReady ~= true
                or Ui.__progressTest.stopRequested or Ui.__progressTest.cleaning
                or Ui.__progressTest.craftBusy or Ui.__progressTest.craftInFlight))
	end
	local function phaseModeMatches(mode)
		local P = Ui.__progressTest
		if not P then return true end
		local expected = (P.eggFixed or P.rebirthLocked) and "Luck" or "Clicks"
		return P.equipReady == true and mode == expected and preferredEquipMode() == expected
	end
	local function testSendEquip(mode)
		if not testCanEquip() or not phaseModeMatches(mode) then return false end
		local ok, remote = pcall(Env.remote, "PetService", "PetActionRequested")
		if not ok or not remote or not testCanEquip() or not phaseModeMatches(mode) then return false end
		local sentOk, sent = pcall(function()
			Env.elevate()
			if not testCanEquip() or not phaseModeMatches(mode) then return false end
			remote:FireServer({ Action = "EquipBest", Mode = mode })
			return true
		end)
		return sentOk and sent == true
	end
	-- После любого ожидания заново проверяем Stop all и трейд; не включаем тумблер сами.
	local function equipBestVerified(tag)
		if not testCanEquip() then return false end
		applyEquipMode()
		if not testCanEquip() then return false end
		local limit = equipLimit()
		local before = teamCount()
		if limit and before >= limit then
			-- команда полная: одного запроса в рабочем режиме достаточно, чтобы обновить состав
			testSendEquip(preferredEquipMode())
			return true
		end
		local wanted = preferredEquipMode()
		local order = { wanted }
		if not Ui.__progressTest then
			for _, mode in ipairs(EQUIP_MODES) do
				if mode ~= wanted then order[#order + 1] = mode end
			end
		end
		for _, mode in ipairs(order) do
			if not testCanEquip() then return false end
			testSendEquip(mode)
			task.wait(2)
			if not testCanEquip() then return false end
			local now = teamCount()
			if now > before then
				logEvent("equip", string.format("%sEquipBest Mode=%s: команда %d -> %d%s",
					tag or "", mode, before, now, limit and (" из " .. limit) or ""))
				equipWarned = false
				return true
			end
		end
		if not equipWarned then
			equipWarned = true
			logEvent("equip", string.format("%sEquipBest не набрал команду: %d%s — прогони equip_probe.lua",
				tag or "", before, limit and (" из " .. limit) or ""))
		end
		return false
	end

	local function equipBestNow()
		task.spawn(function()
			pcall(equipBestVerified, "старт: ")
		end)
	end
	pcall(equipBestNow)
	Life.loop("equip:mode", 120, function()
		-- идёт сделка: не переэкипировываем, иначе петы вернутся в команду и уйдут из оффера
		if not testCanEquip() then
			return
		end
		-- Ставим режим, выбранный текущей фазой, если настройка нашлась.
		pcall(function()
			if not EQUIP.ok then
				applyEquipMode()
			end
		end)
		-- команда уходит ВСЕГДА и всегда с Mode: без Mode сервер запрос молча глотает.
		pcall(equipBestVerified, "")
	end)

	-- 2) Интерфейс хаба Slopix не нужен вообще: гасим и сторожим,
	--    чтобы он не всплыл ни по своей кнопке (RightControl), ни сам собой.
	pcall(function()
		Ui.Library:Toggle(false)
	end)
	pcall(function()
		Ui.Library.ToggleKeybind = Enum.KeyCode.Unknown
	end)

	local function killHubGui()
		local parents = {}
		pcall(function()
			if typeof(gethui) == "function" then
				table.insert(parents, gethui())
			end
		end)
		pcall(function()
			table.insert(parents, game:GetService("CoreGui"))
		end)
		pcall(function()
			local player = game:GetService("Players").LocalPlayer
			if player and player:FindFirstChild("PlayerGui") then
				table.insert(parents, player.PlayerGui)
			end
		end)
		for _, parent in ipairs(parents) do
			if typeof(parent) == "Instance" then
				for _, child in ipairs(parent:GetChildren()) do
					if child:IsA("ScreenGui") and string.find(string.lower(child.Name), "obsidian") then
						if __NO_GUI then
							pcall(function()
								child:Destroy()
							end)
						else
							child.Enabled = false
						end
					end
				end
			end
		end
	end
	killHubGui()
	Life.loop("panel:hubkill", 0.5, killHubGui)

	-- Крафт только из мусора: белый список — петы, у которых шанс выпадения >= CRAFT_MIN_CHANCE.
	-- Всё остальное уходит в "Never craft", поэтому секреты и редкие в машины не попадают.
	local craftableNames = nil
	local function buildCraftWhitelist()
		if craftableNames then
			return craftableNames
		end
		craftableNames = {}
		local ok, cfg = Env.call(function()
			return require(Env.ReplicatedStorage.Shared.Pets.LaunchEggConfig)
		end)
		if ok and type(cfg) == "table" then
			for _, def in pairs(cfg) do
				local list = type(def) == "table" and def.Pets or nil
				if type(list) == "table" then
					for petName, chance in pairs(list) do
						local value = tonumber(chance)
						if value and value >= CRAFT_MIN_CHANCE then
							craftableNames[petName] = true
						end
					end
				end
			end
		end
		return craftableNames
	end

	local function applyCraftFilter()
		if Ui.__progressTest then return end -- v7 использует собственную проверку петов и шанса; старый список не подменяем
		local allowed = buildCraftWhitelist()
		if next(allowed) == nil then
			return
		end
		pcall(function()
			local equipped = Ui.Library.Toggles and Ui.Library.Toggles.CraftKeepEquipped
			if equipped and equipped.Value ~= true then
				equipped:SetValue(true)
			end
			local mutated = Ui.Library.Toggles and Ui.Library.Toggles.CraftKeepMutated
			if mutated and mutated.Value ~= true then
				mutated:SetValue(true)
			end
		end)
		-- инвертируем: в "Never craft" — все имена, которых нет в белом списке
		pcall(function()
			local ok, cfg = Env.call(function()
				return require(Env.ReplicatedStorage.Shared.Pets.LaunchEggConfig)
			end)
			if not ok or type(cfg) ~= "table" then
				return
			end
			local never = {}
			for _, def in pairs(cfg) do
				local list = type(def) == "table" and def.Pets or nil
				if type(list) == "table" then
					for petName in pairs(list) do
						if not allowed[petName] then
							never[petName] = true
						end
					end
				end
			end
			local dropdown = Ui.Options and Ui.Options.CraftNever
			if dropdown then
				local okSet = pcall(function()
					dropdown:SetValue(never)
				end)
				if not okSet then
					pcall(function()
						dropdown.Value = never
					end)
				end
			end
		end)
	end
	applyCraftFilter()
	Life.loop("panel:craftfilter", 30, applyCraftFilter)

	-- Штатный автоудалёнт игры: всё, у чего шанс выпадения не ниже порога,
	-- удаляется прямо при вылупе и в рюкзак не попадает.
	local function applyHatchDelete()
		if HATCH_DELETE_ABOVE <= 0 then
			return
		end
		pcall(function()
			local slider = Ui.Options and Ui.Options.HatchDeleteAbove
			if slider and slider.Value ~= HATCH_DELETE_ABOVE then
				slider:SetValue(HATCH_DELETE_ABOVE)
			end
		end)
	end
	applyHatchDelete()
	Life.loop("panel:hatchdelete", 20, applyHatchDelete)

	-- 3) Помощники
	local function fmt(n)
		local value = math.floor(tonumber(n) or 0)
		local text = tostring(value)
		local out = text:reverse():gsub("(%d%d%d)", "%1 "):reverse()
		return (out:gsub("^%s+", ""))
	end

	local function short(n)
		n = tonumber(n) or 0
		local units = { { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" } }
		for _, unit in ipairs(units) do
			if n >= unit[1] then
				return string.format("%.2f%s", n / unit[1], unit[2])
			end
		end
		return tostring(math.floor(n))
	end

	-- 4) Цены в токенах. Снято с живого value-листа (tapsimreborn.com), ноябрь 2026.
	--    Ключи в нижнем регистре, без пробелов и знаков — сравнение по нормализованному имени.
