		["neoncat"] = 7270,
		["sanguineheart"] = 8180,
		-- добавлено 06.11: этих секретов не было в таблице и вебхук писал "цена не найдена".
		-- Значения из справочника SECRET_TOKENS; где живая цена уже была под опечаткой — взята она.
		["darkcat"] = 12000,
		["phantommirror"] = 2380,
