	}

	-- Мутация стоит в начале названия ("Golden 30M Phantom Serpent"), а цены в таблице
	-- на чистого пета. Без этой чистки любой мутированный пет получал "цена не найдена".
	local MUTATION_WORDS = { "Golden", "Diamond", "Rainbow", "Shiny", "Gold", "Mutated" }
	local function normalize(name)
		local text = tostring(name or "")
		for _ = 1, 3 do
			local cut = false
			for _, word in ipairs(MUTATION_WORDS) do
				if string.lower(string.sub(text, 1, #word + 1)) == string.lower(word) .. " " then
					text = string.sub(text, #word + 2)
					cut = true
					break
				end
			end
			if not cut then
				break
			end
		end
		return (text:lower():gsub("[^%w]", ""))
	end

	local function priceOf(petName)
		return PRICES[normalize(petName)]
	end

	local function tokenText(value)
		if value == nil then
			return "цена не найдена"
		end
		if value >= 1000 then
			return string.format("%.2fK", value / 1000)
		end
		return tostring(value)
	end

	-- 5) Вебхук: очередь, чтобы не ловить 429
	local httpRequest = request or http_request or (syn and syn.request) or (http and http.request)
	-- Цены в токенах теперь живые: сервер забирает их с demand.gg и раздаёт здесь.
	-- Своя таблица выше остаётся запасной — если сервер недоступен, работаем по ней.
	local PRICE_SYNC_URL = string.gsub(LOG_URL, "/ingest$", "/api/prices")
	local function syncPrices()
		if type(httpRequest) ~= "function" then
			return false
		end
		local ok, response = pcall(function()
			return httpRequest({ Url = PRICE_SYNC_URL, Method = "GET" })
		end)
		local code = ok and type(response) == "table" and tonumber(response.StatusCode or response.Status or 0) or 0
		if code ~= 200 then
			logEvent("warn", "живые цены недоступны, работаю по встроенной таблице")
			return false
		end
		local okBody, body = pcall(function()
			return HttpService:JSONDecode(response.Body)
		end)
		if not okBody or type(body) ~= "table" or type(body.pets) ~= "table" then
			return false
		end
		local fresh, added, changed = 0, 0, 0
		for name, price in pairs(body.pets) do
			local number = tonumber(price)
			if number then
				fresh += 1
				local key = normalize(name)
				if PRICES[key] == nil then
					added += 1
				elseif PRICES[key] ~= number then
					changed += 1
				end
				PRICES[key] = number
			end
		end
		logEvent("prices", string.format("живые цены с demand.gg: %d петов (новых %d, изменилось %d)",
			fresh, added, changed))
		return true
	end
	pcall(syncPrices)
	Life.loop("prices:sync", 6 * 3600, function()
		pcall(syncPrices)
	end)

	local queue = {}
	local function enqueue(content)
		queue[#queue + 1] = content
		while #queue > 30 do
			table.remove(queue, 1)
		end
	end

	if type(httpRequest) == "function" and WEBHOOK_URL:match("^https://discord") then
		Life.spawn("hook:post", function()
			while Life.alive do
				local content = table.remove(queue, 1)
				if content then
					local body = HttpService:JSONEncode({
						content = content,
						allowed_mentions = { parse = {}, users = { PING_ID } },
					})
					pcall(function()
						httpRequest({
							Url = WEBHOOK_URL,
							Method = "POST",
							Headers = { ["Content-Type"] = "application/json" },
							Body = body,
						})
					end)
					Life.wait(1.3)
				else
					Life.wait(0.5)
				end
			end
		end)
	end

	-- 6) Мониторинг петов: что поймали и сколько это в токенах
	local PetPower = (function()
		local ok, module = Env.call(function()
			local node = Env.ReplicatedStorage
			for _, part in ipairs({ "Shared", "Pets", "PetPower" }) do
				node = node:FindFirstChild(part)
			end
			return node and require(node)
		end)
		return ok and type(module) == "table" and module or nil
	end)()

	local function isSecret(pet)
		return type(pet) == "table" and type(pet.Rarity) == "string"
			and pet.Rarity:lower():find("secret", 1, true) ~= nil
	end

	-- Godly — отдельная редкость выше секретов. В вебхук такие петы не идут вообще
	-- (у них часто 30M power, и раньше они пролезали по порогу POWER_THRESHOLD).
	local function isGodly(pet)
		return type(pet) == "table" and type(pet.Rarity) == "string"
			and pet.Rarity:lower():find("godly", 1, true) ~= nil
	end

	local function powerOf(pet, powers, id)
		if powers then
			local value = tonumber(powers[id])
			if value then
				return value
			end
		end
		return tonumber(type(pet) == "table" and pet.Power) or nil
	end

	local function displayName(pet)
		local parts = {}
		if type(pet.Mutation) == "string" and pet.Mutation ~= "" then
			parts[#parts + 1] = pet.Mutation
		end
		if type(pet.Tier) == "string" and pet.Tier ~= "Normal" then
			parts[#parts + 1] = pet.Tier
		end
		parts[#parts + 1] = tostring(pet.Name)
		return table.concat(parts, " ")
	end

	local seen = {}
	local firstScanDone = false
	local secretsCount = 0

	Life.loop("hook:pets", 2, function()
		local data = Env.data()
		local owned = data and data.Pets and data.Pets.Owned
		if type(owned) ~= "table" then
			return
		end
		local powers
		if PetPower and type(PetPower.GetOwnedPowers) == "function" then
			local ok, result = Env.call(PetPower.GetOwnedPowers, owned)
			if ok and type(result) == "table" then
				powers = result
			end
		end

		local secrets = 0
		local petCount = 0
		for id, pet in pairs(owned) do
			petCount += 1
			local key = tostring(id)
			local secret = isSecret(pet)
			if secret then
				secrets += 1
			end
			if not seen[key] then
				seen[key] = true
				if firstScanDone then
					local power = powerOf(pet, powers, id)
					if not isGodly(pet) and (secret or (NOTIFY_POWER_PETS and power and power > POWER_THRESHOLD)) then
						local name = type(pet) == "table" and tostring(pet.Name or "?") or "?"
						local price = priceOf(name)
						local lines = {
							string.format("<@%s> 🎉 Поймали **%s**", PING_ID, displayName(pet)),
							string.format("токенов: **%s**", tokenText(price)),
						}
						if type(pet.Rarity) == "string" then
							lines[#lines + 1] = "редкость: " .. pet.Rarity
						end
						if power then
							lines[#lines + 1] = "power: " .. short(power)
						end
						local player = Env.LocalPlayer
						lines[#lines + 1] = string.format("аккаунт: %s", player and player.Name or "?")
						enqueue(table.concat(lines, "\n"))
						LOG.secretsCaught += 1
						logEvent("secret", string.format("%s — %s токенов", displayName(pet), tokenText(price)))
					end
				end
			end
		end
		secretsCount = secrets
		LOG.secrets = secrets

		-- каждое новое яйцо = прибавка петов в рюкзаке
		if LOG.lastPets then
			local gained = petCount - LOG.lastPets
			if gained > 0 then
				LOG.pets += gained
			end
		end
		LOG.lastPets = petCount
		firstScanDone = true
	end)

	-- 7) Логи: считаем ответы на яйца и раз в LOG_EVERY секунд шлём отчёт на сервер
	Life.spawn("log:hatch", function()
		local ok, remote = pcall(function()
			return Env.remote("EggService", "EggHatchResult")
		end)
		if ok and remote then
			Life.connect(remote.OnClientEvent, function(payload)
				LOG.hatches += 1
				if type(payload) == "table" then
					-- реальные яйца: сервер сам говорит, сколько вылупилось (Rolls),
					-- независимо от того, что потом съест авто-удаление
					local rolls = tonumber(payload.Rolls)
					if rolls and rolls > 0 then
						LOG.rolls += rolls
						local now = os.clock()
						LOG.window[#LOG.window + 1] = { at = now, rolls = rolls }
						local cutoff = now - ROLL_WINDOW
						while LOG.window[1] and LOG.window[1].at < cutoff do
							table.remove(LOG.window, 1)
						end
					end
					if payload.Egg ~= nil then
						LOG.lastEgg = tostring(payload.Egg)
					end
					if payload.Error then
						local kind = tostring(payload.Error)
						errors[kind] = (errors[kind] or 0) + 1
						LOG.error = kind
						if (errors[kind] % 10) == 1 then
							logEvent("error", string.format("%s (всего %d)", kind, errors[kind]))
						end
					end
				end
			end, "log:hatch:count")
		end
	end)

	-- Что из рюкзака реально стоит денег — списком на сайт. Панель показывает не только
	-- сумму в токенах, но и какие именно петы её дают, поэтому топ уходит в отчёте.
	local BEST_MIN_TOKENS = 20
	local function collectBest(owned)
		local list = {}
		for _, pet in pairs(owned) do
			if type(pet) == "table" then
				local price = priceOf(pet.Name)
				local rarity = string.lower(tostring(pet.Rarity or ""))
				local notable = string.find(rarity, "godly", 1, true) ~= nil
						or string.find(rarity, "secret", 1, true) ~= nil
				if price and (price >= BEST_MIN_TOKENS or notable) then
					list[#list + 1] = {
						name = tostring(pet.Name),
						price = price,
						power = tonumber(pet.Power) or 0,
						rarity = tostring(pet.Rarity or ""),
					}
				end
			end
		end
		table.sort(list, function(a, b)
			if a.price ~= b.price then
				return a.price > b.price
			end
			return a.power > b.power
		end)
		local top = {}
		for index = 1, math.min(#list, 8) do
			top[index] = list[index]
		end
		return top
	end

	if type(httpRequest) == "function" then
		Life.loop("log:push", LOG_EVERY, function()
			local data = Env.data()
			local player = Env.LocalPlayer
			local function currency(name)
				local c = data and type(data.Currencies) == "table" and data.Currencies
				return tonumber(type(c) == "table" and c[name]) or 0
			end
			local owned = data and data.Pets and data.Pets.Owned
			if type(owned) ~= "table" then
				owned = {}
			end
			local value, secretNow, used = 0, 0, 0
			for _, pet in pairs(owned) do
				used += 1
				if isSecret(pet) then
					secretNow += 1
				end
				local price = priceOf(type(pet) == "table" and pet.Name)
				if price then
					value += price
				end
			end
			LOG.secrets = secretNow
			local limit = tonumber(data and data.Pets and data.Pets.StorageLimit)
			if limit and used / limit > 0.95 and not LOG.storageWarned then
				LOG.storageWarned = true
				logEvent("warn", string.format("хранилище %d/%d — нужна чистка", used, limit))
			elseif limit and used / limit < 0.8 then
				LOG.storageWarned = false
			end

			local uptime = math.floor(os.clock() - LOG.started)
			local stats = data and data.Statistics
			local okSend, response = pcall(function()
				return httpRequest({
					Url = LOG_URL,
					Method = "POST",
					Headers = { ["Content-Type"] = "application/json", ["X-Key"] = LOG_KEY },
					Body = HttpService:JSONEncode({
						account = player and player.Name or "?",
						user_id = player and player.UserId or 0,
						place = game.PlaceId,
						status = LOG.error and "error" or "ok",
						error = LOG.error,
						uptime = uptime,
						eggs = LOG.rolls,              -- реальные яйца (сумма Rolls), а не прирост рюкзака
						eggs_rolls = LOG.rolls,
						hatches = LOG.hatches,
						pets = LOG.pets,
						secrets = LOG.secrets,
						tokens_value = value,
						-- pets: сколько уцелело в рюкзаке после авто-удаления (в v14 это поле звалось eggs)
						coins = currency("Coins"),
						gems = currency("Gems"),
						tokens = currency("Tokens") + currency("PaidTokens"),
						rebirths = tonumber(type(stats) == "table" and stats.Rebirths) or 0,
						storage_used = used,
						storage_limit = limit or 0,
						best = collectBest(owned),
						ppm = windowRate(),            -- честный темп: яиц/мин по окну 5 минут
						ppm_avg = uptime > 10 and (LOG.rolls / (uptime / 60)) or 0, -- среднее за сессию
						events = LOG.events,
					}),
				})
			end)
			local code = nil
			if okSend and type(response) == "table" then
				code = response.StatusCode or response.Status or response.status
			end
			if okSend and (code == nil or tonumber(code) == 200) then
				LOG.error = nil
				LOG.events = {}
			else
				LOG.error = okSend and ("сервер ответил " .. tostring(code)) or "нет связи с сервером логов"
			end
		end)
	end

	-- ==== чистка рюкзака запросом (без интерфейса) ============================
	-- Рюкзак полный -> игра перестаёт открывать яйца ("Storage full").
	-- Удаление найдено в самой игре и проверено на живом аккаунте:
	--   PetService.RE.PetActionRequested:FireServer({
	--       PetIds = { "<id>", … }, Action = "Delete", Batch = 1 })
	-- Без Action и Batch сервер молчит (проверено: петы остаются на месте).
	-- Инвентарь не открываем, кнопки не жмём, карточки не ищем: работаем прямо
	-- во время фермы, на ПК и на эмуляторе одинаково.
	--
	-- Кого удаляем: сначала самых слабых по мощи, потом по редкости.
	-- Кого не трогаем: ТОЛЬКО секретов (по полю Rarity) и петов из команды.
	-- Godly тоже удаляем; если годли (или любой не-секрет) залочен — сначала снимаем лок,
	-- иначе сервер удаление не принимает.
	local CLEAN = {
		enabled = true, -- исходная чистка: на прокачке и в фазе 30M
		startAt = 0.90,     -- с какой доли хранилища начинаем чистку
		targetAt = 0.80,    -- до какой доли чистим за один заход
		batch = 50,         -- сколько id в одном запросе
		rounds = 10,        -- сколько запросов подряд максимум за заход
		pause = 2,          -- пауза между запросами, секунд
		deleted = 0,
		note = "ждёт",
		running = false,
		failures = 0,
		warnedLimit = false,
	}

	local function cleanPetData()
		local data = Env.data()
		if not data or type(data.Pets) ~= "table" then
			return nil, nil, 0, 0
		end
		local owned = type(data.Pets.Owned) == "table" and data.Pets.Owned or {}
		local count = 0
		for _ in pairs(owned) do
			count += 1
		end
		return data, owned, count, tonumber(data.Pets.StorageLimit) or 0
	end

	-- секреты берём из справочника яиц: у пета в данных редкость есть, а имя секрета нет
	local secretNames = nil
	local function secretSet()
		if secretNames then
			return secretNames
		end
		secretNames = {}
		local ok, config = Env.call(function()
			return require(Env.ReplicatedStorage.Shared.Pets.LaunchEggConfig)
		end)
		if ok and type(config) == "table" then
			for _, egg in pairs(config) do
				local list = type(egg) == "table" and egg.Secrets or nil
				if type(list) == "table" then
					for name in pairs(list) do
						secretNames[name] = true
					end
				end
			end
		end
		local total = 0
		for _ in pairs(secretNames) do
			total += 1
		end
		logEvent("clean", string.format("справочник секретов: %d имён", total))
		return secretNames
	end

	-- Жёсткая страховка: эти имена не удаляются НИКОГДА, даже если справочник яиц
	-- не загрузится или в нём изменится название. Список секретов на 06.11.2026.
	local HARD_SECRETS = {
		["Dark Cat"] = true,
		["Sanguine Heart"] = true,
		["Neon Cat"] = true,
		["Malevolent Treat"] = true,
		["Hallow Lord"] = true,
		["Nevermore"] = true,
		["King Of Hell"] = true,
		["Phantom Mirror"] = true,
		["Enigma"] = true,
		["Witches Hat"] = true,
		["King Kraken"] = true,
		["30M Candycorn Dragon"] = true,
		["Vanguard"] = true,
		["30M Imperfection"] = true,
		["Orca Dominator"] = true,
		["First Light"] = true,
		["Helfire Spirit"] = true,
		["30M Vampire Coffin"] = true,
		["Crystalline Colossus"] = true,
		["Angelus"] = true,
		["Sand Sovereign"] = true,
		["Party Doggy"] = true,
		["Party Kitty"] = true,
		["Soul Hunter"] = true,
		["Forsaken Knight"] = true,
		["Reanimation"] = true,
		["Arch Angel"] = true,
		["Dragon Tamer"] = true,
		["Eternal Emerald"] = true,
		["King Shroomie"] = true,
		["Shinigami"] = true,
		["Void Overseer"] = true,
		["Anubis"] = true,
		["Inferno Dragon"] = true,
		["Sharkie"] = true,
		["Nameless Diety"] = true,
		["30M Cursed Gift"] = true,
		["Infernal Lord"] = true,
		["Count Batula"] = true,
		["Cinder Eye"] = true,
		["Void Wraith"] = true,
		["Autumn Warden"] = true,
		["Crystal Guardian"] = true,
		["Diamond Piercer"] = true,
		["Flame Fungi"] = true,
		["Oaisis Spirit"] = true,
		["30M Phantom Serpent"] = true,
		["30M Midnight Cat"] = true,
	}

	-- Секрет — ТОЛЬКО по полю Rarity (Secret I / II / III). Имена не смотрим: из-за списков
	-- имён «секретами» считались и обычные петы, чистка говорила «чистить нечего», а рюкзак
	-- стоял полным (StorageFull). Godly секретом не считается — такие петы удаляются.
	local function isSecret(pet)
		if type(pet) ~= "table" then
			return false
		end
		return string.find(string.lower(tostring(pet.Rarity or "")), "secret", 1, true) ~= nil
	end

	-- Годли секретом НЕ считается: такие петы тоже уходят под нож.
	local function isGodly(pet)
		if type(pet) ~= "table" then
			return false
		end
		return string.find(string.lower(tostring(pet.Rarity or "")), "godly", 1, true) ~= nil
	end

	-- nil -> пет уходит под нож, строка -> причина, по которой остаётся.
	-- Правило: остаются ТОЛЬКО секреты (Secret I/II/III) и петы из команды.
	-- Godly удаляем; лок ничего не защищает — с не-секретов он снимается перед удалением.
	-- Кто в команде. У петов в Owned бывает и Id, и только ключ таблицы, а Equipped бывает
	-- массивом id, массивом таблиц {Id=…} и множеством {[id]=true} — читаем все формы.
	local function teamSet(data)
		local ids = {}
		local equipped = type(data) == "table" and data.Pets and data.Pets.Equipped or nil
		if type(equipped) ~= "table" then
			return ids, 0, "нет"
		end
		local count = 0
		for key, value in pairs(equipped) do
			count += 1
			local id
			if type(value) == "table" then
				id = value.Id or value.PetId or value.PetID or key
			elseif value == true then
				id = key          -- {[id] = true}
			elseif value == false or value == nil then
				id = nil
			else
				id = value        -- массив id
			end
			if id ~= nil then
				ids[tostring(id)] = true
			end
		end
		return ids, count, type(equipped)
	end

	-- nil -> пет уходит под нож, строка -> причина, по которой остаётся.
	-- Правило: остаются ТОЛЬКО секреты (Secret I/II/III) и петы из команды.
	-- Godly удаляем; лок ничего не защищает — с не-секретов он снимается перед удалением.
	local function keepReason(pet, aliases, team)
		if type(pet) ~= "table" or type(pet.Rarity) ~= "string" or pet.Rarity == "" then
			return "нет записи" -- неизвестная редкость не доказывает, что это не секрет
		end
		if isSecret(pet) then
			return "секрет"
		end
		if pet.Equip == true or pet.Equipped == true or pet.IsEquipped == true then
			return "в команде"
		end
		for _, id in ipairs(aliases) do
			if team[id] then return "в команде" end
		end
		if isGodly(pet) then return "годли" end -- Godly ВНЕ команды удаляются, как в исходнике
		return nil
	end

	-- Не достаточно распознать хотя бы одного пета: все идентификаторы Equipped должны
	-- однозначно совпасть с Owned, включая секретов. При неполной реплике чистка ждёт.
	local function cleanTeamVerified(data, owned)
		local pets = type(data) == "table" and data.Pets or nil
		local equipped = type(pets) == "table" and pets.Equipped or nil
		if type(equipped) ~= "table" or type(owned) ~= "table" then return false end
		local aliases, primary, entry = {}, {}, 0
		local function scalar(value)
			return (type(value) == "string" or type(value) == "number") and tostring(value) ~= ""
		end
		local function mark(value, token)
			if not scalar(value) then return end
			local id = tostring(value)
			if aliases[id] ~= nil and aliases[id] ~= token then aliases[id] = false
			elseif aliases[id] == nil then aliases[id] = token end
		end
		for key, pet in pairs(owned) do
			if type(pet) == "table" then
				entry += 1
				local id = pet.Id or key
				if not scalar(id) or primary[tostring(id)] then return false end
				primary[tostring(id)] = true
				mark(key, entry); mark(pet.Id, entry); mark(pet.PetId, entry); mark(pet.PetID, entry)
			end
		end
		local active, selected = 0, {}
		for key, value in pairs(equipped) do
			if value ~= false and value ~= nil then
				local id
				if type(value) == "table" then
					id = value.Id or value.PetId or value.PetID
					if id == nil and type(key) == "string" then id = key end
				elseif value == true then
					id = key
				elseif scalar(value) then
					id = value
				end
				if not scalar(id) then return false end
				local token = aliases[tostring(id)]
				if not token or selected[token] then return false end
				selected[token] = true
				active += 1
			end
		end
		return active > 0
	end

	-- Лок снимаем ОДИН раз на пет: ToggleLock — переключатель, второй вызов залочит обратно.
	local cleanCacheKey = "__ts30CleanUnlocksV4_" .. tostring(Env.LocalPlayer and Env.LocalPlayer.UserId or "unknown")
	local CLEAN_UNLOCKED = type(Env.genv) == "table" and Env.genv[cleanCacheKey] or nil
	if type(CLEAN_UNLOCKED) ~= "table" then
		CLEAN_UNLOCKED = {}
		if type(Env.genv) == "table" then Env.genv[cleanCacheKey] = CLEAN_UNLOCKED end
	end
	local function cleanAllowed()
		local P = Ui.__progressTest
		local phase = P and P.phase
		local lockedPhase = P and (P.eggFixed or P.rebirthLocked) and (phase == "save" or phase == "hatch" or phase == "storage_wait"
			or phase == "target_wait" or phase == "locked_wait")
		local farmPhase = P and not P.eggFixed and not P.rebirthLocked and phase == "rebirth" and not P.farmThresholdReached
			and not P.holdHatch and not P.holdCraft and not P.pending
		return Life.alive and P and P.cleaning and (lockedPhase or farmPhase) and not P.stopRequested and not P.pending
			and not (P.eggFixed and not P.rebirthLocked and (P.targetProbeRequired
				or (type(P.nextSendAt) == "number" and os.clock() >= P.nextSendAt)))
			and not P.hatchUncertain and not P.craftUncertain and not P.craftBusy and not P.craftInFlight
			and not P.previousHatchPending and not P.previousRebirthPending and not P.previousCraftPending
			and not (Env.genv and Env.genv.__handoverPaused)
	end
	local function unlockJunk(owned)
		local ids = {}
		local godly = 0
		local data = Env.data()
		local team = teamSet(data)
		for key, pet in pairs(owned) do
			local aliases = { tostring(key), type(pet) == "table" and tostring(pet.Id or key) or tostring(key),
				type(pet) == "table" and tostring(pet.PetId or key) or tostring(key),
				type(pet) == "table" and tostring(pet.PetID or key) or tostring(key) }
			local reason = keepReason(pet, aliases, team)
			if type(pet) == "table" and pet.Locked == true and (reason == nil or reason == "годли") then
				local id = tostring(pet.Id or key)
				if not CLEAN_UNLOCKED[id] then
					ids[#ids + 1] = id
					if isGodly(pet) then
						godly += 1
					end
				end
			end
		end
		if #ids == 0 then
			return 0
		end
		local failed = 0
		local uncertain, sentCount = 0, 0
		for _, id in ipairs(ids) do
			if not cleanAllowed() then break end
			local attempted = false
			local ok = pcall(function()
				local remote = Env.remote("PetService", "PetActionRequested")
				if not cleanAllowed() then error("cleaning stopped") end
				local fresh = Env.data()
				local pets = type(fresh) == "table" and fresh.Pets or nil
				if type(pets) ~= "table" or not cleanTeamVerified(fresh, pets.Owned) then error("team unknown") end
				local liveTeam = teamSet(fresh)
				local allowed = false
				for key, pet in pairs(pets.Owned) do
					if type(pet) == "table" and tostring(pet.Id or key) == id and pet.Locked == true then
						local reason = keepReason(pet, { tostring(key), tostring(pet.Id or key), tostring(pet.PetId or key), tostring(pet.PetID or key) }, liveTeam)
						allowed = reason == nil or reason == "годли"
						break
					end
				end
				if not allowed or not cleanAllowed() then error("pet protected or cleaning stopped") end
				local send = remote and remote.FireServer
				if type(send) ~= "function" then error("remote unavailable before send") end
				Env.elevate()
				if not cleanAllowed() then error("cleaning stopped") end
				-- Только сейчас отмечаем попытку: ошибку FireServer после вызова нельзя отличить
				-- от отправленного переключателя, поэтому повторять её в этой сессии нельзя.
				CLEAN_UNLOCKED[id] = true
				attempted = true
				send(remote, { Action = "ToggleLock", PetId = id })
			end)
			if not ok then
				failed += 1
				if attempted then uncertain += 1 end
			else
				sentCount += 1
			end
			if attempted and cleanAllowed() then Life.wait(0.1) end -- не шлём пачку локов в один кадр
		end
		if uncertain > 0 then logEvent("warn", "чистка: ответ на снятие лока неясен; повторять переключение не буду") end
		logEvent("clean", string.format("запросы на снятие лока: %d; кандидатов Godly %d%s",
			sentCount, godly, failed > 0 and (" — ошибок или пауз " .. failed) or ""))
		return sentCount
	end

	-- порядок на удаление: слабейшие первыми
	local function buildCleanPlan(data, owned)
		local team, teamRaw, teamKind = teamSet(data)
		local entries = {}
		for key, pet in pairs(owned) do
			if type(pet) == "table" then
				-- один пет может лежать и под ключом, и со своим Id — проверяем оба
				local aliases = { tostring(key) }
				if pet.Id ~= nil then aliases[#aliases + 1] = tostring(pet.Id) end
				if pet.PetId ~= nil then aliases[#aliases + 1] = tostring(pet.PetId) end
				if pet.PetID ~= nil then aliases[#aliases + 1] = tostring(pet.PetID) end
				entries[#entries + 1] = { id = tostring(pet.Id or key), aliases = aliases, pet = pet }
			end
		end
		table.sort(entries, function(a, b)
			local ap, bp = tonumber(a.pet.Power) or 0, tonumber(b.pet.Power) or 0
			if ap ~= bp then
				return ap < bp
			end
			return a.id < b.id
		end)
		local plan = {}
		local stats = { total = #entries, team = 0, secret = 0, godly = 0, bad = 0 }
		for _, entry in ipairs(entries) do
			local onTeam = entry.pet.Equip == true or entry.pet.Equipped == true or entry.pet.IsEquipped == true
			for _, id in ipairs(entry.aliases) do if team[id] then onTeam = true end end
			if onTeam then stats.team += 1 end -- в том числе секрет или пет без редкости
			local reason = keepReason(entry.pet, entry.aliases, team)
			if reason == "годли" then
				stats.godly += 1
				plan[#plan + 1] = entry.id
			elseif reason == nil then
				plan[#plan + 1] = entry.id
			elseif reason == "в команде" then
				-- Уже учтён в stats.team выше.
			elseif reason == "секрет" then
				stats.secret += 1
			else
				stats.bad += 1
			end
		end
		stats.teamRaw = teamRaw
		stats.teamKind = teamKind
		return plan, stats
	end

	-- сам запрос
	local function deleteByIds(ids)
		if #ids == 0 then
			return false
		end
		local ok, err = pcall(function()
			local remote = Env.remote("PetService", "PetActionRequested")
			if not cleanAllowed() then error("cleaning stopped") end
			local data, owned = cleanPetData()
			if not cleanTeamVerified(data, owned) then error("equipped pets not fully identified") end
			local plan = buildCleanPlan(data, owned)
			local allowed, unlocked = {}, {}
			for _, id in ipairs(plan) do allowed[id] = true end
			for key, pet in pairs(owned) do
				if type(pet) == "table" and pet.Locked ~= true then unlocked[tostring(pet.Id or key)] = true end
			end
			local safe = {}
			for _, id in ipairs(ids) do if allowed[id] and unlocked[id] then safe[#safe + 1] = id end end
			if #safe == 0 or not cleanAllowed() then error("no verified unequipped pets to delete") end
			Env.elevate()
			remote:FireServer({ PetIds = safe, Action = "Delete", Batch = 1 })
		end)
		if not ok then
			logEvent("warn", "чистка: ошибка или неподтверждённый запрос — " .. tostring(err))
			return false
		end
		return true
	end

	local function fillState()
		local data, owned, count, limit = cleanPetData()
		if not data then
			CLEAN.note = "данные игрока ещё не пришли"
			return nil
		end
		return { data = data, owned = owned, count = count, limit = limit,
			fill = limit > 0 and (count / limit) or 0 }
	end

	local function cleanTriggered(state)
		if state.fill >= CLEAN.startAt then return true end
		local P = Ui.__progressTest
		local needed = math.max(3, tonumber(P and P.storageNeeded) or 3)
		return P and (P.phase == "storage_wait" or (P.phase == "rebirth" and P.farmStorageFull))
			and state.limit - state.count < needed
	end

	-- один заход: чистим до targetAt, но не больше rounds запросов
	local function cleanNow()
		if CLEAN.running then
			return 0
		end
		local state = fillState()
		if not state then
			return 0
		end
		if state.limit <= 0 then
			if not CLEAN.warnedLimit then
				CLEAN.warnedLimit = true
				logEvent("warn", "чистка: лимит хранилища не пришёл, чистить не буду")
			end
			CLEAN.note = string.format("%d петов, лимит неизвестен", state.count)
			return 0
		end
		if not cleanTriggered(state) then
			CLEAN.note = string.format("%d/%d — запас есть", state.count, state.limit)
			return 0
		end

		-- Не удаляем ничего, пока каждый id команды однозначно не сопоставлен с Owned.
		if not cleanTeamVerified(state.data, state.owned) then
			CLEAN.note = "команда распознана не полностью — чистка на паузе"; logEvent("clean", CLEAN.note); return 0
		end
		CLEAN.running = true
		-- Годли и прочий не-секрет под локом: снимаем лок, ждём, пока данные обновятся,
		-- и только потом считаем план удаления.
		if unlockJunk(state.owned) > 0 then
			Life.wait(1.5)
			local fresh = fillState()
			if fresh then
				state = fresh
			end
		end
		local target = math.floor(state.limit * CLEAN.targetAt)
		local P = Ui.__progressTest
		local needed = math.max(3, tonumber(P and P.storageNeeded) or 3)
		target = math.min(target, math.max(0, state.limit - needed))
		local removedTotal = 0
		local round = 0
		while state.count > target and round < CLEAN.rounds and cleanAllowed() do
			round += 1
			local plan, stats = buildCleanPlan(state.data, state.owned)
			if #plan == 0 then
				-- Пишем, ИЗ ЧЕГО состоит рюкзак: без этого «чистить нечего» ничего не объясняет.
				CLEAN.note = string.format(
					"чистить нечего: %d петов — в команде %d, секретов %d, годли %d, без записи %d",
					stats.total, stats.team, stats.secret, stats.godly, stats.bad)
				logEvent("clean", CLEAN.note)
				break
			end
			if round == 1 then
				logEvent("clean", string.format(
					"%d/%d — к удалению %d (в команде %d, секретов %d, годли %d)",
					state.count, state.limit, #plan, stats.team, stats.secret, stats.godly))
				-- Разбор команды: если «в команде 1», по этой строке сразу видно, чья вина —
				-- пустой/непривычной формы Equipped или петов с флагом Equip.
				logEvent("clean", string.format(
					"команда: Equipped=%s, записей %d, совпало петов %d%s",
						stats.teamKind, stats.teamRaw, stats.team,
						stats.team == 0 and " — НЕ РАСПОЗНАЛ, проверь форму" or ""))
			end
			-- берём ровно столько, сколько нужно до цели: лишнего не удаляем
			local need = state.count - target
			local unlocked, batch = {}, {}
			for key, pet in pairs(state.owned) do
				if type(pet) == "table" and pet.Locked ~= true then unlocked[tostring(pet.Id or key)] = true end
			end
			for _, id in ipairs(plan) do
				if unlocked[id] then batch[#batch + 1] = id end
				if #batch >= math.min(CLEAN.batch, math.max(need, 1)) then break end
			end
			if #batch == 0 then
				CLEAN.note = "нет подтверждённо разблокированных кандидатов — жду"
				logEvent("clean", CLEAN.note)
				break
			end
			if not deleteByIds(batch) then
				CLEAN.note = "ошибка или неподтверждённое удаление"
				break
			end
			Life.wait(CLEAN.pause)
			local again = fillState()
			if not again then
				break
			end
			local gone = state.count - again.count
			state = again
			if gone <= 0 then
				CLEAN.failures += 1
				CLEAN.note = string.format("удаление пока не видно (%d/%d)", state.count, state.limit)
				logEvent("warn", "чистка: после запроса изменений пока не видно — жду следующего захода")
				break
			end
			CLEAN.failures = 0
			CLEAN.deleted += gone
			removedTotal += gone
			CLEAN.note = string.format("-%d → %d/%d", gone, state.count, state.limit)
			logEvent("clean", string.format("удалено %d, стало %d/%d", gone, state.count, state.limit))
		end
		CLEAN.running = false
		if removedTotal > 0 then
			CLEAN.note = string.format("удалено %d, стало %d/%d", removedTotal, state.count, state.limit)
		end
		return removedTotal
	end

	-- Запрос EquipBest не подтверждает применение сервером. Сравниваем две реплики команды;
	-- при меняющемся или неполном составе не начинаем удаление в этом заходе.
	local function cleanTeamSnapshot()
		local data = Env.data()
		local pets = type(data) == "table" and data.Pets or nil
		if type(pets) ~= "table" or not cleanTeamVerified(data, pets.Owned) then return nil end
		local team = teamSet(data)
		local parts = {}
		for id in pairs(team) do parts[#parts + 1] = "id:" .. id end
		for key, pet in pairs(pets.Owned) do
			if type(pet) == "table" and (pet.Equip == true or pet.Equipped == true or pet.IsEquipped == true) then
				parts[#parts + 1] = "flag:" .. tostring(pet.Id or key)
			end
		end
		table.sort(parts)
		return table.concat(parts, "\0")
	end

	-- Существующая чистка: в обеих фазах при >=90% или нехватке мест под партию.
	-- Краткая пауза нужна, чтобы не удалять пета в тот же момент, когда EquipBest ставит его в команду.
	Life.loop("pet:clean", 10, function()
		local P = Ui.__progressTest
		local phase = P and P.phase
		local lockedPhase = P and (P.eggFixed or P.rebirthLocked) and (phase == "save" or phase == "hatch" or phase == "storage_wait"
			or phase == "target_wait" or phase == "locked_wait")
		local farmPhase = P and not P.eggFixed and not P.rebirthLocked and phase == "rebirth" and not P.farmThresholdReached
			and not P.holdHatch and not P.holdCraft and not P.pending
		if not CLEAN.enabled or not P or not (lockedPhase or farmPhase) or P.stopRequested or P.cleaning or P.pending
			or (P.eggFixed and not P.rebirthLocked and (P.targetProbeRequired
				or (type(P.nextSendAt) == "number" and os.clock() >= P.nextSendAt)))
			or P.hatchUncertain or P.craftUncertain or P.craftBusy or P.craftInFlight
			or P.previousHatchPending or P.previousRebirthPending or P.previousCraftPending
			or Ui.hatchMoving or Ui.travelling or (Env.genv and Env.genv.__handoverPaused) then return end
		local state = fillState()
		if not state or state.limit <= 0 or not cleanTriggered(state) then return end
		P.cleaning = true
		local ok, err = pcall(function()
			local deadline = os.clock() + 15
			while Ui.hatchInFlight and cleanAllowed() and os.clock() < deadline do Life.wait(0.2) end
			if Ui.hatchInFlight or not cleanAllowed() then return end
			local opt = Ui.Options and Ui.Options.EquipMode
			local desired = (P.eggFixed or P.rebirthLocked) and "Luck" or "Clicks"
			local function canEquipForClean()
				return P.equipReady == true and cleanAllowed() and opt and opt.Value == desired
					and ((P.eggFixed or P.rebirthLocked) and "Luck" or "Clicks") == desired and Ui.on("AutoEquipBest")
			end
			if not canEquipForClean() then return end
			local remote = Env.remote("PetService", "PetActionRequested")
			if not remote or not canEquipForClean() then return end
			Env.elevate()
			if not canEquipForClean() then return end
			remote:FireServer({ Action = "EquipBest", Mode = desired })
			P.lastEquipMode, P.lastEquipAt = desired, os.clock()
			Life.wait(2) -- дать реплике обновить команду до старой чистки
			if not canEquipForClean() then return end
			local before = cleanTeamSnapshot()
			if not before then
				CLEAN.note = "команда распознана не полностью — чистка на паузе"
				logEvent("clean", CLEAN.note); return
			end
			Life.wait(1)
			if not cleanAllowed() then return end
			if cleanTeamSnapshot() ~= before then
				CLEAN.note = "команда меняется — чистка на паузе"; logEvent("clean", CLEAN.note); return
			end
			cleanNow()
		end)
		CLEAN.running = false
		P.cleaning = false
		if not ok then logEvent("warn", "чистка остановлена: " .. tostring(err)) end
	end)

	-- 7.6) Логи в консоль: строка раз в минуту, плюс важные события сразу
	local lastReport = { eggs = 0, pets = 0, at = os.clock() }
	Life.loop("log:console", 60, function()
		local data = Env.data()
		local player = Env.LocalPlayer
		local owned = data and data.Pets and data.Pets.Owned
		local storage, limit = 0, tonumber(data and data.Pets and data.Pets.StorageLimit) or 0
		if type(owned) == "table" then
			for _ in pairs(owned) do storage += 1 end
		end
		local function currency(name)
			local c = data and type(data.Currencies) == "table" and data.Currencies
			return tonumber(type(c) == "table" and c[name]) or 0
		end

		local now = os.clock()
		local span = math.max(1, now - lastReport.at)
		local eggsNow = LOG.rolls
		local gained = eggsNow - lastReport.eggs
		local rate = gained * 60 / span
		lastReport.eggs = eggsNow
		lastReport.at = now

		local uptime = math.floor(now - LOG.started)
		local eggNow = player and player:GetAttribute("TAPSIM_Egg")

		-- засуха по яйцам: от неё зависит Secret Luck, а значит и шанс секрета
		local drought, droughtEgg = 0, nil
		local ds = data and data.Eggs and data.Eggs.SecretDroughtSeconds
		if type(ds) == "table" then
			for egg, sec in pairs(ds) do
				local value = tonumber(sec)
				if value and value > drought then
					drought, droughtEgg = value, tostring(egg)
				end
			end
		end

		local errorLine = ""
		for kind, count in pairs(errors) do
			errorLine = errorLine .. string.format(" %s:%d", kind, count)
		end

		print(string.format(
			"[TAPSIM] %s | яйца: +%d за %dс (%.1f/мин, окно %.1f/мин), всего %d, хатчей %d | секреты: %d (поймано %d) | монеты %s, гемы %s, токены %s | рюкзак %d/%d | засуха %s | яйцо: %s | %s | в игре %s%s",
			player and player.Name or "?",
			gained, math.floor(span), rate, windowRate(), eggsNow, LOG.hatches,
			LOG.secrets, LOG.secretsCaught,
			short(currency("Coins")), short(currency("Gems")), short(currency("Tokens") + currency("PaidTokens")),
			storage, limit,
			string.format("%s %.1fч", droughtEgg or "-", drought / 3600),
			tostring(eggNow or LOG.lastEgg or "?"),
			CLEAN.note,
			string.format("%dч %dм", math.floor(uptime / 3600), math.floor(uptime / 60) % 60),
			errorLine
		))
	end)

	print("[TAPSIM] 30M v13 | Clicks и яйца до 20%; после 300 млн/с 30M x3 + Luck и ребёрты; после 900 млн/с ребёрты стоп")
	print(string.format("[TAPSIM] старт | аккаунт %s | панель и логи включены",
		Env.LocalPlayer and Env.LocalPlayer.Name or "?"))

	-- 8) Панель в старом дизайне
	local started = os.clock()
	local gui = Instance.new("ScreenGui")
	gui.Name = "TapSimStats"
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	gui.DisplayOrder = 999
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	local parentGui = (Env.guiParent and Env.guiParent()) or game:GetService("CoreGui")
	gui.Parent = parentGui
	gui.Enabled = false -- панель скрыта; RightShift показывает/прячет

	local main = Instance.new("Frame")
	main.Name = "Main"
	main.AnchorPoint = FULLSCREEN and Vector2.new(0, 0) or Vector2.new(0.5, 0.5)
	main.Position = FULLSCREEN and UDim2.fromOffset(0, 0) or UDim2.fromScale(0.5, 0.5)
	main.Size = FULLSCREEN and UDim2.fromScale(1, 1) or UDim2.fromOffset(300, 0)
	if not FULLSCREEN then
		-- в угол, чтобы не лежать поверх карточек игры
		main.AnchorPoint = Vector2.new(0, 0)
		main.Position = UDim2.fromOffset(8, 8)
	end
	main.AutomaticSize = FULLSCREEN and Enum.AutomaticSize.None or Enum.AutomaticSize.Y
	main.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
	main.BackgroundTransparency = FULLSCREEN and 0 or 0.15
	main.BorderSizePixel = 0
	main.Active = false -- не перехватывать мышь: иначе панель ест нажатия по игре
	main.Parent = gui

	local pad = Instance.new("UIPadding")
	pad.PaddingTop = UDim.new(0, FULLSCREEN and 0 or 12)
	pad.PaddingBottom = UDim.new(0, FULLSCREEN and 0 or 12)
	pad.PaddingLeft = UDim.new(0, FULLSCREEN and 0 or 10)
	pad.PaddingRight = UDim.new(0, FULLSCREEN and 0 or 10)
	pad.Parent = main

	local list = Instance.new("UIListLayout")
	list.Padding = UDim.new(0, FULLSCREEN and 14 or 7)
	list.VerticalAlignment = FULLSCREEN and Enum.VerticalAlignment.Center or Enum.VerticalAlignment.Top
	list.HorizontalAlignment = Enum.HorizontalAlignment.Center
	list.SortOrder = Enum.SortOrder.LayoutOrder
	list.Parent = main

	local order = 0
	local function row(text, color, size)
		order += 1
		local label = Instance.new("TextLabel")
		label.Size = UDim2.new(1, 0, 0, FULLSCREEN and 46 or 16)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.GothamBold
		label.TextSize = size or (FULLSCREEN and 34 or 14)
		label.TextXAlignment = Enum.TextXAlignment.Center
		label.TextColor3 = color or Color3.fromRGB(240, 240, 245)
		label.Text = text
		label.LayoutOrder = order
		label.Parent = main
		return label
	end

	local function divider()
		order += 1
		local line = Instance.new("Frame")
		line.Size = UDim2.new(FULLSCREEN and 0.4 or 0.92, 0, 0, FULLSCREEN and 2 or 1)
		line.BackgroundColor3 = Color3.fromRGB(150, 125, 45)
		line.BorderSizePixel = 0
		line.LayoutOrder = order
		line.Parent = main
		return line
	end

	local userRow = row("👤 Username: …")
	divider()
	row("💼 Farming pets")
	divider()
	local coinsRow = row("💰 Coins: …")
	local gemsRow = row("💎 Gems: …")
	local tokensRow = row("🎫 Tokens: …")
	local rebirthsRow = row("🌟 Rebirths: …")
	local pityRow = row("🥚 Pity: …")
	local rateRow = row("🐣 Pets/min: …")
	local eggsRow = row("🥚 Eggs: …")
	local storageRow = row("🐾 Pets: …")
	divider()
	local secretsRow = row("🔮 Secrets: …")
	divider()
	local timeRow = row("⏰ Time: 00:00:00")
	local linkRow = row("📡 Сервер: …")
	local cleanRow = row("🧹 Cleanup: …")
	local autoDeleteRow = row("🗑 Автоудалёнт: …")
	local craftRow = row("🧪 Крафт: …")

	-- RightShift — скрыть/показать панель
	local UserInputService = game:GetService("UserInputService")
	local connection = UserInputService.InputBegan:Connect(function(input, processed)
		if processed then
			return
		end
		if input.KeyCode == Enum.KeyCode.RightShift then
			gui.Enabled = not gui.Enabled
		end
	end)

	Life.onCleanup(function()
		if connection then
			connection:Disconnect()
		end
		gui:Destroy()
	end)

	local petSamples = {}

	Life.loop("panel:stats", 1, function()
		if not gui.Parent then
			return
		end
		local data = Env.data()
		local function currency(name)
			local c = data and type(data.Currencies) == "table" and data.Currencies
			return tonumber(type(c) == "table" and c[name]) or 0
		end

		local player = Env.LocalPlayer
		userRow.Text = "👤 Username: " .. (player and player.Name or "…")
		coinsRow.Text = "💰 Coins: " .. short(currency("Coins"))
		gemsRow.Text = "💎 Gems: " .. short(currency("Gems"))
		tokensRow.Text = "🎫 Tokens: " .. short(currency("Tokens") + currency("PaidTokens"))
		local stats = data and data.Statistics
		rebirthsRow.Text = "🌟 Rebirths: " .. short(tonumber(type(stats) == "table" and stats.Rebirths) or 0)

		local drought = 0
		local eggs = data and data.Eggs
		local droughts = type(eggs) == "table" and eggs.SecretDroughtSeconds
		if type(droughts) == "table" then
			for _, value in pairs(droughts) do
				local seconds = tonumber(value) or 0
				if seconds > drought then
					drought = seconds
				end
			end
		end
		local fill = math.clamp(drought / 86400, 0, 1)
		pityRow.Text = string.format("🥚 Pity: %d%% (x%.2f)", math.floor(fill * 100), 1 + 3 * fill)

		local owned = data and data.Pets and data.Pets.Owned
		local petCount = 0
		if type(owned) == "table" then
			for _ in pairs(owned) do
				petCount += 1
			end
		end
		local limit = data and data.Pets and tonumber(data.Pets.StorageLimit)
		storageRow.Text = string.format("🐾 Pets: %s / %s", short(petCount), limit and short(limit) or "?")

		petSamples[#petSamples + 1] = { at = os.clock(), count = petCount }
		while #petSamples > 1 and os.clock() - petSamples[1].at > 60 do
			table.remove(petSamples, 1)
		end
		local first = petSamples[1]
		local span = os.clock() - first.at
		rateRow.Text = span > 5 and string.format("🐣 Pets/min: %.1f", (petCount - first.count) * 60 / span)
			or "🐣 Pets/min: …"

		secretsRow.Text = "🔮 Secrets: " .. tostring(secretsCount)

		eggsRow.Text = string.format("🥚 Eggs: %s (хатчей %s)", short(LOG.eggs), short(LOG.hatches))
		cleanRow.Text = string.format("🧹 Cleanup: удалено %s · %s", short(CLEAN.deleted), CLEAN.note)
		do
			local P = Ui.__progressTest
			local label = not P and "недоступен"
				or P.craftUncertain and "остановлен: ответ не подтверждён"
				or (P.eggFixed or P.rebirthLocked) and "выключен после перехода"
				or Ui.on("AutoCraft") and "только при 100%"
				or "пауза / ожидание"
			craftRow.Text = "🧪 Автокрафт: " .. label
		end
		autoDeleteRow.Text = HATCH_DELETE_ABOVE > 0
			and string.format("🗑 Автоудалёнт: обычные от %d%% шанса", HATCH_DELETE_ABOVE)
			or "🗑 Автоудалёнт: настройки игры сохранены"
		linkRow.Text = LOG.error and ("📡 Сервер: " .. LOG.error) or "📡 Сервер: ок"
		linkRow.TextColor3 = LOG.error and Color3.fromRGB(235, 130, 100) or Color3.fromRGB(150, 200, 150)

		local seconds = math.floor(os.clock() - started)
		timeRow.Text = string.format("⏰ Time: %02d:%02d:%02d", math.floor(seconds / 3600), math.floor(seconds / 60) % 60, seconds % 60)

		-- цвет: хранилище почти полное — предупредить
		storageRow.TextColor3 = (limit and petCount / limit > 0.9) and Color3.fromRGB(235, 130, 100)
			or Color3.fromRGB(240, 240, 245)
	end)
end
return Hub
